local factories, cache, loading = {}, {}, {}
local function requireOC(name)
  if cache[name] ~= nil then return cache[name] end
  assert(factories[name], "[OC] Unknown bundled module: " .. tostring(name))
  assert(not loading[name], "[OC] Circular bundled dependency: " .. tostring(name))
  loading[name] = true
  local ok, result = pcall(factories[name])
  loading[name] = nil
  if not ok then error("[OC] Module " .. name .. " failed: " .. tostring(result), 0) end
  cache[name] = result
  return result
end

-- src/OCFoundation/AccountPresentation.luau
factories["AccountPresentation"] = function()
--!nonstrict
-- Only formats values supplied by the account reader. Unknown stays unavailable.
local AccountPresentation = {}

function AccountPresentation.Number(value)
	if type(value) ~= "number" then return "unavailable" end
	if value == math.huge then return "unlimited" end
	return tostring(value)
end

local function keys(map)
	local result = {}
	for key in pairs(map) do table.insert(result, key) end
	table.sort(result, function(a, b) return tostring(a) < tostring(b) end)
	return result
end

function AccountPresentation.Describe(value, depth, seen)
	if value == nil then return "unavailable" end
	if type(value) ~= "table" then return tostring(value) end
	depth = depth or 0
	seen = seen or {}
	if seen[value] then return "<cycle>" end
	local sorted = keys(value)
	if depth >= 2 then return "<" .. tostring(#sorted) .. " entries>" end
	seen[value] = true
	local lines = {}
	for index, key in ipairs(sorted) do
		if index > 10 then table.insert(lines, "... " .. tostring(#sorted - 10) .. " more fields") break end
		table.insert(lines, tostring(key) .. "=" .. AccountPresentation.Describe(value[key], depth + 1, seen))
	end
	seen[value] = nil
	return "{" .. table.concat(lines, ", ") .. "}"
end

function AccountPresentation.List(map, limit)
	if type(map) ~= "table" then return "unavailable" end
	local sorted = keys(map)
	if #sorted == 0 then return "(empty received table)" end
	local lines = {}
	for index, key in ipairs(sorted) do
		if index > limit then table.insert(lines, "... " .. tostring(#sorted - limit) .. " more entries; GetStatus has the complete snapshot") break end
		table.insert(lines, tostring(key) .. ": " .. AccountPresentation.Describe(map[key]))
	end
	return table.concat(lines, "\n")
end

function AccountPresentation.Sections(snapshot, config, limit)
	local sections = {}
	local inventory, bubble, upgrades = snapshot.Inventory or {}, snapshot.Bubble or {}, snapshot.Upgrades or {}
	local balances = {}
	local displayed = {}
	for _, name in ipairs(config.ACCOUNT_SETTINGS.SELECTED_CURRENCIES) do
		table.insert(balances, name .. ": " .. AccountPresentation.Number((snapshot.Balances or {})[name]))
		displayed[name] = true
	end
	for _, name in ipairs(keys(snapshot.Balances or {})) do
		if not displayed[name] then table.insert(balances, name .. ": " .. AccountPresentation.Number(snapshot.Balances[name])) end
	end
	table.insert(balances, "Bubbles: " .. AccountPresentation.Number(bubble.Amount) .. " / " .. AccountPresentation.Number(bubble.Capacity))
	table.insert(balances, "Power per blow: " .. AccountPresentation.Number(bubble.PowerPerBlow))
	table.insert(balances, "Equipped gum: " .. tostring(bubble.Gum or "unavailable") .. "; flavor: " .. tostring(bubble.Flavor or "unavailable"))
	sections.Balances = table.concat(balances, "\n")
	sections.Pets = "Active team: " .. tostring(inventory.TeamEquipped or "unavailable")
		.. "\nEquip limit: " .. AccountPresentation.Number(inventory.MaxEquipped)
		.. "\nEquipped IDs:\n" .. AccountPresentation.List(inventory.EquippedIds, limit)
		.. "\nEquipped records:\n" .. (inventory.EquippedIds and AccountPresentation.List(inventory.EquippedPets, limit) or "unavailable")
		.. "\nUnresolved equipped IDs:\n" .. (inventory.EquippedIds and AccountPresentation.List(inventory.UnresolvedEquippedIds, limit) or "unavailable")
		.. "\nPet inventory:\n" .. AccountPresentation.List(inventory.Pets, limit)
	sections.Inventory = "Storage used / capacity (game-defined units): " .. AccountPresentation.Number(inventory.StorageUsed)
		.. " / " .. AccountPresentation.Number(inventory.StorageCapacity)
		.. "\nPowerups:\n" .. AccountPresentation.List(inventory.Powerups, limit)
		.. "\nPotions:\n" .. AccountPresentation.List(inventory.Potions, limit)
	sections.Worlds = "Unlocked worlds:\n" .. AccountPresentation.List(snapshot.UnlockedWorlds, limit)
		.. "\nDiscovered islands:\n" .. AccountPresentation.List(snapshot.UnlockedIslands, limit)
	sections.Upgrades = "Owned gum:\n" .. AccountPresentation.List(upgrades.Gum, limit)
		.. "\nOwned flavors:\n" .. AccountPresentation.List(upgrades.Flavors, limit)
		.. "\nMastery upgrades:\n" .. AccountPresentation.List(upgrades.MasteryUpgrades, limit)
	sections.Mastery = "Received levels:\n" .. AccountPresentation.List(upgrades.MasteryLevels, limit)
		.. "\nVerified next tiers:\n" .. AccountPresentation.List(snapshot.AvailableProgression and snapshot.AvailableProgression.Mastery, limit)
	return sections
end

local function finite(value)
	return type(value) == "number" and value == value and math.abs(value) < math.huge
end

local function diagnosticSummary(status, previous, now)
	local travel, snapshot = status.EggTravel or {}, status.Snapshot or {}
	local result, ledger = travel.LastResult or {}, travel.Lease or travel.LastResult or {}
	local intent, pets = travel.BrainIntent or {}, status.Pets or {}
	local hatch = pets.Hatch or {}
	local blocker = status.Error or travel.LastPreflightReason or travel.Reason
	if not blocker and not snapshot.Ready then blocker = snapshot.Status or "account data unavailable" end
	local stage = travel.LastPreflightReason and "PREFLIGHT_BLOCKED" or result.Status
		or travel.Reason and "BLOCKED" or travel.Lease and travel.Lease.Status or "waiting"
	local parts = {
		tostring(status.State),
		"goal=TRAVEL_ONLY:" .. tostring(intent.EggName or result.EggName or "waiting for accessible native egg"),
		"egg travel=" .. tostring(stage),
		"direct attempts=" .. (ledger.DirectPositionAttempted == true and "1" or "0"),
		"native travel attempts=" .. (ledger.NativeTravelAttempted == true and "1" or "0"),
		"hatch commands=" .. tostring(hatch.RequestedHatches or result.HatchCommands or 0),
		"equipment commands=" .. tostring(pets.EquipmentCommands or 0),
		"spending=" .. tostring(result.Spending or 0),
	}
	if result.HatchInteraction then table.insert(parts, "hatch interaction=" .. tostring(result.HatchInteraction)) end
	for _, currency in ipairs({ "Coins", "Gems" }) do
		local value, old = (snapshot.Balances or {})[currency], (previous.Balances or {})[currency]
		local delta = finite(value) and finite(old) and string.format("%+.0f", value - old) or "unknown"
		table.insert(parts, currency .. "=" .. (finite(value) and string.format("%.0f", value) or "unknown") .. " (balance change " .. delta .. ")")
	end
	table.insert(parts, "blocker=" .. tostring(blocker or "none observed"):gsub("[\r\n]+", " "):sub(1, 220))
	table.insert(parts, string.format("interval %.1fs; owner live acceptance pending", math.max(0, now - previous.At)))
	return table.concat(parts, " | ")
end

-- Console-only formatting. One previous displayed balance baseline; never sum batch results or visual cleanup.
function AccountPresentation.Summary(status, previous, now, config)
	-- The retained diagnostic reason is the same preflight result printed by the
	-- Brain/manager. A separate paid pet/farming WAIT must not hide that blocker.
	if status.EggTravel and status.EggTravel.Mode == "TRAVEL_ONLY" then
		return diagnosticSummary(status, previous, now)
	end
	local snapshot, farming, world = status.Snapshot or {}, status.Farming or {}, status.WorldProgression or {}
	local goal = status.Plan and status.Plan.Objective
	local balances, metadata = snapshot.Balances or {}, goal and goal.Metadata or {}
	local travel = status.EggTravel or {}
	local travelOnly = travel.Mode == "TRAVEL_ONLY"
	local displayGoal = travelOnly and ("TRAVEL_ONLY:" .. tostring(travel.BrainIntent and travel.BrainIntent.EggName or "waiting for accessible native egg"))
		or goal and (goal.Title or goal.Id) or "waiting for account/goal"
	local parts = { tostring(status.State), "goal=" .. tostring(displayGoal),
		"activity=" .. tostring(status.State ~= "RUNNING" and status.State or farming.Activity
			or (world.Decision and world.Decision.Kind) or (farming.Decision and (farming.Decision.Mode or farming.Decision.Kind)) or "WAIT"),
		"island=" .. tostring(farming.Area or "unknown") }
	local owner = status.Scheduler and status.Scheduler.ActiveOwner
	if owner == "REWARDS" or owner == "EGG_TRAVEL" or owner == "ANTI_AFK" or owner == "PETS" then table.insert(parts, "local task=" .. owner) end
	local pets = status.Pets
	if pets and pets.Enabled then
		local hatch, decision = pets.Hatch or {}, pets.Decision or {}
		local location, pending = hatch.Location or {}, hatch.Pending
		local target = pending and pending.EggName or decision.EggName or location.EggName
			or status.EggTravel and status.EggTravel.BrainIntent and status.EggTravel.BrainIntent.EggName
		table.insert(parts, "pet task=" .. tostring(decision.Kind or "WAIT") .. ":" .. tostring(target or "no eligible egg"))
		table.insert(parts, "hatches=" .. tostring(hatch.VerifiedHatches or 0) .. "/" .. tostring(hatch.RequestedHatches or 0) .. " received/requested")
	end
	if status.Rewards and status.Rewards.Pending then table.insert(parts, "reward=" .. tostring(status.Rewards.Pending.Kind) .. ":" .. tostring(status.Rewards.Pending.Status)) end
	if status.Rewards and status.Rewards.AttributionBlocked then table.insert(parts, "farming attribution=excluded/pending reward evidence") end
	if status.EggTravel and status.EggTravel.Enabled then table.insert(parts, "egg travel=" .. tostring(status.EggTravel.LastResult and status.EggTravel.LastResult.Status or status.EggTravel.Reason or "waiting")) end
	if status.AntiAFK and status.AntiAFK.Enabled then table.insert(parts, "anti-AFK=" .. tostring(status.AntiAFK.Fault or status.AntiAFK.Suppression or "guarded ScrollLock pair; effectiveness unverified")) end
	for _, currency in ipairs({ "Coins", "Gems" }) do
		local value, old = balances[currency], (previous.Balances or {})[currency]
		local delta = finite(value) and finite(old) and string.format("%+.0f", value - old) or "unknown"
		table.insert(parts, currency .. "=" .. (finite(value) and string.format("%.0f", value) or "unknown") .. " (balance change " .. delta .. ")")
	end
	local cost, deficit = metadata.Cost, nil
	local progression = metadata.Progression
	if progression then
		local node = snapshot.ProgressionGraph and snapshot.ProgressionGraph.Next
		cost = node and progression.Node and node.Id == progression.Node.Id and node.Kind == "WORLD"
			and (node.State == "FUNDING" or node.State == "READY") and node.Cost or nil
	end
	local currency = cost and cost.Currency or metadata.Requirement and metadata.Requirement.Currency or farming.Decision and farming.Decision.Currency
	if cost and cost.Type == "Currency" and finite(cost.Amount) and cost.Amount >= 0 and finite(balances[currency]) then
		local field = ({ Coins = "COIN_RESERVE", Gems = "GEM_RESERVE", Tickets = "TICKET_RESERVE", Pearls = "PEARL_RESERVE" })[currency]
		deficit = math.max(0, cost.Amount + (field and config.RESOURCE_SETTINGS[field] or 0) - balances[currency])
	end
	local entry = farming.Rates and farming.Rates.STATIONARY
	local rate, rateDescription = nil, "unknown (no adequate current stationary sample)"
	if entry and finite(entry.LastAt) and finite(entry.Seconds) then
		local age = now - entry.LastAt
		if age < 0 or age > config.FARMING_SETTINGS.RATE_WINDOW_SECONDS then rateDescription = "unknown (stale/future sample)"
		elseif entry.Ready and entry.Seconds >= config.FARMING_SETTINGS.MINIMUM_RATE_SAMPLE_SECONDS
			and currency and entry.PerMinute and finite(entry.PerMinute[currency]) and entry.PerMinute[currency] >= 0 then
			rate = entry.PerMinute[currency]
			rateDescription = string.format("%.2f %s/min, sample %.1fs, age %.1fs", rate, currency, entry.Seconds, age)
		end
	end
	table.insert(parts, "rate=" .. rateDescription)
	table.insert(parts, "shortage=" .. (deficit and string.format("%.0f %s", deficit, currency) or "unknown/no fixed resource target"))
	local hours = deficit and rate and rate > 0 and deficit / rate / 60 or nil
	local eta = "unknown"
	if deficit == 0 then eta = "funded"
	elseif finite(hours) then eta = string.format("%.2f days / %.1fh (short-sample estimate, not guaranteed)", hours / 24, hours) end
	table.insert(parts, "funding ETA=" .. eta)
	local blocker = status.Error or farming.Error or farming.CleanupBlocker
	if not blocker and travelOnly then blocker = travel.Reason end
	if not blocker and pets and pets.Enabled and not travelOnly then
		blocker = pets.Fault or pets.Hatch and pets.Hatch.Fault
		if not blocker and pets.Decision and pets.Decision.Kind == "WAIT" and pets.Analysis then
			local analysis = pets.Analysis
			if analysis.Team and analysis.Team.BaselineIncomplete then blocker = tostring(analysis.Team.BaselineStatus) .. " | " .. tostring(analysis.Team.SearchStatus) end
			for _, egg in ipairs(analysis.CoinsAvailability or {}) do
				if not blocker and egg.Loaded and egg.Eligible and egg.FundingStatus == "PROTECTED_RESERVE" then
					blocker = "PROTECTED_RESERVE | normal reserve=" .. tostring(egg.NormalReserve or egg.Reserve) .. " Coins; spendable=" .. tostring(egg.Spendable)
				end
			end
		end
		blocker = blocker or pets.Decision and (pets.Decision.Kind == "WAIT" or pets.Decision.Kind == "OBSERVE") and pets.Decision.Reason
	end
	if not blocker and world.Decision and world.Decision.Kind == "WAIT" then blocker = world.Decision.Reason end
	if not blocker and farming.Decision and (farming.Decision.Kind == "WAIT" or farming.Decision.Kind == "INSPECT") then blocker = farming.Decision.Reason end
	if not blocker then blocker = farming.CollectionBlocker end
	local lastBatch = farming.Stationary and farming.Stationary.LastResult
	if not blocker and lastBatch and lastBatch.Outcome == "INCONCLUSIVE_NO_MATCHING_CREDIT" then
		blocker = "Last batch inconclusive: no matching LocalData currency credit; server acceptance unknown"
	end
	if not blocker and finite(hours) and hours > config.WORLD_SETTINGS.FUNDING_HORIZON_HOURS then
		blocker = "Estimated funding time exceeds the configured horizon; earning-power review needed"
	end
	if not blocker and not snapshot.Ready then blocker = snapshot.Status or "account data unavailable" end
	table.insert(parts, "blocker=" .. tostring(blocker or "none observed"):gsub("[\r\n]+", " "):sub(1, 220))
	table.insert(parts, string.format("interval %.1fs; net balance change includes possible external rewards/spending", math.max(0, now - previous.At)))
	return table.concat(parts, " | ")
end

return AccountPresentation

end

-- src/OCFoundation/AccountStateReader.luau
factories["AccountStateReader"] = function()
--!nonstrict
-- Read-only adapter for this workspace's LocalData and Shared game definitions.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local CollectionService = game:GetService("CollectionService")

local ProgressionGraph = requireOC("ProgressionGraph")
local AccountStateReader = {}
AccountStateReader.__index = AccountStateReader

local function copy(value, seen)
	if type(value) ~= "table" then return value end
	seen = seen or {}
	if seen[value] then return seen[value] end
	local result = {}
	seen[value] = result
	for key, entry in pairs(value) do result[key] = copy(entry, seen) end
	return result
end

local function number(value)
	if type(value) == "number" and value == value and value >= 0 then return value end
	return nil
end

local function findPath(path)
	local node = ReplicatedStorage
	for name in string.gmatch(path, "[^%.]+") do
		node = node and node:FindFirstChild(name)
	end
	return node
end

local function allowed(list, name)
	return #list == 0 or table.find(list, name) ~= nil
end

function AccountStateReader.new(config, player)
	local self = setmetatable({}, AccountStateReader)
	self.Config = config
	self.Player = player or Players.LocalPlayer
	self.Changed = Instance.new("BindableEvent")
	self.Dependencies = {}
	self.Connections = {}
	self.Threads = {}
	self.Destroyed = false
	self.StartedAt = nil
	self.Revision = 0
	self.DiscoveredCurrencies = {}
	self.NativeGiftFacts = { Available = false, Revision = 0, Records = {}, Reason = "Ordinary gift observer not bound" }
	self.Snapshot = { Ready = false, Status = "NOT_STARTED", Diagnostics = {}, Revision = 0 }
	return self
end

function AccountStateReader:GetTaskRequirement(questId, index, profile)
	local raw = profile or self:GetLiveProfile()
	local util = self:_dependency("QuestUtil")
	if not raw or type(raw.Quests) ~= "table" or not util or type(util.GetRequirement) ~= "function" then return nil end
	for _, quest in pairs(raw.Quests) do
		if type(quest) ~= "table" or quest.Id ~= questId or type(quest.Tasks) ~= "table" or type(quest.Progress) ~= "table" then continue end
		local taskDefinition = quest.Tasks[index]
		if type(taskDefinition) ~= "table" then return nil end
		local kind, currency = taskDefinition.Type, nil
		if kind == "Collect" then
			local item = taskDefinition.Item
			if type(item) ~= "table" or item.Type ~= "Currency" or (item.Currency ~= "Coins" and item.Currency ~= "Gems") then return nil end
			currency = item.Currency
		elseif kind ~= "Bubbles" and kind ~= "Sell" then return nil end
		local ok, required = pcall(util.GetRequirement, util, taskDefinition)
		local current = number(quest.Progress[index])
		if not ok or not number(required) or required >= math.huge or required <= 0 or not current or current >= math.huge or current >= required then return nil end
		return { QuestId = questId, TaskIndex = index, Type = kind, Currency = currency, Required = required, Current = current,
			Source = "LocalData.Quests.Tasks/Progress + Shared.Utils.Stats.QuestUtil:GetRequirement" }
	end
	return nil
end

function AccountStateReader:_load(name, path, expectedType)
	local entry = { Status = "LOADING", Path = path }
	self.Dependencies[name] = entry
	local module = findPath(path)
	if not module or not module:IsA("ModuleScript") then
		entry.Status = "MISSING"
		entry.Error = "ModuleScript is absent: " .. path
		return
	end
	table.insert(self.Threads, task.defer(function()
		local ok, result = pcall(require, module)
		if self.Destroyed then return end
		if ok and type(result) ~= (expectedType or "table") then
			ok = false
			result = "Observed game interface requires " .. (expectedType or "table") .. "; module returned " .. type(result)
		end
		entry.Status = ok and "READY" or "ERROR"
		entry.Value = ok and result or nil
		entry.Error = not ok and tostring(result) or nil
		if name == "LocalData" and ok and type(result) == "table" then
			for _, signalName in ipairs({ "Changed", "DataReady", "PetsChanged" }) do
				local signal = result[signalName]
				if typeof(signal) == "RBXScriptSignal" then
					table.insert(self.Connections, signal:Connect(function() self:_queueRefresh() end))
				end
			end
		end
		if name == "Remote" and ok then self:_bindNativeGiftObserver() end
		self:Refresh()
	end))
	table.insert(self.Threads, task.delay(self.Config.ACCOUNT_SETTINGS.MODULE_LOAD_TIMEOUT_SECONDS, function()
		if self.Destroyed or entry.Status ~= "LOADING" then return end
		entry.Status = "TIMED_OUT"
		entry.Error = "Game module has not finished loading: " .. path
		self:Refresh()
	end))
end

function AccountStateReader:_dependency(name)
	local entry = self.Dependencies[name]
	return entry and entry.Status == "READY" and entry.Value or nil
end

-- The public RenderGifts callback supplies identity before PhysicalItem stores
-- only an ID-named BasePart. Observe that event; never inspect private closures.
function AccountStateReader:_acceptNativeGiftFacts(payload)
	local state = self.NativeGiftFacts
	if self.Destroyed or not state or not state.Available then return end
	local function reject(reason)
		state.Available, state.Reason = false, reason
		self:_queueRefresh()
	end
	if type(payload) ~= "table" then reject("Malformed native RenderGifts payload; ordinary identity blocked") return end
	local updates = {}
	for id, record in pairs(payload) do
		if type(id) ~= "string" or id == "" or type(record) ~= "table" or type(record.Name) ~= "string" or record.Name == ""
			or typeof(record.Position) ~= "Vector3" then
			reject("Malformed native RenderGifts identity; ordinary identity blocked") return
		end
		local position = record.Position
		for _, axis in ipairs({ position.X, position.Y, position.Z }) do
			if type(axis) ~= "number" or axis ~= axis or math.abs(axis) == math.huge then
				reject("Nonfinite native RenderGifts position; ordinary identity blocked") return
			end
		end
		local previous = state.Records[id]
		if previous and (previous.Name ~= record.Name or previous.Position.X ~= position.X
			or previous.Position.Y ~= position.Y or previous.Position.Z ~= position.Z) then
			reject("Conflicting native gift ID identity; ordinary identity blocked") return
		end
		if not previous then updates[id] = { Name = record.Name, Position = position } end
	end
	state.Revision += 1
	for id, record in pairs(updates) do
		record.Revision = state.Revision
		state.Records[id] = record
	end
	self:_queueRefresh()
end

function AccountStateReader:_bindNativeGiftObserver()
	local state = self.NativeGiftFacts
	if self.Destroyed or not self.Config.ACCOUNT_SETTINGS.ENABLE_ACCOUNT_READER
		or not self.Config.MYSTERY_BOX_SETTINGS.AUTO_OPEN_MYSTERY_BOXES or self.NativeGiftObserverAttempted then return end
	local remote = self:_dependency("Remote")
	if not remote then return end -- The normal dependency loader will bind once ready.
	self.NativeGiftObserverAttempted = true
	local epochOK, epoch = pcall(function() return game:GetService("HttpService"):GenerateGUID(false) end)
	if not epochOK or type(epoch) ~= "string" or epoch == "" then state.Reason = "Unique reader gift identity epoch unavailable" return end
	state.Epoch = epoch
	if type(remote.Event) ~= "function" then state.Reason = "Native RenderGifts event unavailable" return end
	local eventOK, signal = pcall(remote.Event, "RenderGifts") -- Native interface uses dot syntax.
	if not eventOK or not signal then state.Reason = "Native RenderGifts signal unavailable" return end
	local connected, connection = pcall(function()
		return signal:Connect(function(payload) self:_acceptNativeGiftFacts(payload) end)
	end)
	if not connected or not connection then state.Reason = "Native RenderGifts observer connection unavailable" return end
	self.NativeGiftConnection = connection
	table.insert(self.Connections, connection)
	state.Available, state.Reason = true, nil
end

function AccountStateReader:GetNativeGiftFacts()
	self:_bindNativeGiftObserver()
	local state, records = self.NativeGiftFacts, {}
	for id, record in pairs(state.Records) do
		records[id] = table.freeze({ Name = record.Name, Position = record.Position, Revision = record.Revision })
	end
	return table.freeze({ Available = not self.Destroyed and state.Available, Epoch = state.Epoch,
		Revision = state.Revision, Records = table.freeze(records), Reason = self.Destroyed and "Reader destroyed" or state.Reason })
end

function AccountStateReader:_stat(method, raw, diagnostics)
	local stats = self:_dependency("StatsUtil")
	if not stats then return nil end
	if type(stats[method]) ~= "function" then
		table.insert(diagnostics, "StatsUtil is missing method " .. method)
		return nil
	end
	local ok, result = pcall(stats[method], stats, raw)
	if not ok then
		table.insert(diagnostics, method .. " failed: " .. tostring(result))
		return nil
	end
	return number(result)
end

function AccountStateReader:_catalog(snapshot)
	local result = { Worlds = {}, Islands = {}, Upgrades = {}, Mastery = {} }
	local worlds = self:_dependency("Worlds")
	local sceneWorlds = workspace:FindFirstChild("Worlds")
	local gates = {}
	for _, gate in ipairs(CollectionService:GetTagged("WorldGate")) do
		local destination = gate:GetAttribute("World")
		if type(destination) == "string" and gate:IsDescendantOf(workspace) then
			local node, area, origin = gate, nil, nil
			while node and node ~= workspace do
				if node.Parent and node.Parent.Name == "Islands" then area = node.Name end
				if node.Parent == sceneWorlds then origin = node.Name end
				node = node.Parent
			end
			if gates[destination] then gates[destination].Ambiguous = true
			else
				local activation = gate:FindFirstChild("Activation")
				local root = activation and activation:FindFirstChild("Root")
				gates[destination] = { RequiredIsland = area, OriginWorld = origin, Path = gate:GetFullName(),
					ActivationObserved = root ~= nil and root:IsA("BasePart") }
			end
		end
	end
	if type(worlds) == "table" and sceneWorlds then
		for name, definition in pairs(worlds) do
			-- A retained seasonal definition is not proof that its event is active.
			if type(definition) == "table" and not definition.Event and not definition.Removed and sceneWorlds:FindFirstChild(name) then
				local gate = gates[name]
				local fastTravel = sceneWorlds[name]:FindFirstChild("FastTravel")
				local worldSpawn = fastTravel and fastTravel:FindFirstChild("Spawn")
				table.insert(result.Worlds, {
					Name = name, Order = definition.Order or 999,
					Cost = copy(definition.UnlockCost), Gate = gate,
					Unlocked = snapshot.UnlockedWorlds and snapshot.UnlockedWorlds[name] ~= nil,
					Selected = allowed(self.Config.BRAIN_SETTINGS.SELECTED_WORLDS, name),
					WorldTravelPath = name ~= "Seven Seas" and worldSpawn and worldSpawn:IsA("BasePart") and worldSpawn:GetFullName() or nil,
				})
				local islandRoot = sceneWorlds[name]:FindFirstChild("Islands")
				for _, island in ipairs(definition.Islands or {}) do
					local instance = islandRoot and islandRoot:FindFirstChild(island.Name)
					if instance then
						local islandModel = instance:FindFirstChild("Island")
						local portal = islandModel and islandModel:FindFirstChild("Portal")
						local spawn = portal and portal:FindFirstChild("Spawn")
						local character = self.Player and self.Player.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						local facilities = {}
						if self.Config.WORLD_SETTINGS.ENABLE_WORLD_PROGRESSION and islandModel then
							for _, kind in ipairs({ "Eggs", "Chests", "Mastery" }) do
								local object = islandModel:FindFirstChild(kind)
								if object then facilities[kind] = { Path = object:GetFullName(), SceneChildren = #object:GetChildren(),
									Evidence = "Scene container/model only; native feature execution deferred" } end
							end
							local station = islandModel:FindFirstChild("Sell")
							local stationRoot = station and station:FindFirstChild("Root")
							if stationRoot and stationRoot:IsA("BasePart") then facilities.Sell = { Path = station:GetFullName(),
								Multiplier = station:GetAttribute("Multiplier") or 1, Currency = station:GetAttribute("Currency") or "Coins",
								Evidence = "Native HUD.findBestSell / Activation attributes; no selling enabled" } end
						end
						table.insert(result.Islands, {
							Name = island.Name, World = name,
							Height = instance:GetAttribute("Height") or island.Height,
							Unlocked = snapshot.UnlockedIslands and snapshot.UnlockedIslands[island.Name] ~= nil,
							TravelPath = "Workspace.Worlds." .. name .. ".Islands." .. island.Name .. ".Island.Portal.Spawn", -- native WorldMap/WorldUtil supports server-only destinations
							DestinationPartObserved = spawn ~= nil and spawn:IsA("BasePart"),
							Reached = root and spawn and spawn:IsA("BasePart") and (root.Position - spawn.Position).Magnitude <= self.Config.ISLAND_SETTINGS.ARRIVAL_DISTANCE_STUDS or nil,
							Facilities = facilities,
						})
					end
				end
			end
		end
	end
	table.sort(result.Worlds, function(a, b) return a.Order < b.Order end)
	table.sort(result.Islands, function(a, b)
		if a.World == b.World then return (a.Height or math.huge) < (b.Height or math.huge) end
		return a.World < b.World
	end)
	for _, kind in ipairs({ "Gum", "Flavors" }) do
		local definitions = self:_dependency(kind)
		if type(definitions) == "table" then
			for name, definition in pairs(definitions) do
				if type(definition) == "table" and type(definition.Cost) == "table"
					and definition.Cost.Type == "Currency" and allowed(self.Config.BRAIN_SETTINGS.SELECTED_UPGRADES, name) then
					local accessKnown = definition.Area == nil or (snapshot.UnlockedWorlds ~= nil and snapshot.UnlockedIslands ~= nil)
					local accessible = definition.Area == nil or (accessKnown and (snapshot.UnlockedWorlds[definition.Area] ~= nil
						or snapshot.UnlockedIslands[definition.Area] ~= nil))
					local owned = kind == "Gum" and snapshot.Upgrades.Gum or snapshot.Upgrades.Flavors
					table.insert(result.Upgrades, {
						Name = name, Kind = kind, Cost = copy(definition.Cost), Area = definition.Area,
						BaseStat = number(kind == "Gum" and definition.Storage or definition.Bubbles),
						Accessible = accessible == true, AccessKnown = accessKnown,
						Owned = owned and owned[name] ~= nil, OwnershipKnown = owned ~= nil,
					})
				end
			end
		end
	end
	local mastery = self:_dependency("Mastery")
	if type(mastery) == "table" then
		for _, branch in ipairs(self.Config.BRAIN_SETTINGS.MASTERY_PRIORITIES) do
			local definition = mastery[branch]
			local current = snapshot.Upgrades.MasteryLevels and number(snapshot.Upgrades.MasteryLevels[branch])
			-- Never infer a missing Mastery level as level zero.
			if type(definition) == "table" and type(definition.Levels) == "table" then
				local maximum = 0
				for level in pairs(definition.Levels) do if type(level) == "number" then maximum = math.max(maximum, level) end end
				local nextLevel = current and definition.Levels[current + 1]
				table.insert(result.Mastery, {
					Name = branch, Current = current, Maximum = maximum,
					NextCost = nextLevel and copy(nextLevel.Cost),
					NextUpgrades = nextLevel and copy(nextLevel.Upgrades),
				})
			end
		end
	end
	return result
end

function AccountStateReader:Read()
	local diagnostics = {}
	for name, entry in pairs(self.Dependencies) do
		if entry.Status ~= "READY" then table.insert(diagnostics, name .. ": " .. (entry.Error or entry.Status)) end
	end
	local snapshot = {
		Ready = false, Status = "WAITING_FOR_ACCOUNT", Diagnostics = diagnostics,
		Revision = self.Revision + 1, ReadAt = os.clock(),
		Identity = self.Player and { UserId = self.Player.UserId, AccountAge = self.Player.AccountAge } or {},
		Balances = {}, Bubble = {}, Inventory = {}, Upgrades = {}, UnavailableFields = {}, Dependencies = {},
	}
	for name, entry in pairs(self.Dependencies) do
		snapshot.Dependencies[name] = { Status = entry.Status, Path = entry.Path, Error = entry.Error }
	end
	local settings = self.Config.ACCOUNT_SETTINGS
	if not settings.ENABLE_ACCOUNT_READER then
		snapshot.Status = "READER_DISABLED"
		table.insert(diagnostics, "Account reading is disabled in OCConfig.")
	else
		local service = self:_dependency("LocalData")
		if service and type(service.IsReady) == "function" and type(service.Get) == "function" then
			local readyOK, ready = pcall(service.IsReady, service)
			local dataOK, raw = pcall(service.Get, service)
			if readyOK and ready and dataOK and type(raw) == "table" then
				snapshot.Ready = true
				snapshot.Status = "READY"
				snapshot.Source = "ReplicatedStorage.Client.Framework.Services.LocalData:Get()"
				snapshot.TaskRequirements = {}
				for _, quest in pairs(type(raw.Quests) == "table" and raw.Quests or {}) do
					if type(quest) ~= "table" or type(quest.Id) ~= "string" then continue end
					for index in pairs(type(quest.Tasks) == "table" and quest.Tasks or {}) do
						local requirement = self:GetTaskRequirement(quest.Id, index, raw)
						if requirement then table.insert(snapshot.TaskRequirements, requirement) end
					end
				end
				for _, currency in ipairs(settings.SELECTED_CURRENCIES) do
					snapshot.Balances[currency] = number(raw[currency])
				end
				for currency in pairs(self.DiscoveredCurrencies) do snapshot.Balances[currency] = number(raw[currency]) end
				if type(raw.Bubble) == "table" then
					snapshot.Bubble.Amount = number(raw.Bubble.Amount)
					snapshot.Bubble.Gum = raw.Bubble.Gum
					snapshot.Bubble.Flavor = raw.Bubble.Flavor
				end
				snapshot.Bubble.Capacity = self:_stat("GetBubbleStorage", raw, diagnostics)
				snapshot.Bubble.PowerPerBlow = self:_stat("GetBubblePower", raw, diagnostics)
				local gum, flavors = self:_dependency("Gum"), self:_dependency("Flavors")
				local gumDefinition = gum and gum[snapshot.Bubble.Gum]
				local flavorDefinition = flavors and flavors[snapshot.Bubble.Flavor]
				snapshot.Bubble.BaseCapacity = gumDefinition and number(gumDefinition.Storage)
				snapshot.Bubble.BaseOutput = flavorDefinition and number(flavorDefinition.Bubbles)
				if settings.READ_PET_INVENTORY then
					snapshot.Inventory.Pets = type(raw.Pets) == "table" and copy(raw.Pets) or nil
					snapshot.Inventory.Teams = type(raw.Teams) == "table" and copy(raw.Teams) or nil
					snapshot.Inventory.TeamEquipped = raw.TeamEquipped
					local team = snapshot.Inventory.Teams and snapshot.Inventory.Teams[raw.TeamEquipped]
					snapshot.Inventory.EquippedIds = team and type(team.Pets) == "table" and copy(team.Pets) or nil
					snapshot.Inventory.EquippedPets = {}
					snapshot.Inventory.UnresolvedEquippedIds = {}
					if snapshot.Inventory.Pets and snapshot.Inventory.EquippedIds then
						local byId = {}
						for _, pet in pairs(snapshot.Inventory.Pets) do
							if type(pet) == "table" and type(pet.Id) == "string" then byId[pet.Id] = pet end
						end
						for _, id in ipairs(snapshot.Inventory.EquippedIds) do
							if byId[id] then table.insert(snapshot.Inventory.EquippedPets, byId[id])
							else table.insert(snapshot.Inventory.UnresolvedEquippedIds, id) end
						end
					end
					snapshot.Inventory.MaxEquipped = self:_stat("GetMaxPetsEquipped", raw, diagnostics)
					snapshot.Inventory.StorageCapacity = self:_stat("GetMaxPetStorage", raw, diagnostics)
					snapshot.Inventory.StorageUsed = self:_stat("GetUsedPetStorage", raw, diagnostics)
				end
				if settings.READ_ITEM_INVENTORY then
					snapshot.Inventory.Powerups = type(raw.Powerups) == "table" and copy(raw.Powerups) or nil
					snapshot.Inventory.Potions = type(raw.Potions) == "table" and copy(raw.Potions) or nil
				end
				if settings.READ_UPGRADES then
					snapshot.Upgrades.Gum = type(raw.Gum) == "table" and copy(raw.Gum) or nil
					snapshot.Upgrades.Flavors = type(raw.Flavors) == "table" and copy(raw.Flavors) or nil
				end
				if settings.READ_MASTERY then
					snapshot.Upgrades.MasteryLevels = type(raw.MasteryLevels) == "table" and copy(raw.MasteryLevels) or nil
					snapshot.Upgrades.MasteryUpgrades = type(raw.MasteryUpgrades) == "table" and copy(raw.MasteryUpgrades) or nil
				end
				if settings.READ_UNLOCKS then
					snapshot.UnlockedIslands = type(raw.AreasUnlocked) == "table" and copy(raw.AreasUnlocked) or nil
					snapshot.UnlockedWorlds = type(raw.WorldsUnlocked) == "table" and copy(raw.WorldsUnlocked) or nil
				end
			elseif type(service.DidLoadFail) == "function" then
				local ok, failed = pcall(service.DidLoadFail, service)
				if ok and failed then snapshot.Status = "ACCOUNT_LOAD_FAILED" end
			end
			if not readyOK then table.insert(diagnostics, "LocalData:IsReady failed: " .. tostring(ready)) end
			if not dataOK then table.insert(diagnostics, "LocalData:Get failed: " .. tostring(raw)) end
		end
		if not snapshot.Ready and self.StartedAt and os.clock() - self.StartedAt >= settings.ACCOUNT_LOAD_TIMEOUT_SECONDS then
			if snapshot.Status == "WAITING_FOR_ACCOUNT" then snapshot.Status = "ACCOUNT_DATA_UNAVAILABLE" end
			table.insert(diagnostics, "No ready player profile was received from LocalData. Check its module status and whether your client received PlayerDataLoaded. No statistics have been substituted.")
		end
	end
	if snapshot.Ready then
		for name, value in pairs({ Coins = not table.find(settings.SELECTED_CURRENCIES, "Coins") or snapshot.Balances.Coins ~= nil,
			Gems = not table.find(settings.SELECTED_CURRENCIES, "Gems") or snapshot.Balances.Gems ~= nil,
			Bubbles = snapshot.Bubble.Amount ~= nil, Capacity = snapshot.Bubble.Capacity ~= nil,
			PetInventory = not settings.READ_PET_INVENTORY or snapshot.Inventory.Pets ~= nil,
			EquippedPets = not settings.READ_PET_INVENTORY or snapshot.Inventory.EquippedIds ~= nil,
			Powerups = not settings.READ_ITEM_INVENTORY or snapshot.Inventory.Powerups ~= nil,
			Potions = not settings.READ_ITEM_INVENTORY or snapshot.Inventory.Potions ~= nil,
			Mastery = not settings.READ_MASTERY or snapshot.Upgrades.MasteryLevels ~= nil,
			MasteryUpgrades = not settings.READ_MASTERY or snapshot.Upgrades.MasteryUpgrades ~= nil,
			Upgrades = not settings.READ_UPGRADES or (snapshot.Upgrades.Gum ~= nil and snapshot.Upgrades.Flavors ~= nil),
			Islands = not settings.READ_UNLOCKS or snapshot.UnlockedIslands ~= nil,
			Worlds = not settings.READ_UNLOCKS or snapshot.UnlockedWorlds ~= nil }) do
			if not value then table.insert(snapshot.UnavailableFields, name) end
		end
		if #snapshot.UnavailableFields > 0 then snapshot.Status = "PARTIAL_ACCOUNT_DATA" end
	end
	snapshot.AvailableProgression = settings.ENABLE_ACCOUNT_READER and self:_catalog(snapshot) or {}
	if self.Config.WORLD_SETTINGS.ENABLE_WORLD_PROGRESSION then
		snapshot.ProgressionGraph = ProgressionGraph.Build(self.Config, snapshot, self:_dependency("Worlds"), snapshot.AvailableProgression)
	end
	table.sort(diagnostics)
	return snapshot
end

function AccountStateReader:_queueRefresh()
	if self.Destroyed or self.RefreshThread then return end
	local interval = self.Config.ACCOUNT_SETTINGS.MINIMUM_SNAPSHOT_INTERVAL_SECONDS
	local waitSeconds = math.max(0, interval - (os.clock() - (self.LastRefreshAt or -math.huge)))
	self.RefreshThread = task.delay(waitSeconds, function()
		self.RefreshThread = nil
		if not self.Destroyed then self:Refresh() end
	end)
end

function AccountStateReader:Refresh()
	if self.Destroyed then return end
	self.LastRefreshAt = os.clock()
	local ok, result = xpcall(function() return self:Read() end, debug.traceback)
	if not ok then
		result = { Ready = false, Status = "READER_ERROR", Revision = self.Revision + 1,
			Diagnostics = { tostring(result) }, UnavailableFields = {}, AvailableProgression = {} }
	end
	self.Revision = result.Revision
	self.Snapshot = result
	self.Changed:Fire(result)
end

function AccountStateReader:GetSnapshot()
	return copy(self.Snapshot)
end

-- Internal consumers treat this native profile as read-only. No writes or synthetic values.
function AccountStateReader:GetLiveProfile()
	if self.Destroyed or not self.Config.ACCOUNT_SETTINGS.ENABLE_ACCOUNT_READER then return nil end
	local service = self:_dependency("LocalData")
	if not service or type(service.Get) ~= "function" or type(service.IsReady) ~= "function" then return nil end
	local ok, ready = pcall(service.IsReady, service)
	if not ok or not ready then return nil end
	local received, profile = pcall(service.Get, service)
	return received and type(profile) == "table" and profile or nil
end

function AccountStateReader:RegisterCurrency(name)
	if type(name) == "string" then self.DiscoveredCurrencies[name] = true end
end

function AccountStateReader:ReadBalances()
	local raw, result = self:GetLiveProfile(), {}
	if not raw then return result end
	for _, name in ipairs(self.Config.ACCOUNT_SETTINGS.SELECTED_CURRENCIES) do result[name] = number(raw[name]) end
	for name in pairs(self.DiscoveredCurrencies) do result[name] = number(raw[name]) end
	return result
end

function AccountStateReader:Start()
	if self.StartedAt or self.Destroyed then return end
	self.StartedAt = os.clock()
	if self.Config.ACCOUNT_SETTINGS.ENABLE_ACCOUNT_READER then
		if RunService:IsClient() then self:_load("LocalData", "Client.Framework.Services.LocalData")
		else self.Dependencies.LocalData = { Status = "ERROR", Path = "Client.Framework.Services.LocalData", Error = "Client runtime is required" } end
		for name, path in pairs({ Worlds = "Shared.Data.Worlds", Gum = "Shared.Data.Gum",
			Flavors = "Shared.Data.Flavors", Mastery = "Shared.Data.Mastery", StatsUtil = "Shared.Utils.Stats.StatsUtil" }) do
			self:_load(name, path)
		end
		local pets = self.Config.PET_SETTINGS
		if self.Config.EGG_TRAVEL_SETTINGS.ENABLE_SELECTED_EGG_TRAVEL or pets.ENABLE_PET_INTELLIGENCE then
			self:_load("ProximityPrompt", "Client.Gui.ProximityPrompt")
			self:_load("Chunker", "Shared.Utils.Chunker")
		end
		local localFeatures = self.Config.EGG_TRAVEL_SETTINGS.ENABLE_SELECTED_EGG_TRAVEL
			or self.Config.PLAYTIME_SETTINGS.AUTO_CLAIM_PLAYTIME
			or self.Config.MYSTERY_BOX_SETTINGS.AUTO_OPEN_MYSTERY_BOXES
			or self.Config.ANTIAFK_SETTINGS.ENABLE_ANTI_AFK
		if self.Config.EGG_TRAVEL_SETTINGS.ENABLE_SELECTED_EGG_TRAVEL and not pets.ENABLE_PET_INTELLIGENCE then
			self:_load("Eggs", "Shared.Data.Eggs")
			self:_load("WorldUtil", "Shared.Utils.WorldUtil")
		end
		if localFeatures then
			self:_load("Time", "Shared.Framework.Utilities.Math.Time")
			self:_load("HatchPresentation", "Client.Effects.HatchEgg")
		end
		if self.Config.PLAYTIME_SETTINGS.AUTO_CLAIM_PLAYTIME then self:_load("Playtime", "Shared.Data.Playtime") end
		if self.Config.ANTIAFK_SETTINGS.ENABLE_ANTI_AFK then self:_load("AFKReport", "Client.AFKReport") end
		if self.Config.MYSTERY_BOX_SETTINGS.AUTO_OPEN_MYSTERY_BOXES then
			self:_load("Powerups", "Shared.Data.Powerups")
			self:_load("Constants", "Shared.Constants")
			self:_load("ItemUtil", "Shared.Utils.Stats.ItemUtil")
			self:_load("PhysicalGift", "Client.Effects.PhysicalItem.Gift")
		end
		if pets.ENABLE_PET_INTELLIGENCE then
			self:_load("Eggs", "Shared.Data.Eggs") self:_load("Pets", "Shared.Data.Pets")
			self:_load("PetUtil", "Shared.Utils.Stats.PetUtil")
			self:_load("GetEggPool", "Shared.Utils.GetEggPool", "function")
			self:_load("WorldUtil", "Shared.Utils.WorldUtil")
			if pets.AUTO_HATCH and not localFeatures then
				self:_load("HatchPresentation", "Client.Effects.HatchEgg")
				self:_load("Time", "Shared.Framework.Utilities.Math.Time")
			end
		end
		if localFeatures or self.Config.FARMING_SETTINGS.AUTO_RESOURCE_FARM or self.Config.WORLD_SETTINGS.ENABLE_WORLD_PROGRESSION
			or (pets.ENABLE_PET_INTELLIGENCE and (pets.AUTO_HATCH or pets.AUTO_EQUIP)) then
			if self.Config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS and self.Config.PICKUP_SETTINGS.ENABLE_CONTINUOUS_SCANNING
				and self.Config.PICKUP_SETTINGS.ENABLE_NATIVE_REGISTRY_DISCOVERY then
				self:_load("Tutorial", "Client.Tutorial")
				if not self.Dependencies.Chunker then self:_load("Chunker", "Shared.Utils.Chunker") end
			end
			self:_load("GetPickupZones", "Shared.Utils.GetPickupZones", "function")
			self:_load("Remote", "Shared.Framework.Network.Remote")
			if self.Config.WORLD_SETTINGS.ENABLE_WORLD_PROGRESSION and not pets.ENABLE_PET_INTELLIGENCE then self:_load("WorldUtil", "Shared.Utils.WorldUtil") end
			self:_load("QuestUtil", "Shared.Utils.Stats.QuestUtil")
			self:_load("GuiFrame", "Client.Gui.GuiFrame")
			self:_load("PhysicalItem", "Client.Effects.PhysicalItem")
			self:_load("FishingPlayerRods", "Client.Gui.Frames.Fishing.FishingPlayerRods")
			self:_load("IsTradingPlaza", "Shared.Utils.IsTradingPlaza", "function")
		end
	end
	self:Refresh()
	if not self.Config.ACCOUNT_SETTINGS.ENABLE_ACCOUNT_READER then return end
	table.insert(self.Threads, task.spawn(function()
		while not self.Destroyed do
			task.wait(self.Config.ACCOUNT_SETTINGS.SNAPSHOT_REFRESH_SECONDS)
			if not self.Destroyed then self:Refresh() end
		end
	end))
end

function AccountStateReader:Destroy()
	if self.Destroyed then return end
	self.Destroyed = true
	self.NativeGiftFacts.Available = false
	if self.RefreshThread then pcall(task.cancel, self.RefreshThread) end
	for _, connection in ipairs(self.Connections) do connection:Disconnect() end
	for _, thread in ipairs(self.Threads) do pcall(task.cancel, thread) end
	self.Changed:Destroy()
end

return AccountStateReader

end

-- src/OCFoundation/AntiAFKManager.luau
factories["AntiAFKManager"] = function()
--!nonstrict
-- Periodic intent only. The existing scheduler and mechanics adapter own all input.
local AntiAFKManager = {}
AntiAFKManager.__index = AntiAFKManager

function AntiAFKManager.new(controller)
	return setmetatable({ Controller = controller, SentPulses = 0, AttemptedPulses = 0,
		Running = false, Destroyed = false, Capability = { Available = false, Status = "UNASSESSED" } }, AntiAFKManager)
end

function AntiAFKManager:_settings()
	return self.Controller.Config.ANTIAFK_SETTINGS or {}
end

function AntiAFKManager:_mechanics()
	return self.Controller.Farming and self.Controller.Farming.Mechanics
end

function AntiAFKManager:_fault(reason)
	self.Fault = self.Fault or tostring(reason)
	if not self.FaultReported then
		self.FaultReported = true
		if self.Controller.Log then self.Controller:Log("ANTI_AFK][ERROR", self.Fault, true) end
	end
end

function AntiAFKManager:_release()
	local mechanics = self:_mechanics()
	if not mechanics or type(mechanics.ReleaseAntiAFKInput) ~= "function" then return end
	local ok, released, reason = pcall(mechanics.ReleaseAntiAFKInput, mechanics)
	if not ok or released == false then
		self:_fault("Input cleanup failed: " .. tostring(ok and reason or released))
	end
end

function AntiAFKManager:Observe()
	if self.Destroyed then return end
	local running = self.Controller.State == "RUNNING"
	if not running then
		if self.Running or self.Executing then self:Halt("Controller is not running") end
		return
	end
	self.Running = true
	local settings = self:_settings()
	if not settings.ENABLE_ANTI_AFK then self.NextDueAt = nil return end
	if not self.NextDueAt then self.NextDueAt = os.clock() + settings.INTERVAL_SECONDS end
end

function AntiAFKManager:_guard()
	local mechanics = self:_mechanics()
	if not mechanics or type(mechanics.AntiAFKGuard) ~= "function" then
		self:_fault("The anti-AFK interaction guard is unavailable")
		return false, self.Fault
	end
	local ok, allowed, reason = pcall(mechanics.AntiAFKGuard, mechanics, self)
	if not ok then self:_fault("Anti-AFK guard failed: " .. tostring(allowed)) return false, self.Fault end
	return allowed == true, reason or (allowed ~= true and "Input is suppressed" or nil)
end

function AntiAFKManager:Select()
	self:Observe()
	local settings = self:_settings()
	if self.Destroyed or not settings.ENABLE_ANTI_AFK or not self.Running or self.Fault then return false end
	if not self.NextDueAt or os.clock() < self.NextDueAt then return false end
	if settings.METHOD ~= "VIRTUAL_INPUT_SCROLL_LOCK" then self:_fault("Unsupported anti-AFK input method") return false end
	local active = self.Controller.Scheduler and self.Controller.Scheduler.Active
	if self.Executing or active and (not active.Definition or active.Definition.Owner ~= "ANTI_AFK") then
		self.LastSuppression = "Another scheduler operation owns the foreground"
		return false
	end
	local mechanics = self:_mechanics()
	if not mechanics or type(mechanics.AntiAFKCapability) ~= "function" or type(mechanics.AntiAFKPulse) ~= "function"
		or type(mechanics.ReleaseAntiAFKInput) ~= "function" then
		self:_fault("The anti-AFK runtime adapter is unavailable") return false
	end
	local ok, capability = pcall(mechanics.AntiAFKCapability, mechanics, settings.METHOD)
	if not ok or type(capability) ~= "table" or capability.Available ~= true then
		self.Capability = type(capability) == "table" and capability or { Available = false, Status = "UNAVAILABLE" }
		self:_fault("Anti-AFK capability unavailable: " .. tostring(ok and self.Capability.Reason or capability))
		return false
	end
	self.Capability = capability
	local allowed, reason = self:_guard()
	if not allowed then self.LastSuppression = reason return false end
	self.LastSuppression = nil
	return true, { Kind = "ANTI_AFK", Method = settings.METHOD }
end

function AntiAFKManager:Definition(_, generation)
	local controller = self.Controller
	return { Id = "OC_GAMEPLAY", Owner = "ANTI_AFK", Generation = generation, Priority = 60, TimeoutSeconds = 2,
		CanRun = function() return not self.Destroyed and controller.State == "RUNNING" and generation == controller.Generation end,
		Execute = function(token)
			if self.Destroyed or token:CheckCancelled() or controller.State ~= "RUNNING" or generation ~= controller.Generation then
				return { Status = "CANCELLED", InputSent = false }
			end
			local owns = self:Select()
			if not owns then return { Status = "SUPPRESSED", InputSent = false, Reason = self.LastSuppression or self.Fault } end
			self.Executing = true
			-- Record before the risky adapter call. A failure never triggers a rapid retry.
			self.NextDueAt = os.clock() + self:_settings().INTERVAL_SECONDS
			self.AttemptedPulses += 1
			local mechanics = self:_mechanics()
			local ok, sent, reason = pcall(mechanics.AntiAFKPulse, mechanics, self, token)
			self:_release() -- Always finalize the adapter's tracked possible key-down, including call failures.
			self.Executing = false
			local suppressed = ok and sent ~= true and type(reason) == "string" and reason:sub(1, 11) == "SUPPRESSED:"
			local result = { Status = ok and sent == true and "INPUT_SENT_UNVERIFIED" or suppressed and "SUPPRESSED" or "INPUT_FAILED",
				InputSent = ok and sent == true, Method = self:_settings().METHOD, Reason = ok and reason or sent,
				CancelledAfterDispatch = token:CheckCancelled() or controller.State ~= "RUNNING" or generation ~= controller.Generation,
				NativeActivity = "INPUT_HANDLER_INSPECTED_RUNTIME_PENDING", IdlePrevention = "OWNER_LONG_DURATION_PENDING" }
			if result.InputSent then self.SentPulses += 1 self.LastPulseAt = os.clock()
			elseif suppressed then
				self.LastSuppression = reason
				-- Account/Brain planning performs this retry; there is no independent timer.
				if not result.CancelledAfterDispatch then self.NextDueAt = os.clock() + 5 end
			else self:_fault("Anti-AFK input failed: " .. tostring(result.Reason)) end
			self.LastResult = result
			return result
		end,
		IsComplete = function(result) return type(result) == "table" end }
end

function AntiAFKManager:Completed(_, result)
	if type(result) == "table" then self.LastResult = result end
	if type(result) == "table" and result.InputSent and self.LastLoggedPulseAt ~= self.LastPulseAt then
		self.LastLoggedPulseAt = self.LastPulseAt
		if self.Controller.Log then self.Controller:Log("ANTI_AFK", "INPUT_SENT_UNVERIFIED | method=" .. tostring(self:_settings().METHOD)
			.. "; pulses=" .. tostring(self.SentPulses) .. "; native activity handler inspected; runtime effect/idle prevention remain owner-tested") end
	end
	self:Observe()
end

function AntiAFKManager:Resume()
	if self.Destroyed then return false end
	self.Running = self.Controller.State == "RUNNING"
	self.NextDueAt = self.Running and self:_settings().ENABLE_ANTI_AFK
		and os.clock() + self:_settings().INTERVAL_SECONDS or nil
	self.LastSuppression = nil
	return true
end

function AntiAFKManager:Halt(reason)
	self.Running = false
	self.NextDueAt = nil -- Resume starts a fresh interval; no immediate duplicate pulse.
	self.LastSuppression = reason or "Stopped"
	self:_release() -- Synchronous, before scheduler destruction can discard a coroutine.
end

function AntiAFKManager:Destroy()
	if self.Destroyed then return end
	self:Halt("Destroyed")
	self.Destroyed = true
end

function AntiAFKManager:GetStatus()
	return { Enabled = self:_settings().ENABLE_ANTI_AFK == true, Method = self:_settings().METHOD,
		Capability = self.Capability, NextDueAt = self.NextDueAt, LastPulseAt = self.LastPulseAt,
		AttemptedPulses = self.AttemptedPulses, SentPulses = self.SentPulses, Pending = self.Executing == true,
		Suppression = self.LastSuppression, Fault = self.Fault, LastResult = self.LastResult,
		NativeActivity = "INPUT_HANDLER_INSPECTED_RUNTIME_PENDING", IdlePrevention = "OWNER_LONG_DURATION_PENDING" }
end

return AntiAFKManager

end

-- src/OCFoundation/ConfigResolver.luau
factories["ConfigResolver"] = function()
--!nonstrict
-- Overrides replace setting values, including entire arrays; the defaults are never mutated.
local ConfigResolver = {}

local function copy(value)
	if type(value) ~= "table" then return value end
	local result = {}
	for key, item in pairs(value) do result[key] = copy(item) end
	return result
end

function ConfigResolver.Resolve(defaults, overrides)
	assert(overrides == nil or type(overrides) == "table", "[OC] Config must be a table")
	local result = copy(defaults)
	for category, values in pairs(overrides or {}) do
		assert(defaults[category] ~= nil, "[OC] Unknown configuration category: " .. tostring(category))
		assert(type(values) == "table", "[OC] " .. category .. " must be a table")
		for key, value in pairs(values) do
			local expected = defaults[category][key]
			local path = category .. "." .. tostring(key)
			assert(expected ~= nil, "[OC] Unknown configuration setting: " .. path)
			assert(type(value) == type(expected), "[OC] " .. path .. " must be a " .. type(expected))
			if type(value) == "table" then
				local count = 0
				for index, item in pairs(value) do
					assert(type(index) == "number" and index >= 1 and index % 1 == 0 and type(item) == "string",
						"[OC] " .. path .. " must be an array of strings")
					count += 1
				end
				for index = 1, count do assert(value[index] ~= nil, "[OC] Sparse array: " .. path) end
			end
			result[category][key] = copy(value)
		end
	end
	assert(result.FARMING_SETTINGS.FARMING_STRATEGY == "EFFICIENCY" or result.FARMING_SETTINGS.FARMING_STRATEGY == "PICKUP_FIRST", "[OC] Unknown FARMING_STRATEGY")
	local preferred = result.ISLAND_SETTINGS.PREFERRED_FARMING_ISLAND
	assert(preferred == "" or preferred == "Zen" or preferred == "The Void", "[OC] PREFERRED_FARMING_ISLAND must be Zen, The Void or empty")
	local pickup = result.PICKUP_SETTINGS
	if pickup.COLLECTION_METHOD == "STATIONARY_EXPERIMENT" then pickup.COLLECTION_METHOD = "STATIONARY" end -- Old Config compatibility.
	assert(pickup.COLLECTION_METHOD == "STATIONARY", "[OC] Only STATIONARY pickup collection is supported")
	pickup.ENABLE_CLUSTER_ROUTING = false -- Legacy overrides cannot reactivate movement collection.
	for key, minimum in pairs({ STATIONARY_REQUEST_COOLDOWN_SECONDS = 0.05, STATIONARY_ID_RETRY_SECONDS = 5,
		STATIONARY_MAXIMUM_ATTEMPTS_PER_ID = 1, STATIONARY_MAXIMUM_BATCH_SIZE = 1, STATIONARY_BATCH_COOLDOWN_SECONDS = 0.2 }) do
		local value = pickup[key]
		assert(value == value and value < math.huge and value >= minimum, "[OC] Invalid PICKUP_SETTINGS." .. key)
	end
	assert(pickup.STATIONARY_MAXIMUM_ATTEMPTS_PER_ID % 1 == 0 and pickup.STATIONARY_MAXIMUM_ATTEMPTS_PER_ID <= 2, "[OC] Stationary attempts per ID must be 1 or 2")
	assert(pickup.STATIONARY_MAXIMUM_BATCH_SIZE % 1 == 0 and pickup.STATIONARY_MAXIMUM_BATCH_SIZE <= 64, "[OC] Stationary batch size must be an integer up to 64")
	return result
end

return ConfigResolver

end

-- src/OCFoundation/EggTravelManager.luau
factories["EggTravelManager"] = function()
--!nonstrict
-- Selected-location ledger and scene observation. Only the existing scheduler
-- executes its task; native transport/direct transforms stay in GameMechanics.
local EggTravelManager = {}
EggTravelManager.__index = EggTravelManager

local function finite(n) return type(n) == "number" and n == n and math.abs(n) < math.huge end
local function vector(v) return v ~= nil and finite(v.X) and finite(v.Y) and finite(v.Z) end
local function live(part)
	return part ~= nil and part.Parent ~= nil and part:IsA("BasePart") and part:IsDescendantOf(workspace)
end
local function child(parent, name) return parent and parent:FindFirstChild(name) end
local function selected(config, intent)
	local names = config.HATCH_SETTINGS and config.HATCH_SETTINGS.SELECTED_EGGS
	local mode = config.HATCH_SETTINGS and config.HATCH_SETTINGS.EGG_SELECTION_MODE or "MANUAL"
	if intent then
		local diagnostic = (config.EGG_TRAVEL_SETTINGS.MODE or "NORMAL") == "TRAVEL_ONLY"
		local contract = diagnostic and intent.Kind == "EGG_TRAVEL" and intent.Scope == "TRAVEL_ONLY"
			and intent.DecisionSource == "BRAIN_TRAVEL_DIAGNOSTIC"
			or not diagnostic and intent.Kind == "HATCH" and intent.DecisionSource == "BRAIN" and intent.Scope ~= "TRAVEL_ONLY"
		if not contract or intent.SelectionMode ~= mode
			or type(intent.EggName) ~= "string" or intent.EggName == "" then return nil, "Fresh Brain hatch destination unavailable or stale" end
		if mode == "MANUAL" and not table.find(names or {}, intent.EggName) then return nil, "Manual egg authorization changed" end
		return intent.EggName
	end
	if (config.EGG_TRAVEL_SETTINGS.MODE or "NORMAL") == "TRAVEL_ONLY" then return nil, "TRAVEL_ONLY requires a read-only Brain destination" end
	if mode == "AUTO" then return nil, "AUTO travel requires an actual useful affordable Brain decision; no random destination" end
	if type(names) ~= "table" or #names ~= 1 or type(names[1]) ~= "string" or names[1] == "" then
		return nil, "Egg travel requires exactly one explicitly selected egg"
	end
	return names[1]
end

function EggTravelManager.new(controller)
	return setmetatable({ Controller = controller, Attempts = {}, Blocked = {}, Sequence = 0 }, EggTravelManager)
end

function EggTravelManager:Settings() return self.Controller.Config.EGG_TRAVEL_SETTINGS end
function EggTravelManager:Report(message, key, force)
	-- Planning may revisit an unchanged preflight blocker every second. Keep a
	-- bounded set of report keys so interleaved messages cannot defeat dedup.
	local now = os.clock()
	self.ReportTimes, self.ReportOrder = self.ReportTimes or {}, self.ReportOrder or {}
	key = key or message
	local previous = self.ReportTimes[key]
	if not force and previous and now - previous < 30 then return false end
	if previous == nil then
		table.insert(self.ReportOrder, key)
		if #self.ReportOrder > 32 then self.ReportTimes[table.remove(self.ReportOrder, 1)] = nil end
	end
	self.ReportTimes[key], self.LastReport = now, message
	if type(self.Controller.Log) == "function" then self.Controller:Log("EGG_TRAVEL", message) end
	return true
end
function EggTravelManager:DiagnosticTrace(event, record, reason)
	if (self:Settings().MODE or "NORMAL") ~= "TRAVEL_ONLY" then return end
	if event == "PREFLIGHT_BLOCKED" then
		self.Reason, self.LastPreflightReason = reason, reason
	elseif event == "TARGET_SELECTED" then
		self.Reason, self.LastPreflightReason = nil, nil
	end
	local intent = self.BrainIntent or {}
	local distance = record and finite(record.Distance) and string.format("%.2f", record.Distance) or "UNKNOWN"
	local name, world = tostring(record and record.EggName or intent.EggName or "UNSELECTED"), tostring(record and record.World or intent.World or "UNKNOWN")
	local island = tostring(record and record.Island or intent.Island or "surface/UNKNOWN")
	local generation = tostring(record and record.Generation or intent.Generation or self.Controller.Generation or "UNKNOWN")
	local revision = tostring(intent.SelectionRevision or self:Settings().SELECTION_REVISION)
	reason = reason or "Observation pending; server acceptance unverified"
	local model = record and record.Model or intent.Model
	local identity = record and record.IdentityId
	if not record then identity = intent.IdentityId end
	if identity == nil and model ~= nil then
		-- Instance tostring/GetFullName do not distinguish duplicate names/paths.
		-- This fallback is a local logging ID only, never target authorization.
		self.DiagnosticModelIds = self.DiagnosticModelIds or setmetatable({}, { __mode = "k" })
		if self.DiagnosticModelIds[model] == nil then
			self.DiagnosticModelSequence = (self.DiagnosticModelSequence or 0) + 1
			self.DiagnosticModelIds[model] = self.DiagnosticModelSequence
		end
		identity = "LOCAL_MODEL_" .. tostring(self.DiagnosticModelIds[model])
	end
	-- Different blocker/candidate messages remain independently throttled. Only
	-- a real non-blocked stage transition permits an immediate blocker recurrence.
	if event ~= "PREFLIGHT_BLOCKED" and event ~= "TRAVEL_BLOCKED" and event ~= self.LastDiagnosticStage then
		self.DiagnosticReportEpoch = (self.DiagnosticReportEpoch or 0) + 1
	end
	self.LastDiagnosticStage = event
	local key = table.concat({ tostring(self.DiagnosticReportEpoch or 0), event, name, world, island, generation, revision, tostring(identity or "UNRESOLVED"), reason }, "|")
	self.DiagnosticEventKeys = self.DiagnosticEventKeys or {}
	if self.DiagnosticEventKeys[event] == key then return end
	self.DiagnosticEventKeys[event] = key
	-- Fresh geometry records do not carry the lease's adapter-attempt ledger.
	local attempted = self.Lease or self.LastResult or record
	local direct = event ~= "PREFLIGHT_BLOCKED" and attempted and attempted.DirectPositionAttempted == true
	local native = event ~= "PREFLIGHT_BLOCKED" and attempted and attempted.NativeTravelAttempted == true
	local evidence = record and (record.LocationOnly and "access=LocalData unlock membership; location=verified native physical original Root; physical radius is diagnostic policy, hatch eligibility separate"
		or "access=LocalData unlock membership + resolved native egg; geometry=actual Root/Prompt; clearance/arrival verified separately")
		or "access/instance/standing geometry=preflight unresolved; no arrival claimed"
	self:Report(string.format("%s | egg=%s; instance=%s | world=%s; island=%s | generation=%s; revision=%s | distance=%s; %s radius=%s | %s | %s | direct attempts=%d; native travel attempts=%d; hatch commands=0; spending=0",
		event, name, tostring(identity or "UNRESOLVED"), world, island, generation, revision, distance, record and record.LocationOnly and "physical policy" or "native", tostring(record and record.Range or "UNKNOWN"), evidence, reason,
		direct and 1 or 0, native and 1 or 0), "DIAGNOSTIC:" .. key)
end
function EggTravelManager:Key()
	local name, reason = selected(self.Controller.Config, self.BrainIntent)
	if not name then return nil, reason end
	local prefix = self.BrainIntent and self.BrainIntent.SelectionMode == "AUTO" and "AUTO:" or ""
	return prefix .. name .. ":" .. tostring((self:Settings() or {}).SELECTION_REVISION or 0), nil, name
end

function EggTravelManager:ReportInstanceDiagnostics(diagnostics, expandedRequested)
	if (self:Settings().MODE or "NORMAL") ~= "TRAVEL_ONLY" then return end
	local knowledge = self.Controller.Knowledge
	local expanded = expandedRequested == true or self.Controller.Config.DIAGNOSTIC_SETTINGS.ENABLE_DEBUG_LOGGING == true
	local diagnosticScope = expanded and "EXPLICIT_EXPANDED" or "UNSELECTED_DIAGNOSTIC_SAMPLE"
	local function position(part)
		return part and vector(part.Position) and string.format("(%.3f,%.3f,%.3f)", part.Position.X, part.Position.Y, part.Position.Z) or "ABSENT/UNKNOWN"
	end
	local names = {} for name in pairs(diagnostics or {}) do table.insert(names, name) end table.sort(names)
	if not expanded then
		local selectedName = self.BrainIntent and self.BrainIntent.EggName
		if not selectedName and self.Controller.Config.HATCH_SETTINGS.EGG_SELECTION_MODE == "MANUAL" then
			selectedName = self.Controller.Config.HATCH_SETTINGS.SELECTED_EGGS[1]
		end
		if selectedName and diagnostics and diagnostics[selectedName] then diagnosticScope = "SELECTED_TARGET" end
		-- A blocked Brain may have no selected target. One clearly labelled sample
		-- exposes the evidence gap without turning a diagnostic name into authority.
		selectedName = selectedName and diagnostics and diagnostics[selectedName] and selectedName or names[1]
		names = selectedName and diagnostics and diagnostics[selectedName] and { selectedName } or {}
	end
	self.InstanceDiagnosticReports = self.InstanceDiagnosticReports or {}
	self.InstanceDiagnosticReportOrder = self.InstanceDiagnosticReportOrder or {}
	for index, name in ipairs(names) do
		if index > 40 then break end
		local observation, lines = diagnostics[name], {}
		local candidates = table.clone(observation.Candidates or {})
		if not expanded then
			table.sort(candidates, function(a, b)
				local function rank(candidate) return candidate.LocationVerified and 3 or candidate.Verified and 2 or candidate.Root and 1 or 0 end
				if rank(a) ~= rank(b) then return rank(a) > rank(b) end
				return tostring(a.IdentityId) < tostring(b.IdentityId)
			end)
		end
		for candidateIndex, candidate in ipairs(candidates) do
			if candidateIndex > (expanded and 20 or 4) then break end
			local model, ancestry, attrs = candidate.Model, {}, {}
			local ancestor = model and model.Parent
			if expanded then
				for _ = 1, 8 do
					if not ancestor or not ancestor.Name then break end
					table.insert(ancestry, ancestor.Name .. "[" .. knowledge:InstanceId(ancestor) .. "]") ancestor = ancestor.Parent
				end
				for _, key in ipairs({ "World", "Island", "Unlocked", "Offset", "Size", "BonusLuck" }) do
					local value = model and model:GetAttribute(key)
					if value ~= nil then table.insert(attrs, key .. "=" .. tostring(value)) end
				end
			end
			local engine = candidate.NativePrompt
			local interface = candidate.Verified and "REGISTERED" or candidate.LocationVerified and "LOCATION_VERIFIED; HATCH_INTERACTION_UNVERIFIED" or "UNVERIFIED/EXCLUDED"
			local raw = self.Controller.Reader:GetLiveProfile()
			local opened = raw and type(raw.EggsOpened) == "table" and raw.EggsOpened[name] ~= nil and model:GetAttribute("Unlocked") == true
			local interaction = opened and "opened Root<=16; global Visible=0; nearest registered check still required"
				or "initial native cached Prompt required; range<=6.5"
			local worldAccess = raw and type(raw.WorldsUnlocked) == "table" and candidate.World and raw.WorldsUnlocked[candidate.World] ~= nil
			local islandAccess = candidate.Island == nil or raw and type(raw.AreasUnlocked) == "table" and raw.AreasUnlocked[candidate.Island] ~= nil
			local promptEligible = engine and engine.Parent == candidate.Prompt and engine.Enabled == true and engine.RequiresLineOfSight == false
				and finite(engine.MaxActivationDistance) and engine.MaxActivationDistance > 0 and candidate.PromptCacheMember == true
			local interfaceEligible = candidate.Verified and worldAccess and islandAccess and (opened or promptEligible)
			if expanded then
				table.insert(lines, string.format("id=%s; path=%s; parents=%s; attrs={%s}; Root=%s; Prompt=%s; world=%s; island=%s; eligibility=%s (%s); cached prompt=%s; prompt enabled=%s; max distance=%s; %s",
					tostring(candidate.IdentityId), tostring(candidate.Path or "UNKNOWN"), table.concat(ancestry, " <- "), table.concat(attrs, ","),
					position(candidate.Root), position(candidate.Prompt), tostring(candidate.World or "UNKNOWN"), tostring(candidate.Island or "surface/UNKNOWN"),
					interface, tostring(candidate.LocationEvidence or candidate.LocationReason or candidate.IdentityEvidence or candidate.Reason), tostring(candidate.PromptCacheMember == true), tostring(engine and engine.Enabled),
					tostring(engine and engine.MaxActivationDistance), interaction .. "; interface/access eligible=" .. tostring(interfaceEligible == true) .. "; actual stable range pending"))
			else
				local parent = model and model.Parent
				local parentLabel = parent and parent.Name and (parent.Name .. "[" .. knowledge:InstanceId(parent) .. "]") or "UNKNOWN"
				local nativeState = candidate.Verified and "VERIFIED" or tostring(candidate.Reason):find("PENDING", 1, true) and "PENDING" or "UNVERIFIED"
				table.insert(lines, string.format("id=%s%s; parent=%s; Root=%s; Prompt=%s; location=%s; registered=%s; access=%s; native=%s",
					tostring(candidate.IdentityId), self.BrainIntent and self.BrainIntent.Model == model and " SELECTED" or "", parentLabel,
					position(candidate.Root), position(candidate.Prompt), tostring(candidate.LocationVerified == true),
					tostring(candidate.Verified == true), tostring(worldAccess and islandAccess or false), nativeState))
			end
		end
		local selectedId = self.BrainIntent and self.BrainIntent.EggName == name and self.BrainIntent.Model and knowledge:InstanceId(self.BrainIntent.Model) or "UNSELECTED"
		local message = string.format("INSTANCE_DIAGNOSTIC_READ_ONLY | scope=%s; egg=%s; selected=%s; matching Models=%d; location verified=%d; registered=%d; shown=%d; omitted=%d | %s\n%s",
			diagnosticScope, name, selectedId, observation.Count or 0, observation.LocationVerifiedCount or observation.LocationCount or 0, observation.VerifiedCount or 0, #lines,
			math.max(0, #candidates - #lines), tostring(observation.Reason), table.concat(lines, "\n"))
		-- Full evidence forms the key: changed membership/ancestry/geometry prints
		-- immediately; unchanged observations remain silent between summaries.
		local previous = self.InstanceDiagnosticReports[name]
		if not previous or previous.Message ~= message then
			if not previous then
				table.insert(self.InstanceDiagnosticReportOrder, name)
				if #self.InstanceDiagnosticReportOrder > 64 then self.InstanceDiagnosticReports[table.remove(self.InstanceDiagnosticReportOrder, 1)] = nil end
			end
			self.InstanceDiagnosticReports[name] = { Message = message, At = os.clock() }
			self:Report(message, "INSTANCES:" .. name, true)
		end
	end
end

function EggTravelManager:RevalidateIntent()
	local intent, c = self.BrainIntent, self.Controller
	if not intent then return true end -- Preserve separately authorized manual travel-only tests.
	if intent.Scope == "TRAVEL_ONLY" then
		local blocker = c.Brain:TravelDiagnosticBlocker()
		if blocker then return false, blocker end
		if not c.Reader.Player or c.Reader.Player.UserId ~= self.BrainUserId then return false, "Travel diagnostic account identity changed" end
		local goalId = c.Plan and c.Plan.Objective and c.Plan.Objective.Id or "TRAVEL_ONLY_DIAGNOSTIC"
		if intent.GoalId ~= goalId then return false, "Acquired diagnostic Brain goal changed; no stale travel" end
		if not c.Pets or type(c.Pets.Fresh) ~= "function" then return false, "Fresh native egg observations unavailable" end
		local snapshot, context = c.Pets:Fresh()
		local fresh = c.Brain:PlanEggTravelDiagnostic(snapshot, context, c.Knowledge:Get("Eggs"), c.Knowledge:Get("Worlds"), intent)
		if not fresh or fresh.Kind ~= "EGG_TRAVEL" or fresh.EggName ~= intent.EggName or fresh.Model ~= intent.Model
			or fresh.World ~= intent.World or fresh.Island ~= intent.Island then
			return false, fresh and fresh.Reason or "Fresh accessible diagnostic destination changed; no travel"
		end
		return true
	end
	if not c.Config.PET_SETTINGS.AUTO_HATCH or not c.Config.PET_SETTINGS.ENABLE_PET_INTELLIGENCE
		or not c.Reader.Player or c.Reader.Player.UserId ~= self.BrainUserId then return false, "Brain hatch authorization/account changed" end
	if not c.Pets or type(c.Pets.Fresh) ~= "function" or type(c.Pets.State) ~= "function" then return false, "Fresh pet decision interface unavailable" end
	local snapshot, context = c.Pets:Fresh()
	if not snapshot or not snapshot.Ready or context.Currency ~= intent.Currency then return false, "Brain currency objective or account readiness changed" end
	-- Received results/presentation retain location without re-authorizing movement.
	if self.Lease and self.Lease.Status == "ARRIVED" then return true end
	local report = c.Brain:AnalyzePets(snapshot, context)
	local fresh = c.Brain:PlanPets(report, context, c.Pets:State())
	if not fresh or fresh.Kind ~= "HATCH" or fresh.EggName ~= intent.EggName or fresh.Model ~= intent.Model
		or fresh.Currency ~= intent.Currency then return false, fresh and fresh.Reason or "Fresh useful hatch/reserve decision changed; no travel" end
	return true
end

function EggTravelManager:HatchInteractionAt(record, position, force)
	-- This read-only question is deliberately separate from physical travel.
	-- Exact current registration plus real initial/opened range semantics remain
	-- mandatory before reporting a hatch-range observation, even with AUTO_HATCH off.
	local c = self.Controller
	local identity, reason = c.Knowledge:ResolveEggInstance(record.EggName, force, record.Model)
	if not identity then return false, reason or "Exact native egg interaction identity unavailable" end
	if identity.Model ~= record.Model or identity.Root ~= record.TargetRoot then return false, "Native interaction anchor differs from selected physical original" end
	local profile = c.Reader:GetLiveProfile()
	if not profile or type(profile.EggsOpened) ~= "table" then return false, "Native egg opened-state facts unavailable; physical location remains separate" end
	local prompt = child(record.Model, "Prompt")
	local native = table.clone(record)
	native.LocationOnly = false
	native.Opened = profile and type(profile.EggsOpened) == "table" and profile.EggsOpened[record.EggName] ~= nil
		and record.Model:GetAttribute("Unlocked") == true
	native.RangeOrigin, native.Range = record.TargetRoot, 16
	if native.Opened then
		local prompts = c.Knowledge:Get("ProximityPrompt")
		if type(prompts) ~= "table" or prompts.Visible ~= 0 then return false, "Native opened-egg prompt visibility unavailable/blocked" end
	else
		if identity.PromptCacheMember ~= true then return false, "Exact initial native prompt registration is unverified; physical location remains separate" end
		if not live(prompt) or not vector(prompt.Position) then return false, "Actual native initial egg Prompt geometry unavailable" end
		local engine = prompt:FindFirstChildOfClass("ProximityPrompt")
		if not engine or engine.Parent ~= prompt or engine.Enabled ~= true or engine.RequiresLineOfSight ~= false
			or not finite(engine.MaxActivationDistance) or engine.MaxActivationDistance <= 0 then
			return false, "Native initial egg prompt eligibility unavailable/disabled"
		end
		native.RangeOrigin, native.Range = prompt, math.min(6.5, engine.MaxActivationDistance)
	end
	local eligible, blocker = self:RangeEligibleAt(native, position, force)
	return eligible, blocker or "Exact native interaction identity and actual range observed", native
end

function EggTravelManager:Resolve(force)
	local c, settings = self.Controller, self:Settings()
	local diagnostic = (settings and settings.MODE or "NORMAL") == "TRAVEL_ONLY"
	if self.Destroyed or not settings or not settings.ENABLE_SELECTED_EGG_TRAVEL then return nil, "Selected-egg travel disabled" end
	local key, reason, name = self:Key()
	if not key then return nil, reason end
	local permitted, blocker = self:RevalidateIntent()
	if not permitted then return nil, blocker end
	local profile, snapshot = c.Reader:GetLiveProfile(), c.Reader:GetSnapshot()
	if not profile or not snapshot or not snapshot.Ready or type(profile.WorldsUnlocked) ~= "table"
		or type(profile.AreasUnlocked) ~= "table" or not diagnostic and type(profile.EggsOpened) ~= "table" then return nil, "Fresh account world/island/egg access unavailable" end
	local root, humanoid = c.Farming.Tracker:Root()
	local character = c.Reader.Player and c.Reader.Player.Character
	if not character or not root or not humanoid or not vector(root.Position) then return nil, "Living character unavailable" end
	local definitions, worlds = c.Knowledge:Get("Eggs"), c.Knowledge:Get("Worlds")
	local def = type(definitions) == "table" and definitions[name]
	if type(def) ~= "table" then return nil, "Selected egg definition unavailable" end
	if def.Event or def.ProductId or def.IsAdminEgg or name == "Infinity Egg" then
		return nil, "Special/event/premium egg availability has no verified current adapter; manual approach required, no event chase"
	end
	local world = def.World
	local worldDef = type(worlds) == "table" and worlds[world]
	if type(world) ~= "string" or type(worldDef) ~= "table" or worldDef.Removed
		or profile.WorldsUnlocked[world] == nil then return nil, "Selected egg world/access unknown, removed or locked; manual approach required" end
	local worldUtil = c.Knowledge:Get("WorldUtil")
	local okWorld, currentWorld = pcall(function() return worldUtil:GetPlayerWorld(c.Reader.Player) end)
	if not okWorld or type(currentWorld) ~= "string" then return nil, "Native current-world observation unavailable" end
	local identity, identityReason, observations
	if diagnostic then
		identity, identityReason, observations = c.Knowledge:ResolveEggLocation(name, force, self.BrainIntent and self.BrainIntent.Model, root)
	else
		identity, identityReason, observations = c.Knowledge:ResolveEggInstance(name, force, self.BrainIntent and self.BrainIntent.Model)
	end
	if observations then self:ReportInstanceDiagnostics({ [name] = observations }) end
	if not identity then return nil, identityReason end
	local model, part = identity.Model, identity.Root
	if not live(part) or not vector(part.Position) then return nil, "Selected physical egg Root geometry unavailable" end
	if diagnostic and identity.LocationVerified ~= true then return nil, "Selected native physical egg location is unverified; no travel" end
	if diagnostic and identity.World ~= world then return nil, "Verified physical egg world differs from the selected native definition" end
	local bestDistance = (part.Position - root.Position).Magnitude
	local island = identity.Island or model:GetAttribute("Island") or def.Island
	if island ~= nil and (type(island) ~= "string" or profile.AreasUnlocked[island] == nil) then
		return nil, "Selected egg island access locked or unknown; no discovery or purchase"
	end
	local opened = model:GetAttribute("Unlocked") == true and type(profile.EggsOpened) == "table" and profile.EggsOpened[name] ~= nil
	local prompt = child(model, "Prompt")
	if not diagnostic and (not live(prompt) or not vector(prompt.Position)) then return nil, "Actual egg Prompt geometry unavailable" end
	local rangeOrigin, range, nativePrompt, visible = part, 16
	if diagnostic then
		-- A conservative near-Root travel policy is not native hatch-range proof.
		-- Missing registration/Prompt state must not block an evidenced location.
		range = 6.5
	elseif opened then
		local prompts = c.Knowledge:Get("ProximityPrompt")
		visible = type(prompts) == "table" and prompts.Visible
		if not finite(visible) or visible < 0 or visible % 1 ~= 0 then return nil, "Native opened-egg prompt visibility unavailable" end
		if visible ~= 0 then return nil, "A visible native proximity prompt blocks the opened-egg scan" end
	else
		nativePrompt = prompt:FindFirstChildOfClass("ProximityPrompt")
		if not nativePrompt or nativePrompt.Parent ~= prompt or nativePrompt.Enabled ~= true
			or nativePrompt.RequiresLineOfSight ~= false or not finite(nativePrompt.MaxActivationDistance)
			or nativePrompt.MaxActivationDistance <= 0 then return nil, "Native initial egg prompt eligibility unavailable/disabled" end
		rangeOrigin, range = prompt, math.min(6.5, nativePrompt.MaxActivationDistance)
	end
	local worldModel = child(child(workspace, "Worlds"), world)
	local destination, path, known
	if island then
		for _, entry in ipairs(worldDef.Islands or {}) do if entry.Name == island then known = true break end end
		if known then
			local islandModel = child(child(child(worldModel, "Islands"), island), "Island")
			destination = child(child(islandModel, "Portal"), "Spawn")
			path = "Workspace.Worlds." .. world .. ".Islands." .. island .. ".Island.Portal.Spawn"
		end
	else
		destination = child(child(worldModel, "FastTravel"), "Spawn")
		if live(destination) then path, known = destination:GetFullName(), true end
	end
	if not live(destination) then destination = nil end
	local record = { SelectionKey = key, EggName = name, Model = model, IdentityId = identity.IdentityId, IdentityEvidence = identity.IdentityEvidence,
		LocationOnly = diagnostic, LocationVerified = diagnostic and identity.LocationVerified == true or identity.Verified == true,
		LocationEvidence = identity.LocationEvidence, PhysicalRange = diagnostic and range or nil,
		TargetRoot = part, PromptPart = prompt, NativePrompt = nativePrompt,
		TargetPosition = part.Position, Character = character, CharacterRoot = root, Humanoid = humanoid,
		World = world, Island = island, CurrentWorld = currentWorld, Range = range, Opened = opened,
		RangeOrigin = rangeOrigin, RangeOriginPosition = rangeOrigin.Position, PromptPosition = live(prompt) and vector(prompt.Position) and prompt.Position or nil, PromptVisible = visible,
		Distance = (rangeOrigin.Position - root.Position).Magnitude, RootDistance = bestDistance,
		-- Surface eggs also require their native area arrival when coming from an
		-- island. Absence of an Island annotation cannot authorize a vertical jump.
		NeedsNativeTravel = currentWorld ~= world or math.abs(root.Position.Y - part.Position.Y) > 16,
		Destination = destination, DestinationPath = path, NativeAreaKnown = known == true }
	local eligible, rangeBlocker = self:RangeEligibleAt(record, root.Position)
	record.InRange, record.RangeBlocker = currentWorld == world and eligible, rangeBlocker
	if diagnostic then
		local interaction, interactionReason = self:HatchInteractionAt(record, root.Position, force)
		record.InteractionVerified, record.InteractionReason = currentWorld == world and interaction, interactionReason
	end
	return record
end

function EggTravelManager:RangeEligibleAt(record, position, force)
	if not vector(position) or not live(record.RangeOrigin) then return false, "Native range geometry unavailable" end
	local distance = (position - record.RangeOrigin.Position).Magnitude
	if record.LocationOnly then
		if record.LocationVerified ~= true or record.RangeOrigin ~= record.TargetRoot or not finite(record.PhysicalRange)
			or record.PhysicalRange <= 0 then return false, "Physical egg location identity/anchor unavailable" end
		if distance <= record.PhysicalRange then return true end
		return false, "Outside diagnostic physical arrival radius; native hatch eligibility is separate"
	end
	if distance > record.Range then return false, "Outside the actual native egg range origin" end
	if record.Opened then
		local prompts = self.Controller.Knowledge:Get("ProximityPrompt")
		if type(prompts) ~= "table" or prompts.Visible ~= 0 or record.Model:GetAttribute("Unlocked") ~= true then return false, "Native opened-egg scan eligibility unavailable/blocked" end
		-- Match the native nearest-unlocked selection conservatively using original
		-- loaded models; never read the private client registration table.
		for _, model in ipairs(self.Controller.Knowledge:InteractiveEggModels(force)) do
			local root = model ~= record.Model and model.Parent and model:IsDescendantOf(workspace) and child(model, "Root") or nil
			if live(root) and model:GetAttribute("Unlocked") == true and vector(root.Position)
				and (root.Position - position).Magnitude <= distance + 0.05 then return false, "Another or equally near unlocked egg owns the native nearest-egg scan" end
		end
	end
	return true
end

function EggTravelManager:Validate(record, token, force)
	local lease = self.Lease
	if not lease or not record or record.LeaseId ~= lease.LeaseId or self.Controller.State ~= "RUNNING"
		or lease.Generation ~= nil and lease.Generation ~= self.Controller.Generation
		or token and token:CheckCancelled() then return nil, "Egg location task cancelled or stale" end
	local fresh, reason = self:Resolve(force)
	if not fresh then return nil, reason end
	-- A first authorized hatch can change the native initial-prompt interface to
	-- the opened scanner. Refresh observed range only; never reposition on it.
	if not lease.LocationOnly and lease.Status == "ARRIVED" and not lease.Opened and fresh.Opened and self.Controller.Pets
		and (self.Controller.Pets.Hatch.RequestedHatches or 0) > 0 then
		lease.Opened, lease.NativePrompt, lease.RangeOrigin, lease.Range = fresh.Opened, fresh.NativePrompt, fresh.RangeOrigin, fresh.Range
		lease.RangeOriginPosition, lease.PromptVisible = fresh.RangeOriginPosition, fresh.PromptVisible
	end
	if fresh.SelectionKey ~= lease.SelectionKey or fresh.Model ~= lease.Model or fresh.TargetRoot ~= lease.TargetRoot
		or fresh.LocationOnly ~= lease.LocationOnly or fresh.LocationOnly and fresh.LocationVerified ~= true
		or not lease.LocationOnly and (fresh.PromptPart ~= lease.PromptPart or fresh.NativePrompt ~= lease.NativePrompt or fresh.Opened ~= lease.Opened)
		or fresh.RangeOrigin ~= lease.RangeOrigin or fresh.Range ~= lease.Range
		or fresh.Character ~= lease.Character or fresh.CharacterRoot ~= lease.CharacterRoot
		or fresh.World ~= lease.World or fresh.Island ~= lease.Island then return nil, "Selection, target, access or character changed; no position restoration" end
	if (fresh.TargetPosition - lease.TargetPosition).Magnitude > 0.5 then return nil, "Selected egg moved; new geometry requires explicit rearm" end
	if not lease.LocationOnly and (fresh.PromptPosition - lease.PromptPosition).Magnitude > 0.5
		or (fresh.RangeOriginPosition - lease.RangeOriginPosition).Magnitude > 0.5 then return nil, "Egg location/prompt geometry changed; explicit rearm required" end
	local movement = fresh.Humanoid.MoveDirection
	if lease.Status == "TRAVELING" and vector(movement) and movement.Magnitude > 0.05 then
		return nil, "Manual movement during arrival; explicit rearm required"
	end
	if os.clock() >= lease.Deadline then return nil, "Egg location lease expired" end
	fresh.LeaseId = lease.LeaseId
	return fresh
end

function EggTravelManager:ResolveStanding(record)
	local ok, frameOrReason = pcall(function()
		local root, humanoid, target = record.CharacterRoot, record.Humanoid, record.RangeOrigin
		if not live(target) or not vector(root.Size) or not finite(humanoid.HipHeight) or humanoid.HipHeight < 0 then
			return "Avatar/target geometry unavailable"
		end
		if type(workspace.Raycast) ~= "function" or type(workspace.GetPartBoundsInBox) ~= "function"
			or not RaycastParams or not OverlapParams or not CFrame then return "Standing-surface or clearance runtime unavailable" end
		if type(record.Character.GetBoundingBox) ~= "function" or not root.CFrame then return "Full observed avatar clearance unavailable" end
		local bodyFrame, bodySize = record.Character:GetBoundingBox()
		if not bodyFrame or not vector(bodySize) or bodySize.X <= 0 or bodySize.Y <= 0 or bodySize.Z <= 0 then
			return "Full observed avatar bounds unavailable"
		end
		local bodyOffset = root.CFrame:ToObjectSpace(bodyFrame)
		if not vector(bodyOffset.Position) or not vector(bodyOffset.RightVector) or not vector(bodyOffset.UpVector)
			or not vector(bodyOffset.LookVector) then return "Full avatar/root orientation unavailable" end
		-- Candidate root is upright. Transform the observed full avatar box relative
		-- to that root; include legs/head/accessories rather than only HRP.Size.
		local halfVertical = (math.abs(bodyOffset.RightVector.Y) * bodySize.X + math.abs(bodyOffset.UpVector.Y) * bodySize.Y
			+ math.abs(bodyOffset.LookVector.Y) * bodySize.Z) / 2
		local height = math.max(humanoid.HipHeight + root.Size.Y / 2, halfVertical - bodyOffset.Position.Y) + 0.15
		local ray = RaycastParams.new()
		ray.FilterType = Enum.RaycastFilterType.Exclude
		ray.FilterDescendantsInstances = { record.Character }
		ray.RespectCanCollide = true
		local overlap = OverlapParams.new()
		overlap.FilterType = Enum.RaycastFilterType.Exclude
		overlap.RespectCanCollide = true
		local radius = math.min(4, record.Range / 2)
		local pos = target.Position
		-- Try the source-associated anchor X/Z first. Visible egg overlap alone is
		-- not collision: only actual CanCollide geometry blocks the avatar volume.
		-- Keep collidable Rendered platforms/egg parts in the floor/clearance query.
		local diagonal = radius / math.sqrt(2)
		for _, offset in ipairs({ Vector3.new(0, 0, 0), Vector3.new(radius, 0, 0), Vector3.new(-radius, 0, 0), Vector3.new(0, 0, radius), Vector3.new(0, 0, -radius),
			Vector3.new(diagonal, 0, diagonal), Vector3.new(diagonal, 0, -diagonal), Vector3.new(-diagonal, 0, diagonal), Vector3.new(-diagonal, 0, -diagonal) }) do
			local horizontal = pos + offset
			local result = workspace:Raycast(horizontal + Vector3.new(0, record.Range, 0), Vector3.new(0, -record.Range * 2, 0), ray)
			local floor = result and result.Instance
			if live(floor) and floor.CanCollide == true and floor.Anchored == true and vector(result.Position)
				and vector(result.Normal) and result.Normal.Y >= 0.98 then
				local standing = Vector3.new(horizontal.X, result.Position.Y + height, horizontal.Z)
				if (standing - pos).Magnitude <= record.Range - 0.25 and self:RangeEligibleAt(record, standing) then
					local facing = Vector3.new(pos.X - standing.X, 0, pos.Z - standing.Z)
					if facing.Magnitude < 0.05 then
						local observed = root.CFrame.LookVector
						if not vector(observed) then return "Observed avatar facing unavailable at the physical anchor" end
						facing = Vector3.new(observed.X, 0, observed.Z)
						if facing.Magnitude < 0.05 then return "Observed avatar facing has no upright standing direction" end
					end
					local frame = CFrame.lookAt(standing, standing + facing)
					-- A center hit does not prove footprint support. Accept only a
					-- numerically level solid block whose full padded avatar projection
					-- fits its observed top face; other shapes remain unverified.
					local floorFrame, floorSize = floor.CFrame, floor.Size
					local supported = floor:IsA("Part") and floor.Shape == Enum.PartType.Block and floorFrame
						and vector(floorSize) and floorSize.X > 0 and floorSize.Y > 0 and floorSize.Z > 0
						and vector(floorFrame.RightVector) and vector(floorFrame.UpVector) and vector(floorFrame.LookVector)
						and floorFrame.UpVector.Y >= 1 - 1e-6 and math.abs(floorFrame.RightVector.Y) <= 1e-6
						and math.abs(floorFrame.LookVector.Y) <= 1e-6
					if supported then
						local body = frame * bodyOffset
						local half = (bodySize + Vector3.new(0.3, 0.1, 0.3)) * 0.5
						for _, x in ipairs({ -1, 1 }) do
							for _, y in ipairs({ -1, 1 }) do
								for _, z in ipairs({ -1, 1 }) do
									local corner = body.Position + body.RightVector * (x * half.X)
										+ body.UpVector * (y * half.Y) + body.LookVector * (z * half.Z)
									local top = floorFrame:PointToObjectSpace(Vector3.new(corner.X, result.Position.Y, corner.Z))
									if not vector(top) or math.abs(top.Y - floorSize.Y / 2) > 0.01
										or math.abs(top.X) > floorSize.X / 2 - 0.15 or math.abs(top.Z) > floorSize.Z / 2 - 0.15 then
										supported = false
									end
								end
							end
						end
					end
					if not supported then continue end
					overlap.FilterDescendantsInstances = { record.Character, floor }
					local blocked = false
					for _, obstacle in ipairs(workspace:GetPartBoundsInBox(frame * bodyOffset, bodySize + Vector3.new(0.3, 0.1, 0.3), overlap)) do
						if obstacle.CanCollide == true then blocked = true break end
					end
					if not blocked then return frame end
				end
			end
		end
		return record.LocationOnly and "No supported floor and clear full avatar volume within diagnostic physical radius; manual approach required"
			or "No supported floor and clear full avatar volume within native hatch range; manual approach required"
	end)
	if not ok then return nil, "Standing-geometry observation failed: " .. tostring(frameOrReason) end
	if type(frameOrReason) == "string" then return nil, frameOrReason end
	return frameOrReason
end

function EggTravelManager:Release(reason, blocked)
	local lease = self.Lease
	if self.DiagnosticConsumed then self.DiagnosticEnded = true end
	if lease then
		if blocked then self.Blocked[lease.SelectionKey] = reason end
		self.LastResult = { Status = blocked and "HALTED" or "RELEASED", EggName = lease.EggName,
			Reason = reason, DirectPositionAttempted = lease.DirectPositionAttempted == true, NativeTravelAttempted = lease.NativeTravelAttempted == true,
			HatchCommands = 0, Spending = 0 }
		if self.BrainIntent and self.BrainIntent.Scope == "TRAVEL_ONLY" then self.LastResult.Scope = "TRAVEL_ONLY" end
	end
	self:DiagnosticTrace("TRAVEL_BLOCKED", lease, reason)
	self.Lease = nil
	self.Reason = reason
	if (self:Settings().MODE or "NORMAL") ~= "TRAVEL_ONLY" then
		self:Report(tostring(lease and lease.EggName or "Selected egg") .. " | " .. tostring(reason) .. " | hatch commands=0; spending=0")
	end
end

function EggTravelManager:Observe()
	if not self.Lease then return end
	if self.Controller.State ~= "RUNNING" then self:Release("Controller paused/stopped; no restore", true) return end
	local fresh, reason = self:Validate(self.Lease)
	if not fresh then self:Release(reason, true) return end
	if self.Lease.Status == "ARRIVED" and not fresh.InRange then
		self:Release("Manual departure or position correction observed; same selection will not snap back; change SELECTION_REVISION to rearm", true)
	end
end

function EggTravelManager:OwnsLocation() return self.Lease ~= nil and self.Controller.State == "RUNNING" end
function EggTravelManager:HatchEligible(egg)
	if (self:Settings().MODE or "NORMAL") == "TRAVEL_ONLY" or self.BrainIntent and self.BrainIntent.Scope == "TRAVEL_ONLY" then
		return false, "TRAVEL_ONLY never authorizes a hatch handoff"
	end
	local key, reason = self:Key()
	if not key or self.Blocked[key] then return false, self.Blocked[key] or reason end
	local lease = self.Lease
	if not lease or lease.Status ~= "ARRIVED" or not egg or egg.Name ~= lease.EggName or egg.Model ~= lease.Model then
		return false, "Selected Brain egg requires observed stable arrival of the same original model"
	end
	local fresh, blocker = self:Validate(lease)
	if not fresh or not fresh.InRange or not self:RangeEligibleAt(fresh, fresh.CharacterRoot.Position, true) then
		self:Release(blocker or "Manual departure from native range; no snap-back", true)
		return false, blocker or "Native selected egg range changed"
	end
	return true
end
function EggTravelManager:AtOwnedLocation(area)
	local lease = self.Lease
	if not lease or lease.Status ~= "ARRIVED" or not area then return false end
	local fresh = self:Validate(lease)
	return fresh ~= nil and fresh.InRange and area.World == lease.World and area.Name == (lease.Island or lease.World)
end

function EggTravelManager:Select(_plan, intent)
	local diagnostic = (self:Settings().MODE or "NORMAL") == "TRAVEL_ONLY"
	if diagnostic and self.DiagnosticConsumed and (self.DiagnosticEnded or not self.Lease) then
		if not self.LastResult or self.LastResult.PhysicalArrivalVerified ~= true then
			self:DiagnosticTrace("TRAVEL_BLOCKED", nil, "One bounded diagnostic consumed; no retry or revision rearm")
		end
		return false, { Kind = "WAIT", Reason = "One bounded TRAVEL_ONLY attempt consumed; no automatic retry or revision rearm", OwnsLocation = false }
	end
	if intent then
		local name, reason = selected(self.Controller.Config, intent)
		if not name then self:DiagnosticTrace("PREFLIGHT_BLOCKED", nil, reason) return false, { Kind = "WAIT", Reason = reason } end
		if self.Lease and self.BrainIntent and (intent.EggName ~= self.BrainIntent.EggName
			or intent.Model ~= self.BrainIntent.Model or intent.Currency ~= self.BrainIntent.Currency
			or diagnostic and (intent.GoalId ~= self.BrainIntent.GoalId or intent.Generation ~= self.BrainIntent.Generation
				or intent.SelectionRevision ~= self.BrainIntent.SelectionRevision)) then
			self:Release("Brain target/model/objective changed; no stale arrival or automatic restoration", true)
			return false, { Kind = "WAIT", Reason = self.Reason }
		end
		if not self.BrainIntent or not self.Lease then self.BrainUserId = self.Controller.Reader.Player and self.Controller.Reader.Player.UserId end
		self.BrainIntent = table.clone(intent)
	elseif (self.Controller.Config.HATCH_SETTINGS.EGG_SELECTION_MODE or "MANUAL") == "AUTO" then
		return false, { Kind = "WAIT", Reason = "AUTO travel requires a fresh Brain destination" }
	end
	self:Observe()
	local settings = self:Settings()
	if not settings or not settings.ENABLE_SELECTED_EGG_TRAVEL or self.Destroyed then return false, { Kind = "WAIT", Reason = "Selected-egg travel disabled" } end
	local key, reason = self:Key()
	if not key then self.Reason = reason self:DiagnosticTrace("PREFLIGHT_BLOCKED", nil, reason) if not diagnostic then self:Report(reason) end return false, { Kind = "WAIT", Reason = reason } end
	if self.Blocked[key] then self.Reason = self.Blocked[key] self:DiagnosticTrace("TRAVEL_BLOCKED", nil, self.Reason) if not diagnostic then self:Report(self.Reason) end return false, { Kind = "WAIT", Reason = self.Reason } end
	if self.Lease then
		local pets = self.Controller.Config.PET_SETTINGS
		if self.Lease.Status == "ARRIVED" and pets and pets.AUTO_HATCH then
			return false, { Kind = "HANDOFF", OwnsLocation = true, Reason = "Selected range observed; separate existing hatch authority decides spending" }
		end
		return true, { Kind = self.Lease.Status == "ARRIVED" and "OBSERVE" or "EGG_TRAVEL", Record = self.Lease, OwnsLocation = true }
	end
	if (self.Attempts[key] or 0) >= settings.MAXIMUM_ATTEMPTS_PER_SELECTION then return false, { Kind = "WAIT", Reason = "Selected-egg attempt limit reached; explicit revision required" } end
	local record, blocker = self:Resolve(true)
	if not record then self.Reason = blocker self:DiagnosticTrace("PREFLIGHT_BLOCKED", nil, blocker) if not diagnostic then self:Report(blocker) end return false, { Kind = "WAIT", Reason = blocker } end
	if record.NeedsNativeTravel and (not settings.ENABLE_NATIVE_ISLAND_TRAVEL or not record.NativeAreaKnown or not record.DestinationPath) then
		self.Reason = "Correct unlocked native area travel unavailable/disabled; direct positioning cannot cross unknown worlds/islands"
		self:DiagnosticTrace("PREFLIGHT_BLOCKED", record, self.Reason)
		if not diagnostic then self:Report(self.Reason) end
		return false, { Kind = "WAIT", Reason = self.Reason }
	end
	if not record.InRange and not settings.ENABLE_DIRECT_POSITIONING and not settings.ENABLE_NATIVE_ISLAND_TRAVEL then
		self.Reason = record.RangeBlocker or "Outside selected egg range; positioning and native island travel are disabled"
		self:DiagnosticTrace("PREFLIGHT_BLOCKED", record, self.Reason)
		if not diagnostic then self:Report(self.Reason) end
		return false, { Kind = "WAIT", Reason = self.Reason }
	end
	-- Consume this controller's diagnostic permission before it can enter the
	-- scheduler. Cancellation, skipped execution and uncertain movement cannot
	-- turn Pause/Resume or a selection revision into a second travel attempt.
	if diagnostic then self.DiagnosticConsumed = true self.DiagnosticEnded = false end
	self.Sequence += 1
	record.LeaseId, record.Status = self.Sequence, "PLANNED"
	record.Generation, record.Scope = self.Controller.Generation, diagnostic and "TRAVEL_ONLY" or "AUTHORIZED_HATCH_OR_MANUAL_TRAVEL"
	record.StartedAt, record.Deadline = os.clock(), os.clock() + settings.MAXIMUM_LOCATION_SECONDS
	self.Lease = record
	self:DiagnosticTrace("TARGET_SELECTED", record, self.BrainIntent and self.BrainIntent.Reason or "Exact owner-selected native destination")
	self:DiagnosticTrace("PHYSICAL_TARGET_RESOLVED", record, "Exact accessible egg Instance and native physical Root resolved; safe standing geometry is checked before assignment; hatch interaction separate")
	return true, { Kind = "EGG_TRAVEL", Record = record, OwnsLocation = true }
end

function EggTravelManager:Execute(record, token)
	local settings, c = self:Settings(), self.Controller
	if settings.OWNER_DIRECT_EGG_TELEPORT_TEST then
		return c.Farming.Mechanics:ExecuteOwnerDirectEggTeleportTest(self, record, token)
	end
	local fresh, reason = self:Validate(record, token)
	if not fresh then self:Release(reason, true) return { Verified = false, Reason = reason } end
	local lease = self.Lease
	if lease.Status == "ARRIVED" then self:Observe() if not token:CheckCancelled() then task.wait(1) end return { Verified = self.Lease ~= nil, Reason = "Observing selected location; no repositioning" } end
	self.Attempts[lease.SelectionKey] = (self.Attempts[lease.SelectionKey] or 0) + 1
	lease.Status = "TRAVELING"
	if not fresh.InRange and fresh.NeedsNativeTravel and settings.ENABLE_NATIVE_ISLAND_TRAVEL and fresh.NativeAreaKnown and fresh.DestinationPath then
		lease.NativeTravelAttempted = true
		self:DiagnosticTrace("AREA_TRAVEL_ADAPTER_ATTEMPTED", fresh, "Existing native adapter attempt for " .. fresh.DestinationPath .. "; native request dispatch remains separately reported")
		local ok, why = c.Farming.Mechanics:TravelSelectedEgg(self, fresh, token)
		if not ok then self:DiagnosticTrace("ARRIVAL_UNCONFIRMED", fresh, why or "Native area arrival unconfirmed") self:Release(why or "Native selected-area travel unconfirmed", true) return { Verified = false, Reason = self.Reason } end
		fresh, reason = self:Validate(lease, token)
		if fresh and not fresh.NeedsNativeTravel then self:DiagnosticTrace("AREA_ARRIVAL_OBSERVED", fresh, "Existing adapter observed native target-area arrival; egg interaction range still pending") end
	end
	if not fresh then self:Release(reason, true) return { Verified = false, Reason = reason } end
	if fresh.NeedsNativeTravel then self:Release("Correct native target area arrival unconfirmed; no direct cross-world/island positioning", true) return { Verified = false, Reason = self.Reason } end
	-- Native area transport and final positioning each have a bounded window.
	-- A slow but valid area arrival must still leave time for hatch-range stability.
	local deadline = math.min(lease.Deadline, os.clock() + settings.ARRIVAL_TIMEOUT_SECONDS)
	if not fresh.InRange then
		if not settings.ENABLE_DIRECT_POSITIONING then self:Release("Native area reached; selected egg remains outside range; manual approach required", true) return { Verified = false, Reason = self.Reason } end
		local frame, geometryReason = self:ResolveStanding(fresh)
		if not frame then self:Release(geometryReason, true) return { Verified = false, Reason = geometryReason } end
		fresh, reason = self:Validate(lease, token)
		if not fresh then self:Release(reason, true) return { Verified = false, Reason = reason } end
		lease.DirectPositionAttempted = true -- Retain even on uncertain adapter error; no automatic repeat.
		lease.RequestedStandingPosition = frame.Position
		self:DiagnosticTrace("DIRECT_POSITION_ATTEMPTED", fresh, "One existing guarded HRP CFrame adapter attempt; standing surface/full-avatar clearance observed; assignment does not certify arrival")
		local ok, why = c.Farming.Mechanics:PositionSelectedEgg(self, fresh, frame, token)
		if not ok then self:DiagnosticTrace("DIRECT_POSITION_FAILED", fresh, why or "Direct assignment failed/unconfirmed") self:Release(why or "Direct positioning failed/unconfirmed", true) return { Verified = false, Reason = self.Reason } end
	end
	local stableAt, stablePosition
	while os.clock() < deadline do
		fresh, reason = self:Validate(lease, token)
		if not fresh then self:Release(reason, true) return { Verified = false, Reason = reason } end
		local position = fresh.CharacterRoot.Position
		local move = fresh.Humanoid.MoveDirection
		if vector(move) and move.Magnitude > 0.05 then self:Release("Manual movement during arrival; explicit rearm required", true) return { Verified = false, Reason = self.Reason } end
		local requestedPositionObserved = not lease.RequestedStandingPosition or (position - lease.RequestedStandingPosition).Magnitude <= 0.5
		if fresh.InRange and requestedPositionObserved and (not stablePosition or (position - stablePosition).Magnitude <= 0.35) then
			stableAt, stablePosition = stableAt or os.clock(), stablePosition or position
			if os.clock() - stableAt >= settings.STABILITY_SECONDS then
				local guardOK, allowed, blocker = pcall(function()
					if type(c.Farming.Mechanics.LocalFeatureGuard) ~= "function" then return false, "Foreground presentation guard unavailable" end
					return c.Farming.Mechanics:LocalFeatureGuard()
				end)
				if not guardOK or not allowed then self:Release(blocker or "Foreground presentation eligibility unavailable", true) return { Verified = false, Reason = self.Reason } end
				fresh, reason = self:Validate(lease, token)
				if not fresh or not fresh.InRange or (fresh.CharacterRoot.Position - stablePosition).Magnitude > 0.35 then
					self:Release(reason or "Actual arrival eligibility changed during final guards", true) return { Verified = false, Reason = self.Reason }
				end
				lease.Status, lease.ArrivedAt = "ARRIVED", os.clock()
				local diagnostic = self.BrainIntent and self.BrainIntent.Scope == "TRAVEL_ONLY"
				self.LastResult = { Status = diagnostic and "PHYSICAL_ARRIVAL_OBSERVED" or "HATCH_RANGE_OBSERVED", EggName = fresh.EggName, Distance = fresh.Distance, Range = fresh.Range,
					StabilitySeconds = settings.STABILITY_SECONDS, DirectPositionAttempted = lease.DirectPositionAttempted == true,
					NativeTravelAttempted = lease.NativeTravelAttempted == true, HatchCommands = 0, Spending = 0,
					RangeOrigin = fresh.Opened and "EGG_ROOT" or "INITIAL_PROMPT", PromptVisible = fresh.PromptVisible,
					Reason = "Observed stable native range/interaction guards; separate hatch budget/capacity/cooldown and server acceptance remain required" }
				if diagnostic then
					local interaction, interactionReason, native = self:HatchInteractionAt(fresh, fresh.CharacterRoot.Position, true)
					local physical, physicalReason = self:Validate(lease, token, true)
					if not physical or not physical.InRange or (physical.CharacterRoot.Position - stablePosition).Magnitude > 0.35
						or lease.RequestedStandingPosition and (physical.CharacterRoot.Position - lease.RequestedStandingPosition).Magnitude > 0.5 then
						self:Release(physicalReason or "Physical arrival changed during final interaction observation", true)
						return { Verified = false, Reason = self.Reason }
					end
					self.LastResult.Status, self.LastResult.Scope = "PHYSICAL_ARRIVAL_OBSERVED", "TRAVEL_ONLY"
					self.LastResult.World, self.LastResult.Island = fresh.World, fresh.Island
					self.LastResult.PhysicalArrivalVerified, self.LastResult.InteractionVerified = true, interaction == true
					self.LastResult.IdentityId = fresh.IdentityId
					self.LastResult.HatchInteraction = interaction and "HATCH_RANGE_OBSERVED" or "HATCH_INTERACTION_UNVERIFIED"
					self.LastResult.InteractionReason = interactionReason
					self.LastResult.NativeRange = native and native.Range
					self.LastResult.RangeOrigin = "VERIFIED_PHYSICAL_EGG_ROOT; diagnostic 6.5-stud policy"
					self.LastResult.Reason = "Stable physical arrival near the exact verified egg Root observed; native hatch eligibility is a separate read-only result; owner live acceptance still required"
					self.Reason, self.LastPreflightReason = nil, nil
					self.DiagnosticEnded, self.Lease = true, nil
					self:DiagnosticTrace("PHYSICAL_ARRIVAL_OBSERVED", fresh, "Actual character position stable near the exact physical original; no hatch/equipment/pickups or spending")
					self:DiagnosticTrace(self.LastResult.HatchInteraction, fresh, interactionReason)
				end
				self:Report(string.format("%s | %s | distance=%.2f/%s; stability=%ss; direct attempt=%s; native travel attempt=%s; hatch commands=0; spending=0",
					fresh.EggName, self.LastResult.Status, fresh.Distance, tostring(fresh.Range), tostring(settings.STABILITY_SECONDS), tostring(lease.DirectPositionAttempted == true), tostring(lease.NativeTravelAttempted == true)))
				return { Verified = true, Reason = self.LastResult.Reason }
			end
		else stableAt, stablePosition = nil, nil end
		task.wait(0.1)
	end
	local arrivalReason = record.LocationOnly and "Stable physical arrival at the requested standing destination unconfirmed; no retry or old-position restore"
		or "Stable hatch-range arrival unconfirmed; no retry or old-position restore"
	self:DiagnosticTrace("ARRIVAL_UNCONFIRMED", fresh, arrivalReason)
	self:Release(arrivalReason, true)
	return { Verified = false, Reason = self.Reason }
end

function EggTravelManager:Definition(decision, generation)
	local c, record = self.Controller, decision.Record
	return { Id = "OC_GAMEPLAY", Owner = "EGG_TRAVEL", Generation = generation, Priority = 65,
		TimeoutSeconds = ((self:Settings() or {}).ARRIVAL_TIMEOUT_SECONDS or 12) * 2 + 2,
		CanRun = function() return c.State == "RUNNING" and generation == c.Generation and self.Lease == record end,
		Execute = function(token) return self:Execute(record, token) end,
		IsComplete = function(result) return type(result) == "table" end }
end

function EggTravelManager:Completed(status, _result, reason)
	if self.DiagnosticConsumed and not self.DiagnosticEnded and status and status ~= "COMPLETED" then
		self:Release(reason or "Travel diagnostic task did not complete; no retry", true)
	end
	self:Observe()
end
function EggTravelManager:Halt(stopped) self:Release(stopped and "Stopped; no position restore or automatic retry" or "Paused; explicit revision required before another movement attempt", true) end
function EggTravelManager:Destroy() if self.Destroyed then return end self:Halt(true) self.Destroyed = true end
function EggTravelManager:GetStatus()
	return { Enabled = self:Settings() and self:Settings().ENABLE_SELECTED_EGG_TRAVEL == true,
		Lease = self.Lease, OwnsLocation = self:OwnsLocation(), Attempts = table.clone(self.Attempts),
		LastResult = self.LastResult, Reason = self.Reason, LastPreflightReason = self.LastPreflightReason, BrainIntent = self.BrainIntent,
		Mode = (self:Settings() or {}).MODE or "NORMAL", DiagnosticConsumed = self.DiagnosticConsumed == true, DiagnosticEnded = self.DiagnosticEnded == true,
		HatchPermission = "SEPARATE", LiveVerification = "OWNER_PENDING" }
end

return EggTravelManager

end

-- src/OCFoundation/FarmingCoordinator.luau
factories["FarmingCoordinator"] = function()
--!nonstrict
-- Observations may run in the background; every action is an OCBrain-selected scheduler task.
local PickupTracker = requireOC("PickupTracker")
local GameMechanics = requireOC("GameMechanics")
local ResourceMetrics = requireOC("ResourceMetrics")
local FarmingPolicy = requireOC("FarmingPolicy")
local GameKnowledge = requireOC("GameKnowledge")
local StationaryExperiment = requireOC("StationaryExperiment")
local FarmingCoordinator = {}
FarmingCoordinator.__index = FarmingCoordinator

local function balancesText(values)
	local items = {}
	for name, amount in pairs(values) do table.insert(items, string.format("%s=%.0f", name, amount)) end
	table.sort(items)
	return #items > 0 and table.concat(items, ", ") or "unavailable"
end

function FarmingCoordinator.new(controller, player)
	local self = setmetatable({ Controller = controller, Config = controller.Config, Reader = controller.Reader,
		Activity = nil, Decision = nil, Destroyed = false, LastLogAt = -math.huge, SaleEvidence = {}, ProbeStart = nil,
		IslandProbeHistory = {}, PickupProbe = nil, PickupEvidence = {}, CombinedEvidence = {}, LastPickupLogAt = -math.huge, CollectionVisits = 0 }, FarmingCoordinator)
	self.Knowledge = controller.Knowledge or GameKnowledge.new(self.Reader)
	self.Tracker = PickupTracker.new(self.Config, self.Reader, player, self.Knowledge)
	self.Mechanics = GameMechanics.new(self.Config, self.Reader, self.Tracker, player, function(tag, message) controller:Log(tag, message) end)
	self.Mechanics.BubbleGoalProvider = function()
		local plan = self.Controller.Plan
		local expected = plan and plan.Objective and plan.Objective.Metadata and plan.Objective.Metadata.Requirement
		if not expected or (expected.Type ~= "Bubbles" and expected.Type ~= "Sell") or type(self.Reader.GetTaskRequirement) ~= "function" then return nil end
		local actual = self.Reader:GetTaskRequirement(expected.QuestId, expected.TaskIndex)
		return actual and actual.Type == expected.Type and actual or nil
	end
	self.Metrics = ResourceMetrics.new(self.Config.FARMING_SETTINGS)
	self.Stationary = StationaryExperiment.new(self)
	return self
end

function FarmingCoordinator:_beginCombined(scope)
	if self.Cycle and self.Cycle.Scope == scope then return end
	local raw = self.Reader:GetLiveProfile()
	self.CycleSequence = (self.CycleSequence or 0) + 1
	self.Cycle = { Id = self.CycleSequence, Scope = scope, StartedAt = os.clock(), Before = self.Reader:ReadBalances(),
		InitialBubble = raw and raw.Bubble and raw.Bubble.Amount, LastBubble = raw and raw.Bubble and raw.Bubble.Amount, Requests = 0 }
	self.Controller:Log("FARM][CYCLE", "begin=" .. self.Cycle.Id .. " island=" .. scope .. " initial bubble=" .. tostring(self.Cycle.InitialBubble))
end

function FarmingCoordinator:_finishCombined()
	local cycle = self.Cycle
	if not cycle or not cycle.SaleAt then return end
	local after, gains, spending = self.Reader:ReadBalances(), {}, false
	for currency, before in pairs(cycle.Before) do
		local value = after[currency]
		if type(value) == "number" then
			if value < before then spending = true end
			if value > before then gains[currency] = value - before end
		end
	end
	local seconds = os.clock() - cycle.StartedAt
	local complete = cycle.InitialBubble == 0 and cycle.Requests > 0 and cycle.GrowthAt and cycle.PickupAt and not spending and not cycle.Spending and next(gains) ~= nil
	if complete then
		self.Metrics:AddSample("COMBINED", cycle.Scope, gains, seconds, os.clock())
		self.CombinedEvidence[cycle.Scope] = { GrowthAt = cycle.GrowthAt, PickupAt = cycle.PickupAt, SaleAt = cycle.SaleAt, ReturnedAt = os.clock() }
	end
	self.Controller:Log("FARM][CYCLE", string.format("end=%d island=%s elapsed=%.1fs requests=%d complete=%s | includes loading, failures, selling and return; external rewards may contribute; pre-existing bubbles excluded", cycle.Id, cycle.Scope, seconds, cycle.Requests, tostring(complete == true)))
	self.Cycle = nil
end

function FarmingCoordinator:_background(token)
	return false -- Currency pickup work never starts a bubble cycle, including legacy combined overrides.
end

function FarmingCoordinator:Observe()
	local hatch = self.Config.PET_SETTINGS.ENABLE_PET_INTELLIGENCE and self.Config.PET_SETTINGS.AUTO_HATCH and self.Config.HATCH_SETTINGS.ENABLE_BACKGROUND_PICKUPS
	if self.Destroyed or not self.Config.FARMING_SETTINGS.AUTO_RESOURCE_FARM and not hatch then return end
	local now, snapshot = os.clock(), self.Reader:GetSnapshot()
	local ok, reason = xpcall(function() self.Tracker:Refresh(snapshot, now) end, debug.traceback)
	if not ok then self.Tracker.Error = tostring(reason) end
	self:_logPickupScan(now)
	local balances = self.Reader:ReadBalances()
	if self.Cycle then
		for currency, value in pairs(balances) do
			local old = (self.Cycle.LastBalances or self.Cycle.Before)[currency]
			if type(old) == "number" and value < old then self.Cycle.Spending = true end
		end
		self.Cycle.LastBalances = table.clone(balances)
	end
	local gains
	if self.Controller.RewardAttributionBlocked and self.Controller:RewardAttributionBlocked() then
		self.Metrics.Last = { At = now, Balances = table.clone(balances) }
		gains = {} -- Delayed playtime/box credits remain outside farming-rate evidence.
	else gains = self.Metrics:Observe(balances, now) end
	local live = self.Reader:GetLiveProfile()
	local amount = live and live.Bubble and live.Bubble.Amount
	if self.Controller.State == "RUNNING" and self.Metrics.Active and type(amount) == "number" and type(self.LastBubbleAmount) == "number"
		and amount < self.LastBubbleAmount then
		self.SaleSequence = (self.SaleSequence or 0) + 1
		if self.Metrics.Active.Mode == "PICKUPS" or self.Metrics.Active.Mode == "STATIONARY" then
			local scope = self.Metrics.Active.Scope
			for index = #self.Metrics.Samples, 1, -1 do
				local sample = self.Metrics.Samples[index]
				if sample.Scope == scope and (sample.Mode == "PICKUPS" or sample.Mode == "STATIONARY") then table.remove(self.Metrics.Samples, index) end
			end
			for key in pairs(self.PickupEvidence) do if key:sub(1, #scope + 1) == scope .. ":" then self.PickupEvidence[key] = nil end end
			if self.PickupProbe then self.PickupProbe.Confirmed = false end
			self.Controller:Log("PICKUP][RESULT", "UNCONFIRMED: bubble amount decreased during isolated measurement; potentially mixed pickup/sale samples discarded")
		end
		self.PendingSale = { Scope = self.Metrics.Active.Scope, Mode = self.Metrics.Active.Mode, ExpiresAt = now + self.Config.FARMING_SETTINGS.EARNINGS_CONFIRMATION_TIMEOUT_SECONDS }
	end
	if self.PendingSale and next(gains) and now <= self.PendingSale.ExpiresAt then
		if self.Metrics.Active and (self.Metrics.Active.Mode == "PICKUPS" or self.Metrics.Active.Mode == "STATIONARY") then
			local scope = self.Metrics.Active.Scope
			for index = #self.Metrics.Samples, 1, -1 do
				local sample = self.Metrics.Samples[index]
				if sample.Scope == scope and (sample.Mode == "PICKUPS" or sample.Mode == "STATIONARY") then table.remove(self.Metrics.Samples, index) end
			end
			if self.PickupProbe then self.PickupProbe.Confirmed = false end
		end
		if self.PendingSale.Mode == "COMBINED" then
			local scope = self.PendingSale.Scope
			self.CombinedEvidence[scope] = self.CombinedEvidence[scope] or {}
			self.CombinedEvidence[scope].SaleAt = now self.CombinedProbeStart = nil
			if self.Cycle and self.Cycle.Scope == scope then
				self.Cycle.SaleAt = now
				if not self.ReturnKey and self.Activity and self.Activity.Kind ~= "SELL" then self:_finishCombined() end
			end
		end
		self.SaleEvidence[self.PendingSale.Scope] = true self.ProbeStart = nil self.PendingSale = nil
		self.Controller:Log("FARM][SELL", "Observed native sale: bubble amount decreased and actual balances subsequently increased")
	end
	if self.PendingSale and now > self.PendingSale.ExpiresAt then self.PendingSale = nil end
	self.LastBubbleAmount = amount
	if self.Cycle then
		local cycle = self.Cycle
		if self.Activity and self.Activity.Kind == "FARM" and self.Activity.Mode == "COMBINED" and self.Activity.Cluster
			and self.Activity.Cluster.AreaKey == cycle.Scope and type(amount) == "number" and type(cycle.LastBubble) == "number" and amount > cycle.LastBubble then
			cycle.GrowthAt = now
		end
		cycle.LastBubble = amount
		if now - cycle.StartedAt > self.Config.FARMING_SETTINGS.BUBBLE_PROBE_TIMEOUT_SECONDS + self.Config.ISLAND_SETTINGS.TRAVEL_RETRY_COOLDOWN_SECONDS then
			self.Controller:Log("FARM][CYCLE", "incomplete cycle expired; no combined income published") self.Cycle = nil
		end
	end
	local current = self.Tracker.Current
	if self.PickupProbe then
		local probe = self.PickupProbe
		local sample = self.Metrics:Rates(probe.Key, now).STATIONARY
		local confirmed = probe.Confirmed and (probe.Attempts or 0) > 0 and sample and sample.Ready
		local finished = (now >= (probe.ReadyAt or probe.StartedAt) and (not current or current.Key ~= probe.Key))
			or probe.Currency ~= (self.Decision and self.Decision.Currency)
			or confirmed or now - probe.StartedAt >= self.Config.ISLAND_SETTINGS.PICKUP_PROBE_TIMEOUT_SECONDS
		if finished then
			self.IslandProbeHistory[probe.Key .. ":" .. probe.Currency] = now
			self.PickupProbe = nil
			self.Metrics:SetMode(nil, nil, balances, now)
			self.Controller:Log("FARM][EXPLORE", probe.Key .. " | trial ended | " .. (confirmed
				and string.format("actual sample %.1fs, %.2f %s/min; external rewards may affect attribution", sample.Seconds, sample.PerMinute[probe.Currency] or 0, probe.Currency)
				or "insufficient sample, unavailable location, or timeout; pickup income remains unverified"))
		end
	end
	if current then
		if self.ReturnKey == current.Key and self.Activity == nil then self.ReturnKey = nil self:_finishCombined() end
		self.EmptySince = self.EmptySince or {}
		if current.EligibleCount > 0 then
			self.EmptySince[current.Key] = nil
			local failure = self.Mechanics.Failures["ISLAND:" .. current.Key]
			if failure and failure.Reason == "No eligible pickups observed" then self.Mechanics.Failures["ISLAND:" .. current.Key] = nil end
		elseif not self.PickupProbe and now - (self.Tracker.ArrivedAt or now) >= self.Config.ISLAND_SETTINGS.ARRIVAL_PICKUP_GRACE_SECONDS then
			self.EmptySince[current.Key] = self.EmptySince[current.Key] or now
			if now - self.EmptySince[current.Key] >= self.Config.ISLAND_SETTINGS.EMPTY_ISLAND_CONFIRMATION_SECONDS
				and self.Mechanics:Available("ISLAND:" .. current.Key) then
				self.Mechanics:Failure("ISLAND:" .. current.Key, self.Config.ISLAND_SETTINGS.EMPTY_ISLAND_RETRY_SECONDS, "No eligible pickups observed")
			end
		end
	end
	if self.Controller.State == "RUNNING" then
		local raw = self.Reader:GetLiveProfile()
		local capacity = raw and self.Reader:_stat("GetBubbleStorage", raw, {})
		local full = raw and raw.Bubble and type(raw.Bubble.Amount) == "number" and capacity and capacity > 0
			and raw.Bubble.Amount / capacity >= self.Config.BUBBLE_SETTINGS.SELL_AT_CAPACITY_RATIO
		if full and not self.FullSince then self.Controller:Log("FARM][SELL_TIMING", "Threshold observed; stable discretionary-delay clock started") end
		self.FullSince = full and (self.FullSince or now) or nil
		if self.Activity and self.Activity.Kind ~= "SELL" and full and self.Mechanics:BubbleRequirement() and self.Config.BUBBLE_SETTINGS.AUTO_SELL_BUBBLES and not self.Config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST
			and (self.Activity.Kind == "TRAVEL" or self.Activity.Probe or self.Activity.Mode == "BUBBLES"
				or now - self.FullSince >= self.Config.FARMING_SETTINGS.MAXIMUM_COMBINED_SELL_DELAY_SECONDS) then
			self.Controller.Scheduler:CancelActive("Bubble reached sell threshold") self.Mechanics:StopMovement()
		end
		self.Controller:_requestPlan(false)
	end
	self.Controller:_notify()
end

function FarmingCoordinator:_beginPickupProbe(key, currency)
	local now = os.clock()
	local readyAt = now + self.Config.ISLAND_SETTINGS.ARRIVAL_PICKUP_GRACE_SECONDS
	for index = #self.Metrics.Samples, 1, -1 do
		local sample = self.Metrics.Samples[index]
		if sample.Scope == key and sample.Mode == "PICKUPS" then table.remove(self.Metrics.Samples, index) end
	end
	self.PickupEvidence[key .. ":" .. currency] = nil
	self.PickupProbe = { Key = key, Currency = currency, CreatedAt = now, ReadyAt = readyAt, StartedAt = readyAt, Attempts = 0, Confirmed = false }
	self.IslandProbeHistory[key .. ":" .. currency] = now
	self.Controller:Log("FARM][EXPLORE", key .. " | begin bounded isolated pickup trial | loading grace=" .. self.Config.ISLAND_SETTINGS.ARRIVAL_PICKUP_GRACE_SECONDS .. "s")
end

function FarmingCoordinator:_pickupRates(key, now)
	local rates = self.Metrics:Rates(key, now)
	rates.PICKUPS = rates.STATIONARY -- Compatibility policy view; these are actual stationary observation windows.
	local pickups = rates.PICKUPS
	if pickups then
		for currency in pairs(pickups.PerMinute) do
			local evidence = self.PickupEvidence[key .. ":" .. currency]
			if not evidence or now - evidence > self.Config.FARMING_SETTINGS.RATE_WINDOW_SECONDS then pickups.PerMinute[currency] = nil end
		end
		if next(pickups.PerMinute) == nil then pickups.Ready = false end
	end
	if rates.BUBBLES and not self.SaleEvidence[key] then rates.BUBBLES.Ready = false end
	if rates.COMBINED then
		local evidence = self.CombinedEvidence[key]
		if not evidence or not evidence.GrowthAt or not evidence.PickupAt or not evidence.SaleAt or not evidence.ReturnedAt
			or now - math.min(evidence.GrowthAt, evidence.PickupAt, evidence.SaleAt) > self.Config.FARMING_SETTINGS.RATE_WINDOW_SECONDS then rates.COMBINED.Ready = false end
	end
	return rates
end

function FarmingCoordinator:_logPickupScan(now)
	if not self.Config.DIAGNOSTIC_SETTINGS.LOG_PICKUP_DIAGNOSTICS or now - self.LastPickupLogAt < math.max(5, self.Config.DIAGNOSTIC_SETTINGS.MINIMUM_LOG_INTERVAL_SECONDS) then return end
	self.LastPickupLogAt = now
	local tracker, report = self.Tracker, self.Tracker.ScanReport
	local range = tracker:ReadRange()
	local area = tracker.Current
	local function counts(values)
		local entries = {} for name, count in pairs(values or {}) do table.insert(entries, tostring(name) .. "=" .. count) end
		table.sort(entries) return #entries > 0 and table.concat(entries, "; ") or "none"
	end
	if not report then self.Controller:Log("PICKUP][SCAN", "Scan unavailable: " .. tostring(tracker.Error or "collection/scanning disabled or not initialized")) return end
	self.Controller:Log("PICKUP][SCAN", string.format("island=%s | candidates=%d Models=%d | actual range=%s | scan age=%.1fs", area and area.Key or "unknown", report.RenderedObjects, report.Models, range and string.format("%.2f", range) or "unavailable", now - report.At))
	self.Controller:Log("PICKUP][SOURCES", string.format("registry: %s entries=%d active IDs=%d | Rendered.Chunker folders=%d objects=%d | legacy Pickups folder=%s objects=%d | spawn listener=%s events=%d valid records=%d metadata IDs=%d without position/model=%d", report.RegistryStatus, report.RegistryEntries, report.RegistryActiveIds, report.ChunkerFolders, report.ChunkerObjects, tostring(report.FolderPresent), report.LegacyObjects, tostring(report.SpawnListener), report.NativeSpawnEvents, report.NativeSpawnRecords, report.MetadataIds, report.MetadataWithoutModel))
	self.Controller:Log("PICKUP][DETECTED", string.format("ID candidates=%d positions resolved=%d | ID sources: %s | current island=%d currency=%d unidentified=%d unloaded/stale registry entries=%d", report.CandidateIds, report.PositionsResolved, counts(report.IdSources), report.CurrentDetected, report.CurrencyCount, report.Unidentified, report.UnloadedEntries))
	self.Controller:Log("PICKUP][CLASSIFIED", string.format("current currency=%d eligible=%d | currencies: %s | identities: %s", report.CurrentCurrency, area and area.EligibleCount or 0, counts(report.Currencies), counts(report.Sources)))
	local reason = report.RenderedObjects == 0 and ("No live candidates from checked native registry/Chunker/legacy sources; " .. report.RegistryStatus .. "; spawn metadata alone has no exact position") or counts(report.Rejected)
	self.Controller:Log("PICKUP][REJECTED", reason .. (tracker.Error and " | " .. tracker.Error or ""))
	if self.Config.DIAGNOSTIC_SETTINGS.LOG_PICKUP_DETAIL_PATHS then
		for _, example in ipairs(report.Examples) do self.Controller:Log("PICKUP][REJECTED", example) end
	end
end

function FarmingCoordinator:StartObservations()
	local hatch = self.Config.PET_SETTINGS.ENABLE_PET_INTELLIGENCE and self.Config.PET_SETTINGS.AUTO_HATCH and self.Config.HATCH_SETTINGS.ENABLE_BACKGROUND_PICKUPS
	if self.ObservationThread or not self.Config.FARMING_SETTINGS.AUTO_RESOURCE_FARM and not hatch then return end
	self.ObservationThread = task.spawn(function()
		while not self.Destroyed do
			task.wait(self.Config.FARMING_SETTINGS.OBSERVATION_INTERVAL_SECONDS)
			if not self.Destroyed then self:Observe() end
		end
	end)
end

function FarmingCoordinator:Context(plan)
	local now = os.clock()
	local tracker, mechanics = self.Tracker, self.Mechanics
	local islands, areaRates = {}, {}
	for _, area in pairs(tracker.Areas) do
		area.ActualUnlocked = mechanics:Unlocked(area.World, area.Name)
		area.InBackoff = not mechanics:Available("ISLAND:" .. area.Key)
		local destination = area.Spawn and area.Spawn:GetFullName() or area.DestinationPath
		if destination then
			area.InBackoff = area.InBackoff or not mechanics:Available("TRAVEL:" .. destination)
			area.TravelSeconds = mechanics.TravelTimes and mechanics.TravelTimes[destination]
		end
		table.insert(islands, area) areaRates[area.Key] = self:_pickupRates(area.Key, now)
	end
	local allowed, reason = mechanics:Guard()
	local canBlow, bubbleReason = mechanics:CanBlow()
	canBlow = canBlow and mechanics:Available("BLOW")
	local raw = self.Reader:GetLiveProfile()
	local currentKey = tracker.Current and tracker.Current.Key or "UNKNOWN"
	local snapshot = self.Reader:GetSnapshot()
	local context = { Current = tracker.Current, Islands = islands, AreaRates = areaRates,
		SceneReady = tracker.LastZoneRefresh > -math.huge and tracker.Error == nil,
		Rates = self:_pickupRates(currentKey, now), Sells = mechanics:SellStations(), CanInteract = allowed,
		CanBlow = canBlow, CanTravel = self.Config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND
			and now - mechanics.LastTravelAt >= self.Config.ISLAND_SETTINGS.TRAVEL_COOLDOWN_SECONDS,
		Blocker = reason or tracker.Error, BlowBlocker = bubbleReason, Now = now, ArrivedAt = tracker.ArrivedAt,
		ReturnKey = self.ReturnKey,
		PendingCleanup = mechanics.PendingPickupCleanup ~= nil,
		UpgradeBackoff = {}, EffectiveUpgrades = {},
		FullSince = self.FullSince,
		CombinedProbePending = self.CombinedProbeStart and now - self.CombinedProbeStart < self.Config.FARMING_SETTINGS.BUBBLE_PROBE_TIMEOUT_SECONDS
			and not (self.CombinedEvidence[currentKey] and self.CombinedEvidence[currentKey].SaleAt),
		BubbleProbePending = self.ProbeStart and now - self.ProbeStart.At < self.Config.FARMING_SETTINGS.BUBBLE_PROBE_TIMEOUT_SECONDS
			and not self.SaleEvidence[currentKey] and raw and raw.Bubble and raw.Bubble.Amount > self.ProbeStart.Amount,
		PickupProbe = self.PickupProbe, IslandProbeHistory = self.IslandProbeHistory }
	table.sort(islands, function(a, b) return a.Key < b.Key end)
	for _, upgrade in ipairs((snapshot.AvailableProgression or {}).Upgrades or {}) do
		context.UpgradeBackoff[upgrade.Name] = not mechanics:Available("UPGRADE:" .. upgrade.Name)
		local enabled = upgrade.Kind == "Gum" and self.Config.BUBBLE_SETTINGS.AUTO_BUY_GUM
			or (upgrade.Kind == "Flavors" and self.Config.BUBBLE_SETTINGS.AUTO_BUY_FLAVORS)
		if raw and raw.Bubble and enabled and upgrade.Accessible and upgrade.OwnershipKnown and not upgrade.Owned then
			local cost = upgrade.Cost
			if cost and type(raw[cost.Currency]) == "number" and type(cost.Amount) == "number" and cost.Amount <= raw[cost.Currency]
				and cost.Amount <= self.Config.UPGRADE_SETTINGS.MAXIMUM_PURCHASE_COST then
				-- Project only the equipment field in a detached table; the received profile is never mutated.
				local projected = table.clone(raw) projected.Bubble = table.clone(raw.Bubble)
				projected.Bubble[upgrade.Kind == "Gum" and "Gum" or "Flavor"] = upgrade.Name
				context.EffectiveUpgrades[upgrade.Name] = { Capacity = self.Reader:_stat("GetBubbleStorage", projected, {}),
					Power = self.Reader:_stat("GetBubblePower", projected, {}) }
			end
		end
	end
	local currency = FarmingPolicy.Target(self.Config, snapshot, plan, context)
	if not currency and self.Config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST then currency = self.Config.FARMING_SETTINGS.CURRENCY_PRIORITIES[1] end
	context.Cluster = currency and tracker:Cluster(currency) or nil
	local candidate, stationaryReason = self.Stationary:Candidate(context.Cluster)
	if not candidate then context.Cluster = nil tracker.ClusterReason = stationaryReason end
	context.PickupUnavailableReason = tracker.Error or tracker.ClusterReason
	context.ActiveSweepPending = false
	-- A zero-yield completed trial must not be advertised as proven bubble income merely because time elapsed.
	if not self.SaleEvidence[currentKey] and context.Rates.BUBBLES then context.Rates.BUBBLES.Ready = false end
	return context
end

function FarmingCoordinator:_logUpgrades(decision)
	if not self.Config.DIAGNOSTIC_SETTINGS.LOG_UPGRADE_DIAGNOSTICS or not decision.UpgradeEvaluations then return end
	local now = os.clock()
	if now - (self.LastUpgradeLogAt or -math.huge) < math.max(10, self.Config.DIAGNOSTIC_SETTINGS.MINIMUM_LOG_INTERVAL_SECONDS) then return end
	self.LastUpgradeLogAt = now self.UpgradeLogSignatures = self.UpgradeLogSignatures or {}
	local count = 0
	for _, row in ipairs(decision.UpgradeEvaluations) do
		local reasons = table.concat(row.Reasons, "; ")
		local signature = tostring(row.Eligible) .. ":" .. tostring(row.Owned) .. ":" .. reasons
		if self.UpgradeLogSignatures[row.Name] == signature then continue end
		if count >= self.Config.DIAGNOSTIC_SETTINGS.MAXIMUM_LOG_ENTRIES then break end
		count += 1 self.UpgradeLogSignatures[row.Name] = signature
		self.Controller:Log("UPGRADE][CANDIDATE", row.Name .. " | " .. row.Kind .. " | owned=" .. tostring(row.Owned) .. " | cost=" .. tostring(row.Cost and row.Cost.Amount) .. " " .. tostring(row.Cost and row.Cost.Currency))
		local projection = row.Projection or {}
		self.Controller:Log("UPGRADE][EVALUATION", row.Name .. " | strategy=" .. tostring(decision.Mode) .. " | balance=" .. tostring(row.Balance) .. " budget=" .. tostring(row.Budget)
			.. " resource reserve=" .. tostring(row.Reserve) .. " goal reserve=" .. tostring(row.GoalReserve) .. " | blows/fill=" .. tostring(row.BlowsPerFill)
			.. " urgent capacity=" .. tostring(row.CapacityUrgent) .. " | projected capacity=" .. tostring(projection.Capacity) .. " power=" .. tostring(projection.Power)
			.. " | measured bubble income=" .. tostring(row.BubbleIncome) .. " | estimated discounted payback=" .. tostring(row.Payback))
		self.Controller:Log(row.Eligible and "UPGRADE][EVALUATION" or "UPGRADE][REJECTED", row.Name .. " | " .. (row.Eligible and "Eligible; Brain chooses the qualified candidate with shortest estimated payback" or reasons))
	end
end

function FarmingCoordinator:Select(plan)
	local context = self:Context(plan)
	local decision = self.Controller.Brain:PlanFarming(self.Reader:GetSnapshot(), plan, context)
	self.Decision = decision
	self:_logUpgrades(decision)
	local signature = decision.Kind .. ":" .. tostring(decision.Mode) .. ":" .. tostring(decision.Currency) .. ":" .. (decision.Island and decision.Island.Key or "")
	if signature ~= self.LastDecisionSignature or os.clock() - self.LastLogAt >= math.max(5, self.Config.DIAGNOSTIC_SETTINGS.MINIMUM_LOG_INTERVAL_SECONDS) then
		self.LastDecisionSignature, self.LastLogAt = signature, os.clock()
		self.Controller:Log("FARM][GOAL", tostring(decision.Goal) .. " | required=" .. tostring(decision.Currency) .. " | deficit=" .. tostring(decision.Deficit or "no fixed deficit"))
		for index, candidate in ipairs(decision.IslandCandidates) do
			if index > self.Config.DIAGNOSTIC_SETTINGS.MAXIMUM_LOG_ENTRIES then break end
			self.Controller:Log("FARM][ISLANDS", string.format("%s | %s %s/min | %s | overhead %.1fs | respawn %s", candidate.Key,
				candidate.PerMinute and string.format("%.2f", candidate.PerMinute) or "unknown",
				candidate.Currency, candidate.Evidence, candidate.TravelSeconds, tostring(candidate.RespawnSeconds or "unknown") .. " (observation latency; streaming may contribute)"))
		end
		if self.Config.DIAGNOSTIC_SETTINGS.LOG_ISLAND_DISCOVERY then
			for index, row in ipairs(decision.IslandDiagnostics or {}) do
				if index > self.Config.DIAGNOSTIC_SETTINGS.MAXIMUM_LOG_ENTRIES then break end
				local area, pools = row.Area, {}
				self.DiscoveryLogSignatures = self.DiscoveryLogSignatures or {}
				local discoverySignature = tostring(area.WorldUnlocked) .. ":" .. tostring(area.Discovered) .. ":" .. tostring(area.AtCurrentLocation) .. ":" .. tostring(area.ZoneCount) .. ":" .. row.Reason
				if self.DiscoveryLogSignatures[area.Key] ~= discoverySignature then
				self.DiscoveryLogSignatures[area.Key] = discoverySignature
				self.Controller:Log("FARM][DISCOVERY", string.format("%s | worldUnlocked=%s discovered=%s current=%s | zones=%d configured=%s visible=%d eligible=%d unidentified=%d | destination=%s | %s",
					area.Key, tostring(area.WorldUnlocked), tostring(area.Discovered), tostring(area.AtCurrentLocation), area.ZoneCount or #(area.Zones or {}),
					area.UnknownZoneCount and "partial/unknown" or tostring(area.ConfiguredCount), area.VisibleCount or 0, area.EligibleCount or 0, area.UnknownCount or 0,
					area.Spawn and area.Spawn:GetFullName() or (area.DestinationPath and area.DestinationPath .. " (native path; local part absent)" or "unavailable"), row.Reason))
				end
				local zoneSignature = tostring(area.ZoneCount) .. ":" .. tostring(area.TransitZoneCount or 0) .. ":" .. tostring(area.ConfiguredCount)
				self.ZoneLogSignatures = self.ZoneLogSignatures or {}
				local changedZones = self.ZoneLogSignatures[area.Key] ~= zoneSignature
				if changedZones then
					self.ZoneLogSignatures[area.Key] = zoneSignature
					self.Controller:Log("FARM][ZONES", area.Key .. " | surface zones=" .. tostring(area.ZoneCount) .. " | jump-stage transit zones=" .. tostring(area.TransitZoneCount or 0) .. " (excluded from island routing/yield)")
				end
				if changedZones and self.Config.DIAGNOSTIC_SETTINGS.LOG_PICKUP_DETAIL_PATHS and (area.MappingWarning or area.ZoneCount == 0) then
					for _, zone in ipairs(area.Zones or {}) do
						if #pools >= 3 then break end table.insert(pools, zone.Root:GetFullName())
					end
					if #pools > 0 then self.Controller:Log("FARM][ZONES", table.concat(pools, "; ")) end
				end
			end
		end
		self.Controller:Log(decision.Kind == "WAIT" and "FARM][FALLBACK" or "FARM][DECISION", decision.Kind .. "/" .. tostring(decision.Mode) .. " | " .. decision.Reason)
		if decision.SellComparison then
			local comparison = decision.SellComparison
			self.Controller:Log("FARM][SELL_POLICY", "estimated selling overhead=" .. tostring(comparison.SellSeconds) .. "s | estimated lost pickups=" .. tostring(comparison.LostPickupEstimate)
				.. " | estimated sale value=" .. tostring(comparison.SaleValueEstimate) .. " | delayed=" .. tostring(comparison.Delayed))
		end
		for mode, entry in pairs(context.Rates) do
			if mode == "PICKUPS" and context.Rates.STATIONARY then continue end
			if entry.Ready then
				self.Controller:Log("FARM][EARNINGS", string.format("%s observed sample %.1fs | %.2f %s/min | external rewards can affect attribution",
					mode, entry.Seconds, entry.PerMinute[decision.Currency] or 0, tostring(decision.Currency)))
			end
		end
	end
	return decision
end

function FarmingCoordinator:_settle(token, seconds, tick, finished)
	local deadline = os.clock() + seconds
	while not token:CheckCancelled() and os.clock() < deadline do
		if finished and finished() then break end
		if tick then tick() end
		task.wait(0.1)
	end
end

function FarmingCoordinator:_awaitCredit(before, token, currencies, tick, stopAt)
	local deadline = os.clock() + self.Config.FARMING_SETTINGS.EARNINGS_CONFIRMATION_TIMEOUT_SECONDS
	if stopAt then deadline = math.min(deadline, stopAt) end
	local after = self.Reader:ReadBalances()
	while not token:CheckCancelled() and os.clock() < deadline do
		for currency, value in pairs(after) do if (not currencies or currencies[currency]) and before[currency] ~= nil and value > before[currency] then return after end end
		if tick then tick() end
		task.wait(0.1) after = self.Reader:ReadBalances()
	end
	return after
end

function FarmingCoordinator:_worldFundingPending(decision)
	local plan = self.Controller.Plan
	local goal = plan and plan.Objective
	local progression = goal and goal.Metadata and goal.Metadata.Progression
	if decision.GoalId and decision.GoalId ~= (goal and goal.Id) then return false end
	if not progression or progression.Node.Kind ~= "WORLD" then return true end
	local live = self.Reader:GetLiveProfile()
	if live and live.WorldsUnlocked and live.WorldsUnlocked[progression.Node.Name] ~= nil then return false end
	local snapshot = table.clone(self.Reader:GetSnapshot())
	snapshot.Balances = self.Reader:ReadBalances() -- Recheck received balances even before the next planning refresh.
	return FarmingPolicy.Target(self.Config, snapshot, plan, {}) == decision.Currency
end

function FarmingCoordinator:_collection(decision, token)
	if token:CheckCancelled() then return nil end
	if decision.Mode ~= "PICKUPS" then return { Verified = false, Reason = "Currency goals permit stationary pickups only; no combined bubble task" } end
	local cluster = decision.Cluster
	if not self.Config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS or not cluster then return { Verified = false, Reason = "Stationary collection disabled or IDs unavailable" } end
	if not FarmingPolicy.IsStationaryArea(self.Config, self.Tracker.Current) or self.Tracker.Current.Key ~= cluster.AreaKey then
		return { Verified = false, Reason = "Stationary execution rejected: excluded or stale island" }
	end
	return self.Stationary:Collect(decision, token, function() return self:_worldFundingPending(decision) end)
end

function FarmingCoordinator:_bubble(token)
	if self.Config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST then return { Verified = false, Reason = "Isolated stationary test blocks blowing" } end
	if not self.Config.BUBBLE_SETTINGS.AUTO_BLOW_BUBBLES then return { Verified = false, Reason = "Blowing disabled" } end
	local raw = self.Reader:GetLiveProfile()
	local before = raw and raw.Bubble and raw.Bubble.Amount
	local maximum = before
	local beforeBalances = self.Reader:ReadBalances()
	local requests, deadline = 0, os.clock() + self.Config.FARMING_SETTINGS.ACTION_SLICE_SECONDS
	while not token:CheckCancelled() and os.clock() < deadline do
		local allowed, reason = self.Mechanics:CanBlow()
		if not allowed then self.Mechanics.LastBlocker = reason break end
		local live = self.Reader:GetLiveProfile()
		if live and live.Bubble and type(live.Bubble.Amount) == "number" then maximum = math.max(maximum or 0, live.Bubble.Amount) end
		local capacity = live and self.Reader:_stat("GetBubbleStorage", live, {})
		if live and live.Bubble and capacity and live.Bubble.Amount / capacity >= self.Config.BUBBLE_SETTINGS.SELL_AT_CAPACITY_RATIO then break end
		if self.Mechanics:Blow(token) then requests += 1 end
		task.wait(0.1)
	end
	local live = self.Reader:GetLiveProfile()
	local after = live and live.Bubble and live.Bubble.Amount
	local afterBalances = self.Reader:ReadBalances()
	local income = false
	for currency, value in pairs(afterBalances) do if beforeBalances[currency] and value > beforeBalances[currency] then income = true end end
	local changed = type(before) == "number" and type(maximum) == "number" and maximum > before or income
	if income and self.Metrics.Active then self.SaleEvidence[self.Metrics.Active.Scope] = true end
	if requests > 0 and not changed and not token:CheckCancelled() then self.Mechanics:Failure("BLOW", 10, "No bubble growth confirmed") end
	self.Controller:Log("FARM][BUBBLE", "requests=" .. requests .. " | actual amount " .. tostring(before) .. " -> " .. tostring(after)
		.. " | " .. tostring(self.Mechanics.LastBlocker or "awaiting native sale for currency yield"))
	return { Verified = changed, Reason = self.Mechanics.LastBlocker }
end

function FarmingCoordinator:_sell(decision, token)
	if not self.Mechanics:BubbleRequirement() then return { Verified = false, Reason = "Selling blocked: no active verified bubble requirement" } end
	if self.Config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST then return { Verified = false, Reason = "Isolated stationary test blocks selling and travel" } end
	local sell = decision.Sell
	if not self.Config.BUBBLE_SETTINGS.AUTO_SELL_BUBBLES or not sell then return { Verified = false, Reason = "Selling disabled" } end
	local raw = self.Reader:GetLiveProfile()
	local beforeAmount = raw and raw.Bubble and raw.Bubble.Amount
	local before = self.Reader:ReadBalances()
	local started = os.clock()
	local current = self.Tracker.Current
	local sameArea = current and current.World == sell.World and current.Name == sell.Area
	if not sameArea and FarmingPolicy.IsFarmingArea(self.Config, current) then
		self.ReturnKey = current.Key
		self.Controller:Log("FARM][RETURN", "Saved farming destination " .. current.Key .. "; selling excursion permits travel outside farming selection")
	end
	self.Controller:Log("FARM][SELL_TIMING", "dispatch | threshold age=" .. tostring(self.FullSince and os.clock() - self.FullSince or "unknown") .. "s | travel/activation/credit bounded separately")
	local permitted, reason
	local root = self.Tracker:Root()
	if sameArea and root and ((root.Position - sell.Root.Position) * Vector3.new(1, 0, 1)).Magnitude <= sell.Root.Size.Y / 2
		and math.abs(root.Position.Y - sell.Root.Position.Y) <= 10 then
		permitted = true -- Native activation already in range; no OC movement.
	else
		self.Controller:Log("FARM][TRAVEL", "Native selling-station travel to " .. sell.Key .. " | currency=" .. sell.Currency .. " | multiplier=" .. sell.Multiplier)
		permitted, reason = self.Mechanics:Travel(sell.Root, sell.World, sell.Area, token, false, true)
	end
	if not permitted or token:CheckCancelled() then
		if not token:CheckCancelled() then self.Mechanics:Failure("SELL:" .. sell.Key, self.Config.BUBBLE_SETTINGS.SELL_RETRY_COOLDOWN_SECONDS, reason) end
		return { Verified = false, Reason = reason }
	end
	local deadline = os.clock() + self.Config.BUBBLE_SETTINGS.SELL_CONFIRMATION_TIMEOUT_SECONDS
	while not token:CheckCancelled() and os.clock() < deadline do
		local live = self.Reader:GetLiveProfile()
		local root = self.Tracker:Root()
		if not root or not sell.Root.Parent then break end
		local horizontal = ((root.Position - sell.Root.Position) * Vector3.new(1, 0, 1)).Magnitude
		if horizontal > sell.Root.Size.Y / 2 or math.abs(root.Position.Y - sell.Root.Position.Y) > 10 then
			self.Mechanics:StopMovement() reason = "Native sell activation range was not reached" break
		end
		if live and live.Bubble and type(beforeAmount) == "number" and live.Bubble.Amount < beforeAmount then
			local after = self:_awaitCredit(before, token, { [sell.Currency] = true })
			if token:CheckCancelled() then return nil end
			if type(before[sell.Currency]) ~= "number" or type(after[sell.Currency]) ~= "number" or after[sell.Currency] <= before[sell.Currency] then
				self.Controller:Log("FARM][SELL", "Bubble decreased; matching station-currency credit unconfirmed")
				self.Mechanics:Failure("SELL:" .. sell.Key, self.Config.BUBBLE_SETTINGS.SELL_RETRY_COOLDOWN_SECONDS, "Station-currency credit unconfirmed")
				self.Cycle = nil
				return { Verified = false, BubbleReduced = true, Reason = "Station-currency credit unconfirmed; return remains pending" }
			end
			local gains = self.Metrics:ConfirmCycle(before, after, "Native bubble sale")
			local active = self.Metrics.Active
			if active and next(gains) then self.SaleEvidence[active.Scope] = true end
			if next(gains) then
				if self.Cycle then self.Cycle.SaleAt = os.clock() end
				self.Mechanics.SellTimes = self.Mechanics.SellTimes or {} self.Mechanics.SellTimes[sell.Key] = os.clock() - started
				if active and active.Mode == "COMBINED" then
					local evidence = self.CombinedEvidence[active.Scope] or {} self.CombinedEvidence[active.Scope] = evidence
					evidence.SaleAt = os.clock() self.CombinedProbeStart = nil
				end
			end
			self.ProbeStart = nil
			self.FullSince = nil
			self.Controller:Log("FARM][SELL", string.format("Actual bubble amount %.0f -> %.0f | station multiplier %.2f | %s", beforeAmount, live.Bubble.Amount, sell.Multiplier, self.Metrics.LastConfirmation))
			self.Controller:Log("FARM][EARNINGS", "before: " .. balancesText(before) .. " | after: " .. balancesText(after))
			if not self.ReturnKey then self:_finishCombined() end
			return { Verified = next(gains) ~= nil, BubbleReduced = true, Gains = gains }
		end
		task.wait(0.2)
	end
	if not token:CheckCancelled() then self.Mechanics:Failure("SELL:" .. sell.Key, self.Config.BUBBLE_SETTINGS.SELL_RETRY_COOLDOWN_SECONDS, reason or "Native sale not confirmed") end
	return { Verified = false, Reason = reason or "Native sale not confirmed" }
end

function FarmingCoordinator:Definition(decision, generation)
	if decision.Kind == "WAIT" then return nil end
	return { Id = "OC_GAMEPLAY", Priority = 10, Generation = generation,
		TimeoutSeconds = self.Config.FARMING_SETTINGS.ACTION_SLICE_SECONDS + self.Config.ISLAND_SETTINGS.TRAVEL_CONFIRMATION_TIMEOUT_SECONDS
			+ self.Config.BUBBLE_SETTINGS.SELL_CONFIRMATION_TIMEOUT_SECONDS + self.Config.UPGRADE_SETTINGS.PURCHASE_CONFIRMATION_TIMEOUT_SECONDS + 5,
		CanRun = function() return not self.Destroyed and self.Controller.State == "RUNNING" and generation == self.Controller.Generation end,
		Execute = function(token)
			if token:CheckCancelled() or generation ~= self.Controller.Generation then return nil end
			if decision.Mode == "COMBINED" then return { Verified = false, Reason = "Background bubble farming is disabled; active goals choose one activity" } end
			if decision.Kind == "SELL" or decision.Mode == "BUBBLES" then
				local actual = self.Mechanics:BubbleRequirement()
				local expected = decision.Requirement
				if not actual or not expected or actual.QuestId ~= expected.QuestId or actual.TaskIndex ~= expected.TaskIndex
					or decision.GoalId ~= (self.Controller.Plan and self.Controller.Plan.Objective and self.Controller.Plan.Objective.Id) then
					return { Verified = false, Reason = "Stale or unverified bubble goal; no action dispatched" }
				end
			end
			if decision.GoalId and decision.GoalId ~= (self.Controller.Plan and self.Controller.Plan.Objective and self.Controller.Plan.Objective.Id) then
				return { Verified = false, Reason = "Active goal changed before farming dispatch" }
			end
			if self.Config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST and decision.Kind ~= "INSPECT"
				and (decision.Kind ~= "FARM" or decision.Mode ~= "PICKUPS")
				and (decision.Kind ~= "TRAVEL" or not self.Config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND or not FarmingPolicy.IsStationaryArea(self.Config, decision.Island)) then
				return { Verified = false, Reason = "Pickup-only mode permits selected-island travel, inspection and stationary collection only" }
			end
			if decision.Kind == "TRAVEL" and not FarmingPolicy.IsStationaryArea(self.Config, decision.Island) then return { Verified = false, Reason = "Travel destination excluded or stale" } end
			if decision.Kind == "TRAVEL" and not decision.Returning and not self:_worldFundingPending(decision) then
				return { Verified = false, Reason = "World funding shortage ended or is no longer verified; farming travel cancelled" }
			end
			if decision.Kind == "FARM" and decision.Mode ~= "BUBBLES" and
				(not FarmingPolicy.IsFarmingArea(self.Config, self.Tracker.Current) or not decision.Cluster or decision.Cluster.AreaKey ~= self.Tracker.Current.Key) then
				return { Verified = false, Reason = "Pickup execution rejected: excluded or stale island" }
			end
			self.Activity = decision
			local scope = self.Tracker.Current and self.Tracker.Current.Key or "UNKNOWN"
			local beforeBalances = self.Reader:ReadBalances()
			if decision.Probe and decision.Kind ~= "TRAVEL" and not self.PickupProbe then self:_beginPickupProbe(scope, decision.Currency) end
			if decision.Kind == "FARM" then
				if decision.Mode == "COMBINED" then self:_beginCombined(scope) end
				self.Metrics:SetMode(decision.Mode == "PICKUPS" and "STATIONARY" or decision.Mode, scope, beforeBalances, os.clock())
				if decision.Mode == "COMBINED" and not self.CombinedProbeStart then self.CombinedProbeStart = os.clock() end
				if decision.Mode == "BUBBLES" and not self.ProbeStart then
					local raw = self.Reader:GetLiveProfile()
					self.ProbeStart = raw and raw.Bubble and { Amount = raw.Bubble.Amount, At = os.clock() } or nil
				end
			elseif decision.Kind == "INSPECT" then
				self.Mechanics:RetryPickupCleanup(token)
				local ready = self.PickupProbe and os.clock() >= self.PickupProbe.ReadyAt
				self.Metrics:SetMode(nil, scope, beforeBalances, os.clock())
			elseif decision.Kind ~= "SELL" or (self.Metrics.Active and (self.Metrics.Active.Mode == "PICKUPS" or self.Metrics.Active.Mode == "STATIONARY")) then
				-- A standalone bubble sale cannot count as isolated pickup income.
				self.Metrics:SetMode(nil, scope, beforeBalances, os.clock())
				if decision.Kind == "SELL" and self.PickupProbe then
					self.IslandProbeHistory[self.PickupProbe.Key .. ":" .. self.PickupProbe.Currency] = os.clock()
					self.PickupProbe = nil
					self.Controller:Log("FARM][EXPLORE", "Pickup trial interrupted by required selling; sale excluded from isolated pickup income")
				end
			end
			if decision.Kind == "TRAVEL" then
				local area = decision.Island
				if decision.Probe or decision.Exploration then self.IslandProbeHistory[area.Key .. ":" .. decision.Currency] = os.clock() end
				self.Controller:Log("FARM][TRAVEL", "Request " .. area.Key .. " through native unlocked island Teleport | " .. decision.Reason)
				local success, reason, seconds = self.Mechanics:TravelIsland(area, token)
				if success then
					self.Tracker:Refresh(self.Reader:GetSnapshot(), os.clock())
					local actual = self.Tracker.Current
					success = actual ~= nil and actual.Key == area.Key
					if success then
						self.Controller:Log("FARM][TRAVEL", "Arrival and island identity confirmed: " .. area.Key .. " | " .. tostring(seconds) .. "s")
						if decision.Probe then self:_beginPickupProbe(area.Key, decision.Currency) end
						if self.ReturnKey then
							self.Controller:Log("FARM][RETURN", "Confirmed return to " .. area.Key .. "; farming resumes through Brain")
							self.ReturnKey = nil self:_finishCombined()
						end
					end
				end
				if not success and not token:CheckCancelled() then
					self.Mechanics:Failure("ISLAND:" .. area.Key, self.Config.ISLAND_SETTINGS.TRAVEL_RETRY_COOLDOWN_SECONDS, reason or "Island identity uncertain")
					self.Controller:Log("FARM][TRAVEL", "Unconfirmed arrival: " .. area.Key .. " | " .. tostring(reason))
				end
				return { Verified = success, Reason = reason }
			elseif decision.Kind == "INSPECT" then
				local duration = math.min(2, self.Config.FARMING_SETTINGS.ACTION_SLICE_SECONDS)
				local background = not self.Config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST and (decision.Background or (self.Config.FARMING_SETTINGS.FARMING_STRATEGY == "PICKUP_FIRST" and not decision.Probe))
				self:_settle(token, duration, background and function() self:_background(token) end or nil)
				if token:CheckCancelled() then return nil end
				self.Tracker:Refresh(self.Reader:GetSnapshot(), os.clock())
				return { Verified = false, Reason = "Pickup observation: " .. tostring(self.Tracker.ClusterReason or decision.Reason) }
			elseif decision.Kind == "SELL" then return self:_sell(decision, token)
			elseif decision.Kind == "UPGRADE" then
				local success, reason, evidence = self.Mechanics:Upgrade(decision.Upgrade, token)
				if token:CheckCancelled() then return nil end
				self.Controller:Log(success and "UPGRADE][VERIFIED" or "UPGRADE][REJECTED", decision.Upgrade.Name .. " | " .. tostring(reason) .. " | verified=" .. tostring(success))
				if success then
					self.Metrics.Samples = {} self.SaleEvidence = {} self.CombinedEvidence = {} self.ProbeStart = nil self.CombinedProbeStart = nil
					self.Controller.Brain.FarmingMemory = nil
				end
				return { Verified = success, Reason = reason, Evidence = evidence }
			elseif decision.Mode == "BUBBLES" then return self:_bubble(token)
			else return self:_collection(decision, token) end
		end,
		IsComplete = function(result) return type(result) == "table" end,
	}
end

function FarmingCoordinator:Completed(status, result, reason)
	self.Mechanics:StopMovement()
	self.Activity = nil
	self.Metrics:Observe(self.Reader:ReadBalances(), os.clock())
	if status == "FAILED" then self.Controller:Log("FARM][ERROR", tostring(result))
	elseif result and not result.Verified and not result.CombinedCreditObserved and result.Reason then
		local now = os.clock()
		if self.LastFallbackReason ~= result.Reason or now - (self.LastFallbackLogAt or -math.huge) >= math.max(5, self.Config.DIAGNOSTIC_SETTINGS.MINIMUM_LOG_INTERVAL_SECONDS) then
			self.LastFallbackReason, self.LastFallbackLogAt = result.Reason, now
			self.Controller:Log("FARM][FALLBACK", result.Reason)
		end
	elseif status == "CANCELLED" then self.Controller:Log("FARM][CANCELLED", tostring(reason)) end
	self:Observe()
end

function FarmingCoordinator:Halt(preserveReturn)
	self.Mechanics:StopMovement()
	self.Metrics:SetMode(nil, nil, self.Reader:ReadBalances(), os.clock())
	self.Activity = nil self.ProbeStart = nil self.PendingSale = nil self.EmptySince = {} self.PickupProbe = nil self.FullSince = nil self.CombinedProbeStart = nil
	self.RouteContinuation = nil self.Cycle = nil
	self.Stationary.LastSampleAt, self.Stationary.LastSampleArea = nil, nil -- Resumed sessions exclude paused time without resetting ID deduplication.
	self.Knowledge:ReleaseChunkerObserver()
	if not preserveReturn then self.ReturnKey = nil end
end

function FarmingCoordinator:GetStatus()
	local current = self.Tracker.Current
	return { Activity = self.Activity and (self.Activity.Mode or self.Activity.Kind), Decision = self.Decision,
		Strategy = self.Config.FARMING_SETTINGS.FARMING_STRATEGY, ReturnIsland = self.ReturnKey, FullSince = self.FullSince,
		Cycle = self.Cycle and { Id = self.Cycle.Id, Island = self.Cycle.Scope, Requests = self.Cycle.Requests, SaleAt = self.Cycle.SaleAt },
		Area = current and current.Key, VisiblePickups = current and current.VisibleCount or 0,
		EligiblePickups = current and current.EligibleCount or 0, UnknownPickups = current and current.UnknownCount or 0,
		Disappeared = self.Tracker.Disappeared, ObservedSpawns = self.Tracker.ObservedSpawns,
		RespawnObservations = self.Tracker.RespawnObservations, Radius = self.Tracker.Range, CollectionVisits = self.CollectionVisits,
		Rates = self:_pickupRates(current and current.Key or "UNKNOWN", os.clock()), Scan = self.Tracker.ScanReport, CollectionBlocker = self.Tracker.ClusterReason,
		ConfirmedCycles = self.Metrics.ConfirmedCycles, LastConfirmation = self.Metrics.LastConfirmation,
		Error = self.Tracker.Error, GameKnowledge = self.Knowledge:GetStatus(), Stationary = self.Stationary:GetStatus(),
		CleanupBlocker = self.Mechanics.PendingPickupCleanup and self.Mechanics.PendingPickupCleanup.Reason,
		CollectionMethod = "Continuous stationary ID batches; batch credit checked against LocalData; no movement fallback" }
end

function FarmingCoordinator:Destroy()
	self:Halt() self.Destroyed = true
	if self.ObservationThread then pcall(task.cancel, self.ObservationThread) end
	self.Tracker:Destroy()
	self.Knowledge:Destroy()
end

return FarmingCoordinator

end

-- src/OCFoundation/FarmingPolicy.luau
factories["FarmingPolicy"] = function()
--!nonstrict
-- Pure decision policy used exclusively by OCBrain. Executors cannot choose their own activities.
local FarmingPolicy = {}
local UpgradePolicy = requireOC("UpgradePolicy")
local function allowed(list, value) return #list == 0 or table.find(list, value) ~= nil end
local function reserve(config, currency)
	local field = ({ Coins = "COIN_RESERVE", Gems = "GEM_RESERVE", Tickets = "TICKET_RESERVE", Pearls = "PEARL_RESERVE" })[currency]
	if currency == "Leaves26" then return config.FALL_EVENT_SETTINGS.LEAF_RESERVE end
	if currency == "RebirthShards26" then return config.FALL_EVENT_SETTINGS.REBIRTH_SHARD_RESERVE end
	return field and config.RESOURCE_SETTINGS[field] or 0
end
local function rate(context, mode, currency)
	local entry = context.Rates[mode]
	return entry and entry.Ready and entry.PerMinute[currency] or nil
end

function FarmingPolicy.IsFarmingArea(config, area)
	return area ~= nil and area.Unlocked == true
		and (allowed(config.ISLAND_SETTINGS.SELECTED_ISLANDS, area.Name) or table.find(config.ISLAND_SETTINGS.SELECTED_ISLANDS, area.Key) ~= nil)
		and allowed(config.BRAIN_SETTINGS.SELECTED_WORLDS, area.World)
end

function FarmingPolicy.IsStationaryArea(config, area)
	return FarmingPolicy.IsFarmingArea(config, area) and area.World == "The Overworld" and (area.Name == "The Void" or area.Name == "Zen")
end

function FarmingPolicy.IncomeTarget(config, snapshot, plan, context)
	local candidates = {}
	if plan.Objective then table.insert(candidates, plan.Objective) end
	for _, candidate in ipairs(plan.Candidates or {}) do if candidate ~= plan.Objective then table.insert(candidates, candidate) end end
	for _, candidate in ipairs(candidates) do
		local cost = candidate.Metadata and candidate.Metadata.Cost
		if cost and cost.Type == "Currency" and type(cost.Amount) == "number" and snapshot.Balances[cost.Currency] ~= nil
			and allowed(config.PICKUP_SETTINGS.FARM_CURRENCY_TYPES, cost.Currency) then
			local required = cost.Amount + reserve(config, cost.Currency)
			if candidate.Metadata.Upgrade then required = cost.Amount / config.RESOURCE_SETTINGS.MAXIMUM_UPGRADE_BALANCE_FRACTION + reserve(config, cost.Currency) end
			if snapshot.Balances[cost.Currency] < required then
				return cost.Currency, candidate, required - snapshot.Balances[cost.Currency]
			end
		end
	end
	for _, currency in ipairs(config.FARMING_SETTINGS.CURRENCY_PRIORITIES) do
		if not allowed(config.PICKUP_SETTINGS.FARM_CURRENCY_TYPES, currency) then continue end
		for _, area in ipairs(context.Islands or {}) do if area.Unlocked and area.Currencies[currency] then return currency, plan.Objective, nil end end
		for _, sell in ipairs(context.Sells or {}) do if sell.Currency == currency then return currency, plan.Objective, nil end end
	end
	return nil, plan.Objective, nil
end

function FarmingPolicy.CompareIncome(config, snapshot, plan, context, memory)
	-- Retained pure historical income evaluator. Active Brain decisions use Decide below;
	-- its combined/probe recommendations are never submitted as gameplay tasks.
	local decision = { Kind = "WAIT", Reason = "Waiting for supported farming data", IslandCandidates = {}, IslandDiagnostics = {}, Currency = nil }
	if not config.FARMING_SETTINGS.AUTO_RESOURCE_FARM or not snapshot.Ready or not config.GENERAL_SETTINGS.ENABLE_RECOMMENDATIONS then
		decision.Reason = "Farming disabled or real account/planner not ready" return decision
	end
	if context.SceneReady == false then decision.Reason = context.Blocker or "Waiting for actual zone inspection before selecting a farming activity" return decision end
	local preferred = config.ISLAND_SETTINGS.PREFERRED_FARMING_ISLAND
	if preferred ~= "" and config.ISLAND_SETTINGS.AUTO_SELECT_BEST_ISLAND and config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND then
		local destination, fallback, returning
		for _, area in ipairs(context.Islands or {}) do
			if not FarmingPolicy.IsStationaryArea(config, area) or area.ActualUnlocked ~= true then continue end
			if context.ReturnKey == area.Key then returning = area end
			if area.Name == preferred then destination = area else fallback = area end
		end
		destination = returning or destination or fallback
		if not destination then decision.Reason = "Neither selected farming island has confirmed LocalData world/island access; no unlock or invalid teleport attempted" return decision end
		decision.PreferredIsland = destination.Key
		local current = context.Current
		if not current or current.Key ~= destination.Key then
			if context.CanInteract and context.CanTravel and not destination.InBackoff and (destination.Spawn or destination.DestinationPath) then
				decision.Kind, decision.Island, decision.Returning = "TRAVEL", destination, returning ~= nil
				decision.Reason = returning and "Return to the saved farming island after selling" or "Native island travel: prefer unlocked " .. preferred .. "; The Void is the approved fallback"
			else
				decision.Kind = "INSPECT"
				decision.Reason = "Preferred farming island travel pending: " .. tostring(context.Blocker or (destination.InBackoff and "destination retry backoff" or "native destination/cooldown unavailable"))
			end
			return decision
		end
		if context.Now - (context.ArrivedAt or context.Now) < config.ISLAND_SETTINGS.ARRIVAL_PICKUP_GRACE_SECONDS then
			decision.Kind, decision.Reason = "INSPECT", "Waiting for selected island/character state to stabilize before stationary collection"
			return decision
		end
	end
	if config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST then
		decision.Goal = "Stationary Coins/Gems farming with isolated balance logging"
		if not FarmingPolicy.IsStationaryArea(config, context.Current) then
			decision.Reason = "Selected unlocked island required; enable native island travel or position manually"
		elseif not context.CanInteract then decision.Reason = context.Blocker or "Native interaction guard"
		elseif context.Cluster then
			decision.Kind, decision.Mode, decision.Cluster = "FARM", "PICKUPS", context.Cluster
			decision.Currency = context.Cluster.Currency or "Coins"
			decision.Reason = "Continuous paced stationary ID batches; verify LocalData credit"
		else
			decision.Kind = "INSPECT"
			decision.Reason = context.PickupUnavailableReason or "Waiting for live stationary pickup IDs; no movement fallback"
		end
		return decision
	end
	local currency, goal, deficit = FarmingPolicy.IncomeTarget(config, snapshot, plan, context)
	decision.Currency, decision.Goal, decision.Deficit = currency, goal and goal.Title, deficit
	if not currency then decision.Reason = "No allowed goal currency with an accessible earning source" return decision end
	local current = context.Current
	local currentAllowed = FarmingPolicy.IsFarmingArea(config, current)
	local pickupFirst = config.FARMING_SETTINGS.FARMING_STRATEGY == "PICKUP_FIRST"
	local activeProbe = context.PickupProbe
	local isolated = activeProbe and current and activeProbe.Key == current.Key and activeProbe.Currency == currency
	local bestSell, bestSellScore
	for _, sell in ipairs(context.Sells or {}) do
		if sell.Currency ~= currency then continue end
		local walking = false -- OC walking was removed. Future selling uses separately configured native travel.
		local canTravel = config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND and context.CanTravel
		if not walking and not canTravel then continue end
		local travel = walking and sell.Distance / math.max(1, context.WalkSpeed or 16)
			or sell.TravelSeconds or config.ISLAND_SETTINGS.UNMEASURED_TRAVEL_OVERHEAD_SECONDS
		local bubble = snapshot.Bubble
		local fillSeconds = bubble.Capacity and bubble.PowerPerBlow and bubble.PowerPerBlow > 0
			and bubble.Capacity / bubble.PowerPerBlow * config.BUBBLE_SETTINGS.BLOW_COOLDOWN_SECONDS or nil
		local score = sell.Multiplier / math.max(1, (fillSeconds or 60) + travel + 2)
		if not bestSell or score > bestSellScore then bestSell, bestSellScore = sell, score end
	end
	local bubble = snapshot.Bubble or {}
	local full = bubble.Amount and bubble.Capacity and bubble.Capacity > 0 and bubble.Amount / bubble.Capacity >= config.BUBBLE_SETTINGS.SELL_AT_CAPACITY_RATIO
	-- Sell an existing full bubble even when its station pays a different resource; do not value that payout as target currency.
	if full and config.BUBBLE_SETTINGS.AUTO_SELL_BUBBLES then
		if not context.CanInteract then decision.Reason = "Sale pending: " .. tostring(context.Blocker or "native interaction guard") return decision end
		local sell = bestSell
		if not sell then
			for _, candidate in ipairs(context.Sells or {}) do
				local sameArea = false
				if sameArea or (config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND and context.CanTravel) then
					if not sell or candidate.Distance < sell.Distance then sell = candidate end
				end
			end
		end
		if sell then
			local pickupRate, bubbleRate = rate(context, "PICKUPS", currency), rate(context, "BUBBLES", currency)
			local sellSeconds = sell.SellCycleSeconds or (sell.TravelSeconds or sell.Distance / math.max(1, context.WalkSpeed or 16)) + 2
			local fillSeconds = bubble.Capacity and bubble.PowerPerBlow and bubble.PowerPerBlow > 0 and bubble.Capacity / bubble.PowerPerBlow * config.BUBBLE_SETTINGS.BLOW_COOLDOWN_SECONDS
			local lostPickups = pickupRate and pickupRate * sellSeconds / 60
			local saleEstimate = bubbleRate and fillSeconds and bubbleRate * (fillSeconds + sellSeconds) / 60
			local delay = not isolated and currentAllowed and (pickupFirst or memory.Mode == "COMBINED") and config.BUBBLE_SETTINGS.ENABLE_SIMULTANEOUS_BLOWING and context.Cluster
				and config.BUBBLE_SETTINGS.AUTO_BLOW_BUBBLES and config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS and config.PICKUP_SETTINGS.ENABLE_CONTINUOUS_SCANNING
				and context.CanInteract and context.FullSince and context.Now - context.FullSince < config.FARMING_SETTINGS.MAXIMUM_COMBINED_SELL_DELAY_SECONDS
				and lostPickups and saleEstimate and lostPickups > saleEstimate
			decision.SellComparison = { LostPickupEstimate = lostPickups, SaleValueEstimate = saleEstimate, SellSeconds = sellSeconds, Delayed = delay == true }
			if delay then
				decision.Kind, decision.Mode, decision.Cluster, decision.Sell = "FARM", "COMBINED", context.Cluster, sell
				decision.Reason = "Briefly finish valuable pickup coverage with a full bubble; bounded sell delay, no further blowing"
			else decision.Kind, decision.Sell, decision.Reason = "SELL", sell, "Bubble reached sell threshold; verify native sale before producing more" end
			return decision
		end
		decision.Reason = "Sale pending: no accessible station or native travel cooldown/backoff"
		return decision
	end
	local bestIsland, currentScore = nil, nil
	if config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS and config.PICKUP_SETTINGS.ENABLE_CONTINUOUS_SCANNING then
		for _, area in ipairs(context.Islands or {}) do
			local exclusion
			if decision.PreferredIsland and area.Key ~= decision.PreferredIsland then exclusion = "Excluded by preferred farming island"
			elseif not area.Unlocked then exclusion = "World locked/unknown or island not discovered"
			elseif not (allowed(config.ISLAND_SETTINGS.SELECTED_ISLANDS, area.Name) or table.find(config.ISLAND_SETTINGS.SELECTED_ISLANDS, area.Key) ~= nil) then exclusion = "Excluded by SELECTED_ISLANDS"
			elseif not allowed(config.BRAIN_SETTINGS.SELECTED_WORLDS, area.World) then exclusion = "Excluded by SELECTED_WORLDS"
			elseif area.ZoneCount == 0 then exclusion = "No live tagged PickupZone; availability unknown"
			elseif area.MappingWarning then exclusion = area.MappingWarning
			elseif not area.Currencies[currency] then exclusion = "Native pool has no goal currency " .. currency
			elseif area.InBackoff then exclusion = "Empty island or failed travel in backoff"
			elseif area ~= current and not (area.Spawn or area.DestinationPath) then exclusion = "No verified native island destination"
			elseif area ~= current and (not config.ISLAND_SETTINGS.AUTO_SELECT_BEST_ISLAND or not config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND) then exclusion = "Island selection/travel disabled" end
			table.insert(decision.IslandDiagnostics, { Area = area, Reason = exclusion or "Eligible; off-island pickup availability remains unknown" })
			if exclusion then continue end
			local rates = context.AreaRates[area.Key] or {}
			local observed = rates.PICKUPS and rates.PICKUPS.Ready and rates.PICKUPS or rates.PICKUP_ACTIVITY
			local measured = observed and observed.Ready and observed.PerMinute[currency] or nil
			local cycle = config.ISLAND_SETTINGS.UNMEASURED_COLLECTION_CYCLE_SECONDS
			local overhead = area == current and 0 or area.TravelSeconds or config.ISLAND_SETTINGS.UNMEASURED_TRAVEL_OVERHEAD_SECONDS
			local estimate = area.Expected[currency] and area.Expected[currency] * 60 / math.max(1, cycle) or nil
			local value = measured ~= nil and measured or estimate
			local net = value and value * cycle / math.max(1, cycle + overhead) or nil
			local emptyCurrent = area == current and (area.Available[currency] or 0) == 0
			if measured == nil and emptyCurrent then net = nil end
			local entry = { Key = area.Key, Name = area.Name, Currency = currency, PerMinute = net,
				Evidence = measured ~= nil and (observed == rates.PICKUPS and "OBSERVED" or "OBSERVED_PICKUP_ACTIVITY: excludes sale/return; external rewards may contribute") or (net and "ESTIMATE: definitions, actual stat multiplier, unknown availability/respawn" or (emptyCurrent and "UNKNOWN: no eligible current-island models; requires bounded scan/collection trial" or "UNKNOWN: zone count/stat multiplier unavailable; requires actual trial")), Area = area,
				TravelSeconds = overhead, RespawnSeconds = area.RespawnSeconds, RespawnEvidence = "depletion-to-next-observed-model latency; streaming may contribute" }
			table.insert(decision.IslandCandidates, entry)
			if area == current then currentScore = net end
			if net and (not bestIsland or net > bestIsland.PerMinute or (net == bestIsland.PerMinute and area.Key < bestIsland.Key)) then bestIsland = entry end
		end
	end
	table.sort(decision.IslandCandidates, function(a, b)
		if a.PerMinute == b.PerMinute then return a.Key < b.Key end
		return (a.PerMinute or -1) > (b.PerMinute or -1)
	end)
	-- Mandatory return/enforcement precedes dwell, active sweeps and income comparisons.
	local destination
	if context.ReturnKey then
		for _, entry in ipairs(decision.IslandCandidates) do if entry.Key == context.ReturnKey then destination = entry.Area break end end
	end
	if not currentAllowed or (context.ReturnKey and context.ReturnKey ~= (current and current.Key)) then
		destination = destination or (bestIsland and bestIsland.Area) or (decision.IslandCandidates[1] and decision.IslandCandidates[1].Area)
		if destination and destination ~= current and context.CanTravel and context.CanInteract then
			decision.Kind, decision.Island, decision.Returning = "TRAVEL", destination, context.ReturnKey ~= nil
			decision.Reason = context.ReturnKey and "Return after selling to an eligible farming island" or "Current island excluded; travel to an eligible farming island"
		else
			decision.Kind, decision.Background = "INSPECT", pickupFirst
			decision.Reason = "Farming island return/enforcement pending: " .. tostring(context.Blocker or "travel cooldown, destination backoff or no eligible island")
		end
		return decision
	end
	if bestIsland and currentAllowed and bestIsland.Area ~= current and current.Currencies[currency] and not current.InBackoff then
		if context.Now - (context.ArrivedAt or 0) < config.ISLAND_SETTINGS.MIN_ISLAND_DWELL_SECONDS
			or ((currentScore or 0) > 0 and bestIsland.PerMinute <= currentScore * (1 + config.ISLAND_SETTINGS.MIN_ISLAND_GAIN_ADVANTAGE_PERCENT / 100)) then
			for _, entry in ipairs(decision.IslandCandidates) do if entry.Area == current then bestIsland = entry break end end
		end
	end
	local cluster = context.Cluster
	local pickupReady = currentAllowed and not current.InBackoff and config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS and config.PICKUP_SETTINGS.ENABLE_CONTINUOUS_SCANNING and cluster ~= nil and context.CanInteract
	local bubbleReady = config.BUBBLE_SETTINGS.AUTO_BLOW_BUBBLES and config.BUBBLE_SETTINGS.AUTO_SELL_BUBBLES and bestSell ~= nil and context.CanBlow and not full
	local backgroundReady = config.BUBBLE_SETTINGS.AUTO_BLOW_BUBBLES and config.BUBBLE_SETTINGS.ENABLE_SIMULTANEOUS_BLOWING and context.CanBlow and not full
	-- Execute exploration through the same foreground task. Never manufacture income for an untested island.
	local explore = config.ISLAND_SETTINGS.AUTO_EXPLORE_UNLOCKED_ISLANDS and config.FARMING_SETTINGS.ENABLE_EFFICIENCY_COMPARISON
		and config.FARMING_SETTINGS.ENABLE_ACTIVITY_SWITCHING and config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS and config.PICKUP_SETTINGS.ENABLE_CONTINUOUS_SCANNING
	if explore and isolated then
		decision.Probe = true
		if context.Now < (activeProbe.ReadyAt or activeProbe.StartedAt) then
			decision.Kind = "INSPECT" decision.Reason = "Arrival loading grace; continue scanning before pickup measurement"
		elseif pickupReady then
			decision.Kind, decision.Mode, decision.Cluster, decision.Sell = "FARM", "PICKUPS", cluster, bestSell
			decision.Reason = "Isolated pickup trial; measure actual balances before comparing with bubble sales"
		else decision.Kind = "INSPECT" decision.Reason = "Bounded pickup observation: " .. tostring(context.PickupUnavailableReason or "no eligible models") end
		return decision
	end
	if explore and not activeProbe and context.CanInteract and not context.ActiveSweepPending
		and not context.BubbleProbePending and context.Now - (context.ArrivedAt or 0) >= config.ISLAND_SETTINGS.MIN_ISLAND_DWELL_SECONDS then
		local trial, oldest = nil, math.huge
		for _, entry in ipairs(decision.IslandCandidates) do
			local area = entry.Area
			if pickupFirst and not config.FARMING_SETTINGS.ISOLATED_PICKUP_PROBES and area == current then continue end
			local stamp = (context.IslandProbeHistory or {})[area.Key .. ":" .. currency]
			-- A measured trial need not be repeated while its observed sample is still current.
			if entry.Evidence:sub(1, 8) == "OBSERVED" then continue end
			local last = stamp or -math.huge
			if context.Now - last < config.ISLAND_SETTINGS.ISLAND_EXPLORATION_RETRY_SECONDS then continue end
			if area ~= current and not context.CanTravel then continue end
			if not trial or last < oldest or (last == oldest and (area == current or (trial.Area ~= current and area.Key < trial.Key))) then trial, oldest = entry, last end
		end
		if trial then
			decision.Probe = not pickupFirst or config.FARMING_SETTINGS.ISOLATED_PICKUP_PROBES
			decision.Exploration = true
			if trial.Area ~= current then
				decision.Kind, decision.Island = "TRAVEL", trial.Area
				decision.Reason = "Bounded exploration of " .. trial.Key .. "; pickup earnings unverified; background blowing follows configured strategy"
				return decision
			else
				decision.Kind = "INSPECT"
				decision.Reason = "Begin bounded loading/scanning trial on the current island"
				return decision
			end
		end
	end
	local choices = {}
	if pickupReady then table.insert(choices, "PICKUPS") end
	if bubbleReady then table.insert(choices, "BUBBLES") end
	if pickupReady and bubbleReady and config.BUBBLE_SETTINGS.ENABLE_SIMULTANEOUS_BLOWING then table.insert(choices, "COMBINED") end
	if not config.FARMING_SETTINGS.AUTO_FARM_FALLBACK and memory.Mode and not table.find(choices, memory.Mode) then
		decision.Reason = "Preferred activity unavailable; fallback is disabled" return decision
	end
	local mode, modeScore
	if config.FARMING_SETTINGS.ENABLE_EFFICIENCY_COMPARISON then
		for _, candidate in ipairs(choices) do
			local measured = rate(context, candidate, currency)
			if measured and (not modeScore or measured > modeScore) then mode, modeScore = candidate, measured end
		end
	elseif table.find(choices, "COMBINED") then
		mode = "COMBINED"
	end
	-- Unknown modes get bounded probes, rather than fabricated income rates.
	local untested, oldestTest = nil, math.huge
	for _, candidate in ipairs(choices) do
		local lastTest = memory.LastTest[candidate] or -math.huge
		if candidate ~= memory.Mode and (not memory.Mode or context.Now - memory.StartedAt >= config.FARMING_SETTINGS.MINIMUM_ACTIVITY_HOLD_SECONDS)
			and context.Now - lastTest >= config.FARMING_SETTINGS.EXPLORATION_INTERVAL_SECONDS and lastTest < oldestTest then
			untested, oldestTest = candidate, lastTest
		end
	end
	if config.FARMING_SETTINGS.ENABLE_EFFICIENCY_COMPARISON and untested then mode = untested modeScore = nil end
	mode = mode or choices[1]
	if memory.Mode and table.find(choices, memory.Mode) then
		local age = context.Now - memory.StartedAt
		local currentRate = rate(context, memory.Mode, currency)
		if not config.FARMING_SETTINGS.ENABLE_ACTIVITY_SWITCHING or age < config.FARMING_SETTINGS.MINIMUM_ACTIVITY_HOLD_SECONDS
			or (modeScore and currentRate and modeScore <= currentRate * (1 + config.FARMING_SETTINGS.ACTIVITY_SWITCH_GAIN_RATIO)) then mode = memory.Mode end
		if (memory.Mode == "BUBBLES" and context.BubbleProbePending or memory.Mode == "COMBINED" and context.CombinedProbePending)
			and age < config.FARMING_SETTINGS.BUBBLE_PROBE_TIMEOUT_SECONDS then mode = memory.Mode end
	end
	if pickupFirst then
		mode = pickupReady and (backgroundReady and "COMBINED" or "PICKUPS") or (config.FARMING_SETTINGS.AUTO_FARM_FALLBACK and bubbleReady and "BUBBLES" or nil)
	end
	modeScore = mode and rate(context, mode, currency) or nil
	if bestIsland and bestIsland.Area ~= current and bestIsland.PerMinute > 0 and context.CanTravel and context.CanInteract
		and not (context.ActiveSweepPending and pickupReady) then
		local currentIncome = 0
		if pickupFirst then currentIncome = pickupReady and (rate(context, "PICKUPS", currency) or currentScore or 0) or 0
		else for _, viable in ipairs(choices) do currentIncome = math.max(currentIncome, rate(context, viable, currency) or 0) end end
		if currentIncome == 0 or bestIsland.PerMinute > currentIncome * (1 + config.FARMING_SETTINGS.ACTIVITY_SWITCH_GAIN_RATIO) then
			decision.Kind = "TRAVEL" decision.Island = bestIsland.Area
			decision.Reason = string.format("Best eligible %s island: %s; %.2f/min %s after %.1fs travel overhead", currency, bestIsland.Name, bestIsland.PerMinute, bestIsland.Evidence, bestIsland.TravelSeconds)
			return decision
		end
	end
	if not mode then
		if pickupFirst then decision.Kind, decision.Background = "INSPECT", true end
		decision.Reason = context.Blocker or "No reachable relevant pickups or useful bubble selling route" return decision
	end
	decision.Kind, decision.Mode, decision.Cluster, decision.Sell = "FARM", mode, cluster, bestSell
	decision.Reason = pickupFirst and (pickupReady and (backgroundReady and "Pickup-first farming with guarded background blowing" or "Pickup-first farming; background blow blocked: " .. tostring(context.BlowBlocker or "full/disabled/native guard")) or "Pickup-first fallback: no actionable pickup cluster")
		or modeScore and string.format("Observed %.2f %s/min supports the current goal", modeScore, currency)
		or "Bounded " .. mode .. " trial; observed balances will establish earning efficiency"
	local upgrade, evaluations = UpgradePolicy.Evaluate(config, snapshot, plan, context, currency, mode, bestSell, goal)
	decision.UpgradeEvaluations = evaluations
	if upgrade then
		decision.Kind, decision.Upgrade = "UPGRADE", upgrade.Upgrade
		decision.Reason = upgrade.Upgrade.Owned and "Use a verified better owned upgrade without spending"
			or string.format("Native stat projection; estimated discounted payback %.1fs; protected goal funds %.0f", upgrade.Row.Payback, upgrade.Row.GoalReserve)
	end
	return decision
end

function FarmingPolicy.Requirement(snapshot, plan)
	local expected = plan and plan.Objective and plan.Objective.Metadata and plan.Objective.Metadata.Requirement
	if not expected then return nil end
	for _, actual in ipairs(snapshot.TaskRequirements or {}) do
		if actual.QuestId == expected.QuestId and actual.TaskIndex == expected.TaskIndex and actual.Type == expected.Type
			and actual.Currency == expected.Currency and actual.Current < actual.Required then return actual end
	end
	return nil
end

function FarmingPolicy.Target(config, snapshot, plan, context)
	local goal = plan and plan.Objective
	if not goal then return nil end
	local requirement = FarmingPolicy.Requirement(snapshot, plan)
	if requirement and requirement.Type == "Collect" then return requirement.Currency, goal, requirement.Required - requirement.Current end
	local cost = goal.Metadata and goal.Metadata.Cost
	local balances = snapshot.Balances or {}
	if cost and cost.Type == "Currency" and (cost.Currency == "Coins" or cost.Currency == "Gems")
		and type(cost.Amount) == "number" and cost.Amount >= 0 and cost.Amount < math.huge and type(balances[cost.Currency]) == "number" then
		local required = cost.Amount + reserve(config, cost.Currency)
		if goal.Metadata.Upgrade then required = cost.Amount / config.RESOURCE_SETTINGS.MAXIMUM_UPGRADE_BALANCE_FRACTION + reserve(config, cost.Currency) end
		if balances[cost.Currency] < required then return cost.Currency, goal, required - balances[cost.Currency] end
	end
	return nil, goal
end

function FarmingPolicy.Decide(config, snapshot, plan, context, memory)
	local decision = { Kind = "WAIT", Reason = "No verified resource requirement in the active goal; bubble production and selling remain off",
		IslandCandidates = {}, IslandDiagnostics = {}, Goal = plan.Objective and plan.Objective.Title, GoalId = plan.Objective and plan.Objective.Id }
	if not config.FARMING_SETTINGS.AUTO_RESOURCE_FARM or not snapshot.Ready or not config.GENERAL_SETTINGS.ENABLE_RECOMMENDATIONS then
		decision.Reason = "Farming disabled or actual account/planner not ready" return decision
	end
	local currency, _, deficit = FarmingPolicy.Target(config, snapshot, plan, context)
	local requirement = FarmingPolicy.Requirement(snapshot, plan)
	local bubbleGoal = requirement and (requirement.Type == "Bubbles" or requirement.Type == "Sell")
	local diagnostic = config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST and not currency and not bubbleGoal
	if diagnostic then currency = config.FARMING_SETTINGS.CURRENCY_PRIORITIES[1] end -- Explicit pickup diagnostic; no bubble objective is invented.
	decision.Currency, decision.Deficit, decision.Requirement = currency, deficit, requirement
	local bubbleActionsDisabled = not config.BUBBLE_SETTINGS.AUTO_BLOW_BUBBLES and not config.BUBBLE_SETTINGS.AUTO_SELL_BUBBLES
	if not currency and (not bubbleGoal or bubbleActionsDisabled) and not context.ReturnKey then
		if bubbleGoal then decision.Reason = "Actual bubble task pending, but blowing and selling are disabled; no island travel" end
		if context.PendingCleanup then decision.Kind, decision.Reason = "INSPECT", "Finish pending cleanup of an already-dispatched pickup; no new farming goal" end
		return decision
	end
	if currency and currency ~= "Coins" and currency ~= "Gems" then decision.Reason = "Only Coins/Gems pickup farming is approved" return decision end
	if context.SceneReady == false then decision.Reason = context.Blocker or "Waiting for native scene observations" return decision end
	local preferred = currency == "Coins" and "The Void" or currency == "Gems" and "Zen" or nil
	if diagnostic then preferred = config.ISLAND_SETTINGS.PREFERRED_FARMING_ISLAND ~= "" and config.ISLAND_SETTINGS.PREFERRED_FARMING_ISLAND or preferred end
	local destination, fallback, returning
	for _, area in ipairs(context.Islands or {}) do
		local access = area.ActualUnlocked
		if access == nil then access = snapshot.UnlockedWorlds and snapshot.UnlockedWorlds[area.World] ~= nil and snapshot.UnlockedIslands and snapshot.UnlockedIslands[area.Name] ~= nil end
		if not FarmingPolicy.IsStationaryArea(config, area) or not access then continue end
		if context.ReturnKey == area.Key then returning = area end
		if area.Name == preferred then destination = area
		elseif not fallback or area.Key == (context.Current and context.Current.Key) then fallback = area end
	end
	if destination and (destination.MappingWarning or (destination.InBackoff and destination.Key ~= (context.Current and context.Current.Key))
		or (destination.Key ~= (context.Current and context.Current.Key) and not destination.Spawn and not destination.DestinationPath)) then destination = nil end
	local retained
	if memory.TargetCurrency == currency then
		for _, area in ipairs(context.Islands or {}) do
			if area.Key == memory.TargetIsland and FarmingPolicy.IsStationaryArea(config, area) and area.ActualUnlocked == true and not area.MappingWarning
				and (not area.InBackoff or area.Key == (context.Current and context.Current.Key)) then retained = area end
		end
	end
	destination = returning or retained or destination or fallback
	if not destination then decision.Reason = "Neither selected farming island has confirmed LocalData access; no invalid teleport or unlock attempted" return decision end
	local limitation
	if preferred and destination.Name ~= preferred and not returning then
		if retained and destination == retained then
			limitation = "Retain " .. destination.Name .. " for unchanged " .. currency .. " goal; preferred " .. preferred .. " previously unavailable"
		else limitation = preferred .. " unavailable/locked; evaluate " .. destination.Name .. " for " .. currency end
	end
	decision.Limitation, decision.PreferredIsland = limitation, destination.Key
	if currency and not returning and not (destination.Currencies or {})[currency] then
		decision.Reason = (limitation and limitation .. "; " or "") .. "Native reward pool has no matching currency"
		return decision
	end
	if currency and not returning then memory.TargetCurrency, memory.TargetIsland = currency, destination.Key end
	local current = context.Current
	if not current or current.Key ~= destination.Key then
		if config.ISLAND_SETTINGS.AUTO_SELECT_BEST_ISLAND and config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND and context.CanTravel and context.CanInteract
			and not destination.InBackoff and not destination.MappingWarning and (destination.Spawn or destination.DestinationPath) then
			decision.Kind, decision.Island, decision.Returning = "TRAVEL", destination, returning ~= nil
			decision.Reason = returning and "Return to intended farming island after required bubble selling" or (limitation or "Active " .. tostring(currency or "bubble") .. " goal prefers " .. destination.Name)
		else decision.Kind, decision.Reason = "INSPECT", (limitation and limitation .. "; " or "") .. "Native selected-island travel pending: " .. tostring(context.Blocker or "disabled, cooldown/backoff or missing destination") end
		return decision
	end
	if config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND and context.Now - (context.ArrivedAt or context.Now) < config.ISLAND_SETTINGS.ARRIVAL_PICKUP_GRACE_SECONDS then
		decision.Kind, decision.Reason = "INSPECT", "Waiting for stable selected island arrival" return decision
	end
	if not context.CanInteract then decision.Reason = context.Blocker or "Native interaction guard" return decision end
	if not currency and not bubbleGoal then return decision end -- A completed selling task still returns before going idle.
	if currency then
		decision.Kind = "INSPECT"
		decision.Reason = (limitation and limitation .. "; " or "") .. "Wait for genuine stationary " .. currency .. " pickup IDs; bubbles and selling off"
		if context.Cluster and config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS and config.PICKUP_SETTINGS.ENABLE_CONTINUOUS_SCANNING then
			decision.Kind, decision.Mode, decision.Cluster = "FARM", "PICKUPS", context.Cluster
			decision.Reason = (limitation and limitation .. "; " or "") .. "Stationary pickups for active " .. currency .. " requirement; no bubble cycle"
		end
		return decision
	end
	if config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST then decision.Reason = "Pickup diagnostic blocks bubble actions" return decision end
	local amount, capacity = (snapshot.Bubble or {}).Amount, (snapshot.Bubble or {}).Capacity
	local needsSale = requirement.Type == "Sell" and amount and amount > 0 or amount and capacity and capacity > 0 and amount / capacity >= config.BUBBLE_SETTINGS.SELL_AT_CAPACITY_RATIO
	if needsSale then
		if not config.BUBBLE_SETTINGS.AUTO_SELL_BUBBLES then decision.Reason = "Real bubble task requires selling; AUTO_SELL_BUBBLES is off" return decision end
		local sell
		for _, station in ipairs(context.Sells or {}) do if not sell or station.Distance < sell.Distance then sell = station end end
		if sell and context.CanTravel then decision.Kind, decision.Sell, decision.Reason = "SELL", sell, "Native selling required by the actual bubble task"
		else decision.Reason = "Actual bubble task awaits an accessible native selling route" end
	elseif config.BUBBLE_SETTINGS.AUTO_BLOW_BUBBLES and context.CanBlow then
		decision.Kind, decision.Mode, decision.Reason = "FARM", "BUBBLES", "Blow only for the actual unfinished native bubble task"
	else decision.Reason = "Actual bubble task pending: " .. tostring(context.BlowBlocker or "AUTO_BLOW_BUBBLES is off") end
	return decision
end

return FarmingPolicy

end

-- src/OCFoundation/GameKnowledge.luau
factories["GameKnowledge"] = function()
--!nonstrict
-- ReplicatedStorage knowledge facade. Reuses the approved reader's dependency cache;
-- it neither loads future systems nor executes actions or substitutes account/world facts.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")
local GameKnowledge = {}
local PetPolicy = requireOC("PetPolicy")
GameKnowledge.__index = GameKnowledge

local pickupContract = table.freeze({
	DefinitionSource = "ReplicatedStorage.Shared.Data.Worlds",
	ZoneInterface = "ReplicatedStorage.Shared.Utils.GetPickupZones",
	AssetSource = "ReplicatedStorage.Assets.Pickups",
	SpawnSource = "ReplicatedStorage.Remotes.Pickups.SpawnPickups",
	ClientEvidence = "StarterPlayer.StarterPlayerScripts.ClientScript:1134-1344",
	InitialRenderPath = "Workspace.Rendered.Pickups",
	RenderedPath = "Workspace.Rendered.Chunker (all native folders with this name)",
	ActiveRegistry = "ReplicatedStorage.Client.Tutorial._activePickups",
	RegistryEvidence = "ClientScript:1137-1140,1255-1279; Client.Tutorial:44,522",
	ParentEvidence = "ReplicatedStorage.Shared.Utils.Chunker:33-55,118-167",
	PositionSource = "Actual Model:GetPivot().Position; spawn payload contains Root/Visual/Id, not an exact position",
	IdOrigin = "Received SpawnPickups payload Id; generation is server-side/unavailable",
	ExistingPickupSync = "Read current native registry; past spawn events are not replayed",
	RenderedClass = "Model",
	RangeMethod = "StatsUtil:GetPickupRange(profile)",
	CollectionOwner = "Native radius collector plus scheduler-owned stationary ID batches; per-ID server acceptance unknown",
	OwnerEvidence = "Owner approved Phase 2 stationary collection, visual cleanup, native travel and goal-driven routing; individual request acceptance is not established",
	CleanupEvidence = "ClientScript:1243-1279 destroys Models and calls native Chunker.Remove; OC removes the native chunk and matching registry entry only after dispatch",
	IslandWideBatchFound = false,
	Evidence = "CLIENT_SOURCE_INSPECTED; execution requires owner verification",
	ServerValidation = "UNAVAILABLE",
})

function GameKnowledge.new(reader) return setmetatable({ Reader = reader }, GameKnowledge) end

function GameKnowledge:Get(name)
	-- Returning the same native dependency avoids competing discovery/require loops.
	return self.Reader:_dependency(name)
end

function GameKnowledge:Assets(name)
	local assets = ReplicatedStorage:FindFirstChild("Assets")
	return assets and assets:FindFirstChild(name)
end

function GameKnowledge:PetContract()
	return { Definitions = "Shared.Data.Eggs/Pets + native builders",
		Stats = "Shared.Utils.Stats.PetUtil:GetStats; StatsUtil:GetCurrencyMultiplier/GetBubblePower on detached team projections",
		Pool = "Client.Gui.LootPoolViewer:601-613; GetEggPool; ApplyMultiplierToPool; GetRandomWeightedItem normalizes Chance weights",
		Probability = "CLIENT_UI_ESTIMATE; effective server Secret/Infinity/variant/pity odds UNKNOWN",
		Hatch = "ClientScript:569,616,879,926-931,986-1025; unopened prompt <=6.5 studs, opened egg <=16; account cost/capacity, NextEggOpenAt; HatchEgg(name,count)",
		Equip = "Client.Gui.Frames.Inventory:2140-2192; EquipPet/UnequipPet(base ID); duplicate team IDs represent stacked copies",
		EquipmentRules = "Inventory:2615-2637 EquipTeam exists, but this test preserves the current TeamEquipped; Locked:2229; no pet-favorite field found; no verified server cooldown",
		Space = "StatsUtil:GetUsedPetStorage ordinary Amount counts or Digital Storage JSON bytes; IsInventoryFull native guard; digital requests limited to one egg",
		Result = "Received LocalData.Pets and Teams[TeamEquipped].Pets multiplicity, not invocation or hatch animation",
		Actions = "OWNER_LIVE_PENDING", ServerValidation = "UNAVAILABLE" }
end

local function detached(value)
	if type(value) ~= "table" then return value end
	local result = {}
	for key, entry in pairs(value) do result[key] = detached(entry) end
	return result
end

local function native(object, method, ...)
	if not object or type(object[method]) ~= "function" then return nil end
	local ok, value = pcall(object[method], object, ...)
	if ok then return value end
	return nil
end

local function point(value)
	-- Coordinates are signed. PetPolicy.Finite deliberately rejects negative
	-- economic values and must never validate a world-space component.
	local function component(n) return type(n) == "number" and n == n and math.abs(n) < math.huge end
	return value and component(value.X) and component(value.Y) and component(value.Z)
end

local function eggParts(model)
	if not model or not model:IsA("Model") then return nil end
	local root, prompt = model:FindFirstChild("Root"), model:FindFirstChild("Prompt")
	if root and prompt and root.Parent == model and prompt.Parent == model
		and root:IsA("BasePart") and prompt:IsA("BasePart") and point(root.Position) and point(prompt.Position)
		and model:FindFirstChild("Plate") and model:FindFirstChild("Cost") then return root, prompt end
end

local function eggReceiver(receiver)
	local rendered = workspace:FindFirstChild("Rendered")
	return type(receiver) == "table" and receiver.Mode == "3D" and receiver._chunkSize == 128
		and receiver.RenderDistance == 2 and type(receiver._chunks) == "table" and type(receiver._loaded) == "table"
		and receiver._folder and receiver._folder.Parent == rendered and rendered ~= nil
end

local function classifyObservedEggQueue(receiver, class, definitions)
	-- Queue identity is distinct from private interaction/paid eligibility.
	if type(receiver) ~= "table" or type(class) ~= "table" or getmetatable(receiver) ~= class
		or type(receiver.Remove) ~= "function" or type(receiver.IsValueLoaded) ~= "function"
		or typeof(receiver._folder) ~= "Instance" or not receiver._folder:IsA("Folder")
		or not eggReceiver(receiver) then return false, "NATIVE_CLASS_OR_QUEUE_STRUCTURE_UNVERIFIED" end
	if type(definitions) ~= "table" then return false, "EGG_CATALOG_NOT_READY_FOR_POSITIVE_ANCHOR" end
	local coordinates, entries, loadedCoordinates, loadedCatalog = 0, 0, 0, 0
	for coord, loaded in pairs(receiver._loaded) do
		loadedCoordinates += 1
		if loadedCoordinates > 1000 then return false, "LOADED_COORDINATE_LIMIT_EXCEEDED" end
		if loaded ~= true then return false, "LOADED_FLAG_INCONSISTENT" end
		local values = receiver._chunks[coord]
		-- Native Remove can leave a true loaded flag with an absent bucket.
		if values ~= nil and type(values) ~= "table" then return false, "CHUNK_VALUES_NOT_TABLE" end
	end
	for coord, values in pairs(receiver._chunks) do
		coordinates += 1
		if coordinates > 1000 then return false, "COORDINATE_LIMIT_EXCEEDED" end
		if type(values) ~= "table" then return false, "CHUNK_VALUES_NOT_TABLE" end
		local loaded = receiver._loaded[coord] == true
		for index, value in pairs(values) do
			entries += 1
			if entries > 1000 then return false, "ENTRY_LIMIT_EXCEEDED" end
			if type(index) ~= "number" or index < 1 or index % 1 ~= 0 then return false, "UNSUPPORTED_MEMBER_KEY" end
			if typeof(value) ~= "Instance" or not value:IsA("Model") or not eggParts(value) then
				return false, "ORIGINAL_INTERFACE_OR_GEOMETRY_INCOMPLETE"
			end
			if loaded then
				if value.Parent ~= receiver._folder or not value:IsDescendantOf(workspace) then
					return false, "LOADED_MEMBER_ANCESTRY_INCONSISTENT"
				end
				if definitions[value.Name] then loadedCatalog += 1 end
			elseif value.Parent ~= nil then return false, "UNLOADED_MEMBER_ANCESTRY_INCONSISTENT" end
		end
	end
	if loadedCatalog == 0 then return false, "NO_LOADED_CATALOG_ORIGINAL_ANCHOR" end
	return true, "SOURCE_MATCHING_ORIGINAL_QUEUE_OBSERVED; private interaction/target eligibility checked separately"
end

function GameKnowledge:InstanceId(instance)
	if not instance then return "NONE" end
	self.InstanceIds = self.InstanceIds or setmetatable({}, { __mode = "k" })
	if not self.InstanceIds[instance] then
		self.InstanceSequence = (self.InstanceSequence or 0) + 1
		self.InstanceIds[instance] = string.format("I%04d", self.InstanceSequence)
	end
	return self.InstanceIds[instance]
end

function GameKnowledge:EggModels(force)
	if force or os.clock() - (self.LastEggScan or -math.huge) >= self.Reader.Config.PET_SETTINGS.ANALYSIS_INTERVAL_SECONDS then
		self.LastEggScan, self.NativeEggModels = os.clock(), {}
		local eggs = self:Get("Eggs") or {}
		-- All catalog-named Models are observations, not proof of registration.
		-- Include rendered copies in diagnostics; tags/names/paths are not identity.
		for _, model in ipairs(workspace:GetDescendants()) do
			if model:IsA("Model") and eggs[model.Name] then
				table.insert(self.NativeEggModels, model)
			end
		end
	end
	return self.NativeEggModels or {}
end

function GameKnowledge:ObserveEggModel(model)
	local def = (self:Get("Eggs") or {})[model.Name]
	local record = { Model = model, IdentityId = self:InstanceId(model), Verified = false, World = def and def.World,
		Island = model:GetAttribute("Island") or def and def.Island }
	local ok, path = pcall(function() return model:GetFullName() end)
	record.Path = ok and path or "UNKNOWN"
	record.ParentId = self:InstanceId(model.Parent)
	local root, prompt = eggParts(model)
	record.Root, record.Prompt = root, prompt
	if not model.Parent or not model:IsDescendantOf(workspace) then record.Reason = "UNLOADED_INSTANCE" return record end
	if not root then
		-- Native visual Clone gets Offset/Size and a Hitbox, not the original interface.
		record.Reason = "NON_INTERACTIVE_REPRESENTATION: original Root/Prompt/Plate/Cost interface absent"
		return record
	end
	local prompts = self:Get("ProximityPrompt")
	local engine = prompt:FindFirstChildOfClass("ProximityPrompt")
	record.NativePrompt = engine
	record.PromptCacheMember = engine ~= nil and type(prompts) == "table" and type(prompts._cache) == "table" and prompts._cache[engine] == true
	if record.PromptCacheMember and engine.Parent == prompt then
		record.Verified, record.IdentityEvidence = true, "EXACT_INITIAL_PROMPT_CACHE_MEMBERSHIP (ProximityPrompt:13,29-51; ClientScript:622)"
	end
	local registered, receivers = 0, 0
	for receiver in pairs(self.NativeEggChunkers or {}) do
		if not eggReceiver(receiver) then continue end
		receivers += 1
		if model.Parent ~= receiver._folder then continue end
		for coord in pairs(receiver._loaded) do
			local values = receiver._chunks[coord]
			local member = false
			if type(values) == "table" then
				for _, value in pairs(values) do
					if value == model then member = true break end
				end
			end
			if member then registered += 1 break end
		end
	end
	record.RegisteredReceivers = registered
	if self.EggObservationFinished and receivers == 1 then
		-- One source-matching receiver observed after native Update; membership is
		-- actual Instance equality. A same-parent/path captured copy is not a member.
		record.Verified = registered == 1
		record.IdentityEvidence = registered == 1 and "EXACT_LOADED_EGG_CHUNKER_MEMBERSHIP (ClientScript:375-376,747; Chunker:99-117,148-152)" or nil
	elseif self.EggObservationFinished and receivers > 1 then
		record.Verified = false record.Reason = "AMBIGUOUS_EGG_REGISTRATION_RECEIVER"
	end
	record.Reason = record.Reason or (record.Verified and "REGISTERED_INTERACTIVE_INSTANCE"
		or self.EggObservationFinished and "UNREGISTERED_PHYSICAL_REPRESENTATION_OR_UNKNOWN_REGISTRY"
		or "NATIVE_EGG_REGISTRATION_PENDING: bounded passive observation; no structural/name/path selection")
	return record
end

function GameKnowledge:InteractiveEggModels(force)
	self:ObserveEggChunker()
	local models = {}
	for _, model in ipairs(self:EggModels(force)) do
		if self:ObserveEggModel(model).Verified then table.insert(models, model) end
	end
	return models
end

function GameKnowledge:ResolveEggInstance(name, force, expectedModel)
	self:ObserveEggChunker()
	local observed = { Name = name, Candidates = {}, Count = 0, VerifiedCount = 0 }
	local receivers = 0 for receiver in pairs(self.NativeEggChunkers or {}) do if eggReceiver(receiver) then receivers += 1 end end
	local completeRegistry = self.EggObservationFinished and receivers == 1
	local chosen, unknown = nil, false
	for _, model in ipairs(self:EggModels(force)) do
		if model.Name ~= name then continue end
		local record = self:ObserveEggModel(model)
		observed.Count += 1 table.insert(observed.Candidates, record)
		if record.Verified then
			if not expectedModel or model == expectedModel then chosen = record end
			observed.VerifiedCount += 1
		elseif record.Root and not completeRegistry then unknown = true end
	end
	local reason
	if observed.VerifiedCount > 1 and not expectedModel then
		reason = "AMBIGUOUS_NATIVE_EGG_MODEL: multiple independently registered interactive Instances; exact target unresolved; no nearest/path substitution"
	elseif unknown then reason = self.EggObservationFinished and "NATIVE_EGG_IDENTITY_UNVERIFIED: unresolved physical candidates; native egg receiver unavailable/ambiguous; no travel attempt"
		or "NATIVE_EGG_REGISTRATION_PENDING: physical candidates lack complete current registration evidence; no travel attempt"
	elseif not chosen then reason = expectedModel and "Selected exact egg Instance lacks current registration; no name/path replacement or retarget"
		or observed.Count == 0 and "Selected egg model not loaded; no force-load"
		or "NATIVE_EGG_IDENTITY_UNVERIFIED: no unique current interactive registration; names/paths/attributes cannot authorize travel"
	elseif expectedModel and chosen.Model ~= expectedModel then reason = "Brain selected exact egg Instance changed; no name/path replacement or retarget" end
	observed.Reason = reason or (expectedModel and "EXACT_RETAINED_REGISTERED_INSTANCE; native interaction eligibility checked separately" or "UNIQUE_VERIFIED_INTERACTIVE_INSTANCE")
	return not reason and chosen or nil, reason, observed
end

function GameKnowledge:EggLocationCandidates(name, force)
	local definitions, worlds = self:Get("Eggs") or {}, self:Get("Worlds") or {}
	local def, profile = definitions[name], self.Reader:GetLiveProfile()
	local candidates, observations = {}, { Name = name, Count = 0, VerifiedCount = 0, LocationCount = 0, LocationVerifiedCount = 0, Candidates = {} }
	if type(def) ~= "table" or type(def.World) ~= "string" or def.Event or def.ProductId or def.IsAdminEgg or name == "Infinity Egg" then
		observations.Reason = "EGG_LOCATION_UNSUPPORTED: permanent native world/egg definition required" return candidates, observations
	end
	local worldDef = worlds[def.World]
	if type(worldDef) ~= "table" or worldDef.Removed or worldDef.Event or not profile or type(profile.WorldsUnlocked) ~= "table"
		or profile.WorldsUnlocked[def.World] == nil or type(profile.AreasUnlocked) ~= "table" then
		observations.Reason = "EGG_LOCATION_ACCESS_BLOCKED: actual world/island facts locked or unavailable" return candidates, observations
	end
	local sceneWorlds = workspace:FindFirstChild("Worlds")
	local worldModel = sceneWorlds and sceneWorlds:FindFirstChild(def.World)
	if not worldModel then observations.Reason = "EGG_LOCATION_WORLD_GEOMETRY_UNAVAILABLE" return candidates, observations end
	local function spatialArea(position)
		-- Mirrors native WorldUtil:12-38 and WorldMap:GetLocation:457-475 using
		-- current scene geometry, with conservative tie/missing-data rejection.
		local nearestWorld, distance, tie = nil, math.huge, false
		local worldNames = {}
		for _, entry in ipairs(sceneWorlds:GetChildren()) do
			if worldNames[entry.Name] then return nil, "EGG_LOCATION_AMBIGUOUS_WORLD_GEOMETRY" end
			worldNames[entry.Name] = true
			local spawn = entry:FindFirstChild("Spawn")
			if not spawn or not spawn:IsA("BasePart") or not point(spawn.Position) then return nil, "EGG_LOCATION_WORLD_SPAWN_UNAVAILABLE" end
			local delta = Vector3.new(position.X - spawn.Position.X, 0, position.Z - spawn.Position.Z).Magnitude
			if delta < distance - 0.05 then nearestWorld, distance, tie = entry.Name, delta, false
			elseif math.abs(delta - distance) <= 0.05 then tie = true end
		end
		if tie or nearestWorld ~= def.World then return nil, "EGG_LOCATION_WORLD_SPATIAL_MISMATCH_OR_TIE" end
		local spawn = worldModel:FindFirstChild("Spawn")
		local closest, vertical, areaTie = def.World, math.abs(position.Y - spawn.Position.Y), false
		local islands = worldModel:FindFirstChild("Islands")
		local areaNames = {}
		for _, entry in ipairs(worldDef.Islands or {}) do
			if areaNames[entry.Name] then return nil, "EGG_LOCATION_AMBIGUOUS_ISLAND_DEFINITION" end
			areaNames[entry.Name] = true
			local folder = islands and islands:FindFirstChild(entry.Name)
			local island = folder and folder:FindFirstChild("Island")
			local ok, pivot = pcall(function() return island:GetPivot() end)
			if not ok or not pivot or not point(pivot.Position) then return nil, "EGG_LOCATION_ISLAND_GEOMETRY_UNAVAILABLE: " .. tostring(entry.Name) end
			local delta = math.abs(position.Y - pivot.Position.Y)
			if delta < vertical - 0.05 then closest, vertical, areaTie = entry.Name, delta, false
			elseif math.abs(delta - vertical) <= 0.05 then areaTie = true end
		end
		if areaTie then return nil, "EGG_LOCATION_AMBIGUOUS_VERTICAL_AREA" end
		return closest
	end
	for _, model in ipairs(self:EggModels(force)) do
		if model.Name ~= name then continue end
		local observed = self:ObserveEggModel(model)
		observations.Count += 1 table.insert(observations.Candidates, observed)
		if observed.Verified then observations.VerifiedCount += 1 end
		if not model.Parent or not model:IsDescendantOf(workspace) then observed.LocationReason = "EGG_LOCATION_STREAMED_OUT" continue end
		local root, prompt = eggParts(model)
		if not root then observed.LocationReason = "EGG_LOCATION_ORIGINAL_INTERFACE_UNAVAILABLE: display/decor is not a spatial anchor" continue end
		local parent, rendered = model.Parent, workspace:FindFirstChild("Rendered")
		local chunkedOriginal = parent:IsA("Folder") and parent.Name == "Chunker" and parent.Parent == rendered and rendered ~= nil
		local okTag, tagged = pcall(function() return CollectionService:HasTag(model, "Egg") end)
		local worldOriginal = model:IsDescendantOf(worldModel) and okTag and tagged == true
		if not chunkedOriginal and not worldOriginal then
			observed.LocationReason = "EGG_LOCATION_SOURCE_ASSOCIATION_UNVERIFIED: original interface lacks native placement/tag or chunked ancestry" continue
		end
		local island = model:GetAttribute("Island") or def.Island
		if island ~= nil and (type(island) ~= "string" or profile.AreasUnlocked[island] == nil) then
			observed.LocationReason = "EGG_LOCATION_ISLAND_ACCESS_BLOCKED" continue
		end
		local area, spatialReason = spatialArea(root.Position)
		if not area or area ~= (island or def.World) then
			observed.LocationReason = spatialReason or "EGG_LOCATION_ISLAND_SPATIAL_MISMATCH: annotation and native scene area disagree" continue
		end
		observed.LocationVerified, observed.LocationReason = true, "NATIVE_ORIGINAL_SPATIAL_ANCHOR"
		observations.LocationCount += 1
		observations.LocationVerifiedCount = observations.LocationCount
		observed.LocationEvidence = "ClientScript:658-674,747 original interface/reparenting + WorldUtil:12-38 world Spawn + WorldMap:457-475 area geometry; current LocalData access"
		table.insert(candidates, { Model = model, Root = root, Prompt = prompt, World = def.World, Island = island,
			IdentityId = observed.IdentityId, IdentityEvidence = observed.IdentityEvidence, LocationVerified = true,
			LocationAnchor = root, LocationAnchorPosition = root.Position, InteractionVerified = false, RegistrationVerified = observed.Verified == true,
			LocationEvidence = observed.LocationEvidence })
	end
	if #candidates == 0 then
		local reason = observations.Candidates[1] and observations.Candidates[1].LocationReason
		-- Prefer a physical-original rejection over a decorative-copy explanation.
		for _, row in ipairs(observations.Candidates) do if row.Root and row.LocationReason then reason = row.LocationReason break end end
		observations.Reason = reason or "EGG_LOCATION_NOT_LOADED: no trustworthy physical original"
	else observations.Reason = "PHYSICAL_LOCATION_VERIFIED; hatch eligibility remains independent" end
	return candidates, observations
end

function GameKnowledge:ResolveEggLocation(name, force, expectedModel, characterRoot)
	local candidates, observations = self:EggLocationCandidates(name, force)
	if expectedModel then
		for _, candidate in ipairs(candidates) do if candidate.Model == expectedModel then return candidate, nil, observations end end
		return nil, "EGG_LOCATION_SELECTED_INSTANCE_UNAVAILABLE: retained exact target lost, moved area, or access changed; " .. observations.Reason, observations
	end
	if #candidates == 0 then return nil, observations.Reason, observations end
	local character = self.Reader.Player and self.Reader.Player.Character
	local root = characterRoot or character and character:FindFirstChild("HumanoidRootPart")
	if #candidates > 1 and (not root or not point(root.Position)) then return nil, "EGG_LOCATION_SELECTION_POSITION_UNAVAILABLE", observations end
	for _, candidate in ipairs(candidates) do candidate.Distance = root and (candidate.Root.Position - root.Position).Magnitude or math.huge end
	table.sort(candidates, function(a, b)
		if a.Distance ~= b.Distance then return a.Distance < b.Distance end
		return a.IdentityId < b.IdentityId
	end)
	return candidates[1], nil, observations
end

function GameKnowledge:NativeRegisteredEggModels()
	-- Read every exact loaded value from the already identified public receiver.
	-- Native nearest scanning is not catalog/name-filtered. Do not infer a
	-- complete competing set from the subset returned by EggModels alone.
	self:ObserveEggChunker()
	local receiver, count = nil, 0
	for observed in pairs(self.NativeEggChunkers or {}) do
		if eggReceiver(observed) then receiver = observed count += 1 end
	end
	if not self.EggObservationFinished or count ~= 1 then return nil, "Complete current native egg registration evidence unavailable for nearest selection" end
	local models, seen, entries, coordinates = {}, {}, 0, 0
	for coord, loaded in pairs(receiver._loaded) do
		coordinates += 1
		if coordinates > 1000 then return nil, "Native loaded coordinate observation limit exceeded" end
		local values = receiver._chunks[coord]
		if loaded ~= true then return nil, "Native loaded egg registration coordinates inconsistent" end
		-- Remove:73-75 clears an empty chunk without clearing _loaded. Native
		-- IsValueLoaded:105-107 skips that absent chunk; present malformed data
		-- remains a blocker rather than being treated as an empty coordinate.
		if values == nil then continue end
		if type(values) ~= "table" then return nil, "Native loaded egg registration coordinates inconsistent" end
		for index, model in pairs(values) do
			entries += 1
			if entries > 512 then return nil, "Native loaded egg registration observation limit exceeded" end
			if type(index) ~= "number" or index % 1 ~= 0 or index < 1 then return nil, "Native loaded egg registration array inconsistent" end
			if typeof(model) ~= "Instance" or not model:IsA("Model") or model.Parent ~= receiver._folder
				or not model:IsDescendantOf(workspace) or not eggParts(model) then return nil, "Native loaded original registration geometry inconsistent" end
			if not seen[model] then seen[model] = true table.insert(models, model) end
		end
		-- Native Remove leaves holes (Chunker:66-75). Generic iteration reads
		-- every remaining exact value; a hole is not an unknown registry entry.
	end
	return models
end

function GameKnowledge:NativeEggRangeEligible(egg, root, force)
	-- Existing native physical-egg contract: unopened Prompt / opened nearest Root.
	-- Shared fresh observation, no positioning, registry mutation or new loop.
	local function point(v)
		return v and type(v.X) == "number" and type(v.Y) == "number" and type(v.Z) == "number"
			and v.X == v.X and v.Y == v.Y and v.Z == v.Z
			and math.abs(v.X) < math.huge and math.abs(v.Y) < math.huge and math.abs(v.Z) < math.huge
	end
	local ok, eligible, range, reason = pcall(function()
		local model = egg and egg.Model
		if not model or not model.Parent or not model:IsDescendantOf(workspace) or not root or not point(root.Position) then return false, nil, "Selected egg/character geometry unavailable" end
		local identity, identityReason = self:ResolveEggInstance(model.Name, force, model)
		if not identity then return false, nil, identityReason end
		-- Native create returns before private registration without its visual asset.
		local assets = self:Assets("Eggs")
		local visual = assets and assets:FindFirstChild(model.Name)
		if not visual or not visual:IsA("Model") then
			return false, nil, "Selected native visual prerequisite unavailable; private interaction registration unverified"
		end
		local part, prompt = model:FindFirstChild("Root"), model:FindFirstChild("Prompt")
		if not part or not part:IsA("BasePart") or not point(part.Position) then return false, nil, "Selected original Root geometry unavailable" end
		local raw = self.Reader:GetLiveProfile()
		if not raw or type(raw.EggsOpened) ~= "table" then return false, nil, "Current account EggsOpened unavailable" end
		local opened = model:GetAttribute("Unlocked") == true and raw.EggsOpened[model.Name] ~= nil
		local origin, limit = part, 16
		if not opened then
			if not prompt or not prompt:IsA("BasePart") or not point(prompt.Position) then return false, nil, "Selected initial Prompt geometry unavailable" end
			local nativePrompt = prompt:FindFirstChildOfClass("ProximityPrompt")
			if not nativePrompt or nativePrompt.Parent ~= prompt or nativePrompt.Enabled ~= true
				or nativePrompt.RequiresLineOfSight ~= false or not PetPolicy.Finite(nativePrompt.MaxActivationDistance)
				or nativePrompt.MaxActivationDistance <= 0 or identity.PromptCacheMember ~= true then return false, nil, "Selected initial native Prompt cache/eligibility unavailable" end
			origin, limit = prompt, math.min(6.5, nativePrompt.MaxActivationDistance)
		end
		local record = { Model = model, IdentityId = identity.IdentityId, Range = limit, Distance = (origin.Position - root.Position).Magnitude, Opened = opened,
			RangeOrigin = origin, RangeOriginPosition = origin.Position, InteractionMode = opened and "OPENED_NEAREST" or "INITIAL_PROMPT",
			Mode = opened and "OPENED_NEAREST" or "INITIAL_PROMPT" }
		if record.Distance > limit then return false, record, "Outside selected native " .. record.InteractionMode .. " range" end
		if opened then
			local prompts = self:Get("ProximityPrompt")
			if not prompts or prompts.Visible ~= 0 then return false, record, "Native opened scanner requires known global Prompt Visible=0" end
			local registered, registryReason = self:NativeRegisteredEggModels()
			if not registered then return false, record, registryReason end
			if not table.find(registered, model) then return false, record, "Selected exact original no longer in the complete loaded registration set" end
			for _, other in ipairs(registered) do
				local otherRoot = other ~= model and other.Parent and other:IsDescendantOf(workspace) and other:FindFirstChild("Root")
				if otherRoot and otherRoot:IsA("BasePart") and point(otherRoot.Position) and other:GetAttribute("Unlocked") == true
					and (otherRoot.Position - root.Position).Magnitude <= 16 and (otherRoot.Position - root.Position).Magnitude <= record.Distance + 0.05 then
					return false, record, "Another or tied eligible registered original owns native nearest selection: " .. self:InstanceId(other)
				end
			end
		else
			-- Initial trigger closes over this exact cached prompt. Name/count transport
			-- cannot resolve competing simultaneously usable initial prompts safely.
			local prompts, selectedPrompt = self:Get("ProximityPrompt"), prompt:FindFirstChildOfClass("ProximityPrompt")
			for engine, member in pairs(prompts._cache) do
				if member ~= true or engine == selectedPrompt or not engine.Parent or engine.Enabled ~= true then continue end
				local parent, position = engine.Parent, nil
				if parent:IsA("BasePart") then position = parent.Position
				elseif parent:IsA("Attachment") then position = parent.WorldPosition end
				if not point(position) or not PetPolicy.Finite(engine.MaxActivationDistance) or engine.MaxActivationDistance <= 0 then
					return false, record, "Other enabled cached native Prompt geometry unavailable; active initial interaction unresolved"
				end
				if (position - root.Position).Magnitude <= engine.MaxActivationDistance then
					return false, record, "Competing eligible initial Prompt; exact native active prompt unresolved: " .. self:InstanceId(engine)
				end
			end
		end
		return true, record, "NATIVE_INTERACTION_VERIFIED: exact selected registered original; " .. record.InteractionMode
	end)
	return ok and eligible == true, ok and range or nil, ok and reason or "Native interaction observation failed: " .. tostring(eligible)
end

function GameKnowledge:PetContext(snapshot, plan, tracker, retainedModel)
	local raw = self.Reader:GetLiveProfile()
	local currency = PetPolicy.Currency(self.Reader.Config, plan)
	local context = { Currency = currency, AccountId = self.Reader.Player and self.Reader.Player.UserId, Eggs = {}, EggAvailability = {}, Pets = self:Get("Pets"),
		MinigameParadise = PetPolicy.WorldAccess(nil, "Minigame Paradise") }
	if not raw or not snapshot.Ready then context.Error = "Current LocalData unavailable" return context end
	-- Helpers receive a detached account. Their weak caches cannot mutate live inventory.
	local profile = detached(raw)
	context.MinigameParadise = PetPolicy.WorldAccess(profile, "Minigame Paradise")
	context.AccountFacts = profile -- Final equipment dispatch compares received facts again after any yielding guards.
	context.Inventory, context.Error = PetPolicy.Inventory(profile)
	local stats, util, pools = self:Get("StatsUtil"), self:Get("PetUtil"), self:Get("GetEggPool")
	-- BuffUtil-backed native helpers can decrement uses/update queues even when
	-- estimating. Isolate every call, preserving one immutable account benchmark.
	context.MaxEquipped = native(stats, "GetMaxPetsEquipped", detached(profile))
	context.MaxHatches = native(stats, "GetMaxEggHatches", detached(profile))
	context.StorageUsed, context.StorageCapacity = native(stats, "GetUsedPetStorage", detached(profile)), native(stats, "GetMaxPetStorage", detached(profile))
	context.DigitalStorage = native(stats, "HasDigitalStorage", detached(profile))
	context.InventoryFull = native(stats, "IsInventoryFull", detached(profile))
	context.AutoDeleteKnown = type(profile.AutoDelete) == "table"
	context.AutoDeleteActive = context.AutoDeleteKnown and next(profile.AutoDelete) ~= nil
	context.StorageUnit = context.DigitalStorage == true and "JSON_BYTES" or context.DigitalStorage == false and "PET_QUANTITY" or "UNKNOWN"
	if context.Inventory and stats and currency then
		local function score(ids, pets)
			local projected = detached(profile)
			if pets then projected.Pets = detached(pets) end
			projected.Teams[profile.TeamEquipped].Pets = table.clone(ids)
			if currency == "Bubbles" then return native(stats, "GetBubblePower", projected) end
			return native(stats, "GetCurrencyMultiplier", projected, currency)
		end
		context.ScoreTeam = score
		context.PetStats = function(pet, ids)
			local projected = detached(profile)
			projected.Teams[profile.TeamEquipped].Pets = table.clone(ids or context.Inventory.Team)
			return native(util, "GetStats", detached(pet), projected)
		end
		context.PetScore = function(pet, ids)
			local values = context.PetStats(pet, ids)
			return type(values) == "table" and (values[currency] or (currency ~= "Bubbles" and 1 or nil)) or nil
		end
		context.ScoreNewPet = function(name, ids)
			local pet = { Id = "OC_DETACHED_PROJECTION", Name = name, XP = 0 }
			local pets = table.clone(profile.Pets) table.insert(pets, pet)
			local best = score(ids, pets)
			if not PetPolicy.Finite(best) or not PetPolicy.Finite(context.MaxEquipped) then return nil end
			for slot = 1, #ids + (#ids < context.MaxEquipped and 1 or 0) do
				local old = context.Inventory.ById[ids[slot]]
				if old and (old.Super or PetPolicy.Protected(self.Reader.Config, old, (context.Pets or {})[old.Name]) or not context.Pets or not context.Pets[old.Name] or not context.Pets[old.Name].Rarity) then continue end
				local proposal = table.clone(ids) proposal[slot] = pet.Id
				local value = score(proposal, pets)
				if not PetPolicy.Finite(value) then return nil end
				best = math.max(best, value)
			end
			return best
		end
		-- Evaluate one actually received copy with its real XP/variant/enchants.
		-- No synthetic inventory entry and no equipment action.
		context.ScoreReceivedPet = function(id, ids)
			local pet = context.Inventory.ById[id]
			if not pet or pet.Super or not context.Pets or not context.Pets[pet.Name] then return nil end
			local best = score(ids)
			if not PetPolicy.Finite(best) or not PetPolicy.Finite(context.MaxEquipped) then return nil end
			if (PetPolicy.Counts(ids)[id] or 0) >= (pet.Amount or 1) then return best end
			for slot = 1, #ids + (#ids < context.MaxEquipped and 1 or 0) do
				local old = context.Inventory.ById[ids[slot]]
				if old and (old.Super or PetPolicy.Protected(self.Reader.Config, old, context.Pets[old.Name])
					or not context.Pets[old.Name] or not context.Pets[old.Name].Rarity) then continue end
				local proposal = table.clone(ids) proposal[slot] = id
				local value = score(proposal)
				if not PetPolicy.Finite(value) then return nil end
				best = math.max(best, value)
			end
			return best
		end
	end
	local definitions = self:Get("Eggs") or {}
	local coverage = { Definitions = 0, PermanentDefinitions = 0, LoadedModels = 0, Evaluated = 0, Limit = self.Reader.Config.HATCH_SETTINGS.MAXIMUM_EGGS_ANALYZED,
		Scope = "Loaded native models only; retained definitions/assets do not establish live availability", MissingSelected = {}, UnloadedCoinsDefinitions = {} }
	context.EggCoverage = coverage
	for name, def in pairs(definitions) do
		coverage.Definitions += 1
		if def.World and not def.Event and not def.ProductId and not def.IsAdminEgg and name ~= "Infinity Egg" then coverage.PermanentDefinitions += 1 end
	end
	local currentWorld = native(self:Get("WorldUtil"), "GetPlayerWorld", self.Reader.Player)
	local root = tracker:Root()
	if (self.Reader.Config.EGG_TRAVEL_SETTINGS.MODE or "NORMAL") == "TRAVEL_ONLY" then
		context.EggLocations, context.EggLocationDiagnostics = {}, {}
		local seen = {}
		for _, model in ipairs(self:EggModels()) do
			if seen[model.Name] then continue end seen[model.Name] = true
			local locations, observation = self:EggLocationCandidates(model.Name)
			context.EggLocationDiagnostics[model.Name] = observation
			for _, location in ipairs(locations) do
				location.Name, location.Loaded, location.Accessible = model.Name, true, true
				location.Distance = root and (location.Root.Position - root.Position).Magnitude
				location.Cost = definitions[model.Name].Cost
				table.insert(context.EggLocations, location)
			end
		end
		coverage.PhysicalLocations = #context.EggLocations
	end
	local byName = {}
	context.EggIdentityDiagnostics = {}
	for _, model in ipairs(self:EggModels()) do
		if not model.Parent or not model:IsDescendantOf(workspace) then continue end
		if byName[model.Name] then continue end
		local def = definitions[model.Name]
		local expected = retainedModel and retainedModel.Name == model.Name and retainedModel or nil
		local identity, identityReason, observed = self:ResolveEggInstance(model.Name, false, expected)
		if not identity and not expected and observed and observed.VerifiedCount > 1 then
			-- Reuse Test A's source/access/scene-associated physical selection for
			-- planning. Paid readiness still requires native interaction below; no
			-- name-only nearest substitution or alteration of discovery/movement.
			local physical = self:ResolveEggLocation(model.Name, false, nil, root)
			if physical then identity, identityReason, observed = self:ResolveEggInstance(model.Name, false, physical.Model) end
		end
		context.EggIdentityDiagnostics[model.Name] = observed
		if not identity then
			byName[model.Name] = { Name = model.Name, Loaded = false, Accessible = false, World = def.World, Island = def.Island,
				AccessStatus = "BLOCKED_INSTANCE_IDENTITY", IdentityReason = identityReason, Cost = def.Cost, Reason = identityReason }
			continue
		end
		model = identity.Model
		local part = identity.Root
		local distance = root and (part.Position - root.Position).Magnitude
		local island = model:GetAttribute("Island") or def.Island
		local world = def.World
		local accessible = world ~= nil and not def.Event and not def.ProductId and not def.IsAdminEgg and model.Name ~= "Infinity Egg"
			and type(profile.WorldsUnlocked) == "table" and profile.WorldsUnlocked[world] ~= nil
			and (not island or type(profile.AreasUnlocked) == "table" and profile.AreasUnlocked[island] ~= nil)
		local bonus = model:GetAttribute("BonusLuck")
		local poolWorld = world == currentWorld and currentWorld or "None"
		local luck = native(stats, "GetLuckMultiplier", self.Reader.Player, detached(profile), poolWorld, nil, bonus, model.Name)
		local pool
		if pools and PetPolicy.Finite(luck) and luck > 0 then
			local ok, value = pcall(pools, model.Name, poolWorld, luck, nil, nil, detached(profile))
			if ok then pool = value end
		end
		local opened = model:GetAttribute("Unlocked") == true and type(profile.EggsOpened) == "table" and profile.EggsOpened[model.Name] ~= nil
		local nativeRange, observedRange, interactionReason = self:NativeEggRangeEligible({ Model = model }, root)
		local range = observedRange and observedRange.Range or opened and 16 or 6.5
		local access = not world and "UNKNOWN_ACCESS" or (def.Event or def.ProductId or def.IsAdminEgg or model.Name == "Infinity Egg") and "UNSUPPORTED"
			or accessible and "ACCESSIBLE" or "LOCKED_OR_UNKNOWN_UNLOCK"
		local ok, path = pcall(function() return model:GetFullName() end)
		byName[model.Name] = { Name = model.Name, Model = model, IdentityId = identity.IdentityId, IdentityEvidence = identity.IdentityEvidence,
			World = world, Island = island, Distance = distance, Range = range,
			ModelPath = ok and path or nil, Position = part.Position,
			DefinitionCurrency = def.Cost and def.Cost.Type == "Currency" and def.Cost.Currency or nil,
			AccessStatus = access, Loaded = true, Accessible = accessible == true,
			InRange = accessible and world == currentWorld and nativeRange, NativeRangeEligible = nativeRange,
			RangeOrigin = observedRange and observedRange.RangeOrigin, InteractionDistance = observedRange and observedRange.Distance,
			InteractionMode = observedRange and observedRange.InteractionMode, InteractionReason = interactionReason,
			Cost = native(stats, "GetEggCost", self.Reader.Player, detached(profile), model.Name), Pool = pool, Luck = luck,
			Duration = native(stats, "GetHatchDuration", detached(profile)), Opened = opened, Unlocked = model:GetAttribute("Unlocked"),
			Reason = accessible and "Scene-present native egg; account world/island access confirmed" or "Premium/event/special/locked or unknown access; no hatch action" }
	end
	local names = {} for name in pairs(byName) do table.insert(names, name) end table.sort(names)
	coverage.ObservedEggNames, coverage.BlockedIdentityNames = #names, 0
	for _, egg in pairs(byName) do
		if egg.Loaded then coverage.LoadedModels += 1 else coverage.BlockedIdentityNames += 1 end
	end
	-- Availability/funding covers every loaded original model, even when the
	-- more expensive native team projections reach their configured cap.
	for _, name in ipairs(names) do table.insert(context.EggAvailability, byName[name]) end
	for name, def in pairs(definitions) do
		if not byName[name] and def.World and not def.Event and not def.ProductId and not def.IsAdminEgg and name ~= "Infinity Egg"
			and def.Cost and def.Cost.Type == "Currency" and def.Cost.Currency == "Coins" then table.insert(coverage.UnloadedCoinsDefinitions, name) end
	end
	table.sort(coverage.UnloadedCoinsDefinitions)
	-- Explicit selection is never lost behind the projection cap.
	table.sort(names, function(a, b)
		local x, y = table.find(self.Reader.Config.HATCH_SETTINGS.SELECTED_EGGS, a) ~= nil, table.find(self.Reader.Config.HATCH_SETTINGS.SELECTED_EGGS, b) ~= nil
		return x == y and a < b or x and not y
	end)
	for index, name in ipairs(names) do
		if index > self.Reader.Config.HATCH_SETTINGS.MAXIMUM_EGGS_ANALYZED then context.EggLimitReached = true break end
		table.insert(context.Eggs, byName[name])
	end
	coverage.Evaluated, coverage.LimitReached = #context.Eggs, context.EggLimitReached == true
	for _, name in ipairs(self.Reader.Config.HATCH_SETTINGS.SELECTED_EGGS) do
		if not byName[name] then
			table.insert(coverage.MissingSelected, name)
			local def = definitions[name]
			table.insert(context.Eggs, { Name = name, Loaded = false, Accessible = false, AccessStatus = def and "NOT_LOADED" or "UNKNOWN_DEFINITION",
				World = def and def.World, Island = def and def.Island, Cost = def and def.Cost,
				Reason = def and "Selected definition exists; original native egg model not loaded. Approach manually; no force-load or travel" or "Selected egg definition unavailable" })
		end
	end
	return context
end

function GameKnowledge:PickupContract() return pickupContract end

function GameKnowledge:ProgressionContract()
	return { Definitions = "ReplicatedStorage.Shared.Data.Worlds", Account = "LocalData.AreasUnlocked / WorldsUnlocked",
		WorldGate = "ClientScript:2138-2326; tagged WorldGate.World; UnlockCost; native command UnlockWorld with world identifier",
		Activation = "Client.Activation:357-360 horizontal <= Root.Size.Y/2; vertical <= 10",
		IslandTravel = "Client.Gui.Frames.WorldMap:168-198; Shared.Utils.WorldUtil.toIslandLocation; discovered islands only",
		Traversal = "Client.Effects.Physics uses actual Bubble.Amount and Bubble Gravity; no verified minimum or safe undiscovered-island route",
		IslandDiscovery = "Overworld Island.UnlockHitbox: anchored, touch-enabled, noncolliding; server handler unavailable; simulated contact is an owner-requested runtime experiment",
		DiscoveryVerification = "Correct LocalData.AreasUnlocked absent -> present, received by LocalData PlayerDataChanged; durable save requires owner rejoin testing",
		DiscoveryCapability = "firetouchinterest is runtime-specific, absent from inspected native scripts; check at live execution, never assume Studio support",
		WorldTravel = "Native FastTravel.Spawn; Seven Seas has a separate fishing-area contract, deferred",
		UnlockVerification = "Actual WorldsUnlocked absent -> present; balances logged separately; invocation/visuals not proof",
		ServerValidation = "UNAVAILABLE", LivePhase3Verification = "OWNER_CONFIRMED_DISCOVERY_AND_FUNDING_IN_SESSION",
		SavedDiscoveryPersistence = "OWNER_REJOIN_PENDING", WorldPurchase = "OWNER_LIVE_PENDING", AutomaticGateApproach = "UNVERIFIED_MANUAL_BLOCKER" }
end

function GameKnowledge:ActivePickups()
	local tutorial = self:Get("Tutorial")
	if type(tutorial) ~= "table" then
		local dependency = (self.Reader.Dependencies or {}).Tutorial
		return nil, "Client.Tutorial " .. tostring(dependency and dependency.Status or "not loaded") .. (dependency and dependency.Error and ": " .. dependency.Error or "")
	end
	if type(tutorial._activePickups) ~= "table" then return nil, "Client.Tutorial loaded but _activePickups is absent or not a table" end
	return tutorial._activePickups, "Client.Tutorial._activePickups available"
end

function GameKnowledge:GetStatus()
	local dependencies = {}
	for name, entry in pairs(self.Reader.Dependencies or {}) do
		dependencies[name] = { Status = entry.Status, Source = "ReplicatedStorage." .. entry.Path, Error = entry.Error }
	end
	return { Dependencies = dependencies, PickupAssetsAvailable = self:Assets("Pickups") ~= nil,
		Pickup = table.clone(pickupContract), Progression = self:ProgressionContract(), Pets = self:PetContract(), ServerOnlyRules = "UNAVAILABLE" }
end

function GameKnowledge:ReleaseChunkerObserver()
	if self.ChunkerClass and self.ChunkerClass.Update == self.ChunkerObserver then self.ChunkerClass.Update = self.OriginalChunkerUpdate end
	self.ChunkerClass, self.ChunkerObserver, self.OriginalChunkerUpdate, self.CleanupRegistry = nil, nil, nil, nil
end

function GameKnowledge:ObserveEggChunker()
	if self.Destroyed or self.EggObservationFinished then return end
	if self.EggObservationDeadline and os.clock() >= self.EggObservationDeadline then
		self.EggObservationFinished = true self:ReleaseChunkerObserver() return
	end
	if self:Get("Chunker") then
		if not self.EggObservationDeadline then
			self.EggObservationDeadline = os.clock() + 5
			-- One bounded observer cleanup, no polling/automation thread.
			task.delay(5, function()
				if not self.Destroyed and not self.EggObservationFinished then self.EggObservationFinished = true self:ReleaseChunkerObserver() end
			end)
		end
		self:EnsureChunkerObserver()
	end
end

function GameKnowledge:EnsureChunkerObserver()
	if self.Destroyed then return nil, "Knowledge observation destroyed" end
	if not self.ChunkerObserver then
		local class = self:Get("Chunker")
		if not class or type(class.Update) ~= "function" then return nil, "Native Chunker dependency unavailable" end
		self.ChunkerClass, self.OriginalChunkerUpdate = class, class.Update
		local original = class.Update
		local observer
		observer = function(chunker, ...)
			-- Observe the real receiver; preserve native Update arguments/results and never choose an action here.
			if not self.Destroyed and self.ChunkerObserver == observer then
				pcall(self.RecordNativeEggUpdate, self, chunker, true)
			end
			local result = table.pack(original(chunker, ...))
			if self.Destroyed or self.ChunkerObserver ~= observer then return table.unpack(result, 1, result.n) end
			-- Reporting only: separate protection prevents diagnostics from changing
			-- the existing registration/pickup observation or native return values.
			local diagnosticOK, diagnosticError = pcall(self.RecordNativeEggUpdate, self, chunker)
			if not diagnosticOK then
				self.EggObserverDiagnosticError = tostring(diagnosticError)
			end
			pcall(function() -- Observation failures must never interrupt the game's Update.
				-- Settings alone are shared; inspect every original after native Update.
				if not self.EggObservationFinished and self.EggObservationDeadline and os.clock() < self.EggObservationDeadline then
					if type(chunker) == "table" and self.NativeEggChunkers then self.NativeEggChunkers[chunker] = nil end
					local valid = classifyObservedEggQueue(chunker, class, self:Get("Eggs"))
					if valid then
						self.NativeEggChunkers = self.NativeEggChunkers or setmetatable({}, { __mode = "k" })
						self.NativeEggChunkers[chunker] = true
					end
				end
				if type(chunker) == "table" and type(chunker.Remove) == "function" and type(chunker.IsValueLoaded) == "function" then
					for _, pickup in pairs(self.CleanupRegistry or {}) do
						if pickup.Parent and pickup.Parent == chunker._folder and chunker:IsValueLoaded(pickup) then
							self.NativePickupChunker = chunker
							if not self.EggObservationDeadline or self.EggObservationFinished then self:ReleaseChunkerObserver() end
							break
						end
					end
				end
			end)
			return table.unpack(result, 1, result.n)
		end
		self.ChunkerObserver = observer
		local ok = pcall(function() class.Update = self.ChunkerObserver end)
		if not ok then self.EggObserverInstallFailure = true self:ReleaseChunkerObserver() return nil, "Native Chunker receiver observation unavailable" end
		self.EggObserverInstalled = true
		self.ChunkerObserverAt = os.clock()
	end
	return true
end

function GameKnowledge:EggDiagnosticId(instance)
	if not instance then return "NONE" end
	-- Physical selection has an existing InstanceId tie order. Diagnostics must
	-- never allocate into that namespace before the Brain observes originals.
	if self.EggDiagnosticIds and self.EggDiagnosticIds[instance] then return self.EggDiagnosticIds[instance] end
	if self.InstanceIds and self.InstanceIds[instance] then return self.InstanceIds[instance] end
	self.EggDiagnosticIds = self.EggDiagnosticIds or setmetatable({}, { __mode = "k" })
	if not self.EggDiagnosticIds[instance] then
		self.EggDiagnosticSequence = (self.EggDiagnosticSequence or 0) + 1
		self.EggDiagnosticIds[instance] = string.format("D%04d", self.EggDiagnosticSequence)
	end
	return self.EggDiagnosticIds[instance]
end

function GameKnowledge:RecordNativeEggUpdate(receiver, entered)
	-- No native method invocation, mutation, registry inference or timer here.
	if self.Destroyed or self.EggObservationFinished or not self.EggObservationDeadline
		or os.clock() >= self.EggObservationDeadline then return end
	self.EggObserverStats = self.EggObserverStats or { UpdateCalls = 0, CompletedUpdates = 0, Receivers = setmetatable({}, { __mode = "k" }), ReceiverCount = 0 }
	local stats = self.EggObserverStats
	if entered then stats.UpdateCalls += 1 return end
	stats.CompletedUpdates += 1
	if type(receiver) ~= "table" then stats.NonTableCalls = (stats.NonTableCalls or 0) + 1 return end
	local row = stats.Receivers[receiver]
	if not row then
		if stats.ReceiverCount >= 64 then stats.LimitExceeded = true return end
		stats.ReceiverCount += 1
		row = { Id = self:EggDiagnosticId(receiver), Calls = 0 }
		stats.Receivers[receiver] = row
	end
	row.Calls += 1
	row.StructureMatched, row.Qualifies, row.Entries, row.CatalogOriginals, row.Sentinels, row.NonCatalogOriginals = false, false, 0, 0, 0, 0
	row.FolderId = self:EggDiagnosticId(receiver._folder)
	local function reject(reason) row.Reason = reason end
	if type(receiver.Remove) ~= "function" then reject("MISSING_REMOVE_INTERFACE") return end
	if type(receiver.IsValueLoaded) ~= "function" then reject("MISSING_IS_VALUE_LOADED_INTERFACE") return end
	if not eggReceiver(receiver) then
		local rendered = workspace:FindFirstChild("Rendered")
		local reasons = {}
		if receiver.Mode ~= "3D" then table.insert(reasons, "MODE=" .. tostring(receiver.Mode)) end
		if receiver._chunkSize ~= 128 then table.insert(reasons, "CHUNK_SIZE=" .. tostring(receiver._chunkSize)) end
		if receiver.RenderDistance ~= 2 then table.insert(reasons, "RENDER_DISTANCE=" .. tostring(receiver.RenderDistance)) end
		if type(receiver._chunks) ~= "table" then table.insert(reasons, "CHUNKS_UNAVAILABLE") end
		if type(receiver._loaded) ~= "table" then table.insert(reasons, "LOADED_UNAVAILABLE") end
		if not rendered or not receiver._folder or receiver._folder.Parent ~= rendered then table.insert(reasons, "FOLDER_ANCESTRY_UNVERIFIED") end
		reject(table.concat(reasons, ",")) return
	end
	row.StructureMatched = true
	local definitions = self:Get("Eggs")
	row.EggDefinitionsReady = type(definitions) == "table"
	definitions = definitions or {}
	local coordinates = 0
	for coord, values in pairs(receiver._chunks) do
		coordinates += 1
		if coordinates > 1000 then reject("COORDINATE_LIMIT_EXCEEDED") return end
		if type(values) ~= "table" then reject("CHUNK_VALUES_NOT_TABLE; coord=" .. tostring(coord)) return end
		for _, value in pairs(values) do
			row.Entries += 1
			local suffix = "; coord=" .. tostring(coord) .. "; loaded=" .. tostring(receiver._loaded[coord])
			if row.Entries > 1000 then reject("ENTRY_LIMIT_EXCEEDED" .. suffix) return end
			if typeof(value) ~= "Instance" then reject("ENTRY_NOT_INSTANCE" .. suffix) return end
			suffix ..= "; instance=" .. self:EggDiagnosticId(value) .. "; name=" .. tostring(value.Name)
			local shapeOK, root = pcall(eggParts, value)
			if not shapeOK then reject("ORIGINAL_INTERFACE_READ_FAILED: " .. tostring(root) .. suffix) return end
			if not root then
				local missing = {}
				if not value:IsA("Model") then table.insert(missing, "NOT_MODEL")
				else
					for _, name in ipairs({ "Root", "Prompt" }) do
						local part = value:FindFirstChild(name)
						if not part then table.insert(missing, name .. "_ABSENT")
						elseif part.Parent ~= value then table.insert(missing, name .. "_PARENT_MISMATCH")
						elseif not part:IsA("BasePart") then table.insert(missing, name .. "_NOT_BASEPART")
						elseif not point(part.Position) then table.insert(missing, name .. "_POSITION_NONFINITE_OR_ABSENT") end
					end
					for _, name in ipairs({ "Plate", "Cost" }) do if not value:FindFirstChild(name) then table.insert(missing, name .. "_ABSENT") end end
				end
				reject("ORIGINAL_INTERFACE_OR_GEOMETRY_INCOMPLETE: " .. table.concat(missing, ",") .. suffix) return
			end
			if definitions[value.Name] then row.CatalogOriginals += 1
			elseif value.Name == "Coming Soon" then row.Sentinels += 1
			else row.NonCatalogOriginals += 1 end
		end
	end
	row.Qualifies, row.Reason = classifyObservedEggQueue(receiver, self:Get("Chunker"), self:Get("Eggs"))
end

function GameKnowledge:ReadObservedEggReceiver(receiver, selectedModel, otherOriginals)
	-- Inventory of a captured receiver, including rejected receivers. These raw
	-- facts are never added to NativeEggChunkers and cannot authorize a hatch.
	local row = { Id = self:EggDiagnosticId(receiver), Mode = tostring(receiver.Mode), ChunkSize = receiver._chunkSize,
		RenderDistance = receiver.RenderDistance, FolderId = self:EggDiagnosticId(receiver._folder),
		StructureMatched = eggReceiver(receiver) == true, CatalogReady = type(self:Get("Eggs")) == "table",
		ChunkCoordinates = 0, LoadedCoordinates = 0, Values = 0, Instances = 0, Models = 0,
		FullOriginalInterfaces = 0, CatalogOriginals = 0, Sentinels = 0, MissingCatalog = 0,
		SelectedFound = false, SelectedLoaded = false, OtherOriginalsFound = 0,
		OtherOriginalIds = {}, Issues = {}, Examples = {}, InspectionComplete = true }
	local rendered, definitions = workspace:FindFirstChild("Rendered"), self:Get("Eggs") or {}
	row.FolderUnderRendered = receiver._folder ~= nil and rendered ~= nil and receiver._folder.Parent == rendered
	row.FolderParentId = self:EggDiagnosticId(receiver._folder and receiver._folder.Parent)
	row.FolderParentName = receiver._folder and receiver._folder.Parent and receiver._folder.Parent.Name or "ABSENT"
	local class = self:Get("Chunker")
	row.ClassMetatableMatches = type(class) == "table" and getmetatable(receiver) == class
	row.HasOwnUpdate = type(rawget(receiver, "Update")) == "function"
	row.ResolvedUpdateMatchesPublicClass = type(class) == "table" and type(class.Update) == "function" and receiver.Update == class.Update
	row.SelectedParentEqualsFolder = selectedModel ~= nil and receiver._folder ~= nil and selectedModel.Parent == receiver._folder
	local issueCounts, otherSeen = {}, {}
	local function issue(kind, example)
		issueCounts[kind] = (issueCounts[kind] or 0) + 1
		if example and #row.Examples < 2 then table.insert(row.Examples, kind .. ":" .. example) end
	end
	if type(receiver.Remove) ~= "function" then issue("REMOVE_INTERFACE_UNAVAILABLE") end
	if type(receiver.IsValueLoaded) ~= "function" then issue("IS_VALUE_LOADED_INTERFACE_UNAVAILABLE") end
	if not row.StructureMatched then issue("STRUCTURE_MISMATCH") end
	if type(receiver._loaded) ~= "table" then issue("LOADED_COORDINATES_UNAVAILABLE") row.InspectionComplete = false
	else
		for coord, loaded in pairs(receiver._loaded) do
			row.LoadedCoordinates += 1
			if row.LoadedCoordinates > 1000 then issue("LOADED_COORDINATE_LIMIT") row.InspectionComplete = false break end
			if loaded ~= true then issue("LOADED_FLAG_INCONSISTENT") end
			if type(receiver._chunks) == "table" and receiver._chunks[coord] == nil then row.EmptyLoadedCoordinates = (row.EmptyLoadedCoordinates or 0) + 1 end
		end
	end
	if type(receiver._chunks) ~= "table" then issue("CHUNKS_UNAVAILABLE") row.InspectionComplete = false
	else
		for coord, values in pairs(receiver._chunks) do
			row.ChunkCoordinates += 1
			if row.ChunkCoordinates > 1000 then issue("CHUNK_COORDINATE_LIMIT") row.InspectionComplete = false break end
			local loaded = type(receiver._loaded) == "table" and receiver._loaded[coord]
			if type(values) ~= "table" then issue("CHUNK_VALUES_NOT_TABLE", "coord=" .. tostring(coord)) row.InspectionComplete = false continue end
			for index, value in pairs(values) do
				row.Values += 1
				if row.Values > 1000 then issue("VALUE_LIMIT") row.InspectionComplete = false break end
				if value == selectedModel and selectedModel ~= nil then
					row.SelectedFound = true
					if loaded == true and value.Parent == receiver._folder then row.SelectedLoaded = true end
				end
				if otherOriginals[value] and not otherSeen[value] then
					otherSeen[value] = true row.OtherOriginalsFound += 1
					table.insert(row.OtherOriginalIds, self.InstanceIds and self.InstanceIds[value] or self:EggDiagnosticId(value))
				end
				local suffix = "coord=" .. tostring(coord) .. "; loaded=" .. tostring(loaded)
				if type(index) ~= "number" or index < 1 or index % 1 ~= 0 then issue("UNSUPPORTED_MEMBER_KEY", suffix) end
				if typeof(value) ~= "Instance" then issue("NON_INSTANCE_CONTENT", suffix) continue end
				row.Instances += 1
				if not value:IsA("Model") then issue("NON_MODEL_CONTENT", suffix) continue end
				row.Models += 1
				local ok, root = pcall(eggParts, value)
				if not ok then issue("ORIGINAL_INTERFACE_READ_FAILED", suffix) row.InspectionComplete = false continue end
				if not root then issue("NON_ORIGINAL_OR_INCOMPLETE_INTERFACE", suffix) continue end
				row.FullOriginalInterfaces += 1
				if definitions[value.Name] then row.CatalogOriginals += 1
				elseif value.Name == "Coming Soon" then row.Sentinels += 1
				else
					row.MissingCatalog += 1
					issue(row.CatalogReady and "MISSING_CATALOG_DEFINITION" or "CATALOG_NOT_READY",
						"name=" .. tostring(value.Name) .. "[" .. self:EggDiagnosticId(value) .. "]; " .. suffix)
				end
				if loaded == true and (value.Parent ~= receiver._folder or not value:IsDescendantOf(workspace)) then issue("LOADED_MEMBER_ANCESTRY_INCONSISTENT", suffix) end
			end
			if row.Values > 1000 then break end
		end
	end
	for kind, count in pairs(issueCounts) do table.insert(row.Issues, kind .. "=" .. count) end
	table.sort(row.Issues) table.sort(row.OtherOriginalIds)
	row.ContentSourceCompatible = row.InspectionComplete and row.StructureMatched and row.Values > 0
		and row.Values == row.FullOriginalInterfaces and issueCounts.UNSUPPORTED_MEMBER_KEY == nil
	row.ContentAssessment = row.ContentSourceCompatible and "ORIGINAL_QUEUE_COMPATIBLE; NOT_REGISTRATION_PROOF" or "NON_EGG_OR_INCOMPLETE_CONTENT"
	row.EmptyLoadedCoordinates = row.EmptyLoadedCoordinates or 0
	return row
end

function GameKnowledge:NativeEggRegistrationDiagnostics(selectedModel)
	-- Detached reporting facts only. This method cannot grant identity/eligibility.
	local stats = self.EggObserverStats or {}
	local class = self:Get("Chunker")
	local report = { ModuleLoaded = class ~= nil, DependencyReady = type(class) == "table" and type(class.Update) == "function", Installed = self.EggObserverInstalled == true,
		Active = self.ChunkerObserver ~= nil and self.ChunkerClass ~= nil and self.ChunkerClass.Update == self.ChunkerObserver,
		UpdateCalls = stats.UpdateCalls or 0, CompletedUpdates = stats.CompletedUpdates or 0, CandidateReceivers = stats.ReceiverCount or 0,
		StructureMatched = 0, RejectedReceivers = 0, QualifyingReceivers = 0, Receivers = {},
		SelectedFound = false, SelectedLoaded = false, SelectedObservedFound = false, ReceiverChanged = false }
	for receiver, row in pairs(stats.Receivers or {}) do
		if row.StructureMatched then report.StructureMatched += 1 end
		if not row.Qualifies then report.RejectedReceivers += 1 end
		table.insert(report.Receivers, table.clone(row))
		if row.Qualifies and not eggReceiver(receiver) then report.ReceiverChanged = true end
	end
	table.sort(report.Receivers, function(a, b) return a.Id < b.Id end)
	local entries, coordinates = 0, 0
	local selectedRoot, selectedPrompt
	if selectedModel then selectedRoot, selectedPrompt = eggParts(selectedModel) end
	report.SelectedGeometryAvailable = selectedRoot ~= nil and selectedPrompt ~= nil
	local receiverEntries = 0
	for receiver in pairs(self.NativeEggChunkers or {}) do
		receiverEntries += 1
		if receiverEntries > 64 then report.LimitExceeded = true break end
		if not eggReceiver(receiver) then report.ReceiverChanged = true continue end
		report.QualifyingReceivers += 1
		for coord, values in pairs(receiver._chunks) do
			coordinates += 1
			if coordinates > 1000 then report.LimitExceeded = true break end
			if type(values) ~= "table" then report.ReceiverChanged = true continue end
			for _, value in pairs(values) do
				entries += 1
				if entries > 1000 then report.LimitExceeded = true break end
				if selectedModel and value == selectedModel then
					report.SelectedFound = true
					if receiver._loaded[coord] == true and value.Parent == receiver._folder then
						report.SelectedLoaded = true
						-- Match the separately approved exact-value membership repair.
						-- Reporting stays read-only and cannot allocate physical IDs.
						if report.SelectedGeometryAvailable and selectedModel:IsDescendantOf(workspace) then report.SelectedObservedFound = true end
					end
				end
			end
			if report.LimitExceeded then break end
		end
		if report.LimitExceeded then break end
	end
	if selectedModel then
		report.SelectedDiagnosticId = self:EggDiagnosticId(selectedModel)
		report.SelectedInstanceId = self.InstanceIds and self.InstanceIds[selectedModel] or report.SelectedDiagnosticId
		report.SelectedObservationReason = report.SelectedGeometryAvailable and "ORIGINAL_INTERFACE_PRESENT" or "ORIGINAL_INTERFACE_OR_GEOMETRY_INCOMPLETE"
		local originals, excluded = {}, 0
		local prompts = self:Get("ProximityPrompt")
		for modelIndex, model in ipairs(self.NativeEggModels or {}) do
			if modelIndex > 1000 then report.LimitExceeded = true break end
			if model.Name ~= selectedModel.Name then continue end
			local root, prompt = eggParts(model)
			if not root then excluded += 1 continue end
			local engine = prompt:FindFirstChildOfClass("ProximityPrompt")
			local diagnosticId = self:EggDiagnosticId(model)
			table.insert(originals, { InstanceId = self.InstanceIds and self.InstanceIds[model] or diagnosticId, DiagnosticId = diagnosticId, Selected = model == selectedModel,
				ParentId = self:EggDiagnosticId(model.Parent), Root = root.Position, Prompt = prompt.Position,
				PromptCacheMember = engine ~= nil and type(prompts) == "table" and type(prompts._cache) == "table" and prompts._cache[engine] == true,
				RegisteredReceivers = model == selectedModel and (report.SelectedObservedFound and 1 or 0) or nil })
		end
		table.sort(originals, function(a, b) if a.Selected ~= b.Selected then return a.Selected end return a.InstanceId < b.InstanceId end)
		report.PhysicalOriginals, report.ExcludedRepresentations, report.Originals = #originals, excluded, originals
	end
	local reason
	if self.Destroyed then reason = "OBSERVER_DESTROYED"
	elseif not report.ModuleLoaded then reason = "CHUNKER_DEPENDENCY_UNAVAILABLE"
	elseif not report.DependencyReady then reason = "CHUNKER_UPDATE_INTERFACE_UNAVAILABLE"
	elseif self.EggObserverInstallFailure then reason = "OBSERVER_INSTALL_FAILED"
	elseif not report.Installed and not self.NativeEggChunkers then reason = "OBSERVER_NOT_INSTALLED"
	elseif stats.LimitExceeded or report.LimitExceeded then reason = "READ_ONLY_DIAGNOSTIC_LIMIT_EXCEEDED"
	elseif self.EggObserverDiagnosticError then reason = "READ_ONLY_DIAGNOSTIC_ERROR: " .. self.EggObserverDiagnosticError
	elseif report.ReceiverChanged then reason = "OBSERVED_RECEIVER_STRUCTURE_CHANGED"
	elseif report.QualifyingReceivers > 1 then reason = "MULTIPLE_QUALIFYING_EGG_RECEIVERS"
	elseif report.QualifyingReceivers == 0 then
		if report.UpdateCalls == 0 then reason = self.EggObservationFinished and "TIMED_OUT_BEFORE_ANY_NATIVE_UPDATE" or "WAITING_FOR_NATIVE_UPDATE"
		elseif report.CompletedUpdates == 0 then reason = "NATIVE_UPDATE_ENTERED_WITHOUT_COMPLETED_OBSERVATION"
		else reason = self.EggObservationFinished and "TIMED_OUT_WITHOUT_QUALIFYING_EGG_RECEIVER" or "NATIVE_UPDATES_OBSERVED_NO_QUALIFYING_EGG_RECEIVER" end
	elseif selectedModel and not selectedModel.Parent then reason = "SELECTED_INSTANCE_UNLOADED"
	elseif selectedModel and not report.SelectedFound then reason = "SELECTED_EXACT_INSTANCE_ABSENT_FROM_OBSERVED_CHUNKS"
	elseif selectedModel and not report.SelectedLoaded then reason = "SELECTED_EXACT_INSTANCE_COORDINATE_UNLOADED_OR_ANCESTRY_CHANGED"
	elseif selectedModel and not report.SelectedGeometryAvailable then reason = "SELECTED_ORIGINAL_GEOMETRY_CHANGED: " .. tostring(report.SelectedObservationReason)
	else reason = self.EggObservationFinished and "CURRENT_EXACT_REGISTRATION_OBSERVED" or "REGISTRATION_OBSERVED_WINDOW_STILL_OPEN" end
	report.Stage, report.Reason = reason, reason
	local rejections = {}
	for _, row in ipairs(report.Receivers) do if not row.Qualifies then table.insert(rejections, row.Id .. ":" .. tostring(row.Reason)) end end
	if #rejections > 0 then report.Reason ..= "; rejected={" .. table.concat(rejections, " | ") .. "}" end
	report.Summary = string.format("registration=%s; dependency=%s; installed=%s; active=%s; native Updates=%d; completed=%d; receivers=%d; 3D structure=%d; rejected=%d; qualifying=%d; exact selected in chunks=%s; selected loaded=%s; protected membership=%s",
		report.Stage, tostring(report.DependencyReady), tostring(report.Installed), tostring(report.Active), report.UpdateCalls, report.CompletedUpdates, report.CandidateReceivers,
		report.StructureMatched, report.RejectedReceivers, report.QualifyingReceivers, tostring(report.SelectedFound), tostring(report.SelectedLoaded), tostring(report.SelectedObservedFound))
	if report.Originals then
		local rows = {}
		local function position(v) return string.format("(%.2f,%.2f,%.2f)", v.X, v.Y, v.Z) end
		for i, original in ipairs(report.Originals) do
			if i > 4 then break end
			local label = original.InstanceId .. (original.DiagnosticId ~= original.InstanceId and "[" .. original.DiagnosticId .. "]" or "")
			table.insert(rows, string.format("%s%s parent=%s Root=%s Prompt=%s cached=%s protected selected membership=%s", label,
				original.Selected and " SELECTED" or "", original.ParentId, position(original.Root), position(original.Prompt),
				tostring(original.PromptCacheMember == true), tostring(original.RegisteredReceivers or "not checked")))
		end
		report.Summary ..= string.format("; original-shaped=%d; excluded representations=%d | %s", report.PhysicalOriginals, report.ExcludedRepresentations, table.concat(rows, " | "))
	end
	-- Search ALL captured receivers independently of acceptance. The old trusted
	-- SelectedFound field stays scoped to accepted registration and is not proof
	-- that a selected original was absent from rejected receivers.
	local otherOriginals, cachedCount = {}, 0
	for _, model in ipairs(self.NativeEggModels or {}) do
		cachedCount += 1
		if cachedCount > 1000 then break end
		if selectedModel and model ~= selectedModel and model.Name == selectedModel.Name and model.Parent
			and model:IsDescendantOf(workspace) and eggParts(model) then otherOriginals[model] = true end
	end
	report.CapturedReceivers, report.CapturedSelectedFound, report.CapturedOtherOriginalFound = {}, false, false
	report.FullCandidateInspectionComplete = cachedCount <= 1000 and not stats.LimitExceeded and report.UpdateCalls == report.CompletedUpdates
	report.ReceiverObservationComplete = self.EggObservationFinished == true
	local available, structural, otherSeen = 0, 0, {}
	for receiver, observed in pairs(stats.Receivers or {}) do
		available += 1
		if available > 64 then report.FullCandidateInspectionComplete = false break end
		local ok, row = pcall(self.ReadObservedEggReceiver, self, receiver, selectedModel, otherOriginals)
		if not ok then
			row = { Id = observed.Id, InspectionComplete = false, Issues = { "RECEIVER_READ_FAILED" },
				Examples = { tostring(row) }, OtherOriginalIds = {}, SelectedFound = false, SelectedLoaded = false }
		end
		row.LastObserverReason, row.LastObserverQualified, row.ObservedCalls = observed.Reason, observed.Qualifies == true, observed.Calls
		row.AcceptedReceiver = self.NativeEggChunkers ~= nil and self.NativeEggChunkers[receiver] == true
		if not row.InspectionComplete then report.FullCandidateInspectionComplete = false end
		if row.StructureMatched then structural += 1 end
		if row.SelectedFound then report.CapturedSelectedFound = true end
		for _, id in ipairs(row.OtherOriginalIds) do otherSeen[id] = true report.CapturedOtherOriginalFound = true end
		table.insert(report.CapturedReceivers, row)
	end
	report.CurrentCandidateReceiversCount = #report.CapturedReceivers
	if report.CurrentCandidateReceiversCount < report.CandidateReceivers then report.FullCandidateInspectionComplete = false end
	report.OtherOriginalsFound = 0 for _ in pairs(otherSeen) do report.OtherOriginalsFound += 1 end
	table.sort(report.CapturedReceivers, function(a, b) return a.Id < b.Id end)
	local rawSelected = report.CapturedSelectedFound and "true" or report.FullCandidateInspectionComplete and "false" or "UNKNOWN"
	local rawOther = report.CapturedOtherOriginalFound and "true" or report.FullCandidateInspectionComplete and "false" or "UNKNOWN"
	report.CapturedSelectedPresence = rawSelected
	report.CapturedOtherOriginalPresence = rawOther
	local attribution = report.SelectedFound and report.QualifyingReceivers == 1 and "SOURCE_MATCHING_ACCEPTED_RECEIVER_OBSERVED" or "UNVERIFIED"
	report.ReceiverUpdateAttribution = attribution
	report.ReceiverObservationSummary = string.format("NATIVE_EGG_RECEIVER_OBSERVATION | Updates observed=%d; completed=%d; candidate receivers=%d; currently inspectable=%d; structurally compatible=%d; exact selected in ANY captured=%s; exact other original in ANY captured=%s; qualifying=%d; trusted selected in accepted=%s; observation complete=%s; full inspection=%s; excluded representations=%s; egg receiver Update attribution=%s",
		report.UpdateCalls, report.CompletedUpdates, report.CandidateReceivers, report.CurrentCandidateReceiversCount, structural, rawSelected, rawOther,
		report.QualifyingReceivers, tostring(report.SelectedObservedFound), tostring(report.ReceiverObservationComplete), tostring(report.FullCandidateInspectionComplete), tostring(report.ExcludedRepresentations or "UNKNOWN"), attribution)
	local lines, keys = {}, { tostring(report.ReceiverObservationComplete), tostring(report.FullCandidateInspectionComplete), rawSelected, rawOther, tostring(report.QualifyingReceivers) }
	for index, row in ipairs(report.CapturedReceivers) do
		local issues = table.concat(row.Issues or {}, ",")
		table.insert(keys, table.concat({ row.Id, tostring(row.FolderId), tostring(row.Mode), tostring(row.ChunkSize), tostring(row.RenderDistance),
			tostring(row.CatalogReady), tostring(row.SelectedFound), tostring(row.SelectedLoaded), tostring(row.SelectedParentEqualsFolder),
			tostring(row.OtherOriginalsFound), tostring(row.AcceptedReceiver), tostring(row.ClassMetatableMatches), tostring(row.HasOwnUpdate),
			tostring(row.ResolvedUpdateMatchesPublicClass), issues:gsub("=%d+", "") }, ":"))
		if index > 6 then continue end
		table.insert(lines, string.format("%s | mode=%s; chunk=%s; render=%s; folder=%s; parent=%s[%s]; under Rendered=%s; selected parent equals folder=%s; class metatable=%s; own Update=%s; resolved public Update=%s; coords=%s; loaded coords=%s; empty loaded=%s; values=%s; Instances=%s; Models=%s; full originals=%s; catalog=%s; sentinel=%s; missing catalog=%s; selected present=%s; selected loaded=%s; other originals=%s; accepted=%s | current issues={%s}; last native rejection=%s; examples={%s}",
			row.Id, tostring(row.Mode), tostring(row.ChunkSize), tostring(row.RenderDistance), tostring(row.FolderId), tostring(row.FolderParentName),
			tostring(row.FolderParentId), tostring(row.FolderUnderRendered), tostring(row.SelectedParentEqualsFolder), tostring(row.ClassMetatableMatches),
			tostring(row.HasOwnUpdate), tostring(row.ResolvedUpdateMatchesPublicClass), tostring(row.ChunkCoordinates), tostring(row.LoadedCoordinates),
			tostring(row.EmptyLoadedCoordinates), tostring(row.Values), tostring(row.Instances),
			tostring(row.Models), tostring(row.FullOriginalInterfaces), tostring(row.CatalogOriginals), tostring(row.Sentinels), tostring(row.MissingCatalog),
			tostring(row.SelectedFound), tostring(row.SelectedLoaded), tostring(row.OtherOriginalsFound), tostring(row.AcceptedReceiver), issues,
			tostring(row.LastObserverReason), table.concat(row.Examples or {}, " | ")))
	end
	report.ReceiverObservationSummary ..= "\n" .. table.concat(lines, "\n")
	report.ReceiverObservationKey = table.concat(keys, "|")
	report.Summary = report.Summary:gsub("exact selected in chunks=", "exact selected in ACCEPTED chunks=")
	return report
end

function GameKnowledge:PickupChunker()
	if self.NativePickupChunker then return self.NativePickupChunker end
	if self.ChunkerObserver and os.clock() - self.ChunkerObserverAt >= 5 then
		self:ReleaseChunkerObserver() self.ChunkerRetryAt = os.clock() + 5
	end
	if os.clock() < (self.ChunkerRetryAt or 0) then return nil, "Native pickup Chunker observation is in backoff" end
	local registry = self:ActivePickups()
	if not registry then return nil, "Native pickup registry dependency unavailable" end
	local ok, reason = self:EnsureChunkerObserver()
	if not ok then return nil, reason end
	self.CleanupRegistry = registry
	return nil, "Waiting for native pickup Chunker receiver; no request or visual mutation yet"
end

function GameKnowledge:Destroy()
	self.Destroyed, self.EggObservationFinished = true, true
	self:ReleaseChunkerObserver() self.NativePickupChunker, self.NativeEggChunkers = nil, nil
end

function GameKnowledge:RewardContract()
	return { Playtime = "Shared.Data.Playtime.Gifts[{Time,Luck}]; Client.Gui.Frames.Playtime:99-135,369-376,394-404",
		Claimed = "PlaytimeRewards.Claimed[tostring(index)]~=nil; elapsed Time.now()-Start; received Playtime mastery",
		OrdinaryBox = "ItemUtil:GetOwnedAmount(profile,{Type='Powerup',Name='Mystery Box'}); PromptBuilder:297-383 UseGift(name,count)",
		Physical = "PhysicalItem:GetActiveGifts:109-121; Gift:Hit:206-270; eight guarded native hits precede native ClaimGift",
		Result = "Received exact claimed key or stock debit plus correlated physical completion and observable reward; dispatch is not success",
		Bulk = "ClaimAllPlaytime exists but automatic bulk is not enabled; authoritative server eligibility remains unknown",
		ServerValidation = "UNAVAILABLE", LiveVerification = "OWNER_PENDING" }
end

-- PHASE5_READ_ONLY_MASTERY_BEGIN
-- A detached observation for advisory planning. No request, claim, or scheduler task is emitted.
function GameKnowledge:MasteryContext(snapshot, now, settings)
	settings = settings or {}
	local startedAt = os.clock()
	local function finite(value)
		return type(value) == "number" and value == value and value >= 0 and value < math.huge
	end
	local function equal(left, right, seen)
		if type(left) ~= type(right) then return false end
		if type(left) ~= "table" then return left == right end
		seen = seen or {}
		if seen[left] == right then return true end
		seen[left] = right
		for key, value in pairs(left) do if not equal(value, right[key], seen) then return false end end
		for key in pairs(right) do if left[key] == nil then return false end end
		return true
	end
	local context = { Catalog = {}, Account = nil, Snapshot = type(snapshot) == "table" and detached(snapshot) or {},
		ObservedAt = now, Fresh = false, CategoryObservations = {}, TierObservations = {}, Balances = {},
		EffectiveUpgrades = type(snapshot) == "table" and snapshot.Upgrades and detached(snapshot.Upgrades.MasteryUpgrades) or nil,
		Access = { Visibility = "UNKNOWN", PhysicalEligibility = "UNKNOWN", ServerEligibility = "UNKNOWN",
			Reason = "Received AreasUnlocked unavailable; physical/server purchase requirements unverified" },
		AccessState = "UNKNOWN", TradingPlazaStatus = "UNKNOWN",
		Evidence = "Shared.Data.Mastery.Upgrades; Client.Gui.Frames.Mastery:257,539-568; ClientScript:2010",
		ActionsEnabled = false }
	local function block(reason)
		context.Fresh, context.Blocker = false, reason
		return context
	end
	if self.Destroyed or type(snapshot) ~= "table" or snapshot.Ready ~= true then return block("Ready account snapshot unavailable") end
	local maximumAge = settings.MAXIMUM_ACCOUNT_AGE_SECONDS or 10
	if not finite(now) or not finite(snapshot.ReadAt) or not finite(maximumAge)
		or now < snapshot.ReadAt or now - snapshot.ReadAt > maximumAge then return block("Account snapshot is stale or its age is unknown") end
	if not finite(snapshot.Revision) or snapshot.Revision % 1 ~= 0 or snapshot.Revision ~= self.Reader.Revision then
		return block("Account snapshot revision differs from the current reader revision")
	end
	local current = self.Reader:GetSnapshot()
	if type(current) ~= "table" or current.Revision ~= snapshot.Revision then return block("Current account snapshot revision unavailable or changed") end
	local identity = snapshot.Identity and snapshot.Identity.UserId
	local player = self.Reader.Player
	if not finite(identity) or identity <= 0 or identity % 1 ~= 0 or not player or player.UserId ~= identity then
		return block("Snapshot account identity differs from the actual reader player or is unavailable")
	end
	context.AccountId = identity
	local raw = self.Reader:GetLiveProfile()
	if type(raw) ~= "table" then return block("Ready native LocalData profile unavailable") end
	local account = detached(raw)
	context.Account = account
	local function matchesSnapshot(profile)
		local upgrades = snapshot.Upgrades or {}
		if not equal(upgrades.MasteryLevels, profile.MasteryLevels) or not equal(upgrades.MasteryUpgrades, profile.MasteryUpgrades)
			or not equal(snapshot.UnlockedIslands, profile.AreasUnlocked) or not equal(snapshot.UnlockedWorlds, profile.WorldsUnlocked) then return false end
		for currency, balance in pairs(snapshot.Balances or {}) do if balance ~= profile[currency] then return false end end
		return true
	end
	if not matchesSnapshot(account) then return block("Snapshot Mastery, unlock, or currency facts differ from live LocalData") end
	local catalog = self:Get("Mastery")
	if type(catalog) ~= "table" or type(catalog.Upgrades) ~= "table" then return block("Native Mastery.Upgrades catalog unavailable") end
	context.Catalog = detached(catalog.Upgrades)
	local areas = snapshot.UnlockedIslands
	if type(areas) == "table" then
		context.Access.Visibility = areas["Outer Space"] ~= nil and "VISIBLE" or "LOCKED"
		context.Access.Reason = areas["Outer Space"] ~= nil and "Received AreasUnlocked[Outer Space] entry is present; native HUD prerequisite observed"
			or "Native Mastery HUD requires an AreasUnlocked[Outer Space] entry"
	end
	local plaza = self:Get("IsTradingPlaza")
	if type(plaza) == "function" then
		local ok, value = pcall(plaza)
		if ok and type(value) == "boolean" then
			context.TradingPlazaStatus = value and "ACTIVE" or "INACTIVE"
			if value then context.Access.Visibility, context.Access.Reason = "LOCKED", "Native Mastery HUD is unavailable in Trading Plaza" end
		end
	end
	context.AccessState = context.Access.Visibility
	local currencies = {}
	for currency in pairs(snapshot.Balances or {}) do currencies[currency] = true end
	local levels = snapshot.Upgrades and snapshot.Upgrades.MasteryLevels
	-- Permanent scope is established by the completed native catalog audit, not visibility or Config order.
	local permanent = { Pets = true, Buffs = true, Shops = true, Minigames = true, Rifts = true }
	for name, definition in pairs(context.Catalog) do
		if type(name) ~= "string" or type(definition) ~= "table" then continue end
		local observation = { Visibility = "VISIBLE", VisibilityReason = "Native optional ShouldShow predicate is absent",
			PrerequisiteReason = context.Access.Reason, EarlyUnlockStatus = "UNKNOWN", PriceStatus = "UNKNOWN",
			Permanence = permanent[name] and "VERIFIED_PERMANENT" or "UNKNOWN",
			PermanenceEvidence = "Completed native MASTERY_AND_UPGRADES.md:40; an unreviewed visible category is not assumed permanent" }
		context.CategoryObservations[name] = observation
		if definition.ShouldShow ~= nil then
			if type(definition.ShouldShow) == "function" then
				local ok, shown = pcall(definition.ShouldShow, detached(account))
				if ok and type(shown) == "boolean" then
					observation.Visibility = shown and "VISIBLE" or "LOCKED"
					observation.VisibilityReason = shown and "Native ShouldShow returned true" or "Native ShouldShow returned false"
				else observation.Visibility, observation.VisibilityReason = "UNKNOWN", "Native ShouldShow failed or returned an unsupported result" end
			else observation.Visibility, observation.VisibilityReason = "UNKNOWN", "Native ShouldShow interface is not callable" end
		end
		local tierObservations = {}
		context.TierObservations[name] = tierObservations
		for index, level in pairs(type(definition.Levels) == "table" and definition.Levels or {}) do
			if type(index) ~= "number" or index % 1 ~= 0 or index < 1 or type(level) ~= "table" then continue end
			local tier = { EarlyUnlock = false, EarlyUnlockStatus = "OBSERVED", PriceStatus = "UNKNOWN",
				PriceReason = "Native fixed item Cost unavailable; callable costs are not a verified Mastery contract" }
			tierObservations[index] = tier
			if level.UnlockEarly ~= nil then
				if type(level.UnlockEarly) == "function" then
					local ok, early = pcall(level.UnlockEarly, detached(account))
					if ok and type(early) == "boolean" then tier.EarlyUnlock = early
					else tier.EarlyUnlock, tier.EarlyUnlockStatus = nil, "UNKNOWN" end
				else tier.EarlyUnlock, tier.EarlyUnlockStatus = nil, "UNKNOWN" end
			end
			if tier.EarlyUnlock == true then
				tier.NativePrice, tier.PriceStatus, tier.PriceReason = { Type = "Currency", Currency = "Coins", Amount = 0 }, "OBSERVED", "Native UnlockEarly returned true; native UI substitutes zero Coins"
			elseif tier.EarlyUnlockStatus == "UNKNOWN" then
				tier.PriceReason = "Native early-unlock predicate unavailable; effective price is unknown"
			elseif type(level.Cost) == "table" then
				tier.NativePrice, tier.PriceStatus, tier.PriceReason = detached(level.Cost), "OBSERVED", "Observed native fixed tier Cost"
			end
			if type(level.Cost) == "table" and type(level.Cost.Currency) == "string" then currencies[level.Cost.Currency] = true end
			if tier.NativePrice and type(tier.NativePrice.Currency) == "string" then currencies[tier.NativePrice.Currency] = true end
		end
		local currentLevel = type(levels) == "table" and levels[name] or nil
		local nextTier = finite(currentLevel) and currentLevel % 1 == 0 and tierObservations[currentLevel + 1]
		if nextTier then
			for key, value in pairs(nextTier) do observation[key] = detached(value) end
		else observation.PriceReason = "Actual next tier unavailable; missing category levels are not inferred as zero" end
	end
	for currency in pairs(currencies) do if finite(account[currency]) then context.Balances[currency] = account[currency] end end
	local final = self.Reader:GetLiveProfile()
	local finalSnapshot = self.Reader:GetSnapshot()
	if self.Destroyed or self.Reader.Revision ~= snapshot.Revision or type(finalSnapshot) ~= "table" or finalSnapshot.Revision ~= snapshot.Revision
		or self.Reader.Player ~= player or player.UserId ~= identity or type(final) ~= "table" or not matchesSnapshot(final) then
		return block("Account identity, revision, Mastery, unlock, or balance facts changed during native observation")
	end
	for _, field in ipairs({ "MasteryLevels", "MasteryUpgrades", "AreasUnlocked", "WorldsUnlocked", "OGData" }) do
		if not equal(account[field], final[field]) then return block("Native account prerequisite facts changed during observation") end
	end
	for currency in pairs(currencies) do if account[currency] ~= final[currency] then return block("Relevant native currency balance changed during observation") end end
	local finalCatalog = self:Get("Mastery")
	if type(finalCatalog) ~= "table" or not equal(context.Catalog, finalCatalog.Upgrades) then return block("Native Mastery definitions changed during observation") end
	context.CompletedAt = now + math.max(0, os.clock() - startedAt)
	if context.CompletedAt - snapshot.ReadAt > maximumAge then return block("Account snapshot became stale during native observation") end
	context.Fresh = true
	return context
end
-- PHASE5_READ_ONLY_MASTERY_END
-- PHASE5_READ_ONLY_REWARDS_BEGIN
-- Detached received facts and reviewed pure native getters only. No reward action is prepared.
function GameKnowledge:RewardContext(snapshot, now, settings)
	settings = settings or {}
	local startedAt = os.clock()
	local function finite(value)
		return type(value) == "number" and value == value and value >= 0 and value < math.huge
	end
	local function integer(value) return finite(value) and value % 1 == 0 end
	local function copy(value, seen)
		if type(value) ~= "table" then return value end
		seen = seen or {}
		if seen[value] then return seen[value] end
		local result = {} seen[value] = result
		for key, entry in pairs(value) do result[key] = copy(entry, seen) end
		return result
	end
	local function equal(left, right, seen)
		if type(left) ~= type(right) then return false end
		if type(left) ~= "table" then return left == right end
		seen = seen or {}
		if seen[left] == right then return true end
		seen[left] = right
		for key, value in pairs(left) do if not equal(value, right[key], seen) then return false end end
		for key in pairs(right) do if left[key] == nil then return false end end
		return true
	end
	local context = { Fresh = false, ObservedAt = now, Catalogs = {}, Balances = {}, Diagnostics = {},
		QuestObservations = {}, PrizeObservations = {}, ChestObservations = {}, WorldRewardObservations = {},
		InventoryObservations = { Powerups = {}, Potions = {}, Items = {}, SchemaState = "UNKNOWN" },
		TradingPlazaStatus = "UNKNOWN", WheelQueueState = "UNKNOWN", ActionsEnabled = false,
		Evidence = "Completed REWARDS_QUESTS_AND_EVENTS.md; SHOPS_QUESTS_AND_CONSUMABLES.md; DATA_SCHEMAS.md; native client eligibility is not server permission" }
	local function block(reason) context.Fresh, context.Blocker = false, reason return context end
	local reader = self.Reader
	if self.Destroyed or not reader or reader.Destroyed or type(snapshot) ~= "table" or snapshot.Ready ~= true then
		return block("Ready received account snapshot unavailable")
	end
	local maximumAge = settings.MAXIMUM_ACCOUNT_AGE_SECONDS or 10
	if not finite(now) or not finite(snapshot.ReadAt) or not finite(maximumAge)
		or now < snapshot.ReadAt or now - snapshot.ReadAt > maximumAge then
		return block("Reward account snapshot is stale or its age is unknown")
	end
	if not integer(snapshot.Revision) or snapshot.Revision ~= reader.Revision then
		return block("Reward snapshot revision differs from the current reader revision")
	end
	local current, player = reader:GetSnapshot(), reader.Player
	local identity = snapshot.Identity and snapshot.Identity.UserId
	if type(current) ~= "table" or current.Ready ~= true or current.Revision ~= snapshot.Revision
		or not integer(identity) or identity < 1 or not player or player.UserId ~= identity then
		return block("Reward account identity or current ready snapshot is unavailable or changed")
	end
	local raw = reader:GetLiveProfile()
	if type(raw) ~= "table" then return block("Ready native LocalData reward profile unavailable") end
	local account = copy(raw)
	context.Account, context.Raw, context.AccountId = account, account, identity
	context.EffectiveMasteryUpgrades = copy(account.MasteryUpgrades)
	local function matchesSnapshot(profile)
		local upgrades, inventory = snapshot.Upgrades or {}, snapshot.Inventory or {}
		if upgrades.MasteryLevels ~= nil and not equal(upgrades.MasteryLevels, profile.MasteryLevels) then return false end
		if upgrades.MasteryUpgrades ~= nil and not equal(upgrades.MasteryUpgrades, profile.MasteryUpgrades) then return false end
		if snapshot.UnlockedIslands ~= nil and not equal(snapshot.UnlockedIslands, profile.AreasUnlocked) then return false end
		if snapshot.UnlockedWorlds ~= nil and not equal(snapshot.UnlockedWorlds, profile.WorldsUnlocked) then return false end
		for _, field in ipairs({ "Pets", "Powerups", "Potions" }) do
			if inventory[field] ~= nil and not equal(inventory[field], profile[field]) then return false end
		end
		for currency, balance in pairs(snapshot.Balances or {}) do if balance ~= profile[currency] then return false end end
		return true
	end
	if not matchesSnapshot(account) then return block("Snapshot reward prerequisites, inventory, or currency facts differ from live LocalData") end
	local modules, copiedModules = {}, {}
	local definitions = {
		Playtime = "Shared.Data.Playtime", DailyRewards = "Shared.Data.DailyRewards", WorldRewards = "Shared.Data.WorldRewards",
		Chests = "Shared.Data.Chests", Prizes = "Shared.Data.Prizes", Powerups = "Shared.Data.Powerups",
		Potions = "Shared.Data.Potions", WheelSpin = "Shared.Data.WheelSpin", ChallengePass = "Shared.Data.ChallengePass",
		Seasons = "Shared.Data.Seasons", Worlds = "Shared.Data.Worlds", Constants = "Shared.Constants",
		Time = "Shared.Framework.Utilities.Math.Time", IsTradingPlaza = "Shared.Utils.IsTradingPlaza",
		QuestUtil = "Shared.Utils.Stats.QuestUtil", PrizesUtil = "Shared.Utils.PrizesUtil", ItemUtil = "Shared.Utils.Stats.ItemUtil",
		StatsUtil = "Shared.Utils.Stats.StatsUtil",
	}
	for name, path in pairs(definitions) do
		local value = self:Get(name)
		if value == nil and type(reader.Dependencies) == "table" and reader.Dependencies[name] == nil and type(reader._load) == "function" then
			-- The existing cache/lifecycle owns this one nonblocking static dependency request.
			reader:_load(name, path, name == "IsTradingPlaza" and "function" or "table")
			value = self:Get(name)
		end
		if value ~= nil then modules[name], copiedModules[name] = value, copy(value)
		else
			local entry = type(reader.Dependencies) == "table" and reader.Dependencies[name]
			table.insert(context.Diagnostics, name .. ": " .. tostring(entry and entry.Status or "UNAVAILABLE"))
		end
	end
	for _, name in ipairs({ "Playtime", "DailyRewards", "WorldRewards", "Chests", "Prizes", "Powerups", "Potions", "WheelSpin", "ChallengePass", "Seasons", "Worlds" }) do
		context.Catalogs[name] = copy(modules[name])
	end
	local time = modules.Time
	if type(time) == "table" and type(time.now) == "function" then
		local ok, value = pcall(time.now)
		if ok and finite(value) then context.NativeNow = value else table.insert(context.Diagnostics, "Native Time.now unavailable or invalid") end
	end
	if type(time) == "table" and type(time.getAbsoluteDay) == "function" then
		local ok, value = pcall(time.getAbsoluteDay)
		if ok and integer(value) then context.NativeDay = value else table.insert(context.Diagnostics, "Native UTC absolute day unavailable or invalid") end
	end
	if type(modules.IsTradingPlaza) == "function" then
		local ok, value = pcall(modules.IsTradingPlaza)
		if ok and type(value) == "boolean" then
			context.IsTradingPlaza, context.TradingPlazaStatus = value, value and "ACTIVE" or "INACTIVE"
		end
	end
	if type(account.MasteryUpgrades) == "table" then
		local valid, observed = true, false
		for _, upgrade in pairs(account.MasteryUpgrades) do
			if type(upgrade) ~= "table" or type(upgrade.Type) ~= "string" then valid = false
			elseif upgrade.Type == "Playtime" then observed = true end
		end
		if observed then context.HasPlaytime = true elseif valid then context.HasPlaytime = false end
	end
	for currency, value in pairs(snapshot.Balances or {}) do if finite(value) then context.Balances[currency] = value end end
	local currencies = {}
	for _, definition in pairs(type(context.Catalogs.WorldRewards) == "table" and context.Catalogs.WorldRewards or {}) do
		if type(definition) == "table" and type(definition.Currency) == "string" then currencies[definition.Currency] = true end
	end
	for currency in pairs(currencies) do if finite(account[currency]) then context.Balances[currency] = account[currency] end end
	if type(account.DailyRewards) == "table" and finite(account.DailyRewards.Stars) then context.Balances.Stars = account.DailyRewards.Stars end
	local daily = { State = "UNKNOWN", NativeDay = context.NativeDay, Reason = "Explicit received daily day, streak, claim boolean and native day required" }
	context.DailyObservation = daily
	local receivedDaily = account.DailyRewards
	if type(receivedDaily) == "table" and integer(receivedDaily.LastDay) and integer(receivedDaily.LastStreak)
		and receivedDaily.LastStreak >= 1 and type(receivedDaily.Claimed) == "boolean" and integer(context.NativeDay) then
		daily.Observed, daily.Claimed, daily.DayIndex = true, receivedDaily.Claimed, (receivedDaily.LastStreak - 1) % 7 + 1
		local gifts = context.Catalogs.DailyRewards
		daily.DeclaredReward = type(gifts) == "table" and copy(gifts[daily.DayIndex]) or nil
		daily.GrantAssociation = "UNKNOWN: daily catalog gifts are not independently proven to be granted by the Stars claim request"
		if receivedDaily.LastDay < context.NativeDay then
			daily.State, daily.Locked, daily.Due, daily.Reason = "LOCKED", true, false, "Native daily UI reports a lost streak; recovery/rollover is unverified and never simulated"
		elseif receivedDaily.LastDay > context.NativeDay then
			daily.Reason = "Received daily day is ahead of the observed native day"
		elseif receivedDaily.Claimed then
			daily.State, daily.Due, daily.Reason = "CLAIMED", false, "Explicit received daily claim boolean is true for the native day"
		else
			daily.State, daily.Due, daily.Reason = "DUE", true, "Native daily login visibility prerequisites observed; server claim eligibility remains unknown"
		end
		local constants = modules.Constants
		if type(constants) == "table" and finite(constants.DailyRewardsStarsPerDay) and finite(constants.DailyRewardsStarCap) then
			daily.DeclaredStars = math.clamp(receivedDaily.LastStreak * constants.DailyRewardsStarsPerDay, 0, constants.DailyRewardsStarCap)
		end
	end
	local questUtil = modules.QuestUtil
	local seenQuests = {}
	for _, quest in pairs(type(account.Quests) == "table" and account.Quests or {}) do
		if type(quest) ~= "table" or type(quest.Id) ~= "string" or quest.Id == "" then continue end
		if seenQuests[quest.Id] then
			context.QuestObservations[quest.Id] = { State = "UNKNOWN", Reason = "Duplicate received quest identifiers are ambiguous", Tasks = {} }
			continue
		end
		seenQuests[quest.Id] = true
		local observation = { State = "UNKNOWN", Tasks = {}, Reason = "Complete explicit task requirements and progress required" }
		context.QuestObservations[quest.Id] = observation
		if type(quest.Tasks) ~= "table" or type(quest.Progress) ~= "table" then continue end
		local taskCount, completeCount, valid = 0, 0, true
		for index, taskDefinition in pairs(quest.Tasks) do
			if not integer(index) or index < 1 or type(taskDefinition) ~= "table" then valid = false continue end
			taskCount += 1
			local taskObservation = { Current = finite(quest.Progress[index]) and quest.Progress[index] or nil,
				State = "UNKNOWN", Reason = "Native requirement or explicit received progress unavailable" }
			observation.Tasks[index] = taskObservation
			if type(questUtil) == "table" and type(questUtil.GetRequirement) == "function" then
				local ok, required = pcall(questUtil.GetRequirement, questUtil, copy(taskDefinition))
				if ok and finite(required) and required > 0 then taskObservation.Required = required end
			end
			if taskObservation.Required ~= nil and taskObservation.Current ~= nil then
				taskObservation.Complete = taskObservation.Current == taskObservation.Required
				taskObservation.State, taskObservation.Reason = "OBSERVED", "Native QuestUtil exact-equality requirement and received progress observed"
				if taskObservation.Complete then completeCount += 1 end
			else valid = false end
		end
		if taskCount < 1 then valid = false end
		for index = 1, taskCount do if quest.Tasks[index] == nil then valid = false end end
		if valid then
			observation.Complete, observation.State = completeCount == taskCount, "OBSERVED"
			observation.Reason = "Native sequential task shape and exact-equality progress observed; automatic grant/claim timing unverified"
		end
	end
	local prizes, prizeUtil = context.Catalogs.Prizes, modules.PrizesUtil
	for _, prize in pairs(type(prizes) == "table" and type(prizes.data) == "table" and prizes.data or {}) do
		if type(prize) ~= "table" or type(prize.Key) ~= "string" or prize.Key == "" then continue end
		local observation = { Required = finite(prize.Requirement) and prize.Requirement or nil, State = "UNKNOWN",
			Reason = "Native prize progress helper and explicit prerequisite fields required" }
		context.PrizeObservations[prize.Key] = observation
		if type(prizeUtil) == "table" and type(prizeUtil.GetProgress) == "function" and type(prize.Type) == "string" then
			local ok, progress = pcall(prizeUtil.GetProgress, prizeUtil, copy(account), prize.Type)
			if ok and finite(progress) then observation.Progress = progress end
		end
		if observation.Required ~= nil and observation.Progress ~= nil then
			observation.Complete, observation.State = observation.Progress >= observation.Required, "OBSERVED"
			observation.Reason = "Native PrizesUtil progress meets or falls short of the catalog threshold; grant remains unverified"
		end
	end
	local pass, receivedPass = modules.ChallengePass, account.ChallengePass
	local challenge = { State = "UNKNOWN", Reason = "Current native pass identity, deadline, received points and native time required" }
	context.ChallengeObservation = challenge
	if type(pass) == "table" then
		challenge.Id = type(pass.Id) == "string" and pass.Id or nil
		local expiryOK, expiry = pcall(function() return pass.FinishTime and pass.FinishTime.UnixTimestamp end)
		if expiryOK and finite(expiry) then challenge.ExpiryUnix, challenge.Deadline = expiry, expiry end
		if challenge.Id and challenge.ExpiryUnix and finite(context.NativeNow) then
			challenge.Expired = context.NativeNow >= challenge.ExpiryUnix
			challenge.State = challenge.Expired and "EXPIRED" or "ACTIVE"
			challenge.Reason = "Current native catalog deadline compared with native server time; catalog presence alone is not active account availability"
		end
		if type(receivedPass) == "table" and finite(receivedPass.Points) and type(pass.GetTier) == "function" then
			local ok, tier = pcall(pass.GetTier, pass, receivedPass.Points)
			if ok and integer(tier) then challenge.EligibleTier = tier end
		end
	end
	local inventory = context.InventoryObservations
	local itemUtil = modules.ItemUtil
	local function owned(item, prerequisitePresent)
		if not prerequisitePresent or type(itemUtil) ~= "table" or type(itemUtil.GetOwnedAmount) ~= "function" then return nil end
		local ok, amount = pcall(itemUtil.GetOwnedAmount, itemUtil, copy(account), copy(item))
		return ok and integer(amount) and amount or nil
	end
	local function inventoryEntry(item, amount, definition, reason)
		return { Type = item.Type, Name = item.Name, Level = item.Level, Owned = amount, Amount = amount,
			QuantityStatus = amount ~= nil and "OBSERVED" or "UNKNOWN", State = amount ~= nil and "OBSERVED" or "UNKNOWN",
			Item = item, Definition = copy(definition), Reason = reason }
	end
	if type(account.Powerups) == "table" then
		for name, receivedAmount in pairs(account.Powerups) do
			if type(name) ~= "string" then continue end
			local definition = type(context.Catalogs.Powerups) == "table" and context.Catalogs.Powerups[name]
			local item = { Type = "Powerup", Name = name }
			local amount = type(definition) == "table" and owned(item, true) or nil
			if not integer(receivedAmount) or amount ~= receivedAmount then amount = nil end
			inventory.Powerups[name] = inventoryEntry(item, amount, definition,
				"Native ItemUtil agrees with an explicit received Powerups count; missing definitions or disagreement remain unknown; ownership does not authorize use")
			table.insert(inventory.Items, copy(inventory.Powerups[name]))
		end
	end
	if type(account.Potions) == "table" then
		local shapeValid, seenPotions = true, {}
		for _, record in pairs(account.Potions) do
			if type(record) ~= "table" or type(record.Name) ~= "string" or record.Name == ""
				or record.Level ~= nil and (not integer(record.Level) or record.Level < 1) or not integer(record.Amount) then
				shapeValid = false continue
			end
			local key = record.Name .. ":" .. tostring(record.Level or "DEFAULT")
			local definition = type(context.Catalogs.Potions) == "table" and context.Catalogs.Potions[record.Name]
			local item = { Type = "Potion", Name = record.Name, Level = record.Level }
			local amount = type(definition) == "table" and owned(item, true) or nil
			if amount ~= record.Amount then amount = nil end
			if seenPotions[key] then shapeValid, amount = false, nil end
			seenPotions[key] = true
			inventory.Potions[key] = inventoryEntry(item, amount, definition,
				"Native received Potions records carry exact Name/optional Level/Amount; duplicate, malformed or unsupported records stay unknown")
		end
		inventory.PotionSchemaState = shapeValid and "OBSERVED_NATIVE_RECORDS" or "UNKNOWN"
		for _, entry in pairs(inventory.Potions) do table.insert(inventory.Items, copy(entry)) end
	end
	inventory.SchemaState = type(account.Powerups) == "table" and inventory.PotionSchemaState == "OBSERVED_NATIVE_RECORDS" and "OBSERVED" or "PARTIAL_OR_UNKNOWN"
	local rendered = workspace and workspace:FindFirstChild("Rendered")
	local locations = rendered and rendered:FindFirstChild("Chests")
	local locationEntries = locations and locations:GetChildren() or nil
	for name in pairs(type(context.Catalogs.Chests) == "table" and context.Catalogs.Chests or {}) do
		if type(name) ~= "string" then continue end
		local observation = { Interaction = "UNKNOWN", Reason = "Native location representation is not proof of private physical chest registry membership" }
		context.ChestObservations[name] = observation
		if locationEntries then
			local matches = {}
			for _, instance in ipairs(locationEntries) do if instance.Name == name and instance.Parent == locations then table.insert(matches, instance) end end
			observation.LocationPresent, observation.Loaded = #matches > 0, #matches > 0
			if #matches == 1 then
				local island, world = matches[1]:GetAttribute("Island"), matches[1]:GetAttribute("World")
				observation.Island, observation.World = type(island) == "string" and island or nil, type(world) == "string" and world or nil
				if type(island) == "string" and type(account.AreasUnlocked) == "table" then
					local unlocked = account.AreasUnlocked[island]
					observation.Access, observation.MapAccess = unlocked ~= nil and unlocked ~= false, unlocked ~= nil and unlocked ~= false
					observation.AccessReason = "Native WorldMap map-area visibility uses the received area's truthy entry; physical/server interaction remains unknown"
				else observation.AccessReason = "Native WorldMap skips location entries with no Island; no world or physical access is inferred" end
			elseif #matches > 1 then observation.Reason = "Multiple native chest location representations; interaction and access identity remain unknown" end
		end
	end
	local storage = snapshot.Inventory or {}
	context.StorageObservation = { Used = finite(storage.StorageUsed) and storage.StorageUsed or nil,
		Capacity = finite(storage.StorageCapacity) and storage.StorageCapacity or nil,
		Reason = "Existing reader StatsUtil:GetUsedPetStorage/GetMaxPetStorage observations; missing units and server grant-space rules remain unknown" }
	for world, definition in pairs(type(context.Catalogs.WorldRewards) == "table" and context.Catalogs.WorldRewards or {}) do
		if type(world) ~= "string" or type(definition) ~= "table" then continue end
		local received = type(account.WorldRewards) == "table" and account.WorldRewards[world]
		local worldDefinition = type(context.Catalogs.Worlds) == "table" and context.Catalogs.Worlds[world]
		local observation = { WorldDefinitionState = type(worldDefinition) == "table" and "OBSERVED" or "UNKNOWN",
			WorldActivity = "UNKNOWN", Access = type(account.WorldsUnlocked) == "table" and account.WorldsUnlocked[world] == true or nil,
			Progress = type(received) == "table" and integer(received.Progress) and received.Progress or nil,
			Reason = "Native WorldRewards[world].Progress and strict WorldsUnlocked[world]==true; paid next-tier transaction, no permission" }
		if type(worldDefinition) == "table" then
			observation.Removed = worldDefinition.Removed ~= nil and worldDefinition.Removed ~= false
			observation.Event = worldDefinition.Event ~= nil and worldDefinition.Event ~= false
			observation.WorldActivity = observation.Removed and "REMOVED" or observation.Event and "UNKNOWN_EVENT_ACTIVITY" or "PERMANENT_CATALOG_DEFINITION"
		end
		if type(account.WorldsUnlocked) == "table" then observation.Access = account.WorldsUnlocked[world] == true end
		if observation.Progress ~= nil and type(definition.Levels) == "table" then
			local tier = definition.Levels[observation.Progress + 1]
			observation.NextTier = observation.Progress + 1
			observation.NativePrice = type(tier) == "table" and copy(tier.Cost) or nil
			observation.DeclaredReward = type(tier) == "table" and copy(tier.Reward) or nil
			local reward, stats = type(tier) == "table" and tier.Reward, modules.StatsUtil
			if type(reward) == "table" and reward.Type == "Pet" then
				if type(stats) == "table" and type(stats.IsInventoryFull) == "function" then
					local ok, full = pcall(stats.IsInventoryFull, stats, copy(account))
					if ok and type(full) == "boolean" then
						observation.StorageEligible = not full
						observation.StorageReason = "Native StatsUtil:IsInventoryFull observed for this next paid pet reward; grant sizing/server acceptance remains unverified"
					end
				end
			elseif type(reward) == "table" and type(reward.Type) == "string" then
				observation.StorageEligible, observation.StorageReason = true, "Native next reward descriptor is not a Pet; this does not authorize a paid request"
			end
		end
		context.WorldRewardObservations[world] = observation
	end
	local final, finalSnapshot = reader:GetLiveProfile(), reader:GetSnapshot()
	if self.Destroyed or reader.Destroyed or reader.Player ~= player or player.UserId ~= identity
		or reader.Revision ~= snapshot.Revision or type(finalSnapshot) ~= "table" or finalSnapshot.Ready ~= true
		or finalSnapshot.Revision ~= snapshot.Revision or type(final) ~= "table" or not matchesSnapshot(final) or not equal(account, final) then
		return block("Received reward account identity, revision, prerequisite or inventory facts changed during native observation")
	end
	for name, value in pairs(copiedModules) do if not equal(value, self:Get(name)) then return block("Native reward definitions or getter interfaces changed during observation") end end
	context.CompletedAt = now + math.max(0, os.clock() - startedAt)
	if context.CompletedAt - snapshot.ReadAt > maximumAge then return block("Reward account snapshot became stale during native observation") end
	context.Fresh = true
	return context
end
-- PHASE5_READ_ONLY_REWARDS_END
-- PHASE5_FREE_WHEEL_TICKET_BEGIN
-- One-family received observation. No wheel frame/queue is required or inferred,
-- and no remote/action is invoked. The existing reader owns every dependency load.
local function freeWheelCopy(value, seen)
	if type(value) ~= "table" then return value end
	seen = seen or {}
	if seen[value] then return seen[value] end
	local result = {} seen[value] = result
	for key, entry in pairs(value) do result[key] = freeWheelCopy(entry, seen) end
	return result
end

local function freeWheelEqual(left, right, seen)
	if type(left) ~= type(right) then return false end
	if type(left) ~= "table" then return left == right end
	seen = seen or {}
	if seen[left] == right then return true end
	seen[left] = right
	for key, value in pairs(left) do if not freeWheelEqual(value, right[key], seen) then return false end end
	for key in pairs(right) do if left[key] == nil then return false end end
	return true
end

local function freeWheelNumber(value)
	return type(value) == "number" and value == value and value >= 0 and value < math.huge
end

local function freeWheelCount(value) return freeWheelNumber(value) and value % 1 == 0 end

function GameKnowledge:FreeWheelTicketContext(snapshot, now, settings)
	settings = settings or {}
	local startedAt = os.clock()
	local context = { Fresh = false, AutoClaimSpin = "UNKNOWN", QueueState = "UNKNOWN", ObservedAt = now,
		InterferenceFacts = { Balances = {}, Powerups = {}, OtherRewards = {}, Available = {} },
		NativeInterfaceIds = {}, Evidence = "WheelSpin:373,400-412,595; ItemUtil:466; native queue/proximity and grant attribution remain unverified" }
	local function block(reason) context.Fresh, context.Blocker = false, reason return context end
	if settings.ENABLE_FREE_WHEEL_TICKET_CLAIM ~= true then return block("Free wheel ticket claim observation is disabled") end
	local reader = self.Reader
	if self.Destroyed or not reader or reader.Destroyed then return block("Free wheel ticket reader is unavailable") end
	local guards = { Remote = "Shared.Framework.Network.Remote", HatchPresentation = "Client.Effects.HatchEgg",
		GuiFrame = "Client.Gui.GuiFrame", PhysicalItem = "Client.Effects.PhysicalItem",
		FishingPlayerRods = "Client.Gui.Frames.Fishing.FishingPlayerRods" }
	for name, path in pairs(guards) do
		if self:Get(name) == nil and type(reader.Dependencies) == "table" and reader.Dependencies[name] == nil
			and type(reader._load) == "function" then reader:_load(name, path, "table") end
	end
	-- Reuse received snapshot/coherence checks and the completed reward catalog cache.
	local received = self:RewardContext(snapshot, now, settings)
	if type(received) ~= "table" or received.Fresh ~= true then
		return block(type(received) == "table" and received.Blocker or "Fresh received reward context unavailable")
	end
	context.AccountId, context.Revision, context.ReadAt = received.AccountId, snapshot.Revision, snapshot.ReadAt
	local player, raw = reader.Player, reader:GetLiveProfile()
	local account = freeWheelCopy(received.Account)
	if type(raw) ~= "table" or type(account) ~= "table" or not freeWheelEqual(account, raw) then
		return block("Received free wheel facts changed after reward observation")
	end
	local inventory, upgrades = snapshot.Inventory, snapshot.Upgrades
	if type(inventory) ~= "table" or type(inventory.Powerups) ~= "table" or type(account.Powerups) ~= "table"
		or not freeWheelEqual(inventory.Powerups, account.Powerups) then
		return block("Complete received Powerups inventory baseline is unavailable or inconsistent")
	end
	for name, amount in pairs(account.Powerups) do
		if type(name) ~= "string" or name == "" or not freeWheelCount(amount) then
			return block("Received Powerups map contains an invalid name or count")
		end
	end
	if type(upgrades) ~= "table" or type(upgrades.MasteryUpgrades) ~= "table" or type(account.MasteryUpgrades) ~= "table"
		or not freeWheelEqual(upgrades.MasteryUpgrades, account.MasteryUpgrades) then
		return block("Explicit received MasteryUpgrades evidence is unavailable or inconsistent")
	end
	local autoClaim = false
	for key, upgrade in pairs(account.MasteryUpgrades) do
		if not (type(key) == "string" and key ~= "" or freeWheelCount(key) and key >= 1)
			or type(upgrade) ~= "table" or type(upgrade.Type) ~= "string" or upgrade.Type == "" then
			return block("Received MasteryUpgrades map is malformed; AutoClaimSpin stays UNKNOWN")
		end
		if upgrade.Type == "AutoClaimSpin" then autoClaim = true end
	end
	context.AutoClaimSpin = autoClaim
	if autoClaim then return block("Native AutoClaimSpin is active") end
	local modules = {}
	for name in pairs(guards) do
		local value = self:Get(name)
		if type(value) ~= "table" then return block("Required free wheel guard/transport dependency unavailable: " .. name) end
		modules[name] = value
	end
	if type(modules.Remote.FireServer) ~= "function" or type(modules.HatchPresentation.IsHatching) ~= "function"
		or type(modules.GuiFrame.IsAnyOpen) ~= "function" or type(modules.PhysicalItem.GetActiveObjects) ~= "function"
		or type(modules.FishingPlayerRods.GetRodComponent) ~= "function" then
		return block("Required reviewed free wheel guard/transport interfaces unavailable")
	end
	local guardMethods = { Remote = "FireServer", HatchPresentation = "IsHatching", GuiFrame = "IsAnyOpen",
		PhysicalItem = "GetActiveObjects", FishingPlayerRods = "GetRodComponent" }
	local guardGetters = {}
	for name, method in pairs(guardMethods) do guardGetters[name] = modules[name][method] end
	local giftGetter = guardGetters.PhysicalItem
	local giftOK, giftCount = pcall(giftGetter, modules.PhysicalItem, "Gift")
	if not giftOK or not freeWheelCount(giftCount) then return block("Native active gift count is unavailable or invalid") end
	context.GiftCount = giftCount
	if giftCount > 0 then return block("Known active gifts conflict with free wheel receipt attribution") end
	local itemUtil, powerups, time = self:Get("ItemUtil"), self:Get("Powerups"), self:Get("Time")
	local ticket = type(powerups) == "table" and powerups["Spin Ticket"]
	if type(itemUtil) ~= "table" or type(itemUtil.GetOwnedAmount) ~= "function" or type(ticket) ~= "table"
		or type(received.Catalogs) ~= "table" or type(received.Catalogs.Powerups) ~= "table"
		or not freeWheelEqual(received.Catalogs.Powerups, powerups) then
		return block("Canonical native Spin Ticket definition/getter is unavailable or changed")
	end
	if type(time) ~= "table" or type(time.now) ~= "function" or not freeWheelNumber(received.NativeNow) then
		return block("Native free wheel deadline time is unavailable")
	end
	if not freeWheelNumber(account.NextWheelSpin) then return block("Explicit received NextWheelSpin deadline is unavailable") end
	local getter, clockGetter, ticketBefore = itemUtil.GetOwnedAmount, time.now, freeWheelCopy(ticket)
	local powerupsBefore, itemBefore = freeWheelCopy(powerups), freeWheelCopy(itemUtil)
	local timeOK, nativeBefore = pcall(clockGetter)
	if not timeOK or not freeWheelNumber(nativeBefore) or nativeBefore < received.NativeNow then
		return block("Native free wheel time is unavailable or moved backwards")
	end
	local observedOK, amount = pcall(getter, itemUtil, freeWheelCopy(account), { Type = "Powerup", Name = "Spin Ticket" })
	local expected = account.Powerups["Spin Ticket"]
	-- Native ItemUtil maps an absent item key to zero; only this already validated,
	-- complete received map permits absence. A missing whole inventory never does.
	if expected == nil then expected = 0 end
	if not observedOK or not freeWheelCount(amount) or amount ~= expected then
		return block("Native ItemUtil and complete received canonical Spin Ticket count disagree")
	end
	local finalGiftOK, finalGiftCount = pcall(giftGetter, modules.PhysicalItem, "Gift")
	if not finalGiftOK or not freeWheelCount(finalGiftCount) then
		return block("Native active gift count became unavailable or invalid during item observation")
	end
	context.GiftCount = finalGiftCount
	if finalGiftCount > 0 then return block("Known active gifts appeared during free wheel item observation") end
	local finalTimeOK, nativeAfter = pcall(clockGetter)
	if not finalTimeOK or not freeWheelNumber(nativeAfter) or nativeAfter < nativeBefore then
		return block("Native free wheel time became unavailable or moved backwards during item observation")
	end
	local final, finalSnapshot = reader:GetLiveProfile(), reader:GetSnapshot()
	if self.Destroyed or self.Reader ~= reader or reader.Destroyed or reader.Player ~= player
		or not player or player.UserId ~= context.AccountId or reader.Revision ~= context.Revision
		or type(finalSnapshot) ~= "table" or finalSnapshot.Ready ~= true or finalSnapshot.Revision ~= context.Revision
		or not freeWheelEqual(snapshot, finalSnapshot) or final ~= raw or not freeWheelEqual(account, final) then
		return block("Free wheel account identity, snapshot or received facts changed during native item observation")
	end
	if self:Get("ItemUtil") ~= itemUtil or itemUtil.GetOwnedAmount ~= getter or not freeWheelEqual(itemBefore, itemUtil)
		or self:Get("Powerups") ~= powerups or powerups["Spin Ticket"] ~= ticket
		or not freeWheelEqual(powerupsBefore, powerups) or not freeWheelEqual(ticketBefore, ticket)
		or self:Get("Time") ~= time or time.now ~= clockGetter then
		return block("Native free wheel definition/getter/time identity changed during observation")
	end
	for name, value in pairs(modules) do
		if self:Get(name) ~= value or value[guardMethods[name]] ~= guardGetters[name] then
			return block("Required native free wheel guard/transport identity changed: " .. name)
		end
	end
	local completedAt = now + math.max(0, os.clock() - startedAt)
	local maximumAge = settings.MAXIMUM_ACCOUNT_AGE_SECONDS or 10
	if not freeWheelNumber(maximumAge) or not freeWheelNumber(snapshot.ReadAt) or completedAt - snapshot.ReadAt > maximumAge then
		return block("Free wheel received snapshot became stale during native observation")
	end
	context.NextWheelSpin, context.NativeNow, context.TicketCount = account.NextWheelSpin, nativeAfter, amount
	context.Due, context.TicketDefinition, context.CompletedAt = account.NextWheelSpin <= nativeAfter, freeWheelCopy(ticket), completedAt
	local interference = context.InterferenceFacts
	interference.Balances = freeWheelCopy(received.Balances)
	interference.Available.Balances, interference.Available.Powerups = true, true
	for name, value in pairs(account.Powerups) do if name ~= "Spin Ticket" then interference.Powerups[name] = value end end
	for _, field in ipairs({ "Potions", "Pets" }) do
		interference.Available[field] = type(account[field]) == "table"
		if not interference.Available[field] then return block("Required received interference inventory unavailable: " .. field) end
		interference[field] = freeWheelCopy(account[field])
	end
	-- Preserve availability explicitly. These are received comparison facts, not an
	-- invented queue schema or permission to run any of the other reward families.
	for _, field in ipairs({ "PlaytimeRewards", "DailyRewards", "WorldRewards", "Quests", "QuestsCompleted", "ClaimedPrizes", "ChallengePass", "Season", "Cooldowns" }) do
		interference.Available[field] = account[field] ~= nil
		if account[field] ~= nil then interference.OtherRewards[field] = freeWheelCopy(account[field]) end
	end
	for field, value in pairs(account) do
		if type(field) == "string" and string.sub(field, 1, 4) == "Next" and field ~= "NextWheelSpin" then
			interference.Available[field], interference.OtherRewards[field] = true, freeWheelCopy(value)
		end
	end
	for name, value in pairs({ ItemUtil = itemUtil, GetOwnedAmount = getter, Powerups = powerups, SpinTicket = ticket,
		Time = time, TimeNow = clockGetter, Remote = modules.Remote, FireServer = modules.Remote.FireServer }) do
		context.NativeInterfaceIds[name] = self:InstanceId(value)
	end
	for name, value in pairs(modules) do
		context.NativeInterfaceIds[name] = self:InstanceId(value)
		context.NativeInterfaceIds[name .. "." .. guardMethods[name]] = self:InstanceId(guardGetters[name])
	end
	context.Fresh = true
	return context
end
-- PHASE5_FREE_WHEEL_TICKET_END
return GameKnowledge

end

-- src/OCFoundation/GameMechanics.luau
factories["GameMechanics"] = function()
--!nonstrict
-- Native command adapter. Stationary pickup requests are experimental; server credit is never inferred from invocation.
local GameMechanics = {}
GameMechanics.__index = GameMechanics
local CollectionService = game:GetService("CollectionService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

function GameMechanics.new(config, reader, tracker, player, log)
	return setmetatable({ Config = config, Reader = reader, Tracker = tracker, Player = player,
		LastBlowAt = -math.huge, LastTravelAt = -math.huge, LastDiscoveryAt = -math.huge,
		IslandDiscoveryAttempts = {}, Failures = {}, PathThread = nil, Log = log }, GameMechanics)
end

function GameMechanics:Guard(expectedUnlockTitle)
	local root, humanoid = self.Tracker:Root()
	if not root then return false, "Character is not alive" end
	local plaza = self.Reader:_dependency("IsTradingPlaza")
	local frames = self.Reader:_dependency("GuiFrame")
	local rods = self.Reader:_dependency("FishingPlayerRods")
	if not plaza or not frames or not rods then return false, "Interaction guard modules are not ready" end
	local ok, reason = pcall(function()
		if plaza() then return "Trading plaza is active" end
		if self.Player:GetAttribute("InRace") then return "An island race owns movement" end
		if rods:GetRodComponent(self.Player) ~= nil then return "A fishing rod is active" end
		local gui = self.Player:FindFirstChild("PlayerGui")
		local screen = gui and gui:FindFirstChild("ScreenGui")
		if not gui or not screen then return "Game ScreenGui is unavailable" end
		if gui:FindFirstChild("Intro") or gui:FindFirstChild("TransitionGui") then return "Intro or transition is active" end
		local trading = screen:FindFirstChild("Trading")
		if trading and trading.Visible then return "Trading is active" end
		if screen:FindFirstChild("Prompt") then return "A game prompt or frame is open" end
		if frames:IsAnyOpen() then
			-- Native gate entry itself opens Unlock. Permit only its exact expected world title.
			local unlock = screen:FindFirstChild("Unlock")
			local frame = unlock and unlock:FindFirstChild("Frame")
			local top = frame and frame:FindFirstChild("Top")
			local label = top and top:FindFirstChild("Label")
			if not expectedUnlockTitle or not frames.IsOpen or not frames:IsOpen("Unlock") or frames:IsOpen("WorldMap")
				or not label or label.Text ~= expectedUnlockTitle then return "A game prompt or frame is open" end
		end
		return nil
	end)
	if not ok then return false, "Interaction guards failed: " .. tostring(reason) end
	if reason then return false, reason end
	return true, nil, root, humanoid
end

function GameMechanics:CanBlow()
	if not self:BubbleRequirement() then return false, "No active verified unfinished bubble task" end
	if self.Config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST then return false, "Isolated stationary test blocks blowing" end
	if not self.Config.BUBBLE_SETTINGS.AUTO_BLOW_BUBBLES then return false, "Bubble blowing is disabled" end
	local allowed, reason = self:Guard()
	if not allowed then return false, reason end
	local raw = self.Reader:GetLiveProfile()
	if not raw or type(raw.Bubble) ~= "table" or type(raw.Settings) ~= "table" then return false, "Bubble profile is unavailable" end
	if raw.Settings["Bubble Lock"] == true then return false, "Bubble Lock is enabled" end
	local effects = self.Reader:_dependency("PhysicalItem")
	if not effects then return false, "PhysicalItem guard is unavailable" end
	if effects.IsGiftInRange then return false, "Gift interaction is active" end
	local screen = self.Player.PlayerGui.ScreenGui
	local hud, race = screen:FindFirstChild("HUD"), screen:FindFirstChild("IslandRace")
	if not ((hud and hud.Visible) or (race and race.Visible)) then return false, "Bubble HUD is hidden" end
	local capacity = self.Reader:_stat("GetBubbleStorage", raw, {})
	if type(raw.Bubble.Amount) ~= "number" or not capacity then return false, "Actual bubble capacity is unavailable" end
	if raw.Bubble.Amount >= capacity and not (raw.Passes and raw.Passes["Infinity Gum"]) then return false, "Bubble is full" end
	return true
end

function GameMechanics:Blow(token)
	if token:CheckCancelled() then return false end
	if not self:BubbleRequirement() then return false end
	if os.clock() - self.LastBlowAt < self.Config.BUBBLE_SETTINGS.BLOW_COOLDOWN_SECONDS then return false end
	local permitted, reason = self:CanBlow()
	if not permitted then self.LastBlocker = reason return false end
	local remote = self.Reader:_dependency("Remote")
	if not remote or type(remote.FireServer) ~= "function" then self.LastBlocker = "Native Remote module unavailable" return false end
	if token:CheckCancelled() then return false end
	if not self:BubbleRequirement() then return false end
	self.LastBlowAt = os.clock()
	remote:FireServer("BlowBubble")
	self.LastBlocker = nil
	return true
end

function GameMechanics:BubbleRequirement()
	return self.BubbleGoalProvider and self.BubbleGoalProvider() or nil
end

function GameMechanics:Failure(key, seconds, reason)
	self.Failures[key] = { Until = os.clock() + seconds, Reason = reason }
end

function GameMechanics:Available(key)
	local failed = self.Failures[key]
	return not failed or os.clock() >= failed.Until
end

function GameMechanics:Unlocked(world, area)
	local raw = self.Reader:GetLiveProfile()
	return raw and type(raw.WorldsUnlocked) == "table" and raw.WorldsUnlocked[world] ~= nil
		and (world == area or (type(raw.AreasUnlocked) == "table" and raw.AreasUnlocked[area] ~= nil)) or false
end

function GameMechanics:CollectStationary(record, token)
	local settings = self.Config.PICKUP_SETTINGS
	if token:CheckCancelled() then return false, "Cancelled" end
	if self.PendingPickupCleanup then
		self:RetryPickupCleanup(token)
		if self.PendingPickupCleanup then return false, "Native visual cleanup is pending; new dispatches are held to prevent accumulation" end
	end
	if settings.COLLECTION_METHOD ~= "STATIONARY" or not settings.BULK_COLLECT_PICKUPS or not settings.ENABLE_CONTINUOUS_SCANNING then return false, "Stationary collection disabled" end
	if os.clock() - (self.LastPickupRequestAt or -math.huge) < settings.STATIONARY_REQUEST_COOLDOWN_SECONDS - 1e-6 then return false, "Stationary request cooldown" end
	local permitted, reason, root = self:Guard()
	if not permitted then return false, reason end
	local area = self.Tracker.Current
	local hatchLocation = self.HatchLocationProvider and self.HatchLocationProvider(area)
	if not area or (not hatchLocation and (area.World ~= "The Overworld" or (area.Name ~= "The Void" and area.Name ~= "Zen")))
		or record.AreaKey ~= area.Key or not self:Unlocked(area.World, area.Name) then return false, "Stationary island excluded, stale or locked" end
	if self.Config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND and self.Config.ISLAND_SETTINGS.PREFERRED_FARMING_ISLAND ~= ""
		and os.clock() - (self.Tracker.ArrivedAt or os.clock()) < self.Config.ISLAND_SETTINGS.ARRIVAL_PICKUP_GRACE_SECONDS then return false, "Selected island/character stabilization pending" end
	local selected = self.Config.ISLAND_SETTINGS.SELECTED_ISLANDS
	local worlds = self.Config.BRAIN_SETTINGS.SELECTED_WORLDS
	if not hatchLocation and ((#selected > 0 and not table.find(selected, area.Name) and not table.find(selected, area.Key))
		or (#worlds > 0 and not table.find(worlds, area.World))) then return false, "Stationary island excluded by Config" end
	local registry = self.Tracker.Knowledge:ActivePickups()
	local key = record.RegistryKey or record.Id
	local model = record.Model
	if type(key) ~= "string" and type(key) ~= "number" then return false, "Genuine registry ID unavailable" end
	if (type(key) == "number" and (key ~= key or math.abs(key) == math.huge)) or key == "" then return false, "Invalid native registry ID" end
	if not registry or registry[key] ~= model or not model or not model.Parent or not model:IsA("Model")
		or not model:IsDescendantOf(workspace) or tostring(key) ~= model.Name then return false, "Live native registry entry unavailable or changed" end
	if record.Currency ~= "Coins" and record.Currency ~= "Gems" then return false, "Stationary collection accepts only Coins/Gems" end
	local range = self.Tracker:ReadRange()
	local position = model:GetPivot().Position
	local distance = (position - root.Position).Magnitude
	local outsideNative = nil
	if range then outsideNative = distance > range end
	-- Distance/radius are observations only. Genuine loaded IDs are subject to the server's validation.
	local remotes = ReplicatedStorage:FindFirstChild("Remotes")
	local pickups = remotes and remotes:FindFirstChild("Pickups")
	local remote = pickups and pickups:FindFirstChild("CollectPickup")
	if not remote or not remote:IsA("RemoteEvent") then return false, "Native CollectPickup RemoteEvent unavailable" end
	local chunker, chunkerReason = self.Tracker.Knowledge:PickupChunker()
	if not chunker then return false, chunkerReason end
	if not chunker:IsValueLoaded(model) then return false, "Pickup is no longer in the native pickup Chunker" end
	local freshRegistry = self.Tracker.Knowledge:ActivePickups()
	if not self.Tracker.Current or self.Tracker.Current.Key ~= area.Key or not self:Unlocked(area.World, area.Name)
		or not freshRegistry or freshRegistry[key] ~= model or not model.Parent or tostring(key) ~= model.Name then return false, "Registry/island changed before dispatch" end
	if token:CheckCancelled() then return false, "Cancelled" end
	if hatchLocation and not self.HatchLocationProvider(area) then return false, "Hatch location ownership ended before pickup dispatch" end
	self.LastPickupRequestAt = os.clock()
	local ok, errorText = pcall(function() remote:FireServer(key) end)
	local cleaned, cleanupReason = false, nil
	if ok then
		self.PendingPickupCleanup = { Record = record, Chunker = chunker, Position = position, Until = os.clock() }
		cleaned, cleanupReason = self:RetryPickupCleanup({ CheckCancelled = function() return false end }) -- Finish cleanup of this already-dispatched request.
	end
	return true, ok and "Request invoked; credit awaits LocalData" or "Invocation error; credit unknown: " .. tostring(errorText),
		{ Id = tostring(key), Distance = distance, Radius = range, OutsideNativeRange = outsideNative, InvocationSucceeded = ok, VisualCleaned = cleaned, CleanupError = cleanupReason }
end

function GameMechanics:RetryPickupCleanup(token)
	local pending = self.PendingPickupCleanup
	if not pending then return true end
	if token:CheckCancelled() or os.clock() < pending.Until then return false, pending.Reason or "Native cleanup retry backoff" end
	local record, chunker = pending.Record, pending.Chunker
	local model, key = record.Model, record.RegistryKey or record.Id
	local ok, reason = pcall(function()
		local registry = self.Tracker.Knowledge:ActivePickups()
		if not registry then error("Native registry unavailable for cleanup") end
		if registry[key] ~= nil and registry[key] ~= model then error("Native registry replacement retained; cleanup pending") end
		-- Native Remove releases the actual chunk, Unloaded/animation state and registry entry.
		chunker:Remove(pending.Position, model) -- Also release a chunk that unloaded while cleanup was in backoff.
		if chunker:IsValueLoaded(model) then error("Native Chunker still retains pickup") end
		if registry[key] == model then registry[key] = nil end
		model:Destroy() self.Tracker:ForgetCollected(record)
	end)
	if ok then self.PendingPickupCleanup = nil
	else pending.Reason, pending.Until = tostring(reason), os.clock() + self.Config.PICKUP_SETTINGS.STATIONARY_ID_RETRY_SECONDS end
	return ok, not ok and tostring(reason) or nil
end

function GameMechanics:SellStations()
	local result, root = {}, self.Tracker:Root()
	if not root then return result end
	local worlds = workspace:FindFirstChild("Worlds")
	for _, model in ipairs(CollectionService:GetTagged("Activation")) do
		local stationRoot = model:FindFirstChild("Root")
		if model.Name ~= "Sell" or not model:IsDescendantOf(workspace) or not stationRoot or not stationRoot:IsA("BasePart") then continue end
		local node, world, area = model, nil, nil
		while node and node ~= workspace do
			if node.Parent and node.Parent.Name == "Islands" then area = node.Name end
			if node.Parent == worlds then world = node.Name end
			node = node.Parent
		end
		area = area or world
		-- Match the locations used by native HUD.findBestSell; nested VIP/event facilities have unverified access rules.
		local worldRoot = worlds and worlds:FindFirstChild(world or "")
		local islandRoot = worldRoot and worldRoot:FindFirstChild("Islands")
		local island = islandRoot and islandRoot:FindFirstChild(area or "")
		local islandModel = island and island:FindFirstChild("Island")
		if model.Parent ~= worldRoot and model.Parent ~= islandModel then continue end
		if not world or not self:Unlocked(world, area) or not self:Available("SELL:" .. model:GetFullName()) then continue end
		local multiplier = model:GetAttribute("Multiplier") or 1 -- Verified native HUD defaults.
		local currency = model:GetAttribute("Currency") or "Coins"
		if type(multiplier) ~= "number" or multiplier <= 0 or type(currency) ~= "string" then continue end
		self.Reader:RegisterCurrency(currency)
		table.insert(result, { Model = model, Root = stationRoot, Key = model:GetFullName(), World = world, Area = area,
			Currency = currency, Multiplier = multiplier, Distance = (stationRoot.Position - root.Position).Magnitude,
			SellCycleSeconds = self.SellTimes and self.SellTimes[model:GetFullName()],
			TravelSeconds = self.TravelTimes and self.TravelTimes[stationRoot:GetFullName()] })
	end
	return result
end

function GameMechanics:Travel(destination, world, area, token, islandTravel, sellingTravel)
	if self.PetLocationOwnerProvider and self.PetLocationOwnerProvider() then return false, "Authorized hatch task owns location" end
	local hatch = self.Config.PET_SETTINGS.ENABLE_PET_INTELLIGENCE and self.Config.PET_SETTINGS.AUTO_HATCH and self.Reader:_dependency("HatchPresentation")
	if hatch then local ok, active = pcall(function() return hatch:IsHatching() end) if not ok or active ~= false then return false, "Native hatch presentation owns movement" end end
	if sellingTravel and not self:BubbleRequirement() then return false, "Selling travel requires an active verified bubble task" end
	if self.Config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST and not islandTravel then return false, "Pickup-only mode blocks selling excursions" end
	local permitted, reason = self:Guard()
	if not permitted then return false, reason end
	if token:CheckCancelled() then return false, "Cancelled" end
	if not self.Config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND then return false, "Supported teleport travel is disabled" end
	if not destination or not destination.Parent or not destination:IsA("BasePart") or not destination:IsDescendantOf(workspace)
		or not self:Unlocked(world, area) then return false, "Destination is unavailable or locked" end
	local path = destination:GetFullName()
	if not self:Available("TRAVEL:" .. path) then return false, "Destination travel is in backoff" end
	if os.clock() - self.LastTravelAt < self.Config.ISLAND_SETTINGS.TRAVEL_COOLDOWN_SECONDS then return false, "Travel cooldown" end
	local remote = self.Reader:_dependency("Remote")
	if not remote or type(remote.FireServer) ~= "function" then return false, "Native Remote module unavailable" end
	local started = os.clock()
	self.LastTravelAt = started
	if token:CheckCancelled() then return false, "Cancelled" end
	if sellingTravel and not self:BubbleRequirement() then return false, "Bubble task ended before selling travel" end
	local sent, transportError = pcall(function() remote:FireServer("Teleport", path) end)
	if not sent then
		self:Failure("TRAVEL:" .. path, self.Config.ISLAND_SETTINGS.TRAVEL_RETRY_COOLDOWN_SECONDS, tostring(transportError))
		return false, "Native teleport invocation failed: " .. tostring(transportError)
	end
	local arrivedAt
	while not token:CheckCancelled() and os.clock() - started < self.Config.ISLAND_SETTINGS.TRAVEL_CONFIRMATION_TIMEOUT_SECONDS do
		local root = self.Tracker:Root()
		if root and destination.Parent and (root.Position - destination.Position).Magnitude <= self.Config.ISLAND_SETTINGS.ARRIVAL_DISTANCE_STUDS then
			arrivedAt = arrivedAt or os.clock()
			if os.clock() - arrivedAt >= 0.4 then
				local seconds = os.clock() - started
				self.TravelTimes = self.TravelTimes or {} self.TravelTimes[path] = seconds
				return true, "Character arrival confirmed", seconds
			end
		else arrivedAt = nil end
		task.wait(0.1)
	end
	if not token:CheckCancelled() then self:Failure("TRAVEL:" .. path, self.Config.ISLAND_SETTINGS.TRAVEL_RETRY_COOLDOWN_SECONDS, "Arrival was not confirmed") end
	return false, token:CheckCancelled() and "Cancelled" or "Arrival was not confirmed"
end

function GameMechanics:TravelIsland(area, token)
	if token:CheckCancelled() then return false, "Cancelled" end
	if not self.Config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND or not self.Config.ISLAND_SETTINGS.AUTO_SELECT_BEST_ISLAND then return false, "Native island selection/travel disabled" end
	if not self:Unlocked(area.World, area.Name) then return false, "Actual LocalData island/world access is locked or unavailable" end
	local selected = self.Config.ISLAND_SETTINGS.SELECTED_ISLANDS
	if area.World ~= "The Overworld" or (area.Name ~= "Zen" and area.Name ~= "The Void")
		or (#selected > 0 and not table.find(selected, area.Name) and not table.find(selected, area.Key)) then return false, "Farming teleport destination is excluded" end
	if self.Tracker.Current and self.Tracker.Current.Key == area.Key then
		local root = self.Tracker:Root()
		for _, zone in ipairs(self.Tracker.Current.Zones or {}) do
			if root and math.abs(root.Position.Y - zone.Data.Zone.Height) <= self.Config.PICKUP_SETTINGS.MAXIMUM_VERTICAL_DIFFERENCE_STUDS
				and zone.Data.Zone:GetDistanceToPoint(root.Position) <= self.Config.PICKUP_SETTINGS.MAXIMUM_ROUTE_DISTANCE_STUDS then
				return true, "Already on selected island; no teleport dispatched", 0
			end
		end
	end
	if area.Spawn then return self:Travel(area.Spawn, area.World, area.Name, token, true) end
	local permitted, reason = self:Guard()
	if not permitted then return false, reason end
	if token:CheckCancelled() then return false, "Cancelled" end
	local path = area.DestinationPath
	local expected = "Workspace.Worlds." .. tostring(area.World) .. ".Islands." .. tostring(area.Name) .. ".Island.Portal.Spawn"
	if not self.Config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND or not self.Config.ISLAND_SETTINGS.AUTO_SELECT_BEST_ISLAND
		or not area.CatalogKnown or path ~= expected or area.MappingWarning or not self:Unlocked(area.World, area.Name) then
		return false, "Native island destination/access/zone evidence unavailable"
	end
	if not self:Available("TRAVEL:" .. path) or os.clock() - self.LastTravelAt < self.Config.ISLAND_SETTINGS.TRAVEL_COOLDOWN_SECONDS then return false, "Travel cooldown/backoff" end
	local remote = self.Reader:_dependency("Remote")
	if not remote or type(remote.FireServer) ~= "function" then return false, "Native Remote module unavailable" end
	local started, stable = os.clock(), nil
	self.LastTravelAt = started
	-- Matches native WorldMap/WorldUtil; a server destination need not be replicated locally.
	if token:CheckCancelled() then return false, "Cancelled" end
	local sent, transportError = pcall(function() remote:FireServer("Teleport", path) end)
	if not sent then
		self:Failure("TRAVEL:" .. path, self.Config.ISLAND_SETTINGS.TRAVEL_RETRY_COOLDOWN_SECONDS, tostring(transportError))
		return false, "Native teleport invocation failed: " .. tostring(transportError)
	end
	while not token:CheckCancelled() and os.clock() - started < self.Config.ISLAND_SETTINGS.TRAVEL_CONFIRMATION_TIMEOUT_SECONDS do
		self.Tracker:Refresh(self.Reader:GetSnapshot(), os.clock())
		local actual = self.Tracker.Current
		local root = self.Tracker:Root()
		local inside = false
		if root and actual and actual.Key == area.Key then
			for _, zone in ipairs(actual.Zones) do
				if math.abs(root.Position.Y - zone.Data.Zone.Height) <= self.Config.PICKUP_SETTINGS.MAXIMUM_VERTICAL_DIFFERENCE_STUDS
					and zone.Data.Zone:GetDistanceToPoint(root.Position) <= self.Config.PICKUP_SETTINGS.MAXIMUM_ROUTE_DISTANCE_STUDS then inside = true break end
			end
		end
		if inside then
			stable = stable or os.clock()
			if os.clock() - stable >= 0.4 then
				local seconds = os.clock() - started
				self.TravelTimes = self.TravelTimes or {} self.TravelTimes[path] = seconds
				return true, "Actual island height and nearby target pickup-zone arrival confirmed", seconds
			end
		else stable = nil end
		task.wait(0.2)
	end
	if not token:CheckCancelled() then self:Failure("TRAVEL:" .. path, self.Config.ISLAND_SETTINGS.TRAVEL_RETRY_COOLDOWN_SECONDS, "Target pickup-zone arrival unconfirmed") end
	return false, token:CheckCancelled() and "Cancelled" or "Target pickup-zone arrival unconfirmed"
end

function GameMechanics:StopMovement()
	-- Compatibility hook: this build never owns character movement or pathfinding.
end

function GameMechanics:Walk()
	return false, "OC automatic walking has been removed; no pickup movement fallback"
end

function GameMechanics:Upgrade(upgrade, token)
	if self.Config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST then return false, "Isolated stationary test blocks upgrades" end
	if token:CheckCancelled() then return false, "Cancelled" end
	local permitted, reason = self:Guard()
	if not permitted then return false, reason end
	local config, raw = self.Config, self.Reader:GetLiveProfile()
	if not config.FARMING_SETTINGS.AUTO_RESOURCE_FARM or not config.UPGRADE_SETTINGS.ENABLE_SMART_UPGRADES then return false, "Upgrade automation disabled" end
	if upgrade.Kind == "Gum" and not config.UPGRADE_SETTINGS.ENABLE_CAPACITY_UPGRADES then return false, "Capacity upgrades disabled" end
	if upgrade.Kind == "Flavors" and not config.UPGRADE_SETTINGS.ENABLE_FLAVOR_UPGRADES then return false, "Flavor upgrades disabled" end
	if not raw or type(raw.Bubble) ~= "table" then return false, "No real account/equipment profile" end
	if not self:Available("UPGRADE:" .. upgrade.Name) then return false, "Upgrade is in backoff" end
	local definitions = self.Reader:_dependency(upgrade.Kind)
	local definition = definitions and definitions[upgrade.Name]
	if not definition or type(definition.Cost) ~= "table" or definition.Cost.Type ~= "Currency" then return false, "Verified nonpremium definition unavailable" end
	if definition.Area and not ((raw.AreasUnlocked and raw.AreasUnlocked[definition.Area] ~= nil) or (raw.WorldsUnlocked and raw.WorldsUnlocked[definition.Area] ~= nil)) then
		return false, "Upgrade area is locked" end
	if type(raw[upgrade.Kind]) ~= "table" then return false, "Actual ownership map unavailable" end
	local currentOwned = raw[upgrade.Kind][upgrade.Name] ~= nil
	local evidence = { Name = upgrade.Name, Kind = upgrade.Kind, OwnedBefore = currentOwned, Cost = definition.Cost.Amount, Currency = definition.Cost.Currency }
	local command
	if currentOwned then
		if not config.UPGRADE_SETTINGS.AUTO_EQUIP_OWNED_UPGRADES then return false, "Owned upgrade equip disabled" end
		command = upgrade.Kind == "Gum" and "UpdateStorage" or "UpdateFlavor"
	else
		local enabled = upgrade.Kind == "Gum" and config.BUBBLE_SETTINGS.AUTO_BUY_GUM or (upgrade.Kind == "Flavors" and config.BUBBLE_SETTINGS.AUTO_BUY_FLAVORS)
		if not enabled then return false, "Purchase disabled" end
		local cost = definition.Cost
		if cost.Currency == "Robux" or not table.find(config.UPGRADE_SETTINGS.ALLOWED_PURCHASE_CURRENCIES, cost.Currency) then return false, "Purchase currency is not explicitly authorized" end
		local funds = raw[cost.Currency]
		if type(funds) ~= "number" or type(cost.Amount) ~= "number" or cost.Amount < 0 then return false, "Actual funds or cost unknown" end
		local major = self.ProgressionReserveProvider and self.ProgressionReserveProvider()
		local goalReserve = math.max(upgrade.GoalReserve or 0, major and major.Currency == cost.Currency and major.Amount or 0)
		local spendable = math.max(0, funds - (upgrade.Reserve or 0) - goalReserve)
		if cost.Amount > config.UPGRADE_SETTINGS.MAXIMUM_PURCHASE_COST or cost.Amount > spendable * config.RESOURCE_SETTINGS.MAXIMUM_UPGRADE_BALANCE_FRACTION then
			return false, "Actual funds no longer meet goal reserve and purchase budget" end
		evidence.BeforeBalance = funds
		command = "GumShopPurchase"
	end
	local remote = self.Reader:_dependency("Remote")
	if not remote or type(remote.FireServer) ~= "function" then return false, "Native Remote unavailable" end
	if token:CheckCancelled() then return false, "Cancelled" end
	self.LastUpgrade = evidence
	self:Failure("UPGRADE:" .. upgrade.Name, config.UPGRADE_SETTINGS.PURCHASE_RETRY_COOLDOWN_SECONDS, "Awaiting ownership/equipment confirmation")
	if self.Log then self.Log("UPGRADE][PURCHASE", upgrade.Name .. " | command=" .. command .. " | currency=" .. tostring(evidence.Currency) .. " cost=" .. tostring(evidence.Cost) .. " before=" .. tostring(evidence.BeforeBalance or "owned equip")) end
	remote:FireServer(command, upgrade.Name)
	local deadline = os.clock() + config.UPGRADE_SETTINGS.PURCHASE_CONFIRMATION_TIMEOUT_SECONDS
	while not token:CheckCancelled() and os.clock() < deadline do
		local live = self.Reader:GetLiveProfile()
		if live then
			local owned = live[upgrade.Kind] and live[upgrade.Kind][upgrade.Name] ~= nil
			local equipped = live.Bubble and live.Bubble[upgrade.Kind == "Gum" and "Gum" or "Flavor"] == upgrade.Name
			evidence.OwnedAfter, evidence.Equipped = owned, equipped
			evidence.AfterBalance = live[evidence.Currency]
			if not currentOwned and type(evidence.AfterBalance) == "number" then
				evidence.ObservedDeduction = math.max(evidence.ObservedDeduction or 0, evidence.BeforeBalance - evidence.AfterBalance)
			end
			local paid = not currentOwned and (evidence.Cost == 0 or (evidence.ObservedDeduction or 0) >= evidence.Cost)
			if (not currentOwned and owned and paid) or (currentOwned and equipped) then
				evidence.Verified = true
				return true, currentOwned and "Actual equipped upgrade changed" or ("Actual ownership received and currency deduction observed: " .. tostring(evidence.ObservedDeduction)), evidence
			end
		end
		task.wait(0.2)
	end
	local reason = token:CheckCancelled() and "Cancelled" or (currentOwned and "Equipment change unconfirmed" or
		("Purchase unconfirmed: ownership=" .. tostring(evidence.OwnedAfter) .. "; observed deduction=" .. tostring(evidence.ObservedDeduction or 0) .. "; required=" .. tostring(evidence.Cost)))
	return false, reason, evidence
end

function GameMechanics:IslandDiscoveryCapability()
	return { Available = type(firetouchinterest) == "function", Method = "RUNTIME_SIMULATED_CONTACT",
		Source = "Runtime global firetouchinterest; not a native Studio Luau API", ServerValidation = "UNVERIFIED",
		SavedPersistence = "OWNER_REJOIN_TEST_REQUIRED" }
end

function GameMechanics:IslandDiscovery(node)
	if not node or node.Kind ~= "ISLAND" or node.World ~= "The Overworld" then return nil, "Only researched Overworld island hitboxes are supported by this discovery experiment" end
	if not self:IslandDiscoveryCapability().Available then return nil, "Runtime firetouchinterest unavailable; stationary discovery cannot dispatch; no climbing or movement fallback" end
	local raw, definitions = self.Reader:GetLiveProfile(), self.Reader:_dependency("Worlds")
	if not raw or type(raw.AreasUnlocked) ~= "table" or type(raw.WorldsUnlocked) ~= "table" then return nil, "Actual LocalData discovery/world maps unavailable" end
	if raw.WorldsUnlocked[node.World] == nil then return nil, "Discovery origin world is not unlocked" end
	if raw.AreasUnlocked[node.Name] ~= nil then return nil, "Island already discovered in actual LocalData; refresh the Brain" end
	local worldDefinition = definitions and definitions[node.World]
	local nativeIsland
	for _, island in ipairs(worldDefinition and worldDefinition.Islands or {}) do if island.Name == node.Name then nativeIsland = island break end end
	if not nativeIsland or worldDefinition.Event or worldDefinition.Removed then return nil, "Island is absent from the native permanent Overworld definition" end
	local root = self.Tracker:Root()
	local util = self.Reader:_dependency("WorldUtil")
	if not root or not root.Parent or not util or util:GetPlayerWorld(self.Player) ~= node.World then return nil, "Alive character in the actual Overworld is required; no automatic travel for discovery" end
	local worlds = workspace:FindFirstChild("Worlds")
	local world = worlds and worlds:FindFirstChild(node.World)
	local islands = world and world:FindFirstChild("Islands")
	local island = islands and islands:FindFirstChild(node.Name)
	local model = island and island:FindFirstChild("Island")
	local hitbox = model and model:FindFirstChild("UnlockHitbox")
	if not hitbox or not hitbox:IsA("BasePart") or not hitbox:IsDescendantOf(workspace) or not hitbox.CanTouch or not hitbox.Anchored then
		return nil, "Correct native Island.UnlockHitbox is missing, unloaded or not touch-enabled"
	end
	if root.CanTouch == false then return nil, "Character root has native contact disabled" end
	return { Root = root, Hitbox = hitbox, Path = hitbox:GetFullName(), Distance = (root.Position-hitbox.Position).Magnitude,
		NativeIsland = nativeIsland, Contact = firetouchinterest }
end

function GameMechanics:EndIslandContact()
	local contact = self.PendingIslandContact
	if not contact then return true end
	self.PendingIslandContact = nil -- One end call only, including Pause/Stop and transport errors.
	local ok, reason = pcall(contact.Callback, contact.Root, contact.Hitbox, 1)
	contact.EndSucceeded, contact.EndReason = ok, reason
	if not ok then self.Log("ISLAND][CONTACT", "Contact end failed for " .. contact.Id .. ": " .. tostring(reason) .. "; outcome unconfirmed") end
	return ok, reason
end

function GameMechanics:DiscoverIsland(node, token)
	local settings = self.Config.WORLD_SETTINGS
	local function current()
		local goal = self.ProgressionGoalProvider and self.ProgressionGoalProvider()
		return not token:CheckCancelled() and settings.ENABLE_WORLD_PROGRESSION and settings.AUTO_DISCOVER_ISLANDS
			and not self.Config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST and goal and goal.Kind == "ISLAND" and goal.Id == node.Id
	end
	if not current() then return false, "Discovery disabled, isolated, cancelled or Brain goal changed" end
	local raw = self.Reader:GetLiveProfile()
	if raw and type(raw.AreasUnlocked) == "table" and raw.AreasUnlocked[node.Name] ~= nil then return true, "Already discovered in actual LocalData; no contact replay" end
	local discovery, reason = self:IslandDiscovery(node)
	if not discovery then return false, reason end
	local permitted, guardReason = self:Guard()
	if not permitted then return false, guardReason end
	if self.PendingIslandContact then return false, "A previous contact must finish before another attempt" end
	if not self:Available("DISCOVER:" .. node.Id) or os.clock()-self.LastDiscoveryAt < settings.ISLAND_DISCOVERY_INTERVAL_SECONDS then return false, "Discovery retry/global pacing" end
	if (self.IslandDiscoveryAttempts[node.Id] or 0) >= settings.MAXIMUM_ISLAND_DISCOVERY_ATTEMPTS then return false, "Island contact attempt limit reached" end
	local graph = self.Reader:GetSnapshot().ProgressionGraph
	if not graph or not graph.Next or graph.Next.Id ~= node.Id then return false, "Fresh Brain graph no longer selects this discovery island" end
	-- Recheck identities and received flags immediately before touching; no position or account writes.
	local fresh = self:IslandDiscovery(node)
	if not current() or not fresh or fresh.Root ~= discovery.Root or fresh.Hitbox ~= discovery.Hitbox or fresh.Contact ~= discovery.Contact then return false, "Discovery character, hitbox, runtime capability, access or goal changed" end
	local beforePosition = discovery.Root.Position
	self.IslandDiscoveryAttempts[node.Id] = (self.IslandDiscoveryAttempts[node.Id] or 0)+1
	self.LastDiscoveryAt = os.clock()
	self:Failure("DISCOVER:" .. node.Id, settings.ISLAND_DISCOVERY_RETRY_COOLDOWN_SECONDS, "Awaiting actual island acknowledgement")
	local contactRecord = { Callback = discovery.Contact, Root = discovery.Root, Hitbox = discovery.Hitbox, Id = node.Id }
	self.PendingIslandContact = contactRecord
	self.Log("ISLAND][ATTEMPT", string.format("%s | attempt=%d/%d | distance=%.2f | %s | discoveryBefore=absent | runtime simulated contact, server acceptance unknown",
		node.Id, self.IslandDiscoveryAttempts[node.Id], settings.MAXIMUM_ISLAND_DISCOVERY_ATTEMPTS, discovery.Distance, discovery.Path))
	local began, beginReason = pcall(discovery.Contact, discovery.Root, discovery.Hitbox, 0)
	local contactUntil = os.clock()+settings.ISLAND_DISCOVERY_CONTACT_SECONDS
	while began and current() and os.clock() < contactUntil and self.PendingIslandContact do task.wait(math.min(0.05, contactUntil-os.clock())) end
	local ended, endReason = self:EndIslandContact() -- End is cleanup of this attempt, even after cancellation; never another begin.
	ended, endReason = contactRecord.EndSucceeded, contactRecord.EndReason
	local evidence = { Island = node.Name, BeginSucceeded = began, EndSucceeded = ended, AccountAcknowledged = false, SavedPersistenceVerified = false }
	if not began or not ended then return false, "Runtime contact failed; no discovery inferred: " .. tostring(beginReason or endReason), evidence end
	local started, deadline = self.LastDiscoveryAt, os.clock()+settings.ISLAND_DISCOVERY_CONFIRMATION_TIMEOUT_SECONDS
	while current() and os.clock() < deadline do
		local actual = self.Reader:GetLiveProfile()
		if not actual or type(actual.AreasUnlocked) ~= "table" or type(actual.WorldsUnlocked) ~= "table" then return false, "Actual discovery account maps became unavailable", evidence end
		if actual.WorldsUnlocked[node.World] == nil then return false, "Actual origin world access changed", evidence end
		if actual.AreasUnlocked[node.Name] ~= nil then
			evidence.AccountAcknowledged, evidence.Seconds = true, os.clock()-started
			evidence.CharacterDelta = (discovery.Root.Position-beforePosition).Magnitude
			self.Failures["DISCOVER:" .. node.Id] = nil
			self:EndIslandContact()
			self.Reader:Refresh()
			self.Log("ISLAND][VERIFIED", string.format("%s | LocalData.AreasUnlocked: absent -> present | seconds=%.2f | characterDelta=%.2f | saved persistence requires rejoin test", node.Name, evidence.Seconds, evidence.CharacterDelta))
			return true, "Correct current LocalData discovery acknowledged; saved persistence unverified", evidence
		end
		local allowed, blocker = self:Guard()
		if not allowed then return false, blocker, evidence end
		local actualRoot = self.Tracker:Root()
		if actualRoot ~= discovery.Root or not discovery.Hitbox:IsDescendantOf(workspace) then return false, "Character or discovery hitbox changed during acknowledgement", evidence end
		task.wait(0.1)
	end
	return false, token:CheckCancelled() and "Cancelled; an already-issued contact cannot be recalled" or "Discovery unconfirmed: no correct LocalData.AreasUnlocked acknowledgement; contact invocation is not proof", evidence
end

function GameMechanics:WorldGate(name)
	local definitions, raw = self.Reader:_dependency("Worlds"), self.Reader:GetLiveProfile()
	local definition = definitions and definitions[name]
	if not definition or definition.Event or definition.Removed or not raw or type(raw.WorldsUnlocked) ~= "table"
		or type(raw.AreasUnlocked) ~= "table" then return nil, "Native definition or real unlock maps unavailable" end
	if raw.WorldsUnlocked[name] ~= nil then return nil, "Already unlocked; no request" end
	local worlds, found = workspace:FindFirstChild("Worlds"), nil
	for _, model in ipairs(CollectionService:GetTagged("WorldGate")) do
		if model:IsDescendantOf(workspace) and model:GetAttribute("World") == name then
			if found then return nil, "Ambiguous native WorldGate" end
			found = model
		end
	end
	if not found then return nil, "Native WorldGate unavailable" end
	local node, origin, area = found, nil, nil
	while node and node ~= workspace do
		if node.Parent and node.Parent.Name == "Islands" then area = node.Name end
		if node.Parent == worlds then origin = node.Name end
		node = node.Parent
	end
	if not origin or not self:Unlocked(origin, area or origin) then return nil, "Actual gate origin/discovery prerequisite locked or unknown" end
	local activation = found:FindFirstChild("Activation")
	local target = activation and activation:FindFirstChild("Root")
	if not target or not target.Parent or not target:IsA("BasePart") then return nil, "Live gate Activation.Root unavailable" end
	local root = self.Tracker:Root()
	if not root then return nil, "Character unavailable" end
	local horizontalDistance = ((root.Position - target.Position) * Vector3.new(1, 0, 1)).Magnitude
	local verticalDifference, horizontalLimit = math.abs(root.Position.Y - target.Position.Y), target.Size.Y / 2
	local inRange = horizontalDistance <= horizontalLimit and verticalDifference <= 10 -- Client.Activation:357-360
	local originWorld = worlds and worlds:FindFirstChild(origin)
	local islands = originWorld and originWorld:FindFirstChild("Islands")
	local island = islands and area and islands:FindFirstChild(area)
	local islandModel = island and island:FindFirstChild("Island")
	local portal = islandModel and islandModel:FindFirstChild("Portal")
	local spawn = portal and portal:FindFirstChild("Spawn")
	local expectedPath = area and "Workspace.Worlds." .. origin .. ".Islands." .. area .. ".Island.Portal.Spawn" or nil
	if not spawn or not spawn:IsA("BasePart") or spawn:GetFullName() ~= expectedPath then spawn = nil end
	local catalogIsland = false
	for _, candidate in ipairs((definitions[origin] or {}).Islands or {}) do if candidate.Name == area then catalogIsland = true break end end
	local areaObservation = self.Tracker.Areas and self.Tracker.Areas[origin .. "/" .. tostring(area)]
	local zones = {}
	if catalogIsland and areaObservation and areaObservation.CatalogKnown and areaObservation.DestinationPath == expectedPath and not areaObservation.MappingWarning then
		for _, zone in ipairs(areaObservation.Zones or {}) do if not zone.IsTransit then table.insert(zones, zone) end end
	end
	local current = self.Tracker.Current
	local atIsland = current and current.World == origin and current.Name == area or false
	if not atIsland then
		local util = self.Reader:_dependency("WorldUtil")
		local actualWorld = util and util:GetPlayerWorld(self.Player)
		local highest, currentArea = -math.huge, nil
		for _, candidate in ipairs(islands and islands:GetChildren() or {}) do
			local height = candidate:GetAttribute("Height")
			if type(height) == "number" and height <= root.Position.Y and height > highest then highest, currentArea = height, candidate.Name end
		end
		atIsland = actualWorld == origin and currentArea == area
	end
	return { Name = name, Model = found, OriginWorld = origin, RequiredIsland = area, Root = target,
		Spawn = spawn, DestinationPath = catalogIsland and expectedPath or nil, Zones = zones,
		AtOriginIsland = atIsland or inRange, InRange = inRange, Cost = definition.UnlockCost, Order = definition.Order,
		HorizontalDistance = horizontalDistance, VerticalDifference = verticalDifference, HorizontalLimit = horizontalLimit, VerticalLimit = 10 }
end

function GameMechanics:_gateTravelAuthorized(gate)
	local settings, cost, raw = self.Config.WORLD_SETTINGS, gate.Cost, self.Reader:GetLiveProfile()
	local active = self.ProgressionGoalProvider and self.ProgressionGoalProvider()
	if not active or active.Name ~= gate.Name or active.Kind ~= "WORLD" then return false, "Active Brain world objective changed" end
	if not settings.ENABLE_WORLD_PROGRESSION or not settings.AUTO_TRAVEL_FOR_PROGRESSION then return false, "Progression travel disabled" end
	if not settings.AUTO_UNLOCK_WORLDS then return false, "World spending disabled; no gate travel" end
	if (self.SessionUnlockRequests or 0) >= settings.MAXIMUM_SESSION_WORLD_UNLOCKS
		or (self.UnlockAttempts or {})[gate.Name] and self.UnlockAttempts[gate.Name] >= settings.MAXIMUM_UNLOCK_ATTEMPTS
		or not self:Available("UNLOCK:" .. gate.Name) then return false, "World request limit/backoff blocks gate travel" end
	if type(cost) ~= "table" or cost.Type ~= "Currency" or cost.Currency == "Robux"
		or not table.find(settings.ALLOWED_UNLOCK_CURRENCIES, cost.Currency) or type(cost.Amount) ~= "number"
		or cost.Amount ~= cost.Amount or cost.Amount < 0 or cost.Amount == math.huge
		or cost.Amount > settings.MAXIMUM_WORLD_UNLOCK_COST then return false, "Native gate cost/currency exceeds explicit authorization" end
	local reserveKey = ({ Coins = "COIN_RESERVE", Gems = "GEM_RESERVE", Tickets = "TICKET_RESERVE", Pearls = "PEARL_RESERVE" })[cost.Currency]
	local reserve = reserveKey and self.Config.RESOURCE_SETTINGS[reserveKey] or 0
	local balance = raw and raw[cost.Currency]
	if type(balance) ~= "number" or balance ~= balance or balance == math.huge or balance < cost.Amount + reserve then
		return false, "Actual funds insufficient or unknown after reserve; no gate travel"
	end
	return true
end

function GameMechanics:TravelForProgression(name, token)
	if self.PetLocationOwnerProvider and self.PetLocationOwnerProvider() then return false, "Authorized hatch task owns location" end
	local hatch = self.Config.PET_SETTINGS.ENABLE_PET_INTELLIGENCE and self.Config.PET_SETTINGS.AUTO_HATCH and self.Reader:_dependency("HatchPresentation")
	if hatch then local ok, active = pcall(function() return hatch:IsHatching() end) if not ok or active ~= false then return false, "Native hatch presentation owns movement" end end
	local settings = self.Config.WORLD_SETTINGS
	if token:CheckCancelled() then return false, "Cancelled" end
	if not settings.ENABLE_WORLD_PROGRESSION or not settings.AUTO_TRAVEL_FOR_PROGRESSION then return false, "Progression travel disabled" end
	local active = self.ProgressionGoalProvider and self.ProgressionGoalProvider()
	if not active or active.Name ~= name or active.Kind ~= "WORLD" then return false, "Active Brain world objective changed" end
	local gate, blocker = self:WorldGate(name)
	if not gate then return false, blocker end
	local authorized, authorizationReason = self:_gateTravelAuthorized(gate)
	if not authorized then return false, authorizationReason end
	if gate.AtOriginIsland then return true, "Already at gate island; no teleport", 0 end
	if not gate.Spawn and (not gate.DestinationPath or #gate.Zones == 0) then return false, "Native portal arrival geometry unavailable; no unverified travel" end
	local permitted, reason = self:Guard()
	if not permitted then return false, reason end
	local destination, path = gate.Spawn, gate.Spawn and gate.Spawn:GetFullName() or gate.DestinationPath
	if not self:Available("TRAVEL:" .. path) or os.clock() - self.LastTravelAt < self.Config.ISLAND_SETTINGS.TRAVEL_COOLDOWN_SECONDS then return false, "Travel cooldown/backoff" end
	local remote = self.Reader:_dependency("Remote")
	if not remote or type(remote.FireServer) ~= "function" then return false, "Native Remote unavailable" end
	permitted, reason = self:Guard()
	if not permitted then return false, reason end
	if token:CheckCancelled() then return false, "Cancelled" end
	local fresh = self:WorldGate(name)
	if not fresh or fresh.Spawn ~= destination or fresh.DestinationPath ~= gate.DestinationPath then return false, "Gate access/destination changed" end
	authorized, authorizationReason = self:_gateTravelAuthorized(fresh)
	if not authorized then return false, authorizationReason end
	if token:CheckCancelled() then return false, "Cancelled" end
	local started, stable = os.clock(), nil
	self.LastTravelAt = started
	self.ProgressionTravelRequests = (self.ProgressionTravelRequests or 0) + 1
	self:Failure("TRAVEL:" .. path, self.Config.ISLAND_SETTINGS.TRAVEL_RETRY_COOLDOWN_SECONDS, "Awaiting progression arrival")
	local sent, errorText = pcall(function() remote:FireServer("Teleport", path) end)
	if not sent then return false, "Native teleport invocation failed: " .. tostring(errorText) end
	while not token:CheckCancelled() and os.clock() - started < self.Config.ISLAND_SETTINGS.TRAVEL_CONFIRMATION_TIMEOUT_SECONDS do
		local root = self.Tracker:Root()
		local inside = root and destination and destination.Parent and (root.Position - destination.Position).Magnitude <= self.Config.ISLAND_SETTINGS.ARRIVAL_DISTANCE_STUDS or false
		if root and not destination then
			for _, zone in ipairs(gate.Zones) do
				if zone.Root and zone.Root.Parent and zone.Root:IsDescendantOf(workspace) and zone.Data and zone.Data.Zone
					and math.abs(root.Position.Y - zone.Data.Zone.Height) <= self.Config.PICKUP_SETTINGS.MAXIMUM_VERTICAL_DIFFERENCE_STUDS
					and zone.Data.Zone:GetDistanceToPoint(root.Position) <= self.Config.PICKUP_SETTINGS.MAXIMUM_ROUTE_DISTANCE_STUDS then inside = true break end
			end
		end
		if inside and self:Unlocked(gate.OriginWorld, gate.RequiredIsland) then
			stable = stable or os.clock()
			if os.clock() - stable >= settings.TRAVEL_STABILIZATION_SECONDS then
				self.Failures["TRAVEL:" .. path] = nil return true, "Native portal arrival stabilized", os.clock() - started
			end
		else stable = nil end
		task.wait(0.1)
	end
	return false, token:CheckCancelled() and "Cancelled" or "Progression portal arrival unconfirmed"
end

function GameMechanics:UnlockWorld(name, token)
	local settings = self.Config.WORLD_SETTINGS
	if token:CheckCancelled() then return false, "Cancelled" end
	if not settings.ENABLE_WORLD_PROGRESSION or not settings.AUTO_UNLOCK_WORLDS then return false, "World spending disabled" end
	local active = self.ProgressionGoalProvider and self.ProgressionGoalProvider()
	if not active or active.Name ~= name or active.Kind ~= "WORLD" then return false, "Active Brain world objective changed" end
	local gate, blocker = self:WorldGate(name)
	if not gate then return false, blocker end
	if not gate.InRange then return false, "Outside native gate activation range; manual approach required, no pickup or gate walking" end
	local permitted, reason = self:Guard("World " .. tostring(gate.Order))
	if not permitted then return false, reason end
	local cost, raw = gate.Cost, self.Reader:GetLiveProfile()
	if type(cost) ~= "table" or cost.Type ~= "Currency" or cost.Currency == "Robux"
		or not table.find(settings.ALLOWED_UNLOCK_CURRENCIES, cost.Currency) or type(cost.Amount) ~= "number"
		or cost.Amount ~= cost.Amount or cost.Amount < 0 or cost.Amount > settings.MAXIMUM_WORLD_UNLOCK_COST then return false, "Native unlock cost/currency exceeds explicit authorization" end
	local reserveKey = ({ Coins = "COIN_RESERVE", Gems = "GEM_RESERVE", Tickets = "TICKET_RESERVE", Pearls = "PEARL_RESERVE" })[cost.Currency]
	local reserve = reserveKey and self.Config.RESOURCE_SETTINGS[reserveKey] or 0
	if not raw or type(raw[cost.Currency]) ~= "number" or raw[cost.Currency] ~= raw[cost.Currency]
		or raw[cost.Currency] == math.huge or raw[cost.Currency] < cost.Amount + reserve then return false, "Actual funds insufficient or unknown after reserve" end
	if not self:Available("UNLOCK:" .. name) then return false, "Unlock retry cooldown" end
	self.UnlockAttempts = self.UnlockAttempts or {}
	if (self.UnlockAttempts[name] or 0) >= settings.MAXIMUM_UNLOCK_ATTEMPTS then return false, "Per-world unlock attempt limit reached" end
	if (self.SessionUnlockRequests or 0) >= settings.MAXIMUM_SESSION_WORLD_UNLOCKS then return false, "Controller lifetime unlock request limit reached" end
	local remote = self.Reader:_dependency("Remote")
	if not remote or type(remote.FireServer) ~= "function" then return false, "Native Remote unavailable" end
	-- No yield between final live checks and dispatch. Ledger survives cancellation/Stop.
	if token:CheckCancelled() then return false, "Cancelled" end
	local fresh = self:WorldGate(name)
	if not fresh or fresh.Model ~= gate.Model or not fresh.InRange or fresh.Cost ~= cost then return false, "Gate contract/access changed before dispatch" end
	self.UnlockAttempts[name] = (self.UnlockAttempts[name] or 0) + 1
	self.SessionUnlockRequests = (self.SessionUnlockRequests or 0) + 1
	self:Failure("UNLOCK:" .. name, settings.UNLOCK_RETRY_COOLDOWN_SECONDS, "Awaiting actual world unlock acknowledgement")
	local evidence = { Name = name, Currency = cost.Currency, Cost = cost.Amount, BeforeBalance = raw[cost.Currency], BeforeUnlocked = false, Verified = false }
	if self.Log then self.Log("WORLD][REQUEST", name .. " | UnlockWorld | cost=" .. cost.Amount .. " " .. cost.Currency .. " | before=" .. evidence.BeforeBalance .. " | unlockBefore=false") end
	local sent, errorText = pcall(function() remote:FireServer("UnlockWorld", name) end)
	if not sent then return false, "Unlock invocation failed; delivery/credit unknown: " .. tostring(errorText), evidence end
	local started = os.clock()
	while not token:CheckCancelled() and os.clock() - started < settings.UNLOCK_CONFIRMATION_TIMEOUT_SECONDS do
		local live = self.Reader:GetLiveProfile()
		evidence.AfterBalance = live and live[cost.Currency]
		evidence.AfterUnlocked = live and type(live.WorldsUnlocked) == "table" and live.WorldsUnlocked[name] ~= nil or false
		if evidence.AfterUnlocked then
			evidence.Verified = true
			evidence.ObservedDeduction = type(evidence.AfterBalance) == "number" and evidence.BeforeBalance - evidence.AfterBalance or nil
			if self.Log then self.Log("WORLD][VERIFIED", name .. " | LocalData.WorldsUnlocked: false -> true | " .. cost.Currency .. " before=" .. evidence.BeforeBalance .. " after=" .. tostring(evidence.AfterBalance) .. " deduction=" .. tostring(evidence.ObservedDeduction) .. " | external balance sources may contribute") end
			-- Close only the native result panel for this exact world, without faking gate animations.
			local frames = self.Reader:_dependency("GuiFrame")
			local matches = self:Guard("World " .. tostring(gate.Order))
			if matches and frames and frames.IsOpen and frames:IsOpen("Unlock") then frames:Close() end
			self.Reader:Refresh()
			return true, "Actual LocalData world unlock confirmed; account refreshed", evidence
		end
		task.wait(0.2)
	end
	return false, token:CheckCancelled() and "Cancelled; dispatched request cannot be recalled" or "Unlock unconfirmed: no LocalData WorldsUnlocked acknowledgement", evidence
end

-- Pet managers prepare evidence/ledgers; only this shared adapter invokes native
-- commands, inside the single foreground scheduler task. No yield after final guards.
function GameMechanics:PetAction(manager, decision, token)
	if token:CheckCancelled() or manager.Controller.State ~= "RUNNING" then return false, "Cancelled or stopped" end
	local permitted, blocker = self:Guard()
	if not permitted then return false, blocker end
	local remote = self.Reader:_dependency("Remote")
	if not remote or type(remote.FireServer) ~= "function" then return false, "Native Remote unavailable" end
	local command, first, second, reason = manager:Prepare(decision, token)
	if not command then return false, reason end
	-- Prepare validates fresh account, authorization, limits and native interfaces,
	-- then records the pending request before even an uncertain invocation.
	local ok, err = pcall(function() remote:FireServer(command, first, second) end)
	if not ok then manager:Uncertain("Pet invocation failed; delivery unknown: " .. tostring(err)) end
	return true, ok and "Dispatched; awaiting received LocalData result" or manager.Fault
end


-- Narrow owner-authorized local features. No account fields or native geometry are changed.
local function featureFinite(value)
	return type(value) == "number" and value == value and math.abs(value) < math.huge
end

function GameMechanics:LocalFeatureGuard()
	local allowed, reason, root, humanoid = self:Guard()
	if not allowed then return false, reason end
	local c = self.LocalFeatureController
	if not c or c.State ~= "RUNNING" then return false, "Local feature controller is not running" end
	local ok, blocker = pcall(function()
		local input = game:GetService("UserInputService")
		if input:GetFocusedTextBox() ~= nil then return "Typing owns input" end
		local hatch = self.Reader:_dependency("HatchPresentation")
		if not hatch or type(hatch.IsHatching) ~= "function" or hatch:IsHatching() ~= false then return "Native hatch presentation active or unavailable" end
		local scripts = self.Player:FindFirstChild("PlayerScripts")
		local client = scripts and scripts:FindFirstChild("ClientScript")
		local auto = client and client:FindFirstChild("GetAutoHatchStatus")
		if not auto or not auto:IsA("BindableFunction") or auto:Invoke() ~= nil then return "Native auto-hatch active or unavailable" end
		if c.Pets and (c.Pets.PendingEquip or c.Pets.Hatch.Pending) then return "Pending pet operation owns presentation" end
		return nil
	end)
	if not ok then return false, "Local feature guards unavailable: " .. tostring(blocker) end
	if blocker then return false, blocker end
	return true, nil, root, humanoid
end

function GameMechanics:TravelSelectedEgg(manager, record, token)
	local c = self.LocalFeatureController
	local active = c and c.Scheduler and c.Scheduler.Active
	local function owns()
		return c and c.State == "RUNNING" and manager == c.EggTravel and c.Scheduler.Active == active and active
			and active.Definition.Owner == "EGG_TRAVEL" and active.Definition.Generation == c.Generation and active.Token == token
	end
	if not owns() then return false, "Selected-egg task does not own the scheduler" end
	if not self.Config.EGG_TRAVEL_SETTINGS.ENABLE_NATIVE_ISLAND_TRAVEL then return false, "Selected-egg native travel disabled" end
	local fresh, reason = manager:Validate(record, token)
	if not fresh then return false, reason end
	local allowed, blocker = self:LocalFeatureGuard()
	if not allowed then return false, blocker end
	fresh, reason = manager:Validate(record, token) -- Guard can yield; all eligibility is rechecked.
	if not fresh then return false, reason end
	if not fresh.NeedsNativeTravel then return true, "Already in selected area; no unnecessary native teleport" end
	local path = fresh.DestinationPath
	if not fresh.NativeAreaKnown or type(path) ~= "string" or not self:Unlocked(fresh.World, fresh.Island) then return false, "Exact unlocked native egg-area destination unavailable" end
	if fresh.Island then
		if path ~= "Workspace.Worlds." .. fresh.World .. ".Islands." .. fresh.Island .. ".Island.Portal.Spawn" then return false, "Selected area path does not match native contract" end
	elseif not fresh.Destination or not fresh.Destination.Parent or fresh.Destination:GetFullName() ~= path then return false, "Observed world return destination disappeared" end
	if os.clock() - self.LastTravelAt < self.Config.ISLAND_SETTINGS.TRAVEL_COOLDOWN_SECONDS then return false, "Native travel cooldown; explicit rearm after bounded failure" end
	local remote = self.Reader:_dependency("Remote")
	if not remote or type(remote.FireServer) ~= "function" then return false, "Native Remote unavailable" end
	if token:CheckCancelled() or not owns() or not self.Config.EGG_TRAVEL_SETTINGS.ENABLE_NATIVE_ISLAND_TRAVEL then return false, "Cancelled or selected-egg scheduler ownership changed" end
	fresh, reason = manager:Validate(record, token, true)
	if not fresh or fresh.DestinationPath ~= path or not fresh.NativeAreaKnown then return false, reason or "Native selected-area destination changed before request" end
	if not fresh.NeedsNativeTravel then return true, "Selected area reached during guards; no native request needed" end
	local beforePosition = fresh.CharacterRoot.Position
	local destination = fresh.Destination
	if type(manager.DiagnosticTrace) == "function" then manager:DiagnosticTrace("AREA_TRAVEL_REQUESTED", fresh, "Native Teleport(" .. path .. ") dispatch; area/range arrival remains unconfirmed") end
	if token:CheckCancelled() or not owns() or not self.Config.EGG_TRAVEL_SETTINGS.ENABLE_NATIVE_ISLAND_TRAVEL then return false, "Cancelled before native area request" end
	self.LastTravelAt = os.clock()
	local sent, err = pcall(function() remote:FireServer("Teleport", path) end)
	if not sent then return false, "Native area travel delivery uncertain: " .. tostring(err) end
	local started, stable = os.clock(), nil
	while os.clock() - started < self.Config.EGG_TRAVEL_SETTINGS.ARRIVAL_TIMEOUT_SECONDS do
		fresh, reason = manager:Validate(record, token)
		if not fresh then return false, reason end
		local spawnObserved = destination and destination.Parent and destination:IsDescendantOf(workspace)
			and (fresh.CharacterRoot.Position - destination.Position).Magnitude <= self.Config.ISLAND_SETTINGS.ARRIVAL_DISTANCE_STUDS
		local transitionObserved = not destination and not fresh.NeedsNativeTravel
			and (fresh.CharacterRoot.Position - beforePosition).Magnitude > 1
		if not fresh.NeedsNativeTravel and (spawnObserved or transitionObserved) then
			stable = stable or os.clock()
			if os.clock() - stable >= 0.4 then return true, "Native target-area arrival observed; egg range still requires verification" end
		else stable = nil end
		task.wait(0.1)
	end
	return false, "Native target-area arrival unconfirmed"
end

function GameMechanics:PositionSelectedEgg(manager, record, frame, token)
	local c = self.LocalFeatureController
	local active = c and c.Scheduler and c.Scheduler.Active
	local function owns()
		return c and c.State == "RUNNING" and manager == c.EggTravel and c.Scheduler.Active == active and active
			and active.Definition.Owner == "EGG_TRAVEL" and active.Definition.Generation == c.Generation and active.Token == token
	end
	if not owns() then return false, "Selected-egg task does not own the scheduler" end
	if not self.Config.EGG_TRAVEL_SETTINGS.ENABLE_DIRECT_POSITIONING then return false, "Direct egg positioning disabled" end
	local fresh, reason = manager:Validate(record, token)
	if not fresh then return false, reason end
	local allowed, blocker = self:LocalFeatureGuard()
	if not allowed then return false, blocker end
	fresh, reason = manager:Validate(record, token)
	if not fresh then return false, reason end
	if fresh.NeedsNativeTravel then return false, "Correct unlocked native area must be reached first" end
	if fresh.InRange then return true, fresh.LocationOnly and "Already inside diagnostic physical arrival radius; no direct positioning needed"
		or "Already in observed native hatch range; no direct positioning needed" end
	local clearedFrame, clearanceReason = manager:ResolveStanding(fresh)
	if not clearedFrame then return false, clearanceReason end
	if typeof(frame) ~= "CFrame" or (frame.Position - clearedFrame.Position).Magnitude > 0.25 then return false, "Standing geometry changed during guards; explicit rearm required" end
	frame = clearedFrame -- Assign exactly the freshly cleared avatar orientation/volume.
	if typeof(frame) ~= "CFrame" or not featureFinite(frame.Position.X) or not featureFinite(frame.Position.Y)
		or not featureFinite(frame.Position.Z) or not fresh.RangeOrigin
		or (frame.Position - fresh.RangeOrigin.Position).Magnitude > fresh.Range
		or not manager:RangeEligibleAt(fresh, frame.Position, true) then return false, fresh.LocationOnly
			and "Validated standing transform unavailable or outside verified physical arrival radius"
			or "Validated standing transform unavailable or outside actual native hatch eligibility" end
	if self.LastEggPositionLease == record.LeaseId then return false, "Direct position already attempted for this lease" end
	local final, finalReason = manager:Validate(record, token, true)
	if not final or final.CharacterRoot ~= fresh.CharacterRoot or final.NeedsNativeTravel then return false, finalReason or "Selected egg/character/area changed during final positioning guards" end
	if token:CheckCancelled() or not owns() or not self.Config.EGG_TRAVEL_SETTINGS.ENABLE_DIRECT_POSITIONING then return false, "Cancelled or selected-egg scheduler ownership changed" end
	if final.InRange then return true, final.LocationOnly and "Already inside diagnostic physical arrival radius after guards; no assignment"
		or "Already in observed native hatch range after guards; no assignment" end
	local latestFrame, latestReason = manager:ResolveStanding(final)
	if not latestFrame then return false, latestReason end
	if latestFrame ~= frame then return false, "Standing geometry changed after final destination validation; explicit rearm required" end
	if token:CheckCancelled() or not owns() or not self.Config.EGG_TRAVEL_SETTINGS.ENABLE_DIRECT_POSITIONING then return false, "Cancelled or selected-egg scheduler ownership changed" end
	self.LastEggPositionLease = record.LeaseId -- Mark before assignment; failure cannot trigger repeated snapping.
	local assigned, err = pcall(function() fresh.CharacterRoot.CFrame = frame end)
	return assigned, assigned and "Direct CFrame assigned; observed arrival/stability/range still pending" or "Direct position failed: " .. tostring(err)
end

function GameMechanics:RewardsContext()
	local raw = self.Reader:GetLiveProfile()
	local result = { Raw = raw, UserId = self.Player and self.Player.UserId, Balances = self.Reader:ReadBalances(),
		GiftIds = {}, GiftRecords = {}, CanClaim = false, CanOpen = false, GiftCompletionAvailable = false }
	local time, playtime = self.Reader:_dependency("Time"), self.Reader:_dependency("Playtime")
	if time and type(time.now) == "function" then local ok, value = pcall(time.now) if ok and featureFinite(value) then result.NativeNow = value end end
	result.PlaytimeGifts = playtime and playtime.Gifts
	if raw and type(raw.MasteryUpgrades) == "table" then
		result.HasPlaytime = false
		for _, upgrade in pairs(raw.MasteryUpgrades) do if type(upgrade) == "table" and upgrade.Type == "Playtime" then result.HasPlaytime = true break end end
	end
	local plaza = self.Reader:_dependency("IsTradingPlaza")
	if type(plaza) == "function" then local ok, value = pcall(plaza) if ok and type(value) == "boolean" then result.IsTradingPlaza = value end end
	local item, constants, powerups = self.Reader:_dependency("ItemUtil"), self.Reader:_dependency("Constants"), self.Reader:_dependency("Powerups")
	if raw and item and type(item.GetOwnedAmount) == "function" then
		local ok, value = pcall(item.GetOwnedAmount, item, raw, { Type = "Powerup", Name = "Mystery Box" })
		if ok and featureFinite(value) and value >= 0 and value % 1 == 0 then result.OwnedBoxes = value end
	end
	if constants and featureFinite(constants.MaxSpawnableLimit) and constants.MaxSpawnableLimit >= 1 then result.MaxGiftCount = constants.MaxSpawnableLimit end
	local physical, giftClass = self.Reader:_dependency("PhysicalItem"), self.Reader:_dependency("PhysicalGift")
	local identityOK, identity = false, nil
	if type(self.Reader.GetNativeGiftFacts) == "function" then identityOK, identity = pcall(self.Reader.GetNativeGiftFacts, self.Reader) end
	if identityOK and type(identity) == "table" and identity.Available == true then
		result.GiftIdentityAvailable = true
		result.GiftIdentityEpoch, result.GiftRevision = identity.Epoch, identity.Revision
	end
	if physical and type(physical.GetActiveObjects) == "function" then
		local ok, total = pcall(physical.GetActiveObjects, physical, "Gift")
		if ok and featureFinite(total) and total >= 0 and total % 1 == 0 then result.GiftCount = total end
	end
	if physical and type(physical.GetActiveGifts) == "function" then
		local ok, active = pcall(physical.GetActiveGifts, physical)
		if ok and type(active) == "table" then
			for instance, component in pairs(active) do
				-- Native GetActiveGifts is the loaded Instance -> component subset.
				-- The component has a BasePart Model and no item Name. Item identity
				-- comes only from received RenderGifts facts, never guessed geometry.
				local model = type(component) == "table" and component.Model
				if model == instance and typeof(model) == "Instance" and model:IsA("BasePart") and model.Parent and model:IsDescendantOf(workspace) then
					local id = model.Name
					result.GiftIds[id] = true
					local fact = result.GiftIdentityAvailable and type(identity.Records) == "table" and identity.Records[id]
					if type(fact) == "table" and fact.Name == "Mystery Box" and type(component.Hit) == "function" then
						result.GiftRecords[id] = { Id = id, Name = fact.Name, IdentityEpoch = identity.Epoch,
							Revision = fact.Revision, Model = model, Component = component }
					end
				end
			end
			result.GiftCompletionAvailable = result.GiftIdentityAvailable == true and result.GiftCount ~= nil
				and giftClass ~= nil and type(giftClass.Hit) == "function"
		end
	end
	local allowed, reason = self:LocalFeatureGuard()
	result.Reason = reason
	result.CanClaim = allowed and raw ~= nil and result.IsTradingPlaza == false and result.GiftCount == 0
	result.CanOpen = result.CanClaim and powerups ~= nil and powerups["Mystery Box"] ~= nil
		and result.GiftCompletionAvailable and result.OwnedBoxes ~= nil and result.MaxGiftCount ~= nil
	return result
end

function GameMechanics:RewardAction(manager, decision, token)
	local c = self.LocalFeatureController
	if not c or manager ~= c.Rewards or not c.Scheduler.Active or c.Scheduler.Active.Definition.Owner ~= "REWARDS" then return false, "Reward task does not own the scheduler" end
	if token:CheckCancelled() or manager.Controller.State ~= "RUNNING" then return false, "Cancelled" end
	local allowed, reason = self:LocalFeatureGuard()
	if not allowed then return false, reason end
	local remote = self.Reader:_dependency("Remote")
	if not remote then return false, "Native Remote unavailable" end
	if decision.Kind == "FREE_WHEEL_TICKET" then return self:ClaimFreeWheelTicket(manager, decision, token, remote) end
	if decision.Kind ~= "PLAYTIME" and decision.Kind ~= "MYSTERY_BOX" then return false, "Unsupported reward intent" end
	if decision.Kind == "PLAYTIME" and type(remote.InvokeServer) ~= "function"
		or decision.Kind == "MYSTERY_BOX" and type(remote.FireServer) ~= "function" then return false, "Required native transport unavailable before preparation" end
	local command, first, second, pending = manager:Prepare(decision, token)
	if not command then return false, pending end
	if command ~= "ClaimPlaytime" and not (command == "UseGift" and first == "Mystery Box" and second == 1) then manager:AbortPreparation(pending, "Unsupported local reward command") return false, "Unsupported local reward command" end
	if command == "ClaimPlaytime" and type(remote.InvokeServer) ~= "function" or command == "UseGift" and type(remote.FireServer) ~= "function" then manager:AbortPreparation(pending, "Required native transport unavailable") return false, "Required native transport unavailable" end
	manager.Controller:MarkNonPickupReward(pending)
	if command == "ClaimPlaytime" then
		-- Start transport within this positive foreground lease, then bound the
		-- parent's observation slice even if InvokeServer waits indefinitely.
		self.RewardRPCs = self.RewardRPCs or {}
		local thread = task.spawn(function()
			local active = c.Scheduler.Active
			if token:CheckCancelled() or c.State ~= "RUNNING" or not self.Config.PLAYTIME_SETTINGS.AUTO_CLAIM_PLAYTIME
				or not active or active.Definition.Owner ~= "REWARDS" or active.Definition.Generation ~= c.Generation then
				manager:AbortPreparation(pending, "Cancelled or stale before playtime transport") return
			end
			if not manager:MarkDispatched(pending) then manager:AbortPreparation(pending, "Dispatch reservation rejected") return end
			pending.TransportStarted = true
			local ok, output = pcall(function() return remote:InvokeServer(command, first) end)
			manager:DispatchReturned(pending, ok, output)
		end)
		self.RewardRPCs[thread] = true
	else
		if not manager:MarkDispatched(pending) then manager:AbortPreparation(pending, "Dispatch reservation rejected") return false, "Dispatch reservation rejected" end
		pending.TransportStarted = true
		local ok, output = pcall(function() return remote:FireServer(command, first, second) end)
		manager:DispatchReturned(pending, ok, output)
	end
	return true, "Request recorded; received acknowledgement required"
end

function GameMechanics:CancelRewardTransport()
	for thread in pairs(self.RewardRPCs or {}) do pcall(task.cancel, thread) end
	self.RewardRPCs = {}
end

function GameMechanics:AdvanceMysteryGift(pending, token)
	local c = self.LocalFeatureController
	if not c or c.State ~= "RUNNING" or not c.Scheduler.Active or c.Scheduler.Active.Definition.Owner ~= "REWARDS" then return false, "Gift task does not own the scheduler" end
	if not self.Config.MYSTERY_BOX_SETTINGS.AUTO_OPEN_MYSTERY_BOXES or not c.Rewards or not c.Rewards.Ledger
		or c.Rewards.Ledger.Pending ~= pending or pending.Kind ~= "MYSTERY_BOX" or pending.Attempted ~= true then return false, "Gift task lacks its exact attempted owned-box operation" end
	if token:CheckCancelled() then return false, "Cancelled" end
	local allowed, reason, root = self:LocalFeatureGuard()
	if not allowed then return false, reason end
	local context = self:RewardsContext()
	if not context.GiftCompletionAvailable then return false, "Native gift completion representation unavailable" end
	if os.clock() - (self.LastOrdinaryGiftHit or -math.huge) < 0.5 then return false, "Native gift hit pacing" end
	for id, record in pairs(context.GiftRecords) do
		if id == pending.GiftId and not pending.AmbiguousGift and not pending.BeforeGiftIds[id] and record.Name == "Mystery Box" and record.Model.Parent
			and context.GiftIdentityAvailable == true and context.GiftIdentityEpoch == pending.GiftIdentityEpoch
			and record.IdentityEpoch == pending.GiftIdentityEpoch and featureFinite(record.Revision)
			and featureFinite(pending.BeforeGiftRevision) and record.Revision > pending.BeforeGiftRevision
			and featureFinite(context.GiftRevision) and record.Revision <= context.GiftRevision
			and record.Component.InRange == true and type(record.Component.Hit) == "function" then
			local okPosition, position = pcall(function() return record.Model:GetPivot().Position end)
			local physical = self.Reader:_dependency("PhysicalItem")
			if okPosition and physical and physical.IsGiftInRange == true
				and ((position - root.Position) * Vector3.new(1, 0, 1)).Magnitude <= 15 then
				if token:CheckCancelled() or self.LocalFeatureController.State ~= "RUNNING" then return false, "Cancelled" end
				local active = c.Scheduler.Active
				if not active or active.Definition.Owner ~= "REWARDS" or active.Definition.Generation ~= c.Generation
					or c.Rewards.Ledger.Pending ~= pending or not self.Config.MYSTERY_BOX_SETTINGS.AUTO_OPEN_MYSTERY_BOXES then return false, "Gift lease/operation changed during guards" end
				self.LastOrdinaryGiftHit = os.clock()
				local ok, err = pcall(record.Component.Hit, record.Component)
				return ok, ok and "Guarded native ordinary gift Hit; reward still unverified" or tostring(err)
			end
		end
	end
	return false, "No correlated in-range ordinary gift with verified completion interface; manual completion may be required"
end

function GameMechanics:AntiAFKCapability(method)
	if method ~= "VIRTUAL_INPUT_SCROLL_LOCK" then return { Available = false, Reason = "Unsupported method; native AFK reporting ignores mouse movement" } end
	local ok, service = pcall(game.GetService, game, "VirtualInputManager")
	local readable, callable, key = pcall(function()
		return service and type(service.SendKeyEvent) == "function" and Enum.KeyCode.ScrollLock ~= nil, Enum.KeyCode.ScrollLock
	end)
	if not ok or not readable or not callable then return { Available = false, Method = method, Reason = "VirtualInputManager.SendKeyEvent / ScrollLock unavailable in this runtime" } end
	return { Available = true, Method = method, Status = "API_PRESENT_PERMISSION_UNTESTED", Service = service, Key = key }
end

function GameMechanics:AntiAFKGuard(manager)
	local c = manager.Controller
	if c.State ~= "RUNNING" or not self.Config.ANTIAFK_SETTINGS.ENABLE_ANTI_AFK then return false, "Anti-AFK disabled/stopped" end
	local active = c.Scheduler.Active
	if active and active.Definition.Owner ~= "ANTI_AFK" then return false, "Another scheduler task owns input" end
	if c.EggTravel:OwnsLocation() or c.Pets.Hatch.Location or c.Pets.Hatch.Pending or c.Pets.PendingEquip then return false, "Egg travel/hatch/equipment owns interaction" end
	local rewards = c.Rewards:GetStatus()
	if rewards.Pending then return false, "Reward/gift operation pending or uncertain" end
	local allowed, reason = self:LocalFeatureGuard()
	if not allowed then return false, reason end
	local ok, blocker = pcall(function()
		local raw = self.Reader:GetLiveProfile()
		if not raw or type(raw.Settings) ~= "table" then return "Fresh native keybind settings unavailable" end
		for _, value in pairs(raw.Settings) do
			if value == "ScrollLock" or value == "Enum.KeyCode.ScrollLock" then return "ScrollLock is assigned to a native game action" end
		end
		local report = self.Reader:_dependency("AFKReport")
		if not report or type(report.Get) ~= "function" then return "Native AFK report guard unavailable" end
		local state = report:Get()
		if type(state) ~= "table" or type(state.Pets) ~= "table" or next(state.Pets) ~= nil then return "AFK report/reveal has pending or unknown pet results" end
		local playerGui = self.Player:FindFirstChild("PlayerGui")
		local screen = playerGui and playerGui:FindFirstChild("ScreenGui")
		local afk, reveal = screen and screen:FindFirstChild("AFK"), screen and screen:FindFirstChild("AFKReveal")
		if not afk or not reveal or afk.Visible ~= false or reveal.Visible ~= false then return "Native AFK/report presentation active or unavailable" end
		local input = game:GetService("UserInputService")
		local camera, point = workspace.CurrentCamera, input:GetMouseLocation()
		local viewport = camera and camera.ViewportSize
		if not point or not viewport or not featureFinite(point.X) or not featureFinite(point.Y)
			or point.X < 2 or point.Y < 2 or point.X > viewport.X - 2 or point.Y > viewport.Y - 2 then return "Actual pointer/camera outside safe viewport" end
		if input.MouseBehavior ~= Enum.MouseBehavior.Default then return "Locked camera/cursor owns movement" end
		if #input:GetKeysPressed() > 0 or #input:GetMouseButtonsPressed() > 0 then return "Real keyboard/mouse input is active" end
		local gui = game:GetService("GuiService")
		if gui.MenuIsOpen then return "Roblox menu is open" end
		local physical = self.Reader:_dependency("PhysicalItem")
		if not physical or type(physical.GetActiveObjects) ~= "function" then return "Total gift input guard unavailable" end
		local gifts = physical:GetActiveObjects("Gift")
		if gifts ~= 0 then return "Gift interaction is active or unknown, including unloaded gifts" end
		return nil
	end)
	if not ok then return false, "Anti-AFK guards unavailable: " .. tostring(blocker) end
	return blocker == nil, blocker
end

function GameMechanics:AntiAFKPulse(manager, token)
	local c = self.LocalFeatureController
	if not c or manager ~= c.AntiAFK or not c.Scheduler.Active or c.Scheduler.Active.Definition.Owner ~= "ANTI_AFK"
		or c.Scheduler.Active.Definition.Generation ~= c.Generation then return false, "SUPPRESSED: anti-AFK task lacks current scheduler lease" end
	if token:CheckCancelled() then return false, "SUPPRESSED: Cancelled" end
	local allowed, reason = self:AntiAFKGuard(manager)
	if not allowed then return false, "SUPPRESSED: " .. tostring(reason) end
	local capability = self:AntiAFKCapability(self.Config.ANTIAFK_SETTINGS.METHOD)
	if not capability.Available then return false, capability.Reason end
	if self.AntiAFKHeldInput then return false, "Previous simulated input has not been released" end
	if token:CheckCancelled() or manager.Controller.State ~= "RUNNING" then return false, "SUPPRESSED: Cancelled before keyDown" end
	local active = c.Scheduler.Active
	if manager ~= c.AntiAFK or not active or active.Definition.Owner ~= "ANTI_AFK"
		or active.Definition.Generation ~= c.Generation then return false, "SUPPRESSED: anti-AFK lease changed during guards" end
	-- Reserve before keyDown: even an API error can leave delivery uncertain.
	-- Pause/Stop/Destroy can synchronously release this exact service/key.
	self.AntiAFKHeldInput = { Service = capability.Service, Key = capability.Key }
	local ok, output = pcall(function()
		capability.Service:SendKeyEvent(true, capability.Key, false, game)
		return nil
	end)
	local released, releaseReason = self:ReleaseAntiAFKInput()
	if not released then return false, "ScrollLock release failed; input delivery uncertain: " .. tostring(releaseReason) end
	if not ok or output then return false, tostring(ok and output or output) end
	return true, "Unassigned ScrollLock down/up API accepted; native activity reception and idle-prevention effectiveness remain owner-tested"
end

function GameMechanics:ReleaseAntiAFKInput()
	local held = self.AntiAFKHeldInput
	if not held then return true, "No simulated key/button held" end
	local ok, reason = pcall(function() held.Service:SendKeyEvent(false, held.Key, false, game) end)
	if ok then self.AntiAFKHeldInput = nil return true, "ScrollLock released" end
	return false, tostring(reason)
end

-- Explicit owner diagnostic only. Ordinary standing/positioning methods above stay frozen.
function GameMechanics:ExecuteOwnerDirectEggTeleportTest(manager, record, token)
	local c, settings = self.LocalFeatureController, self.Config.EGG_TRAVEL_SETTINGS
	local active = c and c.Scheduler and c.Scheduler.Active
	local assigned, requestedPosition, beforePosition, last, nativeReason, nativeRange, maxDisplacement = false, nil, nil, nil, nil, nil, 0
	local function scope()
		if not c or manager ~= c.EggTravel or c.State ~= "RUNNING" or not token or token:CheckCancelled()
			or not active or c.Scheduler.Active ~= active or active.Token ~= token
			or active.Definition.Owner ~= "EGG_TRAVEL" or active.Definition.Generation ~= c.Generation
			or manager.Lease ~= record or record.Generation ~= c.Generation or manager.DiagnosticConsumed ~= true
			or manager.DiagnosticEnded then return "Owner direct test cancelled or scheduler/lease changed" end
		if self.Player ~= c.Reader.Player or not self.Player or self.Player.UserId ~= 10864747620
			or manager.BrainUserId ~= 10864747620 then return "Owner direct test requires account 10864747620" end
		local intent, hatch, allowance = manager.BrainIntent, self.Config.HATCH_SETTINGS, self.Config.OWNER_ONE_HATCH_TEST_SETTINGS
		if self.Config ~= c.Config or settings ~= c.Config.EGG_TRAVEL_SETTINGS or settings.OWNER_DIRECT_EGG_TELEPORT_TEST ~= true
			or settings.MODE ~= "TRAVEL_ONLY" or not settings.ENABLE_SELECTED_EGG_TRAVEL or not settings.ENABLE_DIRECT_POSITIONING
			or settings.ENABLE_NATIVE_ISLAND_TRAVEL or settings.MAXIMUM_ATTEMPTS_PER_SELECTION ~= 1
			or hatch.EGG_SELECTION_MODE ~= "MANUAL" or #hatch.SELECTED_EGGS ~= 1 or hatch.SELECTED_EGGS[1] ~= "Common Egg"
			or not intent or intent.Scope ~= "TRAVEL_ONLY" or intent.DecisionSource ~= "BRAIN_TRAVEL_DIAGNOSTIC"
			or intent.EggName ~= "Common Egg" or intent.Model ~= record.Model or intent.World ~= "The Overworld"
			or record.EggName ~= "Common Egg" or record.World ~= "The Overworld" or record.LocationOnly ~= true
			or allowance.OWNER_ONE_COMMON_EGG_FUNCTIONAL_TEST or allowance.OWNER_ONE_HATCH_TEST_ALLOWANCE
			or allowance.AUTHORIZED_ACCOUNT_ID ~= 0 or allowance.MAXIMUM_COIN_ALLOWANCE ~= 0 or allowance.MAXIMUM_EGG_COST ~= 0
			or self.Config.UPGRADE_SETTINGS.MAXIMUM_PURCHASE_COST ~= 0 then return "Owner direct test scope/actions/budgets changed" end
		return c.Brain:TravelDiagnosticBlocker()
	end
	local function finish(arrived, interaction, reason)
		manager.LastResult = { Status = arrived and (interaction and "OWNER_DIRECT_NATIVE_ARRIVAL_OBSERVED" or "OWNER_DIRECT_PHYSICAL_ARRIVAL_OBSERVED")
			or "OWNER_DIRECT_ARRIVAL_UNCONFIRMED", Scope = "TRAVEL_ONLY", EggName = "Common Egg", IdentityId = record.IdentityId,
			World = record.World, PhysicalArrivalVerified = arrived, InteractionVerified = interaction == true,
			PhysicalPolicyInRange = last and last.Distance <= last.Range or false, Distance = last and last.Distance,
			NativeRange = nativeRange, InteractionReason = nativeReason, DirectPositionAttempted = assigned,
			NativeTravelAttempted = false, HatchCommands = 0, EquipmentCommands = 0, Spending = 0,
			RequestedPosition = requestedPosition, ObservedDisplacement = last and requestedPosition and (last.CharacterRoot.Position - requestedPosition).Magnitude,
			MaximumObservedDisplacement = maxDisplacement, MovementObserved = last and beforePosition and (last.CharacterRoot.Position - beforePosition).Magnitude > 0.5,
			Reason = reason }
		manager.DiagnosticEnded, manager.Lease = true, nil
		manager.Reason = not interaction and reason or nil
		if not arrived then manager.Blocked[record.SelectionKey] = reason end
		manager:DiagnosticTrace("OWNER_DIRECT_RESULT", last or record, reason)
		return { Verified = arrived, Reason = reason, InteractionVerified = interaction == true }
	end
	local blocker = scope()
	if blocker then return finish(false, false, blocker) end
	if self.OwnerDirectEggTeleportConsumed then return finish(false, false, "Owner direct test assignment already consumed; no retry") end
	manager:DiagnosticTrace("OWNER_DIRECT_EXCEPTION", record, "Explicit owner test: standing search, footprint and clearance bypassed; Root overlap/fall/correction possible; no hatch/spending")
	local allowed, guardReason = self:LocalFeatureGuard()
	if not allowed then return finish(false, false, guardReason or "Native presentation guard unavailable") end
	local fresh, reason = manager:Validate(record, token, true)
	if not fresh then return finish(false, false, reason) end
	last = fresh
	blocker = scope()
	if blocker then return finish(false, false, blocker) end
	if fresh.Model ~= record.Model or fresh.TargetRoot ~= record.TargetRoot or fresh.CharacterRoot ~= record.CharacterRoot
		or fresh.LocationVerified ~= true or fresh.World ~= "The Overworld" or fresh.CurrentWorld ~= "The Overworld"
		or fresh.NeedsNativeTravel or not fresh.TargetRoot.Parent or not fresh.TargetRoot:IsDescendantOf(workspace)
		or fresh.Model:FindFirstChild("Root") ~= fresh.TargetRoot then return finish(false, false, "Exact loaded Common Egg/character/world/access changed") end
	local position = fresh.TargetRoot.Position
	if not featureFinite(position.X) or not featureFinite(position.Y) or not featureFinite(position.Z) then return finish(false, false, "Selected Root position unavailable") end
	local directFrame = CFrame.new(position) -- Exactly the observed physical Root; no standing/clearance substitution.
	blocker = scope()
	if blocker then return finish(false, false, blocker) end
	self.OwnerDirectEggTeleportConsumed = true -- Consume before setter, including uncertain errors; never repeat.
	manager.Attempts[record.SelectionKey] = (manager.Attempts[record.SelectionKey] or 0) + 1
	record.Status, record.DirectPositionAttempted = "TRAVELING", true
	assigned, requestedPosition, beforePosition = true, position, fresh.CharacterRoot.Position
	local ok, err = pcall(function() fresh.CharacterRoot.CFrame = directFrame end)
	manager:DiagnosticTrace("OWNER_DIRECT_POSITION_ATTEMPTED", fresh, "One owner-authorized physical Root CFrame setter attempted; standing/clearance intentionally bypassed; arrival not yet verified")
	if not ok then return finish(false, false, "Owner direct assignment failed/uncertain; no retry: " .. tostring(err)) end
	local deadline = math.min(record.Deadline, os.clock() + math.min(12, settings.ARRIVAL_TIMEOUT_SECONDS))
	local stableAt, stablePosition, nativeVerified
	while os.clock() < deadline do
		fresh, reason = manager:Validate(record, token)
		if not fresh then return finish(false, false, reason) end
		local observed = fresh.CharacterRoot.Position
		local final, finalReason = manager:Validate(record, token, true)
		if not final then return finish(false, false, finalReason) end
		last, blocker = final, scope()
		if blocker then return finish(false, false, blocker) end
		if final.Model ~= record.Model or final.TargetRoot ~= record.TargetRoot or final.CharacterRoot ~= record.CharacterRoot
			or final.LocationVerified ~= true or final.World ~= "The Overworld" or final.CurrentWorld ~= "The Overworld" then
			return finish(false, false, "Selected physical egg/character/world changed during owner direct observation")
		end
		local interaction, why, native = manager:HatchInteractionAt(final, final.CharacterRoot.Position, true) -- Read-only exact registration evidence.
		local actual = final.CharacterRoot.Position
		local rangeOK, rangeReason = false, nil
		if interaction == true and native and native.Model == record.Model and native.TargetRoot == record.TargetRoot then
			rangeOK, rangeReason = manager:RangeEligibleAt(native, actual, true) -- Preserve native prompt/nearest rules.
		end
		blocker = scope()
		if blocker then return finish(false, false, blocker) end
		actual = final.CharacterRoot.Position -- Delegated native observations may yield; use the position after them.
		nativeVerified = rangeOK == true and native and native.RangeOrigin and native.RangeOrigin.Parent
			and (actual - native.RangeOrigin.Position).Magnitude <= native.Range
		local displacement = (actual - requestedPosition).Magnitude
		maxDisplacement = math.max(maxDisplacement, displacement)
		nativeReason, nativeRange = rangeReason or why, native and native.Range
		final.Distance = (actual - final.RangeOrigin.Position).Magnitude
		local nearby = final.Distance <= final.Range or nativeVerified
		if nearby and (actual - observed).Magnitude <= 0.35 and (not stablePosition or (actual - stablePosition).Magnitude <= 0.35) then
			stableAt, stablePosition = stableAt or os.clock(), stablePosition or actual
			if os.clock() - stableAt >= settings.STABILITY_SECONDS then
				return finish(true, nativeVerified, string.format("Stable actual arrival observed; native interaction=%s (%s); Root displacement=%.2f studs, maximum=%.2f; cause UNKNOWN (physics/external correction possible); one assignment; zero hatch/equipment/spending",
					tostring(nativeVerified == true), tostring(nativeReason), displacement, maxDisplacement))
			end
		else stableAt, stablePosition = nil, nil end
		task.wait(0.2)
	end
	return finish(false, false, string.format("Owner direct arrival unconfirmed; native interaction=%s (%s); maximum observed Root displacement=%.2f studs; cause UNKNOWN; no retry",
		tostring(nativeVerified == true), tostring(nativeReason), maxDisplacement))
end

-- PHASE5_FREE_WHEEL_TICKET_BEGIN
-- Exact fixed command; the existing scheduler and interaction guards remain authoritative.
function GameMechanics:ClaimFreeWheelTicket(manager, decision, token, remote)
	local c = self.LocalFeatureController
	local function owns()
		local active = c and c.Scheduler and c.Scheduler.Active
		return c and manager == c.Rewards and c.State == "RUNNING" and not manager.Destroyed
			and c.Reader and self.Reader == c.Reader and self.Player and self.Player == c.Reader.Player and self.Player.UserId == manager.UserId
			and type(token) == "table" and type(token.CheckCancelled) == "function" and not token:CheckCancelled() and active and active.Token == token
			and type(active.Definition) == "table" and active.Definition.Owner == "REWARDS" and active.Definition.Generation == c.Generation
	end
	if type(decision) ~= "table" or decision.Kind ~= "FREE_WHEEL_TICKET" or decision.Command ~= "ClaimFreeWheelSpin" then return false, "Exact documented free-wheel command required" end
	if not owns() then return false, "Free-wheel task lacks its exact scheduler, token or account" end
	if remote ~= self.Reader:_dependency("Remote") or type(remote) ~= "table" or type(remote.FireServer) ~= "function" then return false, "Verified free-wheel native transport unavailable" end
	local transport = remote.FireServer
	local authorized, reason = manager:_freeWheelAuthorization()
	if not authorized then return false, reason end
	local allowed, blocker = self:LocalFeatureGuard()
	if not allowed or not owns() then return false, blocker or "Free-wheel interaction interrupted" end
	local pending, preparationReason = manager:PrepareFreeWheelTicket(decision, token)
	if not pending then return false, preparationReason end
	local finalAllowed, finalReason = self:LocalFeatureGuard()
	if not finalAllowed or not owns() or remote ~= self.Reader:_dependency("Remote") or remote.FireServer ~= transport then
		manager:AbortPreparation(pending, finalReason or "Free-wheel lease or transport changed before attempt")
		return false, finalReason or "Free-wheel lease or transport changed before attempt"
	end
	local charged, chargeReason = manager:MarkFreeWheelTicketDispatched(pending, token)
	if not charged then manager:AbortPreparation(pending, chargeReason) return false, chargeReason end
	local dispatchValid, dispatchState, dispatchReason = manager:ValidateFreeWheelTicketDispatch(pending, token)
	if not dispatchValid then
		manager:UnresolveFreeWheelTicket(pending, dispatchState, dispatchReason)
		return false, dispatchReason
	end
	local dispatchAllowed, dispatchBlocker = self:LocalFeatureGuard()
	if not dispatchAllowed then
		manager:UnresolveFreeWheelTicket(pending, "AMBIGUOUS", dispatchBlocker or "Native interaction changed after charged observation")
		return false, dispatchBlocker
	end
	local finalAuthorized = manager:_freeWheelAuthorization()
	if not finalAuthorized then
		manager:UnresolveFreeWheelTicket(pending, "CANCELLED_AFTER_DISPATCH", "Charged free-wheel authorization revoked after final guard")
		return false, "Free-wheel authorization revoked before transport"
	end
	local observed = manager.WheelDispatchObservation
	local finalSnapshot = self.Reader:GetSnapshot()
	if not observed or type(finalSnapshot) ~= "table" or finalSnapshot.Ready ~= true
		or finalSnapshot.Revision ~= observed.Revision or self.Reader.Revision ~= observed.Revision
		or os.clock() < observed.ReadAt or os.clock() - observed.ReadAt > manager.Config.FREE_WHEEL_TICKET_SETTINGS.MAXIMUM_ACCOUNT_AGE_SECONDS then
		manager:UnresolveFreeWheelTicket(pending, "AMBIGUOUS", "Received snapshot changed after final interaction guard; no transport or retry")
		return false, "Received snapshot changed before free-wheel transport"
	end
	if not owns() or manager.Ledger.Pending ~= pending or pending.Command ~= "ClaimFreeWheelSpin"
		or not finalAuthorized or manager.Config.FREE_WHEEL_TICKET_SETTINGS.AUTHORIZED_TEST_ID ~= pending.TestId
		or remote ~= self.Reader:_dependency("Remote") or remote.FireServer ~= transport then
		manager:UnresolveFreeWheelTicket(pending, "CANCELLED_AFTER_DISPATCH", "Charged free-wheel attempt interrupted before transport; no automatic retry")
		return false, "Charged free-wheel attempt interrupted"
	end
	pending.TransportStarted = true
	local ok = pcall(function() remote:FireServer("ClaimFreeWheelSpin") end)
	pending.InvocationOk = ok
	if not ok then manager:UnresolveFreeWheelTicket(pending, "AMBIGUOUS", "Free-wheel transport raised after charged attempt; delivery unresolved; no automatic retry") end
	manager:ObserveFreeWheelTicket(pending)
	return true, "One free-wheel attempt recorded; paired received state required"
end
-- PHASE5_FREE_WHEEL_TICKET_END
return GameMechanics

end

-- src/OCFoundation/HatchManager.luau
factories["HatchManager"] = function()
--!nonstrict
-- Session ledger and received-inventory verification; no timer, remote or task authority.
local PetPolicy = requireOC("PetPolicy")
local HatchManager = {}
HatchManager.__index = HatchManager

function HatchManager.new(controller)
	return setmetatable({ Controller = controller, RequestedHatches = 0, RequestCost = 0, VerifiedHatches = 0,
		Once = controller.Config.HATCH_SETTINGS.HATCH_ONE_EGG_ONCE }, HatchManager)
end

function HatchManager:Ended()
	local settings = self.Controller.Config.HATCH_SETTINGS
	return self.EndReason ~= nil or self.Once and self.RequestedHatches >= 1
		or self.RequestedHatches >= settings.MAXIMUM_SESSION_HATCHES or self.RequestCost >= settings.MAXIMUM_SESSION_COST
		or (self.StartedAt ~= nil and os.clock() - self.StartedAt >= settings.MAXIMUM_SESSION_SECONDS)
end

function HatchManager:Observe(raw)
	local pending = self.Pending
	if not pending then return end
	local inv = PetPolicy.Inventory(raw)
	local gained, changes = 0, {}
	if inv then
		for id, pet in pairs(inv.ById) do
			local before = pending.Before[id]
			if pending.Pool[pet.Name] and (not before or before.Name == pet.Name and (before.Shiny == true) == (pet.Shiny == true)
				and (before.Mythic == true) == (pet.Mythic == true) and (before.XL == true) == (pet.XL == true)
				and PetPolicy.Equal(before.Super or false, pet.Super or false)) then
				local delta = (pet.Amount or 1) - (before and (before.Amount or 1) or 0)
				if delta > 0 then
					local variants = {} for _, flag in ipairs({ "Super", "XL", "Shiny", "Mythic" }) do if pet[flag] then table.insert(variants, flag) end end
					gained += delta
					table.insert(changes, { Id = id, Name = pet.Name, Quantity = delta, Variant = #variants > 0 and table.concat(variants, " ") or "Normal",
						Shiny = pet.Shiny == true, Mythic = pet.Mythic == true, XL = pet.XL == true, Super = pet.Super, ExistingStack = before ~= nil })
				end
			end
		end
	end
	table.sort(changes, function(a, b) return a.Id < b.Id end)
	local counter = raw and type(raw.EggsOpened) == "table" and raw.EggsOpened[pending.EggName] or nil
	local delta = PetPolicy.Finite(counter) and counter % 1 == 0 and counter - pending.Counter or nil
	local balances = {}
	for currency, before in pairs(pending.BeforeBalances or {}) do
		local after = raw and raw[currency]
		balances[currency] = { Before = before, After = after, Delta = PetPolicy.Finite(after) and after - before or nil }
	end
	pending.Observed = { CounterDelta = delta, MatchedQuantity = gained, Changes = changes, Balances = balances }
	local confirmed = delta ~= nil and delta >= pending.Count and gained >= pending.Count
	if confirmed or os.clock() >= pending.Deadline then
		-- Keep the detached native projection privately. It contains the exact
		-- pre-request owned-team benchmark; status exposes only its evidence.
		self.ResultBaseline = pending.UsefulnessBaseline
		self.LastResult = { Status = confirmed and "INVENTORY_GAIN_OBSERVED" or "UNCONFIRMED", EggName = pending.EggName,
			DiagnosticBefore = pending.DiagnosticBefore,
			OwnerAllowance = pending.OwnerAllowance,
			Quantity = gained, RequestedQuantity = pending.Count, CounterBefore = pending.Counter, CounterAfter = counter, CounterDelta = delta, Changes = changes,
			BeforeBalance = pending.BeforeBalance, AfterBalance = raw and raw[pending.Currency], Balances = balances,
			TeamBefore = pending.TeamBefore, TeamAfter = inv and table.clone(inv.Team), TeamIndexBefore = pending.TeamIndex,
			TeamIndexAfter = inv and inv.TeamIndex, OCEquipmentCommands = 0,
			UsefulnessBaselineScore = pending.UsefulnessBaseline and pending.UsefulnessBaseline.Score,
			UsefulnessBaselineIds = pending.UsefulnessBaseline and table.clone(pending.UsefulnessBaseline.Ids),
			UsefulnessCurrency = pending.UsefulnessBaseline and pending.UsefulnessBaseline.Currency,
			UsefulnessSearchBoundReached = pending.UsefulnessBaseline and pending.UsefulnessBaseline.SearchBoundReached,
			UsefulnessProjectionFailures = pending.UsefulnessBaseline and pending.UsefulnessBaseline.ProjectionFailures,
			UsefulnessEvidence = "Frozen pre-hatch best feasible owned-team native projection; bounded greedy estimate, global optimum/server modifiers unverified",
			Attribution = "Matching received counter/inventory observations; external/manual activity cannot be excluded; balance change is separate evidence" }
		local before = pending.DiagnosticBefore
		local coins = balances.Coins
		local expected = before and before.Currency == "Coins" and before.RequestedCost or nil
		local debit = coins and type(coins.Delta) == "number" and coins.Delta == coins.Delta
			and math.abs(coins.Delta) < math.huge and -coins.Delta or nil
		self.LastResult.CoinsComparison = { ExpectedDebit = expected, ObservedNetDebit = debit,
			Difference = expected ~= nil and debit ~= nil and debit - expected or nil,
			Status = (expected == nil or debit == nil) and "UNKNOWN" or debit == expected and "NET_MATCH" or "NET_DISCREPANCY",
			Attribution = "Net balance comparison only; concurrent credits/spending and exact server charge remain unverified" }
		if confirmed then
			self.VerifiedHatches += pending.Count
			if delta ~= pending.Count or inv.TeamIndex ~= pending.TeamIndex or not PetPolicy.SameTeam(inv.Team, pending.TeamBefore) then
				self.Fault = "Hatch counter/team changed beyond the frozen request; external activity unresolved. No automatic continuation or retry"
				self.LastResult.Reason = self.Fault self.EndReason = self.Fault
			end
		else
			self.Fault = "Hatch acknowledgement timed out; rejection/delay/delivery unresolved. No automatic retry; request budget retained"
			self.LastResult.Reason = self.Fault self.EndReason = self.Fault
		end
		self.Pending = nil
		if self.Once and pending.OwnerAllowance then self.EndReason = self.EndReason or "Owner one-hatch allowance consumed; normal world reserve restored; no further spending" end
		if self.Once then self.EndReason = self.EndReason or "Single request consumed; hatch result observed; no further spending/equipment" end
	end
end

function HatchManager:ResultText()
	local r = self.LastResult
	if not r then return "No hatch result" end
	local pets, balances = {}, {}
	for _, change in ipairs(r.Changes or {}) do
		table.insert(pets, string.format("%s %s [%s] +%d%s; usefulness=%s; native gain=%s", change.Variant, change.Name, change.Id, change.Quantity,
			change.ExistingStack and " (existing stack)" or "", change.Usefulness or "UNKNOWN", tostring(change.ActualIncrement or "UNKNOWN")))
	end
	for _, currency in ipairs({ "Coins", "Gems", "Tickets", "Pearls" }) do
		local value = r.Balances and r.Balances[currency]
		if value then table.insert(balances, currency .. " net=" .. (value.Delta ~= nil and string.format("%+.3f", value.Delta) or "UNKNOWN")) end
	end
	local owner = r.OwnerAllowance
	local before, comparison = r.DiagnosticBefore or {}, r.CoinsComparison or {}
	local diagnosticText = string.format(" | account=%s; selected instance=%s; expected Coins debit=%s; observed net debit=%s; difference=%s; %s (server charge attribution UNKNOWN)",
		tostring(before.AccountId or "UNKNOWN"), tostring(before.InstanceId or "UNKNOWN"), tostring(comparison.ExpectedDebit or "UNKNOWN"),
		tostring(comparison.ObservedNetDebit or "UNKNOWN"), tostring(comparison.Difference or "UNKNOWN"), tostring(comparison.Status or "UNKNOWN"))
	local allowanceText = owner and string.format(" | owner allowance consumed; exact requested price=%s Coins; world reserve draw=%s; net debit=%s (attribution UNKNOWN); %s",
		tostring(owner.RequestedPrice), tostring(owner.WorldReserveBorrowed), tostring(owner.Result and owner.Result.ObservedNetDebit or "UNKNOWN"), tostring(owner.Persistence)) or ""
	return string.format("%s | %s | requested=%s; matching inventory +%s; egg counter delta=%s | baseline=%s %s pre-hatch owned-team estimate | %s | observed %s (net, attribution unknown) | OC equipment commands during hatch=0 | %s%s",
		r.EggName, r.Status, tostring(r.RequestedQuantity), tostring(r.Quantity), tostring(r.CounterDelta or "UNKNOWN"),
		tostring(r.UsefulnessBaselineScore or "UNKNOWN"), tostring(r.UsefulnessCurrency or "UNKNOWN"),
		#pets > 0 and table.concat(pets, "; ") or "No matching received pet", #balances > 0 and table.concat(balances, ", ") or "balances UNKNOWN",
		r.Reason or "Received hatch verified; an upgrade is not guaranteed. Request ledger retained", allowanceText .. diagnosticText)
end

function HatchManager:GetStatus()
	return { RequestedHatches = self.RequestedHatches, RequestCost = self.RequestCost, VerifiedHatches = self.VerifiedHatches,
		Pending = self.Pending and { EggName = self.Pending.EggName, Count = self.Pending.Count, Deadline = self.Pending.Deadline,
			Observed = self.Pending.Observed, DiagnosticBefore = self.Pending.DiagnosticBefore },
		Location = self.Location, Fault = self.Fault, LastResult = self.LastResult, BestHatch = self.BestHatch,
		SingleHatch = self.Once, Ended = self:Ended(), EndReason = self.EndReason }
end

return HatchManager

end

-- src/OCFoundation/MasteryPolicy.luau
factories["MasteryPolicy"] = function()
--!nonstrict
-- Pure Phase 5 recommendations. This module owns no task or gameplay action.
local MasteryPolicy = {}

local function finite(value)
	return type(value) == "number" and value == value and value >= 0 and value < math.huge
end

local function integer(value)
	return finite(value) and value % 1 == 0
end

local function copy(value, seen)
	if type(value) ~= "table" then return value end
	seen = seen or {}
	if seen[value] then return seen[value] end
	local result = {} seen[value] = result
	for key, entry in pairs(value) do result[key] = copy(entry, seen) end
	return result
end

local function price(value)
	if type(value) ~= "table" or value.Type ~= "Currency" or type(value.Currency) ~= "string"
		or value.Currency == "" or not finite(value.Amount) then return nil end
	return { Type = "Currency", Currency = value.Currency, Amount = value.Amount }
end

local reserveFields = { Coins = "COIN_RESERVE", Gems = "GEM_RESERVE", Tickets = "TICKET_RESERVE", Pearls = "PEARL_RESERVE" }

local function affordability(config, balances, cost)
	if not cost then return "UNKNOWN", nil, nil, nil end
	local balance = type(balances) == "table" and balances[cost.Currency]
	local field = reserveFields[cost.Currency]
	local reserve = field and config.RESOURCE_SETTINGS and config.RESOURCE_SETTINGS[field]
	if not finite(balance) or not finite(reserve) then return "UNKNOWN", finite(balance) and balance or nil, nil, nil end
	local available = math.max(0, balance - reserve)
	local shortage = math.max(0, cost.Amount - available)
	return shortage == 0 and "AFFORDABLE" or "INSUFFICIENT", balance, shortage, reserve
end

local function funding(row, settings, context)
	if not finite(row.Shortage) then return end
	local rate = context.StationaryRate or context.Rate
	local now = context.ObservedAt
	local perMinute = type(rate) == "table" and rate.PerMinute
	if type(perMinute) == "table" then perMinute = perMinute[row.Currency] end
	if type(rate) ~= "table" or rate.ScopeVerified ~= true or rate.Ready ~= true
		or rate.Currency ~= row.Currency or (row.Currency ~= "Coins" and row.Currency ~= "Gems")
		or not finite(rate.Seconds) or not finite(settings.MINIMUM_RATE_SAMPLE_SECONDS)
		or rate.Seconds < settings.MINIMUM_RATE_SAMPLE_SECONDS or not finite(rate.LastAt)
		or not finite(now) or rate.LastAt > now or not finite(settings.MAXIMUM_RATE_AGE_SECONDS)
		or now - rate.LastAt > settings.MAXIMUM_RATE_AGE_SECONDS or not finite(perMinute) then return end
	row.ObservedPerMinute = perMinute
	row.FundingEvidence = "Observed stationary balance sample; unchanged-rate extrapolation; external credits may contribute"
	if perMinute > 0 then
		local seconds = row.Shortage / perMinute * 60
		if finite(seconds) then row.FundingETASeconds = seconds end
	elseif row.Shortage > 0 then row.FundingBlocker = "No positive income in the qualified stationary sample" end
end

local function observedPrice(context, name, index, tier, nextTier)
	local observations = context.TierObservations and context.TierObservations[name]
	local observed = observations and observations[index]
	if not observed and index == nextTier then observed = context.CategoryObservations and context.CategoryObservations[name] end
	if observed then
		if observed.PriceStatus ~= "OBSERVED" then return nil, "Native tier price is unavailable" end
		return price(observed.NativePrice), "Observed native tier price/early-unlock predicate"
	end
	-- A future entitlement predicate cannot be assumed false, and a price
	-- function cannot be executed by this pure policy.
	if type(tier) ~= "table" or tier.UnlockEarly ~= nil then return nil, "Future early-unlock price is unverified" end
	return price(tier.Cost), "Native fixed catalog price"
end

local function category(config, snapshot, context, name, definition, order)
	local row = { Name = name, Category = name, Order = order, Status = "UNKNOWN", Blockers = {},
		CompletedTiers = {}, ExpectedIncomeGain = "UNKNOWN", Effects = {},
		RemainingPackage = { Status = "UNKNOWN", Costs = {}, Unknowns = {} } }
	local observed = context.CategoryObservations and context.CategoryObservations[name]
	row.Visibility = observed and observed.Visibility or "UNKNOWN"
	row.VisibilityReason = observed and observed.VisibilityReason or "Native category visibility unavailable"
	row.Permanence = observed and observed.Permanence or "UNKNOWN"
	row.PermanenceEvidence = observed and observed.PermanenceEvidence or "Permanent category classification unavailable"
	row.PhysicalEligibility = "UNKNOWN"
	row.TradingPlazaStatus = context.TradingPlazaStatus or "UNKNOWN"
	row.EffectiveUpgrades = copy(context.EffectiveUpgrades or snapshot.Upgrades and snapshot.Upgrades.MasteryUpgrades)
	row.EffectiveUpgradeState = type(row.EffectiveUpgrades) == "table" and "RECEIVED" or "UNKNOWN"
	local received = snapshot.Upgrades and snapshot.Upgrades.MasteryLevels and snapshot.Upgrades.MasteryLevels[name]
	row.CurrentTier = integer(received) and received or nil
	if row.Visibility == "LOCKED" then
		-- Locked is not complete. Still report consistent received progress when
		-- its native tier sequence can be established without guessing.
		if type(definition) == "table" and type(definition.Levels) == "table" then
			local count, maximum, valid = 0, 0, true
			for index, tier in pairs(definition.Levels) do
				if not integer(index) or index < 1 or type(tier) ~= "table" then valid = false break end
				count, maximum = count + 1, math.max(maximum, index)
			end
			if valid and count > 0 and count == maximum and row.CurrentTier and row.CurrentTier <= maximum then
				row.MaximumTier = maximum
				for index = 1, row.CurrentTier do table.insert(row.CompletedTiers, index) end
				row.NextTier = row.CurrentTier < maximum and row.CurrentTier + 1 or nil
				row.CompletionObserved = row.CurrentTier == maximum
			end
		end
		row.Status = "LOCKED" table.insert(row.Blockers, row.VisibilityReason) return row
	end
	if type(definition) ~= "table" or type(definition.Levels) ~= "table" then
		table.insert(row.Blockers, "Native category tier definitions unavailable") return row
	end
	if row.Visibility ~= "VISIBLE" then table.insert(row.Blockers, row.VisibilityReason) return row end
	if row.Permanence ~= "VERIFIED_PERMANENT" then table.insert(row.Blockers, row.PermanenceEvidence) return row end
	local maximum, count = 0, 0
	for index, tier in pairs(definition.Levels) do
		if not integer(index) or index < 1 or type(tier) ~= "table" then
			table.insert(row.Blockers, "Malformed native tier index or definition") return row
		end
		maximum, count = math.max(maximum, index), count + 1
	end
	if maximum == 0 or count ~= maximum then
		table.insert(row.Blockers, "Native tier catalog is empty or sparse; completion and sequential prerequisites are UNKNOWN") return row
	end
	row.MaximumTier = maximum
	local current = snapshot.Upgrades and snapshot.Upgrades.MasteryLevels and snapshot.Upgrades.MasteryLevels[name]
	if not integer(current) or current > maximum then
		table.insert(row.Blockers, "Received Mastery level is absent, invalid or inconsistent with the native catalog") return row
	end
	row.CurrentTier = current
	for index = 1, current do table.insert(row.CompletedTiers, index) end
	if current == maximum then
		row.Status = "COMPLETE" row.CompletionObserved = true row.RemainingPackage.Status = "COMPLETE" return row
	end
	row.NextTier = current + 1
	row.Requirements = { "Complete tiers sequentially through " .. tostring(current), "Native category visibility", "Outer Space Mastery HUD access", "Fresh account and native price" }
	table.insert(row.Requirements, "Observe native not-Trading-Plaza HUD condition; advisory review is not purchase eligibility")
	if row.TradingPlazaStatus == "UNKNOWN" then
		table.insert(row.Blockers, "Native Trading Plaza condition UNKNOWN; full HUD/purchase eligibility remains unverified")
	end
	local tier = definition.Levels[row.NextTier]
	row.Effects = copy(type(tier.Upgrades) == "table" and tier.Upgrades or {})
	row.BenefitEvidence = type(tier.Upgrades) == "table" and "Native declared next-tier effects; received effective upgrades remain separate; earning gain UNKNOWN" or "Native next-tier effects UNKNOWN"
	row.NextPrice, row.PriceEvidence = observedPrice(context, name, row.NextTier, tier, row.NextTier)
	row.RemainingPackage.Status = "OBSERVED"
	for index = row.NextTier, maximum do
		local cost = observedPrice(context, name, index, definition.Levels[index], row.NextTier)
		if cost then
			row.RemainingPackage.Costs[cost.Currency] = (row.RemainingPackage.Costs[cost.Currency] or 0) + cost.Amount
			if not finite(row.RemainingPackage.Costs[cost.Currency]) then
				row.RemainingPackage.Status = "UNKNOWN" table.insert(row.RemainingPackage.Unknowns, "Package total is not finite")
			end
		else
			row.RemainingPackage.Status = "UNKNOWN" table.insert(row.RemainingPackage.Unknowns, "Tier " .. tostring(index) .. " price UNKNOWN")
		end
	end
	row.RemainingPackage.Assumption = "Current native prices/entitlements; re-evaluate after each received tier or account change; currencies remain separate"
	if not row.NextPrice then table.insert(row.Blockers, "Next sequential native price UNKNOWN") return row end
	row.Currency, row.Amount = row.NextPrice.Currency, row.NextPrice.Amount
	local balances = context.Balances or snapshot.Balances
	row.Affordability, row.Balance, row.Shortage, row.Reserve = affordability(config, balances, row.NextPrice)
	if row.Affordability == "UNKNOWN" then table.insert(row.Blockers, "Actual currency balance or explicit reserve policy unavailable") end
	local access = context.Access and context.Access.Visibility or "UNKNOWN"
	row.Access = access
	if access ~= "VISIBLE" then
		row.Status = access == "LOCKED" and "PREREQUISITE" or "UNKNOWN"
		table.insert(row.Blockers, context.Access and context.Access.Reason or "Mastery HUD access UNKNOWN") return row
	end
	if row.Affordability == "UNKNOWN" then return row end
	row.Status = row.Affordability == "AFFORDABLE" and "REVIEW" or "FUNDING"
	if row.Status == "FUNDING" then table.insert(row.Blockers, "Earn the remaining native currency without changing configured reserves") end
	funding(row, config.MASTERY_SETTINGS, context)
	return row
end

local function worldGate(config, snapshot, context)
	local node = context.WorldGate
	if not node and snapshot.ProgressionGraph and snapshot.ProgressionGraph.Next
		and snapshot.ProgressionGraph.Next.Kind == "WORLD" then node = snapshot.ProgressionGraph.Next end
	if not node then
		local candidates = {}
		for _, world in pairs(snapshot.AvailableProgression and snapshot.AvailableProgression.Worlds or {}) do
			if type(world) == "table" and type(world.Name) == "string" and world.Selected == true
				and snapshot.UnlockedWorlds and snapshot.UnlockedWorlds[world.Name] == nil then table.insert(candidates, world) end
		end
		table.sort(candidates, function(a, b)
			local left, right = finite(a.Order) and a.Order or math.huge, finite(b.Order) and b.Order or math.huge
			return left == right and a.Name < b.Name or left < right
		end)
		node = candidates[1]
	end
	if not node then return { Status = "UNKNOWN", Reason = "Next paid world gate is unavailable from current native observations" } end
	local result = { Status = "UNKNOWN", Name = node.Name or node.World, Price = price(node.Cost or node.Price), Blockers = {},
		ActionAuthorization = "NONE", Prerequisites = copy(node.Prerequisites or {}) }
	if not result.Price or result.Price.Amount <= 0 then result.Reason = "Next paid world cost UNKNOWN or not a paid gate" return result end
	result.Currency, result.Amount = result.Price.Currency, result.Price.Amount
	result.Affordability, result.Balance, result.Shortage, result.Reserve = affordability(config, context.Balances or snapshot.Balances, result.Price)
	result.Status = "DEFERRED_FOR_MASTERY_REVIEW"
	result.Reason = "Read-only native world gate projection; no purchase, claim or reserve override"
	return result
end

local function recommendation(row)
	local kinds = { REVIEW = "MASTERY_REVIEW", FUNDING = "MASTERY_FUNDING", PREREQUISITE = "MASTERY_PREREQUISITE" }
	return { Kind = kinds[row.Status] or "WAIT", Category = row.Name, Tier = row.NextTier,
		Price = copy(row.NextPrice), Currency = row.Currency, Amount = row.Amount, Balance = row.Balance,
		Shortage = row.Shortage, Affordability = row.Affordability or "UNKNOWN", Reserve = row.Reserve,
		Effects = copy(row.Effects), ExpectedIncomeGain = "UNKNOWN", FundingETASeconds = row.FundingETASeconds,
		Reason = row.Status == "REVIEW" and "Review the next obtainable permanent Mastery tier before the next paid world unlock; configured category order, no claim of optimal ROI"
			or row.Status == "FUNDING" and "Fund the next sequential permanent Mastery tier before the next paid world unlock; stationary income is used only when qualified"
			or row.Status == "PREREQUISITE" and "Resolve observed Mastery access before reviewing this sequential tier; no travel is authorized"
			or "Resolve unavailable Mastery evidence before declaring permanent progression complete",
		Blockers = copy(row.Blockers), Requirements = copy(row.Requirements or {}), ActionAuthorization = "NONE" }
end

function MasteryPolicy.Analyze(config, snapshot, context)
	context, snapshot = context or {}, snapshot or {}
	local settings = config.MASTERY_SETTINGS or {}
	local report = { ReadOnly = true, ActionAuthorization = "NONE", Status = "UNKNOWN", Categories = {}, Unknowns = {},
		Access = copy(context.Access or { Visibility = "UNKNOWN", PhysicalEligibility = "UNKNOWN", ServerEligibility = "UNKNOWN" }),
		TradingPlazaStatus = context.TradingPlazaStatus or "UNKNOWN",
		Recommendation = { Kind = "WAIT", Reason = "Mastery evidence UNKNOWN", Blockers = {}, ActionAuthorization = "NONE" },
		Policy = "Complete currently obtainable permanent Mastery tiers before the next paid world unlock; sequential native tiers, independent currencies and explicit reserves; no automatic action" }
	if settings.ENABLE_MASTERY_INTELLIGENCE ~= true then
		report.Status = "DISABLED" report.Recommendation.Reason = "Read-only Mastery intelligence is disabled" return report
	end
	local now, readAt = context.ObservedAt, snapshot.ReadAt
	if snapshot.Ready ~= true or context.Fresh ~= true or not finite(now) or not finite(readAt) or readAt > now
		or not finite(settings.MAXIMUM_ACCOUNT_AGE_SECONDS) or now - readAt > settings.MAXIMUM_ACCOUNT_AGE_SECONDS then
		table.insert(report.Unknowns, context.Blocker or "Account/native observation is unavailable, stale or inconsistent")
		report.Recommendation.Blockers = copy(report.Unknowns) return report
	end
	if type(context.Catalog) ~= "table" or next(context.Catalog) == nil then
		table.insert(report.Unknowns, "Native Mastery.Upgrades catalog unavailable") report.Recommendation.Blockers = copy(report.Unknowns) return report
	end
	local priorities = {}
	for index, name in ipairs(settings.CATEGORY_ORDER or config.BRAIN_SETTINGS and config.BRAIN_SETTINGS.MASTERY_PRIORITIES or {}) do priorities[name] = index end
	local names = {} for name in pairs(context.Catalog) do
		if type(name) == "string" then table.insert(names, name) else table.insert(report.Unknowns, "Native category identifier is malformed") end
	end
	table.sort(names)
	local selectable, unresolved, eligible = {}, {}, 0
	for _, name in ipairs(names) do
		local row = category(config, snapshot, context, name, context.Catalog[name], priorities[name] or math.huge)
		table.insert(report.Categories, row)
		if row.Status == "UNKNOWN" then table.insert(unresolved, row)
		elseif row.Status ~= "COMPLETE" and row.Status ~= "LOCKED" then table.insert(selectable, row) eligible += 1 end
	end
	local rank = { REVIEW = 1, FUNDING = 2, PREREQUISITE = 3 }
	table.sort(selectable, function(a, b)
		if rank[a.Status] ~= rank[b.Status] then return rank[a.Status] < rank[b.Status] end
		if a.Amount == 0 and b.Amount ~= 0 then return true elseif b.Amount == 0 and a.Amount ~= 0 then return false end
		if a.Order ~= b.Order then return a.Order < b.Order end
		if a.Currency == b.Currency and a.Amount ~= b.Amount then return a.Amount < b.Amount end
		return a.Name < b.Name
	end)
	report.WorldGate = worldGate(config, snapshot, context)
	report.ObtainableRemainingCategories = eligible
	report.UnresolvedCategories = #unresolved
	report.EffectiveUpgrades = copy(context.EffectiveUpgrades or snapshot.Upgrades and snapshot.Upgrades.MasteryUpgrades)
	report.EffectiveUpgradeState = type(report.EffectiveUpgrades) == "table" and "RECEIVED" or "UNKNOWN"
	for _, row in ipairs(unresolved) do table.insert(report.Unknowns, row.Name .. ": " .. table.concat(row.Blockers, "; ")) end
	if selectable[1] then
		report.Status = "READ_ONLY_RECOMMENDATION" report.Recommendation = recommendation(selectable[1])
	elseif #unresolved > 0 or #report.Unknowns > 0 then
		report.Recommendation = unresolved[1] and recommendation(unresolved[1]) or report.Recommendation
	elseif report.WorldGate.Price and report.WorldGate.Affordability ~= "UNKNOWN" then
		report.Status = "READ_ONLY_RECOMMENDATION" report.WorldGate.Status = "REVIEW_AFTER_OBTAINABLE_MASTERY"
		report.Recommendation = { Kind = "WORLD_GATE_REVIEW", World = report.WorldGate.Name, Price = copy(report.WorldGate.Price),
			Currency = report.WorldGate.Currency, Amount = report.WorldGate.Amount, Balance = report.WorldGate.Balance,
			Shortage = report.WorldGate.Shortage, Affordability = report.WorldGate.Affordability,
			Reason = "No known currently obtainable permanent Mastery tier remains; review the native world gate and its separate access/action guards",
			Blockers = { "World action authorization remains separate; locked Mastery categories are not complete" }, ActionAuthorization = "NONE" }
	else
		report.Status = "NO_OBTAINABLE_MASTERY" report.Recommendation.Reason = "No known currently obtainable Mastery tier remains; next paid world gate UNKNOWN"
	end
	return report
end

function MasteryPolicy.Format(report)
	local row = report.Recommendation or {}
	local parts = { "READ_ONLY | " .. tostring(report.Status) .. " | " .. tostring(row.Kind or "WAIT") }
	if row.Category then table.insert(parts, row.Category .. " tier " .. tostring(row.Tier or "UNKNOWN")) end
	if row.World then table.insert(parts, "world=" .. row.World) end
	if row.Price then table.insert(parts, string.format("native price=%g %s; affordability=%s", row.Price.Amount, row.Price.Currency, tostring(row.Affordability or "UNKNOWN")))
	else table.insert(parts, "native price=UNKNOWN") end
	if row.Shortage ~= nil then table.insert(parts, "shortage=" .. tostring(row.Shortage)) end
	if row.FundingETASeconds then table.insert(parts, string.format("stationary funding ETA=%.1fs (conditional)", row.FundingETASeconds)) end
	table.insert(parts, row.Reason or "Evidence UNKNOWN")
	if row.Blockers and #row.Blockers > 0 then table.insert(parts, "blockers=" .. table.concat(row.Blockers, "; ")) end
	table.insert(parts, "earning benefit UNKNOWN; actions=NONE")
	return table.concat(parts, " | ")
end

return MasteryPolicy

end

-- src/OCFoundation/OCBrain.luau
factories["OCBrain"] = function()
--!nonstrict
-- Pure recommendation engine. It never invokes remotes, purchases, or movement.
local OCBrain = {}
local FarmingPolicy = requireOC("FarmingPolicy")
local ProgressionGraph = requireOC("ProgressionGraph")
local TravelPlanner = requireOC("TravelPlanner")
local PetPolicy = requireOC("PetPolicy")
OCBrain.__index = OCBrain

local function countEntries(map)
	if type(map) ~= "table" then return nil end
	local count = 0
	for _ in pairs(map) do count += 1 end
	return count
end

local function reserveFor(config, currency)
	local fields = { Coins = "COIN_RESERVE", Gems = "GEM_RESERVE", Tickets = "TICKET_RESERVE", Pearls = "PEARL_RESERVE" }
	return fields[currency] and config.RESOURCE_SETTINGS[fields[currency]] or 0
end

function OCBrain.new(config)
	return setmetatable({ Config = config, Previous = nil, SelectedAt = 0 }, OCBrain)
end

function OCBrain:Reset()
	self.Previous = nil
	self.SelectedAt = 0
	self.FarmingMemory = { Mode = nil, StartedAt = 0, LastTest = {} }
end

function OCBrain:AnalyzePets(snapshot, context)
	return PetPolicy.Analyze(self.Config, snapshot, context)
end

function OCBrain:PlanEquipmentStep(team, context, state)
	local settings, inv = self.Config.PET_SETTINGS, context.Inventory
	if settings.AUTO_EQUIP and inv and team.Status == "ESTIMATE" and team.Gain > 1e-6 then
		local before, desired = PetPolicy.Counts(inv.Team), PetPolicy.Counts(team.ProposedIds)
		-- One verified improvement at a time; never clear the entire team.
		local adds = {} for id in pairs(desired) do table.insert(adds, id) end table.sort(adds)
		for _, addId in ipairs(adds) do
			local amount = desired[addId]
			if amount <= (before[addId] or 0) then continue end
			if table.find(settings.PROTECTED_PET_IDS, addId) then continue end
			local removes = { false }
			if #inv.Team >= context.MaxEquipped then
				removes = {}
				for id, count in pairs(before) do
					local pet = inv.ById[id]
					if count > (desired[id] or 0) and not PetPolicy.Protected(self.Config, pet, (context.Pets or {})[pet.Name]) then table.insert(removes, id) end
				end
				table.sort(removes)
			end
			for _, removeId in ipairs(removes) do
				local needed = removeId and 2 or 1
				if state.EquipCommands + needed > settings.MAXIMUM_SESSION_EQUIP_COMMANDS then continue end
				local ids = table.clone(inv.Team)
				if removeId then table.remove(ids, table.find(ids, removeId)) end
				table.insert(ids, addId)
				local score = context.ScoreTeam(ids)
				if PetPolicy.Finite(score) and score > team.CurrentScore + 1e-6 then
					return { Kind = "TEAM", AddId = addId, RemoveId = removeId or nil, BeforeIds = table.clone(inv.Team),
						AfterIds = ids, TeamIndex = inv.TeamIndex, BeforeScore = team.CurrentScore, AfterScore = score, OwnsLocation = state.Location ~= nil }
				end
			end
		end
	end
	return nil
end

function OCBrain:PlanPets(report, context, state)
	local settings, hatch = self.Config.PET_SETTINGS, self.Config.HATCH_SETTINGS
	if not settings.ENABLE_PET_INTELLIGENCE or not self.Config.GENERAL_SETTINGS.ENABLE_RECOMMENDATIONS then return { Kind = "WAIT", OwnsLocation = false } end
	if state.Pending then return { Kind = "OBSERVE", OwnsLocation = state.Location ~= nil, Reason = "Awaiting actual inventory/equipment acknowledgement" } end
	if state.Fault then return { Kind = "WAIT", OwnsLocation = state.Location ~= nil, Reason = state.Fault } end
	if state.EquipmentContinuation then return state.EquipmentContinuation end
	if state.Attempt and state.Attempt.Ended then return { Kind = "WAIT", OwnsLocation = false, Reason = "One-time equipment authorization consumed: " .. tostring(state.Attempt.Status) } end
	if self.Config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST then return { Kind = "WAIT", OwnsLocation = false, Reason = "Pickup-only mode excludes pet actions" } end
	local team, inv = report.Team, context.Inventory
	if settings.EQUIP_OWNED_TEAM_ONCE then
		if state.Attempt then
			if state.Attempt.Ended then return { Kind = "WAIT", OwnsLocation = false, Reason = "One-time owned-team attempt ended: " .. tostring(state.Attempt.Status) } end
			if not settings.AUTO_EQUIP then return { Kind = "WAIT", OwnsLocation = false, Reason = "Equipment authorization withdrawn" } end
			return state.Attempt.Steps[state.Attempt.Step] or { Kind = "WAIT", OwnsLocation = false, Reason = "No remaining equipment step" }
		end
		if not settings.AUTO_EQUIP or not inv or team.Status ~= "ESTIMATE" then return { Kind = "WAIT", OwnsLocation = false, Reason = "One-time equipment requires ready native team analysis and authorization" } end
		if team.Gain <= 1e-6 then return { Kind = "TEAM_ATTEMPT_END", OwnsLocation = false, Reason = "No valid owned-team improvement; no equipment change" } end
		-- Freeze a complete serial plan BEFORE any command. Insufficient command budget,
		-- protected membership or a non-improving intermediate swap cannot leave a partial team.
		local projected = table.clone(context) projected.Inventory = table.clone(inv) projected.Inventory.Team = table.clone(inv.Team)
		local steps, commands = {}, state.EquipCommands
		while not PetPolicy.SameTeam(projected.Inventory.Team, team.ProposedIds) do
			local current = context.ScoreTeam(projected.Inventory.Team)
			if not PetPolicy.Finite(current) then return { Kind = "TEAM_ATTEMPT_END", OwnsLocation = false, Reason = "Native intermediate score UNKNOWN; no commands" } end
			local step = self:PlanEquipmentStep({ Status = "ESTIMATE", Gain = team.ProjectedScore - current, CurrentScore = current, ProposedIds = team.ProposedIds }, projected, { EquipCommands = commands })
			if not step then return { Kind = "TEAM_ATTEMPT_END", OwnsLocation = false, Reason = "Complete team plan blocked by command budget/protection or unsupported intermediate improvement; no commands" } end
			step.OwnsLocation = false table.insert(steps, step)
			commands += step.RemoveId and 2 or 1 projected.Inventory.Team = step.AfterIds
		end
		return { Kind = "TEAM_ATTEMPT_START", OwnsLocation = false, Steps = steps, Team = team, RequiredCommands = commands - state.EquipCommands }
	end
	local equipment = self:PlanEquipmentStep(team, context, state)
	if state.HatchOnce then
		local reason = PetPolicy.HatchIsolation(self.Config)
		if reason then return { Kind = "WAIT", OwnsLocation = false, Reason = reason } end
	end
	if equipment then return equipment end
	if settings.AUTO_HATCH and not state.SessionEnded then
		local blockers = {}
		for _, egg in ipairs(report.Eggs) do
			if state.Location and PetPolicy.SelectionMode(self.Config) ~= "AUTO" and egg.Name ~= state.Location.EggName then continue end
			if not PetPolicy.EggSelected(self.Config, egg.Name) then continue end
			local blocker = PetPolicy.EggBlocker(egg)
			if blocker then table.insert(blockers, egg.Name .. ": " .. blocker) continue end
			if not PetPolicy.EggSelected(self.Config, egg.Name) or egg.Status ~= "ESTIMATE" or not egg.Eligible or not egg.Affordable
				or not egg.Cost or not table.find(hatch.ALLOWED_CURRENCIES, egg.Cost.Currency) or egg.Cost.Amount > hatch.MAXIMUM_EGG_COST
				or (egg.ExpectedIncrement <= 1e-6 and egg.ClientTargetProbability <= 0 and not egg.OwnerCommonFunctionalTestEligible) then continue end
			local remainingCost = hatch.MAXIMUM_SESSION_COST - state.RequestCost
			local remaining = hatch.MAXIMUM_SESSION_HATCHES - state.RequestedHatches
			local free = PetPolicy.Finite(context.StorageCapacity) and PetPolicy.Finite(context.StorageUsed) and context.StorageCapacity - context.StorageUsed or 0
			if type(context.DigitalStorage) ~= "boolean" or context.InventoryFull ~= false or not context.AutoDeleteKnown or context.AutoDeleteActive then
				return { Kind = "WAIT", OwnsLocation = state.Location ~= nil, Reason = context.AutoDeleteActive and "NATIVE_AUTO_DELETE_ACTIVE: disable native auto-delete manually before this test; OC will not change it"
					or not context.AutoDeleteKnown and "UNKNOWN_AUTO_DELETE_SETTINGS: no request" or "CAPACITY_UNAVAILABLE_OR_FULL: native storage guard prevents hatch" }
			end
			if context.DigitalStorage then free = 1 end -- Bytes are not pet slots; use native available-space guard, one egg per request.
			local capacity = PetPolicy.Finite(context.MaxHatches) and context.MaxHatches or 0
			local count = math.floor(math.min(remaining, hatch.MAXIMUM_BATCH_HATCHES, capacity, free,
				egg.Spendable / egg.Cost.Amount, remainingCost / egg.Cost.Amount))
			if count < 1 or not PetPolicy.Finite(egg.DurationSeconds) or egg.DurationSeconds <= 0 then
				table.insert(blockers, egg.Name .. ": remaining request budget/capacity or native hatch duration unavailable") continue
			end
			local model
			for _, nativeEgg in ipairs(context.Eggs or {}) do if nativeEgg.Name == egg.Name then model = nativeEgg.Model break end end
			return { Kind = "HATCH", EggName = egg.Name, Model = model, Count = count, OwnsLocation = true,
				DecisionSource = "BRAIN", SelectionMode = PetPolicy.SelectionMode(self.Config), Currency = context.Currency,
				Reason = report.SelectionExplanation or (egg.InRange and "Authorized bounded useful hatch" or "Selected useful native egg requires controlled arrival or manual approach") }
		end
		return { Kind = "WAIT", OwnsLocation = false,
			Reason = #blockers > 0 and table.concat(blockers, "; ") or report.SelectionExplanation or "No useful eligible native egg; no fallback hatch" }
	end
	return { Kind = "WAIT", OwnsLocation = state.Location ~= nil and not state.SessionEnded,
		Reason = state.SessionEnded and "Bounded hatch authorization ended; request ledger retained; no retry" or "Pet action authorization disabled" }
end

function OCBrain:PlanProgression(snapshot, plan, context)
	return TravelPlanner.Decide(self.Config, snapshot, plan, context)
end

local function finite(value)
	return type(value) == "number" and value == value and value >= 0 and value < math.huge
end

-- Read-only analysis of the selected world. No invented income, goals, spending or activity switches.
function OCBrain:ProgressionEconomics(snapshot, plan, context)
	local settings = self.Config.WORLD_SETTINGS
	if not settings.ENABLE_WORLD_PROGRESSION or not settings.ENABLE_ECONOMIC_DIAGNOSTICS then return nil end
	local goal = plan and plan.Objective and plan.Objective.Metadata and plan.Objective.Metadata.Progression
	local node = snapshot.ProgressionGraph and snapshot.ProgressionGraph.Next
	if not goal or not goal.Node or not node or node.Id ~= goal.Node.Id or node.Kind ~= "WORLD"
		or (node.State ~= "FUNDING" and node.State ~= "READY") then return nil end
	local cost = node.Cost
	if type(cost) ~= "table" or type(cost.Currency) ~= "string" then return nil end
	local balance = (snapshot.Balances or {})[cost.Currency]
	if cost.Type ~= "Currency" or not finite(cost.Amount) or not finite(balance) then return nil end
	local result = { GoalId = plan.Objective.Id, World = node.Name, Currency = cost.Currency, Cost = cost.Amount,
		Balance = balance, Reserve = reserveFor(self.Config, cost.Currency), ObservedAt = context.Now,
		Status = "UNMEASURED", HorizonHours = settings.FUNDING_HORIZON_HOURS, Recommendations = {} }
	result.Deficit = math.max(0, result.Cost + result.Reserve - balance)
	local area, rate = context.Current, context.Rate
	local permitted = area and area.World == "The Overworld" and table.find({ "The Void", "Zen" }, area.Name)
		and table.find(self.Config.ISLAND_SETTINGS.SELECTED_ISLANDS, area.Name)
		and snapshot.UnlockedWorlds and snapshot.UnlockedWorlds[area.World] ~= nil
		and snapshot.UnlockedIslands and snapshot.UnlockedIslands[area.Name] ~= nil
	if permitted then result.Island = area.Key end
	local perMinute = rate and rate.PerMinute and rate.PerMinute[cost.Currency]
	if permitted and rate and rate.Ready and finite(rate.Seconds) and rate.Seconds >= self.Config.FARMING_SETTINGS.MINIMUM_RATE_SAMPLE_SECONDS
		and finite(rate.LastAt) and finite(context.Now) and rate.LastAt <= context.Now
		and context.Now - rate.LastAt <= self.Config.FARMING_SETTINGS.RATE_WINDOW_SECONDS and finite(perMinute) then
		result.PerMinute, result.SampleSeconds = perMinute, rate.Seconds
		result.SampleAgeSeconds = context.Now - rate.LastAt
	end
	if result.Deficit == 0 then result.Status = "FUNDED"
	elseif result.PerMinute and result.PerMinute > 0 then
		local minutes = result.Deficit / result.PerMinute
		if finite(minutes) then
			result.ETAMinutes, result.ETAHours, result.ETADays = minutes, minutes / 60, minutes / 1440
			result.Status = result.ETAHours > settings.FUNDING_HORIZON_HOURS and "BOTTLENECK" or "MEASURED"
		end
	elseif result.PerMinute == 0 then result.Status = "NO_OBSERVED_INCOME" end
	local multiplier = area and area.Multipliers and area.Multipliers[cost.Currency]
	if permitted and finite(multiplier) then result.NativePickupMultiplier = multiplier end
	result.Assumption = "Short stationary LocalData balance sample extrapolated at unchanged earning rate; external credits may contribute; ETA is not guaranteed"
	-- Native gum/flavor definitions change bubble storage/power, not the inspected pickup multiplier.
	local suggestions = {}
	for _, upgrade in ipairs((snapshot.AvailableProgression or {}).Upgrades or {}) do
		local price = upgrade.Cost
		local currentBase = upgrade.Kind == "Gum" and (snapshot.Bubble or {}).BaseCapacity or (snapshot.Bubble or {}).BaseOutput
		if (upgrade.Kind == "Gum" or upgrade.Kind == "Flavors") and upgrade.AccessKnown and upgrade.Accessible
			and upgrade.OwnershipKnown and not upgrade.Owned and price and price.Type == "Currency"
			and price.Currency == cost.Currency and finite(price.Amount) and finite(upgrade.BaseStat)
			and finite(currentBase) and upgrade.BaseStat > currentBase then
			table.insert(suggestions, upgrade)
		end
	end
	table.sort(suggestions, function(a, b) return a.Cost.Amount == b.Cost.Amount and a.Name < b.Name or a.Cost.Amount < b.Cost.Amount end)
	local seen = {}
	for _, upgrade in ipairs(suggestions) do
		if not seen[upgrade.Kind] then
			seen[upgrade.Kind] = true
			table.insert(result.Recommendations, string.format("Accessible %s %s: native cost %.0f %s, base %s %.0f; bubble-only candidate, pickup ROI unverified; no purchase",
				upgrade.Kind, upgrade.Name, upgrade.Cost.Amount, upgrade.Cost.Currency, upgrade.Kind == "Gum" and "storage" or "power", upgrade.BaseStat))
		end
	end
	local bestSell
	for _, island in ipairs(snapshot.ProgressionGraph.Islands or {}) do
		local sell = island.Facilities and island.Facilities.Sell
		if sell and sell.Currency == cost.Currency and finite(sell.Multiplier) and sell.Multiplier > 0
			and island.Discovered and snapshot.UnlockedWorlds[island.World] ~= nil
			and (not bestSell or sell.Multiplier > bestSell.Multiplier) then
			bestSell = { Island = island.Id, Multiplier = sell.Multiplier, Path = sell.Path }
		end
	end
	result.BestObservedIslandSell = bestSell
	if bestSell then table.insert(result.Recommendations, string.format("Observed accessible sell station %s: native %.2fx %s; net bubble/sell yield and travel cost unmeasured; selling remains separately authorized", bestSell.Island, bestSell.Multiplier, cost.Currency)) end
	result.EquippedPets = countEntries(snapshot.Inventory and snapshot.Inventory.EquippedIds)
	table.insert(result.Recommendations, "StatsUtil.GetCurrencyMultiplier uses equipped-pet currency stats and native modifiers; pet/hatching analysis deferred to Phase 4; Mastery execution/ROI deferred to Phase 5. Missing Mastery levels remain unknown")
	return result
end

function OCBrain:PlanFarming(snapshot, plan, context)
	self.FarmingMemory = self.FarmingMemory or { Mode = nil, StartedAt = 0, LastTest = {} }
	local scope = context.Current and context.Current.Key
	if scope ~= self.FarmingMemory.Scope then
		self.FarmingMemory = { Mode = nil, StartedAt = 0, LastTest = {}, Scope = scope,
			TargetCurrency = self.FarmingMemory.TargetCurrency, TargetIsland = self.FarmingMemory.TargetIsland }
	end
	local result = FarmingPolicy.Decide(self.Config, snapshot, plan, context, self.FarmingMemory)
	if result.Kind == "FARM" and result.Mode ~= self.FarmingMemory.Mode then
		self.FarmingMemory.Mode, self.FarmingMemory.StartedAt = result.Mode, context.Now
		self.FarmingMemory.LastTest[result.Mode] = context.Now
	end
	return result
end

function OCBrain:Classify(snapshot)
	if not snapshot.Ready then return "UNDETERMINED", "No real player profile is available." end
	local worlds = countEntries(snapshot.UnlockedWorlds)
	local islands = countEntries(snapshot.UnlockedIslands)
	local inventory = snapshot.Inventory or {}
	local pets = countEntries(inventory.Pets)
	local levels = snapshot.Upgrades and snapshot.Upgrades.MasteryLevels
	if worlds == nil or islands == nil or pets == nil or type(levels) ~= "table" then
		return "UNDETERMINED", "Unlock, pet, or Mastery data is missing or disabled."
	end
	local masteryTotal = 0
	for _, level in pairs(levels) do if type(level) == "number" then masteryTotal += level end end
	local stage
	if worlds <= 1 and islands == 0 and pets == 0 and masteryTotal == 0 then stage = "BRAND_NEW"
	elseif worlds <= 1 and islands < 2 then stage = "EARLY_GAME"
	elseif worlds <= 1 then stage = "DEVELOPING"
	elseif worlds == 2 then stage = "MID_GAME"
	else stage = "ADVANCED" end
	return stage, string.format("%d unlocked worlds, %d discovered areas, %d pet records, %d Mastery levels. Full endgame completion is not inferred.",
		worlds, islands, pets, masteryTotal)
end

function OCBrain:Plan(snapshot, token)
	if token and token:CheckCancelled() then return nil end
	local stage, evidence = self:Classify(snapshot)
	local candidates = {}
	local config = self.Config
	local function add(id, title, reason, priority, family, prerequisites, metadata)
		table.insert(candidates, { Id = id, Title = title, Reason = reason, Priority = priority,
			Family = family, Prerequisites = prerequisites or {}, Metadata = metadata or {},
			RecommendationOnly = true, SnapshotRevision = snapshot.Revision })
	end
	if not config.GENERAL_SETTINGS.ENABLE_RECOMMENDATIONS then
		add("RECOMMENDATIONS_DISABLED", "Recommendations are disabled", "Enable GENERAL_SETTINGS.ENABLE_RECOMMENDATIONS to select goals.", 1000, "RESOLVE_BLOCKERS")
	elseif not snapshot.Ready then
		add("WAIT_FOR_ACCOUNT", "Load the game's real player profile", "Account analysis needs LocalData:IsReady() and LocalData:Get().",
			1000, "RESOLVE_BLOCKERS", { "Game server supplies PlayerDataLoaded", "LocalData finishes loading" })
	else
		local inventory = snapshot.Inventory or {}
		local bubble = snapshot.Bubble or {}
		local progression = snapshot.AvailableProgression or {}
		local balances = snapshot.Balances or {}
		if config.WORLD_SETTINGS.ENABLE_WORLD_PROGRESSION then
			local graph = snapshot.ProgressionGraph or { Blocker = "Native progression graph unavailable" }
			local goal = ProgressionGraph.Goal(config, graph)
			if goal then
				add(goal.Id, goal.Title, goal.Reason, 900, "WORLD_UNLOCKS", goal.State == "BLOCKED" and { goal.Reason } or {},
					{ Progression = goal, Cost = goal.Cost })
			end
		end
		local function spendable(currency)
			if balances[currency] == nil then return nil end
			return math.max(0, balances[currency] - reserveFor(config, currency))
		end
		if config.BRAIN_SETTINGS.ENABLE_INVENTORY_RECOMMENDATIONS then
			if inventory.StorageUsed and inventory.StorageCapacity and inventory.StorageUsed >= inventory.StorageCapacity then
				add("REVIEW_INVENTORY", "Resolve full pet inventory", "Storage is full according to the game's own storage helpers; preserve pets and review storage upgrades.",
					950, "RESOLVE_BLOCKERS", { "Free storage through an approved non-destructive action" })
			end
			if inventory.UnresolvedEquippedIds and #inventory.UnresolvedEquippedIds > 0 then
				add("WAIT_FOR_PET_SYNC", "Wait for a consistent pet inventory", "Some equipped IDs are absent from the received pet records; avoid planning a team change from this snapshot.",
					960, "RESOLVE_BLOCKERS", { "LocalData resolves the equipped pet IDs" })
			end
		end
		if config.BRAIN_SETTINGS.ENABLE_EARNING_RECOMMENDATIONS and inventory.Pets and inventory.EquippedIds then
			local total = countEntries(inventory.Pets)
			if total > 0 and #inventory.EquippedIds == 0 then
				add("EQUIP_EXISTING_PETS", "Equip pets you already own", "The active team is empty even though the inventory contains pets.",
					850, "EARNING_POWER", { "Select owned pets for the active team" })
			elseif inventory.MaxEquipped and #inventory.EquippedIds < math.min(inventory.MaxEquipped, total) then
				add("FILL_EQUIP_SLOTS", "Use available pet equip slots", "Owned pet records and free equip slots are available; team changes are recommendations only.",
					720, "EARNING_POWER", { "Choose suitable owned pets" })
			end
		end
		for _, requirement in ipairs(snapshot.TaskRequirements or {}) do
			if not config.BRAIN_SETTINGS.ENABLE_EARNING_RECOMMENDATIONS then continue end
			if requirement.Type ~= "Collect" and not config.BUBBLE_SETTINGS.ENABLE_BUBBLE_RECOMMENDATIONS then continue end
			local resource = requirement.Currency or (requirement.Type == "Sell" and "bubble selling" or "bubbles")
			add("TASK:" .. requirement.QuestId .. ":" .. tostring(requirement.TaskIndex), "Progress " .. requirement.QuestId .. " (" .. resource .. ")",
				string.format("Received native task: %.0f/%.0f %s. No task is accepted or claimed by OC.", requirement.Current, requirement.Required, resource),
				700, "EARNING_POWER", {}, { Requirement = requirement })
		end
		if config.BRAIN_SETTINGS.ENABLE_EARNING_RECOMMENDATIONS and config.BUBBLE_SETTINGS.ENABLE_BUBBLE_RECOMMENDATIONS then
			local smallCapacity = bubble.Capacity and bubble.PowerPerBlow and bubble.PowerPerBlow > 0
				and bubble.Capacity / bubble.PowerPerBlow < config.BRAIN_SETTINGS.MINIMUM_BLOWS_PER_FILL
			for _, upgrade in ipairs(progression.Upgrades or {}) do
				if token and token:CheckCancelled() then return nil end
				local current = upgrade.Kind == "Gum" and bubble.BaseCapacity or bubble.BaseOutput
				if upgrade.Accessible and upgrade.OwnershipKnown and current and current > 0 and upgrade.BaseStat then
					local gain = upgrade.BaseStat / current - 1
					if gain >= config.BRAIN_SETTINGS.MINIMUM_UPGRADE_GAIN_RATIO then
						if upgrade.Owned then
							add("EQUIP_UPGRADE:" .. upgrade.Name, "Equip " .. upgrade.Name,
								"This owned upgrade has a higher base stat than the equipped upgrade; effective stats will refresh after a real change.",
								750, "EARNING_POWER", {}, { Upgrade = upgrade.Name, Kind = upgrade.Kind })
						else
							local cost = upgrade.Cost
							local funds = spendable(cost.Currency)
							if funds and type(cost.Amount) == "number" and cost.Amount >= 0 then
								local withinBudget = cost.Amount <= funds * config.RESOURCE_SETTINGS.MAXIMUM_UPGRADE_BALANCE_FRACTION
								local efficiency = math.min(30, gain / math.max(1, cost.Amount) * 100)
								local priority = (withinBudget and 620 or 350) + efficiency
								if upgrade.Kind == "Gum" and smallCapacity then priority += 90 end
								add("BUY_UPGRADE:" .. upgrade.Name,
									(withinBudget and "Consider " or "Save for ") .. upgrade.Name,
									string.format("Base %s improvement %.0f%%; cost %.0f %s. Farming policy separately checks observed income and projected payback before purchasing.",
										upgrade.Kind == "Gum" and "capacity" or "flavor output", gain * 100, cost.Amount, cost.Currency),
									priority, "EARNING_POWER", withinBudget and {} or { "Meet the configured upgrade affordability budget" },
									{ Cost = cost, Upgrade = upgrade.Name, Kind = upgrade.Kind })
								end
						end
					end
				end
			end
		end
		if not config.WORLD_SETTINGS.ENABLE_WORLD_PROGRESSION and config.BRAIN_SETTINGS.ENABLE_WORLD_RECOMMENDATIONS and snapshot.UnlockedWorlds and snapshot.UnlockedIslands then
			for _, world in ipairs(progression.Worlds or {}) do
				if not world.Unlocked and world.Selected and world.Gate then
					local gate = world.Gate
					if not gate.OriginWorld or snapshot.UnlockedWorlds[gate.OriginWorld] == nil then continue end
					if gate.RequiredIsland and snapshot.UnlockedIslands[gate.RequiredIsland] == nil then
						add("DISCOVER:" .. gate.RequiredIsland, "Discover " .. gate.RequiredIsland,
							"The live gate to " .. world.Name .. " is located on this undiscovered island.",
							500, "WORLD_UNLOCKS", { "Reach the island through available game travel" }, { World = world.Name })
					elseif type(world.Cost) == "table" and world.Cost.Type == "Currency" then
						local funds = spendable(world.Cost.Currency)
						if funds and type(world.Cost.Amount) == "number" then
							local affordable = funds >= world.Cost.Amount
							add("UNLOCK_WORLD:" .. world.Name, (affordable and "Unlock " or "Save for ") .. world.Name,
								string.format("Current definition requires %.0f %s; the gate's island prerequisite is discovered.", world.Cost.Amount, world.Cost.Currency),
								affordable and 780 or 450, "WORLD_UNLOCKS",
								affordable and { "Use the verified world gate" } or { "Earn the remaining currency while keeping configured reserves" },
								{ Cost = world.Cost, World = world.Name, Gate = gate.Path })
						end
					end
					break
				end
			end
			for _, island in ipairs(progression.Islands or {}) do
				local selectedWorlds = config.BRAIN_SETTINGS.SELECTED_WORLDS
				if (#selectedWorlds == 0 or table.find(selectedWorlds, island.World)) and snapshot.UnlockedWorlds[island.World] ~= nil and not island.Unlocked then
					add("EXPLORE:" .. island.Name, "Discover " .. island.Name,
						"This scene-present island is the next undiscovered area in its world's height order; route execution is a later phase.",
						400, "WORLD_UNLOCKS", { "Verify and use a reachable game route" }, { World = island.World, Height = island.Height })
					break
				end
			end
		end
		if config.BRAIN_SETTINGS.ENABLE_MASTERY_RECOMMENDATIONS then
			for index, branch in ipairs(progression.Mastery or {}) do
				local cost = branch.NextCost
				if branch.Current ~= nil and type(cost) == "table" and cost.Type == "Currency" then
					local funds = spendable(cost.Currency)
					if funds and type(cost.Amount) == "number" then
						add("MASTERY:" .. branch.Name, "Review " .. branch.Name .. " Mastery level " .. tostring(branch.Current + 1),
							string.format("Next verified tier costs %.0f %s. Mastery purchasing remains a later-phase task.", cost.Amount, cost.Currency),
							(funds >= cost.Amount and 550 or 300) - index, "MASTERY",
							{ "Verify access to the Mastery facility", "Confirm the tier's benefit fits the selected goal" }, { Cost = cost })
					end
				end
			end
		end
		if #candidates == 0 then
			add("REVIEW_AVAILABLE_PROGRESSION", "Review available progression", "No supported recommendation can be established from the enabled readers and current definitions.",
				0, "RESOLVE_BLOCKERS", { "Review missing fields or approve another implementation phase" })
		end
	end
	local priorities = {}
	for index, family in ipairs(config.GENERAL_SETTINGS.PRIORITIES) do priorities[family] = index end
	table.sort(candidates, function(a, b)
		if a.Priority ~= b.Priority then return a.Priority > b.Priority end
		local left, right = priorities[a.Family] or 999, priorities[b.Family] or 999
		if left ~= right then return left < right end
		return a.Id < b.Id
	end)
	local selected = candidates[1]
	if self.Previous and os.clock() - self.SelectedAt < config.GENERAL_SETTINGS.MINIMUM_OBJECTIVE_HOLD_SECONDS then
		for _, candidate in ipairs(candidates) do
			if candidate.Id == self.Previous.Id and selected.Priority < candidate.Priority + config.GENERAL_SETTINGS.OBJECTIVE_SWITCH_PRIORITY_MARGIN then
				selected = candidate break
			end
		end
	end
	if not self.Previous or selected.Id ~= self.Previous.Id then self.SelectedAt = os.clock() end
	self.Previous = selected
	local nextObjective
	for _, candidate in ipairs(candidates) do
		if candidate.Id ~= selected.Id then nextObjective = candidate break end
	end
	local major = snapshot.ProgressionGraph and snapshot.ProgressionGraph.Next
	local reservation = major and major.Kind == "WORLD" and (major.State == "READY" or major.State == "FUNDING") and major.Cost or nil
	return { Progression = stage, ProgressionEvidence = evidence, Objective = selected,
		Graph = snapshot.ProgressionGraph, MajorUnlockReservation = reservation,
		NextObjective = nextObjective,
		Candidates = candidates, SnapshotRevision = snapshot.Revision,
		Reservations = reservation and { reservation } or (selected.Metadata.Cost and { selected.Metadata.Cost } or {}),
		ReservationPolicy = "Farming policy and native upgrade adapter enforce spending reserves before currency purchases." }
end

-- Scoped local additions arbitrate through the same Brain and foreground scheduler.
-- Managers expose eligibility/state; they create no competing gameplay loops.
function OCBrain:TravelDiagnosticBlocker()
	local config, pets, hatch = self.Config, self.Config.PET_SETTINGS, self.Config.HATCH_SETTINGS
	if (config.EGG_TRAVEL_SETTINGS.MODE or "NORMAL") ~= "TRAVEL_ONLY" or not config.EGG_TRAVEL_SETTINGS.ENABLE_SELECTED_EGG_TRAVEL then
		return "TRAVEL_ONLY diagnostic mode/selected egg travel is disabled"
	end
	if not pets.ENABLE_PET_INTELLIGENCE or not config.GENERAL_SETTINGS.ENABLE_RECOMMENDATIONS then
		return "TRAVEL_ONLY requires read-only pet intelligence and Brain recommendations"
	end
	if pets.AUTO_HATCH or pets.AUTO_EQUIP or pets.EQUIP_OWNED_TEAM_ONCE or hatch.HATCH_ONE_EGG_ONCE
		or hatch.MAXIMUM_EGG_COST ~= 0 or hatch.MAXIMUM_SESSION_COST ~= 0 or hatch.ENABLE_BACKGROUND_PICKUPS
		or config.WORLD_SETTINGS.MAXIMUM_WORLD_UNLOCK_COST ~= 0
		or config.OWNER_ONE_HATCH_TEST_SETTINGS and config.OWNER_ONE_HATCH_TEST_SETTINGS.OWNER_ONE_HATCH_TEST_ALLOWANCE then
		return "TRAVEL_ONLY requires hatch/equipment/allowance OFF and zero hatch/world purchase budgets"
	end
	for category, keys in pairs({
		WORLD_SETTINGS = { "ENABLE_WORLD_PROGRESSION", "AUTO_DISCOVER_ISLANDS", "AUTO_UNLOCK_WORLDS", "AUTO_TRAVEL_FOR_PROGRESSION", "AUTO_FARM_UNLOCK_REQUIREMENTS" },
		FARMING_SETTINGS = { "AUTO_RESOURCE_FARM", "AUTO_FARM_FALLBACK" },
		ISLAND_SETTINGS = { "AUTO_TRAVEL_BEST_ISLAND", "AUTO_EXPLORE_UNLOCKED_ISLANDS" },
		PICKUP_SETTINGS = { "BULK_COLLECT_PICKUPS", "STATIONARY_ISOLATED_TEST" },
		BUBBLE_SETTINGS = { "AUTO_BLOW_BUBBLES", "AUTO_SELL_BUBBLES", "AUTO_BUY_GUM", "AUTO_BUY_FLAVORS", "ENABLE_SIMULTANEOUS_BLOWING" },
		UPGRADE_SETTINGS = { "ENABLE_SMART_UPGRADES", "ENABLE_CAPACITY_UPGRADES", "ENABLE_FLAVOR_UPGRADES", "AUTO_EQUIP_OWNED_UPGRADES" },
		PET_SETTINGS = { "AUTO_DELETE_PETS", "AUTO_CRAFT_SHINY", "AUTO_FUSE_PETS" },
		FALL_EVENT_SETTINGS = { "ENABLE_FALL_EVENT", "AUTO_REBIRTH", "AUTO_BUY_REBIRTH_UPGRADES", "AUTO_USE_FALL_ELIXIRS", "AUTO_BUY_AUTUMN_SHOP_ITEMS" },
		PLAYTIME_SETTINGS = { "AUTO_CLAIM_PLAYTIME" }, MYSTERY_BOX_SETTINGS = { "AUTO_OPEN_MYSTERY_BOXES" },
		ANTIAFK_SETTINGS = { "ENABLE_ANTI_AFK" },
	}) do
		for _, key in ipairs(keys) do if config[category][key] then return "TRAVEL_ONLY requires " .. category .. "." .. key .. " OFF" end end
	end
	local mode = PetPolicy.SelectionMode(config)
	if mode ~= "AUTO" and mode ~= "MANUAL" then return "TRAVEL_ONLY egg selection mode unavailable" end
	if mode == "MANUAL" and #hatch.SELECTED_EGGS ~= 1 then return "TRAVEL_ONLY MANUAL requires one exact native egg name" end
	return nil
end

function OCBrain:PlanEggTravelDiagnostic(snapshot, context, definitions, worlds, retainedIntent)
	local blocker = self:TravelDiagnosticBlocker()
	if blocker then return { Kind = "WAIT", OwnsLocation = false, Reason = blocker } end
	if not snapshot or not snapshot.Ready or type(snapshot.UnlockedWorlds) ~= "table" or type(snapshot.UnlockedIslands) ~= "table"
		or type(context) ~= "table" or type(definitions) ~= "table" or type(worlds) ~= "table" then
		return { Kind = "WAIT", OwnsLocation = false, Reason = "TRAVEL_ONLY requires fresh LocalData access and native egg/world definitions" }
	end
	local candidates, reasons, selectedMode = {}, {}, PetPolicy.SelectionMode(self.Config)
	if retainedIntent and (retainedIntent.Scope ~= "TRAVEL_ONLY" or retainedIntent.DecisionSource ~= "BRAIN_TRAVEL_DIAGNOSTIC"
		or retainedIntent.SelectionMode ~= selectedMode or type(retainedIntent.EggName) ~= "string" or not retainedIntent.Model) then
		return { Kind = "WAIT", OwnsLocation = false, Reason = "Acquired diagnostic selection scope/mode/identity changed; no retarget" }
	end
	for _, egg in ipairs(context.EggLocations or context.EggAvailability or context.Eggs or {}) do
		if retainedIntent and (egg.Name ~= retainedIntent.EggName or egg.Model ~= retainedIntent.Model) then continue end
		if not PetPolicy.EggSelected(self.Config, egg.Name) then continue end
		local definition = definitions[egg.Name]
		local world = type(definition) == "table" and definition.World
		local worldDefinition = world and worlds[world]
		local island = egg.Island or type(definition) == "table" and definition.Island
		local reason
		if egg.IdentityReason then reason = egg.IdentityReason
		elseif egg.Loaded ~= true or not egg.Model then reason = "original native model not loaded"
		elseif type(definition) ~= "table" or definition.Event or definition.ProductId or definition.IsAdminEgg or egg.Name == "Infinity Egg" then
			reason = "unsupported event/premium/special or unknown native definition"
		elseif type(world) ~= "string" or type(worldDefinition) ~= "table" or worldDefinition.Removed or worldDefinition.Event then
			reason = "native permanent world unavailable/removed"
		elseif egg.Accessible ~= true or snapshot.UnlockedWorlds[world] == nil or island and snapshot.UnlockedIslands[island] == nil then
			reason = "actual world/island access locked or unknown"
		else
			local cost = egg.Cost or definition.Cost
			local ordinary = type(cost) == "table" and cost.Type == "Currency" and type(cost.Currency) == "string"
				and PetPolicy.Finite(cost.Amount)
			table.insert(candidates, { Egg = egg, World = world, Island = island, OrdinaryCost = ordinary == true,
				Distance = PetPolicy.Finite(egg.Distance) and egg.Distance or math.huge })
		end
		if reason and #reasons < math.min(2, self.Config.HATCH_SETTINGS.MAXIMUM_PLAN_CANDIDATES) then table.insert(reasons, tostring(egg.Name) .. ": " .. reason) end
	end
	table.sort(candidates, function(a, b)
		if a.OrdinaryCost ~= b.OrdinaryCost then return a.OrdinaryCost end
		if a.Distance ~= b.Distance then return a.Distance < b.Distance end
		return a.Egg.Name < b.Egg.Name
	end)
	local candidate = candidates[1]
	if not candidate then
		if #reasons == 0 then
			local names = {} for name in pairs(context.EggLocationDiagnostics or {}) do
				if PetPolicy.EggSelected(self.Config, name) then table.insert(names, name) end
			end table.sort(names)
			for _, name in ipairs(names) do
				if #reasons >= math.min(2, self.Config.HATCH_SETTINGS.MAXIMUM_PLAN_CANDIDATES) then break end
				table.insert(reasons, name .. ": " .. tostring(context.EggLocationDiagnostics[name].Reason))
			end
		end
		return { Kind = "WAIT", OwnsLocation = false, Reason = #reasons > 0 and "TRAVEL_ONLY no eligible destination | " .. table.concat(reasons, "; ")
			or "TRAVEL_ONLY no eligible loaded native egg; no catalog-only or random travel" }
	end
	local egg = candidate.Egg
	return { Kind = "EGG_TRAVEL", Scope = "TRAVEL_ONLY", DecisionSource = "BRAIN_TRAVEL_DIAGNOSTIC", SelectionMode = selectedMode,
		EggName = egg.Name, Model = egg.Model, IdentityId = egg.IdentityId, IdentityEvidence = egg.IdentityEvidence,
		LocationVerified = egg.LocationVerified, LocationEvidence = egg.LocationEvidence,
		World = candidate.World, Island = candidate.Island, OwnsLocation = true,
		DefinitionReference = "ReplicatedStorage.Shared.Data.Eggs[" .. egg.Name .. "]",
		AccessSource = "Received LocalData.WorldsUnlocked/AreasUnlocked + actual loaded original egg model",
		GeometrySource = "Verified original Root + native world/island scene correspondence; floor/full-avatar clearance; physical arrival and hatch interaction observed separately",
		EconomicSelection = "DIAGNOSTIC_PHYSICAL_TARGET; optimal economic choice not claimed",
		Reason = string.format("TRAVEL_ONLY %s selected %s @ %s/%s | actual loaded permanent egg/access; %s; %s | observed distance=%s; economic ROI/affordability/reserves do not authorize or block this zero-spend diagnostic; hatch/equipment/pickups OFF; native path, geometry and stable range still required",
			selectedMode, egg.Name, candidate.World, tostring(candidate.Island or "surface"), candidate.OrdinaryCost and "ordinary native currency cost observed; diagnostic physical selection, no optimal ROI claim" or "price unavailable/unsupported for spending; diagnostic physical selection, no optimal ROI claim",
			retainedIntent and "retained acquired exact original model; character movement/new proximity does not select another egg" or "closest source-associated physical original after native spatial/access checks; distance is travel policy, not hatch identity proof",
			candidate.Distance < math.huge and tostring(candidate.Distance) or "UNKNOWN") }
end

function OCBrain:SelectLocalFeature(controller, plan, petOwns, petDecision)
	if (self.Config.EGG_TRAVEL_SETTINGS.MODE or "NORMAL") == "TRAVEL_ONLY" then
		local blocker = self:TravelDiagnosticBlocker()
		if blocker then controller.EggTravel.Reason = blocker controller.EggTravel:DiagnosticTrace("PREFLIGHT_BLOCKED", nil, blocker) return "PHASE4_WAIT", { Kind = "WAIT", Reason = blocker, OwnsLocation = false } end
		local snapshot, context = controller.Pets:Fresh()
		local retained = controller.EggTravel.Lease and controller.EggTravel.BrainIntent
		local goalId = plan and plan.Objective and plan.Objective.Id or "TRAVEL_ONLY_DIAGNOSTIC"
		if retained and (retained.GoalId ~= goalId or retained.Generation ~= controller.Generation
			or retained.SelectionRevision ~= self.Config.EGG_TRAVEL_SETTINGS.SELECTION_REVISION) then
			controller.EggTravel:Release("Acquired diagnostic goal/generation/revision changed; no stale travel", true)
			return "PHASE4_WAIT", { Kind = "WAIT", Reason = "Acquired diagnostic goal/generation/revision changed", OwnsLocation = false }
		end
		local intent = self:PlanEggTravelDiagnostic(snapshot, context, controller.Knowledge:Get("Eggs"), controller.Knowledge:Get("Worlds"), retained)
		if intent.Kind ~= "EGG_TRAVEL" then
			controller.EggTravel.Reason = intent.Reason
			local names = {} for name in pairs(context and context.EggLocationDiagnostics or {}) do
				if PetPolicy.EggSelected(self.Config, name) then table.insert(names, name) end
			end table.sort(names)
			if names[1] then controller.EggTravel:ReportInstanceDiagnostics({ [names[1]] = context.EggLocationDiagnostics[names[1]] }) end
			controller.EggTravel:DiagnosticTrace("PREFLIGHT_BLOCKED", nil, intent.Reason) return "PHASE4_WAIT", intent
		end
		intent.Generation, intent.AccountId = controller.Generation, controller.Reader.Player and controller.Reader.Player.UserId
		intent.SelectionRevision = self.Config.EGG_TRAVEL_SETTINGS.SELECTION_REVISION
		intent.GoalId = goalId
		local owns, decision = controller.EggTravel:Select(plan, intent)
		return owns and "EGG_TRAVEL" or "PHASE4_WAIT", decision
	end
	if petDecision and self.Config.PET_SETTINGS.AUTO_HATCH then
		-- A sent hatch/verified equipment transaction keeps its foreground authority.
		-- Observing presentation/result cannot be preempted by travel or rewards.
		if petDecision.Kind == "OBSERVE" or petDecision.Kind == "TEAM" or petDecision.Kind == "TEAM_ADD" then return nil end
		if petDecision.Kind == "HATCH" and self.Config.EGG_TRAVEL_SETTINGS.ENABLE_SELECTED_EGG_TRAVEL then
			local owns, decision = controller.EggTravel:Select(plan, petDecision)
			if owns then return "EGG_TRAVEL", decision end
			if decision and decision.Kind == "HANDOFF" then return nil end
			return "PHASE4_WAIT", decision -- Never fall through to a stale hatch or farming destination.
		end
		if petDecision.Kind == "WAIT" then
			if controller.EggTravel:OwnsLocation() and not petDecision.OwnsLocation then
				controller.EggTravel:Release(petDecision.Reason or "Hatch intent ended; no return travel", false)
			end
			return "PHASE4_WAIT", petDecision
		end
		if petOwns then return nil end
	end
	for _, entry in ipairs({ { "REWARDS", controller.Rewards }, { "EGG_TRAVEL", controller.EggTravel },
		{ "ANTI_AFK", controller.AntiAFK } }) do
		local owns, decision = entry[2]:Select(plan)
		if owns then return entry[1], decision end
	end
	return nil
end

-- PHASE5_READ_ONLY_MASTERY_BEGIN
-- Separate read-only intelligence. The existing Plan and action arbitration are unchanged.
function OCBrain:AnalyzeMastery(snapshot, knowledge, context)
	local policy = requireOC("MasteryPolicy")
	local settings = self.Config.MASTERY_SETTINGS or {}
	context = context or {}
	local observed
	if settings.ENABLE_MASTERY_INTELLIGENCE and knowledge then
		observed = knowledge:MasteryContext(snapshot, context.Now or os.clock(), settings)
	else observed = { Fresh = false, Blocker = "READ_ONLY_MASTERY_DISABLED" } end
	observed.StationaryRate = context.StationaryRate
	observed.WorldGate = context.WorldGate
	return policy.Analyze(self.Config, snapshot, observed)
end
-- PHASE5_READ_ONLY_MASTERY_END
-- PHASE5_READ_ONLY_REWARDS_BEGIN
-- Advisory intelligence only; the existing Brain, Mastery and scheduler decisions are untouched.
function OCBrain:AnalyzeRewards(snapshot, knowledge, context)
	local policy = requireOC("RewardPolicy")
	context = context or {}
	local settings = self.Config.REWARD_INTELLIGENCE_SETTINGS or {}
	local observed
	if settings.ENABLE_REWARD_INTELLIGENCE and knowledge then
		observed = knowledge:RewardContext(snapshot, context.Now or os.clock(), settings)
	else observed = { Fresh = false, Blocker = "READ_ONLY_REWARD_INTELLIGENCE_DISABLED" } end
	observed.MasteryReport = context.MasteryReport
	observed.PendingObservation = context.PendingObservation
	return policy.Analyze(self.Config, snapshot, observed)
end
-- PHASE5_READ_ONLY_REWARDS_END
return OCBrain

end

